insert into public.bible_versions (code, name, abbreviation, language, source, is_interlinear, licence_gated, copyright, sort_order) values
  ('INT', 'Interlinear (Hebrew · Greek · Aramaic)', 'INT', 'orig', 'local', true, false, 'Hebrew: Westminster Leningrad Codex (CC BY 4.0). Greek: SBL GNT (CC BY-SA 3.0). Strong''s: public domain.', 10),
  ('YLT', 'Young''s Literal Translation (1898)', 'Literal', 'en', 'local', false, false, 'Public domain.', 20),
  ('CJB', 'Complete Jewish Bible', 'CJB', 'en', 'api_bible', false, true, 'Complete Jewish Bible © 1998 David H. Stern, Messianic Jewish Family Bible Society. Served under licence via API.Bible.', 30),
  ('TPT', 'The Passion Translation', 'Passion', 'en', 'api_bible', false, true, 'The Passion Translation® © 2020 Passion & Fire Ministries, Inc. Served under licence via API.Bible.', 40),
  ('KJV', 'King James Version (1769)', 'KJV', 'en', 'local', false, false, 'Public domain.', 50)
insert into public.verses (version_code, book_id, chapter, verse, text) values
  ('KJV', 'GEN', 1, 1, 'In the beginning God created the heaven and the earth.'),
  ('KJV', 'GEN', 1, 2, 'And the earth was without form and void; and darkness was upon the face of the deep. And the Spirit of God moved upon the face of the waters.'),
  ('KJV', 'GEN', 1, 3, 'And God said, Let there be light: and there was light.'),
  ('KJV', 'GEN', 1, 4, 'And God saw the light, that it was good: and God divided the light from the darkness.'),
  ('KJV', 'GEN', 1, 5, 'And God called the light Day, and the darkness he called Night. And the evening and the morning were the first day.'),
  ('KJV', 'GEN', 1, 6, 'And God said, Let there be a firmament in the midst of the waters, and let it divide the waters from the waters.'),
  ('KJV', 'GEN', 1, 7, 'And God made the firmament, and divided the waters which were under the firmament from the waters which were above the firmament: and it was so.'),
  ('KJV', 'GEN', 1, 8, 'And God called the firmament Heaven. And the evening and the morning were the second day.'),
  ('KJV', 'GEN', 1, 9, 'And God said, Let the waters under the heaven be gathered together unto one place, and let the dry land appear: and it was so.'),
  ('KJV', 'GEN', 1, 10, 'And God called the dry land Earth; and the gathering together of the waters called he Seas: and God saw that it was good.'),
  ('KJV', 'GEN', 1, 11, 'And God said, Let the earth bring forth grass, the herb yielding seed, and the fruit tree yielding fruit after his kind, whose seed is in itself, upon the earth: and it was so.'),
  ('KJV', 'GEN', 1, 12, 'And the earth brought forth grass, and herb yielding seed after his kind, and the tree yielding fruit, whose seed was in itself, after his kind: and God saw that it was good.'),
  ('KJV', 'GEN', 1, 13, 'And the evening and the morning were the third day.'),
  ('KJV', 'GEN', 1, 14, 'And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and years:'),
  ('KJV', 'GEN', 1, 15, 'And let them be for lights in the firmament of the heaven to give light upon the earth: and it was so.'),
  ('KJV', 'GEN', 1, 16, 'And God made two great lights; the greater light to rule the day, and the lesser light to rule the night: he made the stars also.'),
  ('KJV', 'GEN', 1, 17, 'And God set them in the firmament of the heaven to give light upon the earth,'),
  ('KJV', 'GEN', 1, 18, 'And to rule over the day and over the night, and to divide the light from the darkness: and God saw that it was good.'),
  ('KJV', 'GEN', 1, 19, 'And the evening and the morning were the fourth day.'),
  ('KJV', 'GEN', 1, 20, 'And God said, Let the waters bring forth abundantly the moving creature that hath life, and fowl that may fly above the earth in the open firmament of heaven.'),
  ('KJV', 'GEN', 1, 21, 'And God created great whales, and every living creature that moveth, which the waters brought forth abundantly, after their kind, and every winged fowl after his kind: and God saw that it was good.'),
  ('KJV', 'GEN', 1, 22, 'And God blessed them, saying, Be fruitful, and multiply, and fill the waters in the seas, and let fowl multiply in the earth.'),
  ('KJV', 'GEN', 1, 23, 'And the evening and the morning were the fifth day.'),
  ('KJV', 'GEN', 1, 24, 'And God said, Let the earth bring forth the living creature after his kind, cattle, and creeping thing, and beast of the earth after his kind: and it was so.'),
  ('KJV', 'GEN', 1, 25, 'And God made the beast of the earth after his kind, and cattle after their kind, and every thing that creepeth upon the earth after his kind: and God saw that it was good.'),
  ('KJV', 'GEN', 1, 26, 'And God said, Let us make man in our image, after our likeness: and let them have dominion over the fish of the sea, and over the fowl of the air, and over the cattle, and over all the earth, and over every creeping thing that creepeth upon the earth.'),
  ('KJV', 'GEN', 1, 27, 'So God created man in his own image, in the image of God created he him; male and female created he them.'),
  ('KJV', 'GEN', 1, 28, 'And God blessed them, and God said unto them, Be fruitful, and multiply, and replenish the earth, and subdue it: and have dominion over the fish of the sea, and over the fowl of the air, and over every living thing that moveth upon the earth.'),
  ('KJV', 'GEN', 1, 29, 'And God said, Behold, I have given you every herb bearing seed, which is upon the face of all the earth, and every tree, in the which is the fruit of a tree yielding seed; to you it shall be for meat.'),
  ('KJV', 'GEN', 1, 30, 'And to every beast of the earth, and to every fowl of the air, and to every thing that creepeth upon the earth, wherein there is life, I have given every green herb for meat: and it was so.'),
  ('KJV', 'GEN', 1, 31, 'And God saw every thing that he had made, and, behold, it was very good. And the evening and the morning were the sixth day.'),
  ('KJV', 'GEN', 5, 1, 'This is the book of the generations of Adam. In the day that God created man, in the likeness of God made he him;'),
  ('KJV', 'GEN', 5, 2, 'Male and female created he them; and blessed them, and called their name Adam, in the day when they were created.'),
  ('KJV', 'GEN', 5, 3, 'And Adam lived an hundred and thirty years, and begat a son in his own likeness, after his image; and called his name Seth:'),
  ('KJV', 'GEN', 5, 4, 'And the days of Adam after he had begotten Seth were eight hundred years: and he begat sons and daughters:'),
  ('KJV', 'GEN', 5, 5, 'And all the days that Adam lived were nine hundred and thirty years: and he died.'),
  ('KJV', 'GEN', 5, 6, 'And Seth lived an hundred and five years, and begat Enos:'),
  ('KJV', 'GEN', 5, 7, 'And Seth lived after he begat Enos eight hundred and seven years, and begat sons and daughters:'),
  ('KJV', 'GEN', 5, 8, 'And all the days of Seth were nine hundred and twelve years: and he died.'),
  ('KJV', 'GEN', 5, 9, 'And Enos lived ninety years, and begat Cainan:'),
  ('KJV', 'GEN', 5, 10, 'And Enos lived after he begat Cainan eight hundred and fifteen years, and begat sons and daughters:'),
  ('KJV', 'GEN', 5, 11, 'And all the days of Enos were nine hundred and five years: and he died.'),
  ('KJV', 'GEN', 5, 12, 'And Cainan lived seventy years, and begat Mahalaleel:'),
  ('KJV', 'GEN', 5, 13, 'And Cainan lived after he begat Mahalaleel eight hundred and forty years, and begat sons and daughters:'),
  ('KJV', 'GEN', 5, 14, 'And all the days of Cainan were nine hundred and ten years: and he died.'),
  ('KJV', 'GEN', 5, 15, 'And Mahalaleel lived sixty and five years, and begat Jared:'),
  ('KJV', 'GEN', 5, 16, 'And Mahalaleel lived after he begat Jared eight hundred and thirty years, and begat sons and daughters:'),
  ('KJV', 'GEN', 5, 17, 'And all the days of Mahalaleel were eight hundred ninety and five years: and he died.'),
  ('KJV', 'GEN', 5, 18, 'And Jared lived an hundred sixty and two years, and he begat Enoch:'),
  ('KJV', 'GEN', 5, 19, 'And Jared lived after he begat Enoch eight hundred years, and begat sons and daughters:'),
  ('KJV', 'GEN', 5, 20, 'And all the days of Jared were nine hundred sixty and two years: and he died.'),
  ('KJV', 'GEN', 5, 21, 'And Enoch lived sixty and five years, and begat Methuselah:'),
  ('KJV', 'GEN', 5, 22, 'And Enoch walked with God after he begat Methuselah three hundred years, and begat sons and daughters:'),
  ('KJV', 'GEN', 5, 23, 'And all the days of Enoch were three hundred sixty and five years:'),
  ('KJV', 'GEN', 5, 24, 'And Enoch walked with God: and he was not; for God took him.'),
  ('KJV', 'GEN', 5, 25, 'And Methuselah lived an hundred eighty and seven years, and begat Lamech:'),
  ('KJV', 'GEN', 5, 26, 'And Methuselah lived after he begat Lamech seven hundred eighty and two years, and begat sons and daughters:'),
  ('KJV', 'GEN', 5, 27, 'And all the days of Methuselah were nine hundred sixty and nine years: and he died.'),
  ('KJV', 'GEN', 5, 28, 'And Lamech lived an hundred eighty and two years, and begat a son:'),
  ('KJV', 'GEN', 5, 29, 'And he called his name Noah, saying, This same shall comfort us concerning our work and toil of our hands, because of the ground which the Lord hath cursed.'),
  ('KJV', 'GEN', 5, 30, 'And Lamech lived after he begat Noah five hundred ninety and five years, and begat sons and daughters:'),
  ('KJV', 'GEN', 5, 31, 'And all the days of Lamech were seven hundred seventy and seven years: and he died.'),
  ('KJV', 'GEN', 5, 32, 'And Noah was five hundred years old: and Noah begat Shem, Ham, and Japheth.'),
  ('KJV', 'EXO', 12, 1, 'And the Lord spake unto Moses and Aaron in the land of Egypt, saying,'),
  ('KJV', 'EXO', 12, 2, 'This month shall be unto you the beginning of months: it shall be the first month of the year to you.'),
  ('KJV', 'EXO', 12, 3, 'Speak ye unto all the congregation of Israel, saying, In the tenth day of this month they shall take to them every man a lamb, according to the house of their fathers, a lamb for an house:'),
  ('KJV', 'EXO', 12, 4, 'And if the household be too little for the lamb, let him and his neighbour next unto his house take it according to the number of the souls; every man according to his eating shall make your count for the lamb.'),
  ('KJV', 'EXO', 12, 5, 'Your lamb shall be without blemish, a male of the first year: ye shall take it out from the sheep, or from the goats:'),
  ('KJV', 'EXO', 12, 6, 'And ye shall keep it up until the fourteenth day of the same month: and the whole assembly of the congregation of Israel shall kill it in the evening.'),
  ('KJV', 'EXO', 12, 7, 'And they shall take of the blood, and strike it on the two side posts and on the upper door post of the houses, wherein they shall eat it.'),
  ('KJV', 'EXO', 12, 8, 'And they shall eat the flesh in that night, roast with fire, and unleavened bread; and with bitter herbs they shall eat it.'),
  ('KJV', 'EXO', 12, 9, 'Eat not of it raw, nor sodden at all with water, but roast with fire; his head with his legs, and with the purtenance thereof.'),
  ('KJV', 'EXO', 12, 10, 'And ye shall let nothing of it remain until the morning; and that which remaineth of it until the morning ye shall burn with fire.'),
  ('KJV', 'EXO', 12, 11, 'And thus shall ye eat it; with your loins girded, your shoes on your feet, and your staff in your hand; and ye shall eat it in haste: it is the Lord’s passover.'),
  ('KJV', 'EXO', 12, 12, 'For I will pass through the land of Egypt this night, and will smite all the firstborn in the land of Egypt, both man and beast; and against all the gods of Egypt I will execute judgment: I am the Lord.'),
  ('KJV', 'EXO', 12, 13, 'And the blood shall be to you for a token upon the houses where ye are: and when I see the blood, I will pass over you, and the plague shall not be upon you to destroy you, when I smite the land of Egypt.'),
  ('KJV', 'EXO', 12, 14, 'And this day shall be unto you for a memorial; and ye shall keep it a feast to the Lord throughout your generations; ye shall keep it a feast by an ordinance for ever.'),
  ('KJV', 'EXO', 12, 15, 'Seven days shall ye eat unleavened bread; even the first day ye shall put away leaven out of your houses: for whosoever eateth leavened bread from the first day until the seventh day, that soul shall be cut off from Israel.'),
  ('KJV', 'EXO', 12, 16, 'And in the first day there shall be an holy convocation, and in the seventh day there shall be an holy convocation to you; no manner of work shall be done in them, save that which every man must eat, that only may be done of you.'),
  ('KJV', 'EXO', 12, 17, 'And ye shall observe the feast of unleavened bread; for in this selfsame day have I brought your armies out of the land of Egypt: therefore shall ye observe this day in your generations by an ordinance for ever.'),
  ('KJV', 'EXO', 12, 18, 'In the first month, on the fourteenth day of the month at even, ye shall eat unleavened bread, until the one and twentieth day of the month at even.'),
  ('KJV', 'EXO', 12, 19, 'Seven days shall there be no leaven found in your houses: for whosoever eateth that which is leavened, even that soul shall be cut off from the congregation of Israel, whether he be a stranger, or born in the land.'),
  ('KJV', 'EXO', 12, 20, 'Ye shall eat nothing leavened; in all your habitations shall ye eat unleavened bread.'),
  ('KJV', 'EXO', 12, 21, 'Then Moses called for all the elders of Israel, and said unto them, Draw out and take you a lamb according to your families, and kill the passover.'),
  ('KJV', 'EXO', 12, 22, 'And ye shall take a bunch of hyssop, and dip it in the blood that is in the bason, and strike the lintel and the two side posts with the blood that is in the bason; and none of you shall go out at the door of his house until the morning.'),
  ('KJV', 'EXO', 12, 23, 'For the Lord will pass through to smite the Egyptians; and when he seeth the blood upon the lintel, and on the two side posts, the Lord will pass over the door, and will not suffer the destroyer to come in unto your houses to smite you.'),
  ('KJV', 'EXO', 12, 24, 'And ye shall observe this thing for an ordinance to thee and to thy sons for ever.'),
  ('KJV', 'EXO', 12, 25, 'And it shall come to pass, when ye be come to the land which the Lord will give you, according as he hath promised, that ye shall keep this service.'),
  ('KJV', 'EXO', 12, 26, 'And it shall come to pass, when your children shall say unto you, What mean ye by this service?'),
  ('KJV', 'EXO', 12, 27, 'That ye shall say, It is the sacrifice of the Lord’s passover, who passed over the houses of the children of Israel in Egypt, when he smote the Egyptians, and delivered our houses. And the people bowed the head and worshipped.'),
  ('KJV', 'EXO', 12, 28, 'And the children of Israel went away, and did as the Lord had commanded Moses and Aaron, so did they.'),
  ('KJV', 'EXO', 12, 29, 'And it came to pass, that at midnight the Lord smote all the firstborn in the land of Egypt, from the firstborn of Pharaoh that sat on his throne unto the firstborn of the captive that was in the dungeon; and all the firstborn of cattle.'),
  ('KJV', 'EXO', 12, 30, 'And Pharaoh rose up in the night, he, and all his servants, and all the Egyptians; and there was a great cry in Egypt; for there was not a house where there was not one dead.'),
  ('KJV', 'EXO', 12, 31, 'And he called for Moses and Aaron by night, and said, Rise up, and get you forth from among my people, both ye and the children of Israel; and go, serve the Lord, as ye have said.'),
  ('KJV', 'EXO', 12, 32, 'Also take your flocks and your herds, as ye have said, and be gone; and bless me also.'),
  ('KJV', 'EXO', 12, 33, 'And the Egyptians were urgent upon the people, that they might send them out of the land in haste; for they said, We be all dead men.'),
  ('KJV', 'EXO', 12, 34, 'And the people took their dough before it was leavened, their kneadingtroughs being bound up in their clothes upon their shoulders.'),
  ('KJV', 'EXO', 12, 35, 'And the children of Israel did according to the word of Moses; and they borrowed of the Egyptians jewels of silver, and jewels of gold, and raiment:'),
  ('KJV', 'EXO', 12, 36, 'And the Lord gave the people favour in the sight of the Egyptians, so that they lent unto them such things as they required. And they spoiled the Egyptians.'),
  ('KJV', 'EXO', 12, 37, 'And the children of Israel journeyed from Rameses to Succoth, about six hundred thousand on foot that were men, beside children.'),
  ('KJV', 'EXO', 12, 38, 'And a mixed multitude went up also with them; and flocks, and herds, even very much cattle.'),
  ('KJV', 'EXO', 12, 39, 'And they baked unleavened cakes of the dough which they brought forth out of Egypt, for it was not leavened; because they were thrust out of Egypt, and could not tarry, neither had they prepared for themselves any victual.'),
  ('KJV', 'EXO', 12, 40, 'Now the sojourning of the children of Israel, who dwelt in Egypt, was four hundred and thirty years.'),
  ('KJV', 'EXO', 12, 41, 'And it came to pass at the end of the four hundred and thirty years, even the selfsame day it came to pass, that all the hosts of the Lord went out from the land of Egypt.'),
  ('KJV', 'EXO', 12, 42, 'It is a night to be much observed unto the Lord for bringing them out from the land of Egypt: this is that night of the Lord to be observed of all the children of Israel in their generations.'),
  ('KJV', 'EXO', 12, 43, 'And the Lord said unto Moses and Aaron, This is the ordinance of the passover: There shall no stranger eat thereof:'),
  ('KJV', 'EXO', 12, 44, 'But every man’s servant that is bought for money, when thou hast circumcised him, then shall he eat thereof.'),
  ('KJV', 'EXO', 12, 45, 'A foreigner and an hired servant shall not eat thereof.'),
  ('KJV', 'EXO', 12, 46, 'In one house shall it be eaten; thou shalt not carry forth ought of the flesh abroad out of the house; neither shall ye break a bone thereof.'),
  ('KJV', 'EXO', 12, 47, 'All the congregation of Israel shall keep it.'),
  ('KJV', 'EXO', 12, 48, 'And when a stranger shall sojourn with thee, and will keep the passover to the Lord, let all his males be circumcised, and then let him come near and keep it; and he shall be as one that is born in the land: for no uncircumcised person shall eat thereof.'),
  ('KJV', 'EXO', 12, 49, 'One law shall be to him that is homeborn, and unto the stranger that sojourneth among you.'),
  ('KJV', 'EXO', 12, 50, 'Thus did all the children of Israel; as the Lord commanded Moses and Aaron, so did they.'),
  ('KJV', 'EXO', 12, 51, 'And it came to pass the selfsame day, that the Lord did bring the children of Israel out of the land of Egypt by their armies.'),
  ('KJV', 'EXO', 34, 1, 'And the Lord said unto Moses, Hew thee two tables of stone like unto the first: and I will write upon these tables the words that were in the first tables, which thou brakest.'),
  ('KJV', 'EXO', 34, 2, 'And be ready in the morning, and come up in the morning unto mount Sinai, and present thyself there to me in the top of the mount.'),
  ('KJV', 'EXO', 34, 3, 'And no man shall come up with thee, neither let any man be seen throughout all the mount; neither let the flocks nor herds feed before that mount.'),
  ('KJV', 'EXO', 34, 4, 'And he hewed two tables of stone like unto the first; and Moses rose up early in the morning, and went up unto mount Sinai, as the Lord had commanded him, and took in his hand the two tables of stone.'),
  ('KJV', 'EXO', 34, 5, 'And the Lord descended in the cloud, and stood with him there, and proclaimed the name of the Lord.'),
  ('KJV', 'EXO', 34, 6, 'And the Lord passed by before him, and proclaimed, The Lord, The Lord God, merciful and gracious, longsuffering, and abundant in goodness and truth,'),
  ('KJV', 'EXO', 34, 7, 'Keeping mercy for thousands, forgiving iniquity and transgression and sin, and that will by no means clear the guilty; visiting the iniquity of the fathers upon the children, and upon the children’s children, unto the third and to the fourth generation.'),
  ('KJV', 'EXO', 34, 8, 'And Moses made haste, and bowed his head toward the earth, and worshipped.'),
  ('KJV', 'EXO', 34, 9, 'And he said, If now I have found grace in thy sight, O Lord, let my Lord, I pray thee, go among us; for it is a stiffnecked people; and pardon our iniquity and our sin, and take us for thine inheritance.'),
  ('KJV', 'EXO', 34, 10, 'And he said, Behold, I make a covenant: before all thy people I will do marvels, such as have not been done in all the earth, nor in any nation: and all the people among which thou art shall see the work of the Lord: for it is a terrible thing that I will do with thee.'),
  ('KJV', 'EXO', 34, 11, 'Observe thou that which I command thee this day: behold, I drive out before thee the Amorite, and the Canaanite, and the Hittite, and the Perizzite, and the Hivite, and the Jebusite.'),
  ('KJV', 'EXO', 34, 12, 'Take heed to thyself, lest thou make a covenant with the inhabitants of the land whither thou goest, lest it be for a snare in the midst of thee:'),
  ('KJV', 'EXO', 34, 13, 'But ye shall destroy their altars, break their images, and cut down their groves:'),
  ('KJV', 'EXO', 34, 14, 'For thou shalt worship no other god: for the Lord, whose name is Jealous, is a jealous God:'),
  ('KJV', 'EXO', 34, 15, 'Lest thou make a covenant with the inhabitants of the land, and they go a whoring after their gods, and do sacrifice unto their gods, and one call thee, and thou eat of his sacrifice;'),
  ('KJV', 'EXO', 34, 16, 'And thou take of their daughters unto thy sons, and their daughters go a whoring after their gods, and make thy sons go a whoring after their gods.'),
  ('KJV', 'EXO', 34, 17, 'Thou shalt make thee no molten gods.'),
  ('KJV', 'EXO', 34, 18, 'The feast of unleavened bread shalt thou keep. Seven days thou shalt eat unleavened bread, as I commanded thee, in the time of the month Abib: for in the month Abib thou camest out from Egypt.'),
  ('KJV', 'EXO', 34, 19, 'All that openeth the matrix is mine; and every firstling among thy cattle, whether ox or sheep, that is male.'),
  ('KJV', 'EXO', 34, 20, 'But the firstling of an ass thou shalt redeem with a lamb: and if thou redeem him not, then shalt thou break his neck. All the firstborn of thy sons thou shalt redeem. And none shall appear before me empty.'),
  ('KJV', 'EXO', 34, 21, 'Six days thou shalt work, but on the seventh day thou shalt rest: in earing time and in harvest thou shalt rest.'),
  ('KJV', 'EXO', 34, 22, 'And thou shalt observe the feast of weeks, of the firstfruits of wheat harvest, and the feast of ingathering at the year’s end.'),
  ('KJV', 'EXO', 34, 23, 'Thrice in the year shall all your men children appear before the Lord God, the God of Israel.'),
  ('KJV', 'EXO', 34, 24, 'For I will cast out the nations before thee, and enlarge thy borders: neither shall any man desire thy land, when thou shalt go up to appear before the Lord thy God thrice in the year.'),
  ('KJV', 'EXO', 34, 25, 'Thou shalt not offer the blood of my sacrifice with leaven; neither shall the sacrifice of the feast of the passover be left unto the morning.'),
  ('KJV', 'EXO', 34, 26, 'The first of the firstfruits of thy land thou shalt bring unto the house of the Lord thy God. Thou shalt not seethe a kid in his mother’s milk.'),
  ('KJV', 'EXO', 34, 27, 'And the Lord said unto Moses, Write thou these words: for after the tenor of these words I have made a covenant with thee and with Israel.'),
  ('KJV', 'EXO', 34, 28, 'And he was there with the Lord forty days and forty nights; he did neither eat bread, nor drink water. And he wrote upon the tables the words of the covenant, the ten commandments.'),
  ('KJV', 'EXO', 34, 29, 'And it came to pass, when Moses came down from mount Sinai with the two tables of testimony in Moses’ hand, when he came down from the mount, that Moses wist not that the skin of his face shone while he talked with him.'),
  ('KJV', 'EXO', 34, 30, 'And when Aaron and all the children of Israel saw Moses, behold, the skin of his face shone; and they were afraid to come nigh him.'),
  ('KJV', 'EXO', 34, 31, 'And Moses called unto them; and Aaron and all the rulers of the congregation returned unto him: and Moses talked with them.'),
  ('KJV', 'EXO', 34, 32, 'And afterward all the children of Israel came nigh: and he gave them in commandment all that the Lord had spoken with him in mount Sinai.'),
  ('KJV', 'EXO', 34, 33, 'And till Moses had done speaking with them, he put a vail on his face.'),
  ('KJV', 'EXO', 34, 34, 'But when Moses went in before the Lord to speak with him, he took the vail off, until he came out. And he came out, and spake unto the children of Israel that which he was commanded.'),
  ('KJV', 'EXO', 34, 35, 'And the children of Israel saw the face of Moses, that the skin of Moses’ face shone: and Moses put the vail upon his face again, until he went in to speak with him.'),
  ('KJV', 'EXO', 40, 1, 'And the Lord spake unto Moses, saying,'),
  ('KJV', 'EXO', 40, 2, 'On the first day of the first month shalt thou set up the tabernacle of the tent of the congregation.'),
  ('KJV', 'EXO', 40, 3, 'And thou shalt put therein the ark of the testimony, and cover the ark with the vail.'),
  ('KJV', 'EXO', 40, 4, 'And thou shalt bring in the table, and set in order the things that are to be set in order upon it; and thou shalt bring in the candlestick, and light the lamps thereof.'),
  ('KJV', 'EXO', 40, 5, 'And thou shalt set the altar of gold for the incense before the ark of the testimony, and put the hanging of the door to the tabernacle.'),
  ('KJV', 'EXO', 40, 6, 'And thou shalt set the altar of the burnt offering before the door of the tabernacle of the tent of the congregation.'),
  ('KJV', 'EXO', 40, 7, 'And thou shalt set the laver between the tent of the congregation and the altar, and shalt put water therein.'),
  ('KJV', 'EXO', 40, 8, 'And thou shalt set up the court round about, and hang up the hanging at the court gate.'),
  ('KJV', 'EXO', 40, 9, 'And thou shalt take the anointing oil, and anoint the tabernacle, and all that is therein, and shalt hallow it, and all the vessels thereof: and it shall be holy.'),
  ('KJV', 'EXO', 40, 10, 'And thou shalt anoint the altar of the burnt offering, and all his vessels, and sanctify the altar: and it shall be an altar most holy.'),
  ('KJV', 'EXO', 40, 11, 'And thou shalt anoint the laver and his foot, and sanctify it.'),
  ('KJV', 'EXO', 40, 12, 'And thou shalt bring Aaron and his sons unto the door of the tabernacle of the congregation, and wash them with water.'),
  ('KJV', 'EXO', 40, 13, 'And thou shalt put upon Aaron the holy garments, and anoint him, and sanctify him; that he may minister unto me in the priest’s office.'),
  ('KJV', 'EXO', 40, 14, 'And thou shalt bring his sons, and clothe them with coats:'),
  ('KJV', 'EXO', 40, 15, 'And thou shalt anoint them, as thou didst anoint their father, that they may minister unto me in the priest’s office: for their anointing shall surely be an everlasting priesthood throughout their generations.'),
  ('KJV', 'EXO', 40, 16, 'Thus did Moses: according to all that the Lord commanded him, so did he.'),
  ('KJV', 'EXO', 40, 17, 'And it came to pass in the first month in the second year, on the first day of the month, that the tabernacle was reared up.'),
  ('KJV', 'EXO', 40, 18, 'And Moses reared up the tabernacle, and fastened his sockets, and set up the boards thereof, and put in the bars thereof, and reared up his pillars.'),
  ('KJV', 'EXO', 40, 19, 'And he spread abroad the tent over the tabernacle, and put the covering of the tent above upon it; as the Lord commanded Moses.'),
  ('KJV', 'EXO', 40, 20, 'And he took and put the testimony into the ark, and set the staves on the ark, and put the mercy seat above upon the ark:'),
  ('KJV', 'EXO', 40, 21, 'And he brought the ark into the tabernacle, and set up the vail of the covering, and covered the ark of the testimony; as the Lord commanded Moses.'),
  ('KJV', 'EXO', 40, 22, 'And he put the table in the tent of the congregation, upon the side of the tabernacle northward, without the vail.'),
  ('KJV', 'EXO', 40, 23, 'And he set the bread in order upon it before the Lord; as the Lord had commanded Moses.'),
  ('KJV', 'EXO', 40, 24, 'And he put the candlestick in the tent of the congregation, over against the table, on the side of the tabernacle southward.'),
  ('KJV', 'EXO', 40, 25, 'And he lighted the lamps before the Lord; as the Lord commanded Moses.'),
  ('KJV', 'EXO', 40, 26, 'And he put the golden altar in the tent of the congregation before the vail:'),
  ('KJV', 'EXO', 40, 27, 'And he burnt sweet incense thereon; as the Lord commanded Moses.'),
  ('KJV', 'EXO', 40, 28, 'And he set up the hanging at the door of the tabernacle.'),
  ('KJV', 'EXO', 40, 29, 'And he put the altar of burnt offering by the door of the tabernacle of the tent of the congregation, and offered upon it the burnt offering and the meat offering; as the Lord commanded Moses.'),
  ('KJV', 'EXO', 40, 30, 'And he set the laver between the tent of the congregation and the altar, and put water there, to wash withal.'),
  ('KJV', 'EXO', 40, 31, 'And Moses and Aaron and his sons washed their hands and their feet thereat:'),
  ('KJV', 'EXO', 40, 32, 'When they went into the tent of the congregation, and when they came near unto the altar, they washed; as the Lord commanded Moses.'),
  ('KJV', 'EXO', 40, 33, 'And he reared up the court round about the tabernacle and the altar, and set up the hanging of the court gate. So Moses finished the work.'),
  ('KJV', 'EXO', 40, 34, 'Then a cloud covered the tent of the congregation, and the glory of the Lord filled the tabernacle.'),
  ('KJV', 'EXO', 40, 35, 'And Moses was not able to enter into the tent of the congregation, because the cloud abode thereon, and the glory of the Lord filled the tabernacle.'),
  ('KJV', 'EXO', 40, 36, 'And when the cloud was taken up from over the tabernacle, the children of Israel went onward in all their journeys:'),
  ('KJV', 'EXO', 40, 37, 'But if the cloud were not taken up, then they journeyed not till the day that it was taken up.'),
  ('KJV', 'EXO', 40, 38, 'For the cloud of the Lord was upon the tabernacle by day, and fire was on it by night, in the sight of all the house of Israel, throughout all their journeys.'),
  ('KJV', 'PSA', 8, 1, 'To the chief Musician upon Gittith, A Psalm of David. O Lord our Lord, how excellent is thy name in all the earth! who hast set thy glory above the heavens.'),
  ('KJV', 'PSA', 8, 2, 'Out of the mouth of babes and sucklings hast thou ordained strength because of thine enemies, that thou mightest still the enemy and the avenger.'),
  ('KJV', 'PSA', 8, 3, 'When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained;'),
  ('KJV', 'PSA', 8, 4, 'What is man, that thou art mindful of him? and the son of man, that thou visitest him?'),
  ('KJV', 'PSA', 8, 5, 'For thou hast made him a little lower than the angels, and hast crowned him with glory and honour.'),
  ('KJV', 'PSA', 8, 6, 'Thou madest him to have dominion over the works of thy hands; thou hast put all things under his feet:'),
  ('KJV', 'PSA', 8, 7, 'All sheep and oxen, yea, and the beasts of the field;'),
  ('KJV', 'PSA', 8, 8, 'The fowl of the air, and the fish of the sea, and whatsoever passeth through the paths of the seas.'),
  ('KJV', 'PSA', 8, 9, 'O Lord our Lord, how excellent is thy name in all the earth!'),
  ('KJV', 'PSA', 23, 1, 'A Psalm of David. The Lord is my shepherd; I shall not want.'),
  ('KJV', 'PSA', 23, 2, 'He maketh me to lie down in green pastures: he leadeth me beside the still waters.'),
  ('KJV', 'PSA', 23, 3, 'He restoreth my soul: he leadeth me in the paths of righteousness for his name’s sake.'),
  ('KJV', 'PSA', 23, 4, 'Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.'),
  ('KJV', 'PSA', 23, 5, 'Thou preparest a table before me in the presence of mine enemies: thou anointest my head with oil; my cup runneth over.'),
  ('KJV', 'PSA', 23, 6, 'Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the Lord for ever.'),
  ('KJV', 'PSA', 27, 1, 'A Psalm of David. The Lord is my light and my salvation; whom shall I fear? the Lord is the strength of my life; of whom shall I be afraid?'),
  ('KJV', 'PSA', 27, 2, 'When the wicked, even mine enemies and my foes, came upon me to eat up my flesh, they stumbled and fell.'),
  ('KJV', 'PSA', 27, 3, 'Though an host should encamp against me, my heart shall not fear: though war should rise against me, in this will I be confident.'),
  ('KJV', 'PSA', 27, 4, 'One thing have I desired of the Lord, that will I seek after; that I may dwell in the house of the Lord all the days of my life, to behold the beauty of the Lord, and to enquire in his temple.'),
  ('KJV', 'PSA', 27, 5, 'For in the time of trouble he shall hide me in his pavilion: in the secret of his tabernacle shall he hide me; he shall set me up upon a rock.'),
  ('KJV', 'PSA', 27, 6, 'And now shall mine head be lifted up above mine enemies round about me: therefore will I offer in his tabernacle sacrifices of joy; I will sing, yea, I will sing praises unto the Lord.'),
  ('KJV', 'PSA', 27, 7, 'Hear, O Lord, when I cry with my voice: have mercy also upon me, and answer me.'),
  ('KJV', 'PSA', 27, 8, 'When thou saidst, Seek ye my face; my heart said unto thee, Thy face, Lord, will I seek.'),
  ('KJV', 'PSA', 27, 9, 'Hide not thy face far from me; put not thy servant away in anger: thou hast been my help; leave me not, neither forsake me, O God of my salvation.'),
  ('KJV', 'PSA', 27, 10, 'When my father and my mother forsake me, then the Lord will take me up.'),
  ('KJV', 'PSA', 27, 11, 'Teach me thy way, O Lord, and lead me in a plain path, because of mine enemies.'),
  ('KJV', 'PSA', 27, 12, 'Deliver me not over unto the will of mine enemies: for false witnesses are risen up against me, and such as breathe out cruelty.'),
  ('KJV', 'PSA', 27, 13, 'I had fainted, unless I had believed to see the goodness of the Lord in the land of the living.'),
  ('KJV', 'PSA', 27, 14, 'Wait on the Lord: be of good courage, and he shall strengthen thine heart: wait, I say, on the Lord.'),
  ('KJV', 'PSA', 33, 1, 'Rejoice in the Lord, O ye righteous: for praise is comely for the upright.'),
  ('KJV', 'PSA', 33, 2, 'Praise the Lord with harp: sing unto him with the psaltery and an instrument of ten strings.'),
  ('KJV', 'PSA', 33, 3, 'Sing unto him a new song; play skilfully with a loud noise.'),
  ('KJV', 'PSA', 33, 4, 'For the word of the Lord is right; and all his works are done in truth.'),
  ('KJV', 'PSA', 33, 5, 'He loveth righteousness and judgment: the earth is full of the goodness of the Lord.'),
  ('KJV', 'PSA', 33, 6, 'By the word of the Lord were the heavens made; and all the host of them by the breath of his mouth.'),
  ('KJV', 'PSA', 33, 7, 'He gathereth the waters of the sea together as an heap: he layeth up the depth in storehouses.'),
  ('KJV', 'PSA', 33, 8, 'Let all the earth fear the Lord: let all the inhabitants of the world stand in awe of him.'),
  ('KJV', 'PSA', 33, 9, 'For he spake, and it was done; he commanded, and it stood fast.'),
  ('KJV', 'PSA', 33, 10, 'The Lord bringeth the counsel of the heathen to nought: he maketh the devices of the people of none effect.'),
  ('KJV', 'PSA', 33, 11, 'The counsel of the Lord standeth for ever, the thoughts of his heart to all generations.'),
  ('KJV', 'PSA', 33, 12, 'Blessed is the nation whose God is the Lord; and the people whom he hath chosen for his own inheritance.'),
  ('KJV', 'PSA', 33, 13, 'The Lord looketh from heaven; he beholdeth all the sons of men.'),
  ('KJV', 'PSA', 33, 14, 'From the place of his habitation he looketh upon all the inhabitants of the earth.'),
  ('KJV', 'PSA', 33, 15, 'He fashioneth their hearts alike; he considereth all their works.'),
  ('KJV', 'PSA', 33, 16, 'There is no king saved by the multitude of an host: a mighty man is not delivered by much strength.'),
  ('KJV', 'PSA', 33, 17, 'An horse is a vain thing for safety: neither shall he deliver any by his great strength.'),
  ('KJV', 'PSA', 33, 18, 'Behold, the eye of the Lord is upon them that fear him, upon them that hope in his mercy;'),
  ('KJV', 'PSA', 33, 19, 'To deliver their soul from death, and to keep them alive in famine.'),
  ('KJV', 'PSA', 33, 20, 'Our soul waiteth for the Lord: he is our help and our shield.'),
  ('KJV', 'PSA', 33, 21, 'For our heart shall rejoice in him, because we have trusted in his holy name.'),
  ('KJV', 'PSA', 33, 22, 'Let thy mercy, O Lord, be upon us, according as we hope in thee.'),
  ('KJV', 'ISA', 6, 1, 'In the year that king Uzziah died I saw also the Lord sitting upon a throne, high and lifted up, and his train filled the temple.'),
  ('KJV', 'ISA', 6, 2, 'Above it stood the seraphims: each one had six wings; with twain he covered his face, and with twain he covered his feet, and with twain he did fly.'),
  ('KJV', 'ISA', 6, 3, 'And one cried unto another, and said, Holy, holy, holy, is the Lord of hosts: the whole earth is full of his glory.'),
  ('KJV', 'ISA', 6, 4, 'And the posts of the door moved at the voice of him that cried, and the house was filled with smoke.'),
  ('KJV', 'ISA', 6, 5, 'Then said I, Woe is me! for I am undone; because I am a man of unclean lips, and I dwell in the midst of a people of unclean lips: for mine eyes have seen the King, the Lord of hosts.'),
  ('KJV', 'ISA', 6, 6, 'Then flew one of the seraphims unto me, having a live coal in his hand, which he had taken with the tongs from off the altar:'),
  ('KJV', 'ISA', 6, 7, 'And he laid it upon my mouth, and said, Lo, this hath touched thy lips; and thine iniquity is taken away, and thy sin purged.'),
  ('KJV', 'ISA', 6, 8, 'Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me.'),
  ('KJV', 'ISA', 6, 9, 'And he said, Go, and tell this people, Hear ye indeed, but understand not; and see ye indeed, but perceive not.'),
  ('KJV', 'ISA', 6, 10, 'Make the heart of this people fat, and make their ears heavy, and shut their eyes; lest they see with their eyes, and hear with their ears, and understand with their heart, and convert, and be healed.'),
  ('KJV', 'ISA', 6, 11, 'Then said I, Lord, how long? And he answered, Until the cities be wasted without inhabitant, and the houses without man, and the land be utterly desolate,'),
  ('KJV', 'ISA', 6, 12, 'And the Lord have removed men far away, and there be a great forsaking in the midst of the land.'),
  ('KJV', 'ISA', 6, 13, 'But yet in it shall be a tenth, and it shall return, and shall be eaten: as a teil tree, and as an oak, whose substance is in them, when they cast their leaves: so the holy seed shall be the substance thereof.'),
  ('KJV', 'ISA', 40, 1, 'Comfort ye, comfort ye my people, saith your God.'),
  ('KJV', 'ISA', 40, 2, 'Speak ye comfortably to Jerusalem, and cry unto her, that her warfare is accomplished, that her iniquity is pardoned: for she hath received of the Lord’s hand double for all her sins.'),
  ('KJV', 'ISA', 40, 3, 'The voice of him that crieth in the wilderness, Prepare ye the way of the Lord, make straight in the desert a highway for our God.'),
  ('KJV', 'ISA', 40, 4, 'Every valley shall be exalted, and every mountain and hill shall be made low: and the crooked shall be made straight, and the rough places plain:'),
  ('KJV', 'ISA', 40, 5, 'And the glory of the Lord shall be revealed, and all flesh shall see it together: for the mouth of the Lord hath spoken it.'),
  ('KJV', 'ISA', 40, 6, 'The voice said, Cry. And he said, What shall I cry? All flesh is grass, and all the goodliness thereof is as the flower of the field:'),
  ('KJV', 'ISA', 40, 7, 'The grass withereth, the flower fadeth: because the spirit of the Lord bloweth upon it: surely the people is grass.'),
  ('KJV', 'ISA', 40, 8, 'The grass withereth, the flower fadeth: but the word of our God shall stand for ever.'),
  ('KJV', 'ISA', 40, 9, 'O Zion, that bringest good tidings, get thee up into the high mountain; O Jerusalem, that bringest good tidings, lift up thy voice with strength; lift it up, be not afraid; say unto the cities of Judah, Behold your God!'),
  ('KJV', 'ISA', 40, 10, 'Behold, the Lord God will come with strong hand, and his arm shall rule for him: behold, his reward is with him, and his work before him.'),
  ('KJV', 'ISA', 40, 11, 'He shall feed his flock like a shepherd: he shall gather the lambs with his arm, and carry them in his bosom, and shall gently lead those that are with young.'),
  ('KJV', 'ISA', 40, 12, 'Who hath measured the waters in the hollow of his hand, and meted out heaven with the span, and comprehended the dust of the earth in a measure, and weighed the mountains in scales, and the hills in a balance?'),
  ('KJV', 'ISA', 40, 13, 'Who hath directed the Spirit of the Lord, or being his counsellor hath taught him?'),
  ('KJV', 'ISA', 40, 14, 'With whom took he counsel, and who instructed him, and taught him in the path of judgment, and taught him knowledge, and shewed to him the way of understanding?'),
  ('KJV', 'ISA', 40, 15, 'Behold, the nations are as a drop of a bucket, and are counted as the small dust of the balance: behold, he taketh up the isles as a very little thing.'),
  ('KJV', 'ISA', 40, 16, 'And Lebanon is not sufficient to burn, nor the beasts thereof sufficient for a burnt offering.'),
  ('KJV', 'ISA', 40, 17, 'All nations before him are as nothing; and they are counted to him less than nothing, and vanity.'),
  ('KJV', 'ISA', 40, 18, 'To whom then will ye liken God? or what likeness will ye compare unto him?'),
  ('KJV', 'ISA', 40, 19, 'The workman melteth a graven image, and the goldsmith spreadeth it over with gold, and casteth silver chains.'),
  ('KJV', 'ISA', 40, 20, 'He that is so impoverished that he hath no oblation chooseth a tree that will not rot; he seeketh unto him a cunning workman to prepare a graven image, that shall not be moved.'),
  ('KJV', 'ISA', 40, 21, 'Have ye not known? have ye not heard? hath it not been told you from the beginning? have ye not understood from the foundations of the earth?'),
  ('KJV', 'ISA', 40, 22, 'It is he that sitteth upon the circle of the earth, and the inhabitants thereof are as grasshoppers; that stretcheth out the heavens as a curtain, and spreadeth them out as a tent to dwell in:'),
  ('KJV', 'ISA', 40, 23, 'That bringeth the princes to nothing; he maketh the judges of the earth as vanity.'),
  ('KJV', 'ISA', 40, 24, 'Yea, they shall not be planted; yea, they shall not be sown: yea, their stock shall not take root in the earth: and he shall also blow upon them, and they shall wither, and the whirlwind shall take them away as stubble.'),
  ('KJV', 'ISA', 40, 25, 'To whom then will ye liken me, or shall I be equal? saith the Holy One.'),
  ('KJV', 'ISA', 40, 26, 'Lift up your eyes on high, and behold who hath created these things, that bringeth out their host by number: he calleth them all by names by the greatness of his might, for that he is strong in power; not one faileth.'),
  ('KJV', 'ISA', 40, 27, 'Why sayest thou, O Jacob, and speakest, O Israel, My way is hid from the Lord, and my judgment is passed over from my God?'),
  ('KJV', 'ISA', 40, 28, 'Hast thou not known? hast thou not heard, that the everlasting God, the Lord, the Creator of the ends of the earth, fainteth not, neither is weary? there is no searching of his understanding.'),
  ('KJV', 'ISA', 40, 29, 'He giveth power to the faint; and to them that have no might he increaseth strength.'),
  ('KJV', 'ISA', 40, 30, 'Even the youths shall faint and be weary, and the young men shall utterly fall:'),
  ('KJV', 'ISA', 40, 31, 'But they that wait upon the Lord shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.'),
  ('KJV', 'ISA', 41, 1, 'Keep silence before me, O islands; and let the people renew their strength: let them come near; then let them speak: let us come near together to judgment.'),
  ('KJV', 'ISA', 41, 2, 'Who raised up the righteous man from the east, called him to his foot, gave the nations before him, and made him rule over kings? he gave them as the dust to his sword, and as driven stubble to his bow.'),
  ('KJV', 'ISA', 41, 3, 'He pursued them, and passed safely; even by the way that he had not gone with his feet.'),
  ('KJV', 'ISA', 41, 4, 'Who hath wrought and done it, calling the generations from the beginning? I the Lord, the first, and with the last; I am he.'),
  ('KJV', 'ISA', 41, 5, 'The isles saw it, and feared; the ends of the earth were afraid, drew near, and came.'),
  ('KJV', 'ISA', 41, 6, 'They helped every one his neighbour; and every one said to his brother, Be of good courage.'),
  ('KJV', 'ISA', 41, 7, 'So the carpenter encouraged the goldsmith, and he that smootheth with the hammer him that smote the anvil, saying, It is ready for the sodering: and he fastened it with nails, that it should not be moved.'),
  ('KJV', 'ISA', 41, 8, 'But thou, Israel, art my servant, Jacob whom I have chosen, the seed of Abraham my friend.'),
  ('KJV', 'ISA', 41, 9, 'Thou whom I have taken from the ends of the earth, and called thee from the chief men thereof, and said unto thee, Thou art my servant; I have chosen thee, and not cast thee away.'),
  ('KJV', 'ISA', 41, 10, 'Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.'),
  ('KJV', 'ISA', 41, 11, 'Behold, all they that were incensed against thee shall be ashamed and confounded: they shall be as nothing; and they that strive with thee shall perish.'),
  ('KJV', 'ISA', 41, 12, 'Thou shalt seek them, and shalt not find them, even them that contended with thee: they that war against thee shall be as nothing, and as a thing of nought.'),
  ('KJV', 'ISA', 41, 13, 'For I the Lord thy God will hold thy right hand, saying unto thee, Fear not; I will help thee.'),
  ('KJV', 'ISA', 41, 14, 'Fear not, thou worm Jacob, and ye men of Israel; I will help thee, saith the Lord, and thy redeemer, the Holy One of Israel.'),
  ('KJV', 'ISA', 41, 15, 'Behold, I will make thee a new sharp threshing instrument having teeth: thou shalt thresh the mountains, and beat them small, and shalt make the hills as chaff.'),
  ('KJV', 'ISA', 41, 16, 'Thou shalt fan them, and the wind shall carry them away, and the whirlwind shall scatter them: and thou shalt rejoice in the Lord, and shalt glory in the Holy One of Israel.'),
  ('KJV', 'ISA', 41, 17, 'When the poor and needy seek water, and there is none, and their tongue faileth for thirst, I the Lord will hear them, I the God of Israel will not forsake them.'),
  ('KJV', 'ISA', 41, 18, 'I will open rivers in high places, and fountains in the midst of the valleys: I will make the wilderness a pool of water, and the dry land springs of water.'),
  ('KJV', 'ISA', 41, 19, 'I will plant in the wilderness the cedar, the shittah tree, and the myrtle, and the oil tree; I will set in the desert the fir tree, and the pine, and the box tree together:'),
  ('KJV', 'ISA', 41, 20, 'That they may see, and know, and consider, and understand together, that the hand of the Lord hath done this, and the Holy One of Israel hath created it.'),
  ('KJV', 'ISA', 41, 21, 'Produce your cause, saith the Lord; bring forth your strong reasons, saith the King of Jacob.'),
  ('KJV', 'ISA', 41, 22, 'Let them bring them forth, and shew us what shall happen: let them shew the former things, what they be, that we may consider them, and know the latter end of them; or declare us things for to come.'),
  ('KJV', 'ISA', 41, 23, 'Shew the things that are to come hereafter, that we may know that ye are gods: yea, do good, or do evil, that we may be dismayed, and behold it together.'),
  ('KJV', 'ISA', 41, 24, 'Behold, ye are of nothing, and your work of nought: an abomination is he that chooseth you.'),
  ('KJV', 'ISA', 41, 25, 'I have raised up one from the north, and he shall come: from the rising of the sun shall he call upon my name: and he shall come upon princes as upon morter, and as the potter treadeth clay.'),
  ('KJV', 'ISA', 41, 26, 'Who hath declared from the beginning, that we may know? and beforetime, that we may say, He is righteous? yea, there is none that sheweth, yea, there is none that declareth, yea, there is none that heareth your words.'),
  ('KJV', 'ISA', 41, 27, 'The first shall say to Zion, Behold, behold them: and I will give to Jerusalem one that bringeth good tidings.'),
  ('KJV', 'ISA', 41, 28, 'For I beheld, and there was no man; even among them, and there was no counsellor, that, when I asked of them, could answer a word.'),
  ('KJV', 'ISA', 41, 29, 'Behold, they are all vanity; their works are nothing: their molten images are wind and confusion.'),
  ('KJV', 'ISA', 53, 1, 'Who hath believed our report? and to whom is the arm of the Lord revealed?'),
  ('KJV', 'ISA', 53, 2, 'For he shall grow up before him as a tender plant, and as a root out of a dry ground: he hath no form nor comeliness; and when we shall see him, there is no beauty that we should desire him.'),
  ('KJV', 'ISA', 53, 3, 'He is despised and rejected of men; a man of sorrows, and acquainted with grief: and we hid as it were our faces from him; he was despised, and we esteemed him not.'),
  ('KJV', 'ISA', 53, 4, 'Surely he hath borne our griefs, and carried our sorrows: yet we did esteem him stricken, smitten of God, and afflicted.'),
  ('KJV', 'ISA', 53, 5, 'But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.'),
  ('KJV', 'ISA', 53, 6, 'All we like sheep have gone astray; we have turned every one to his own way; and the Lord hath laid on him the iniquity of us all.'),
  ('KJV', 'ISA', 53, 7, 'He was oppressed, and he was afflicted, yet he opened not his mouth: he is brought as a lamb to the slaughter, and as a sheep before her shearers is dumb, so he openeth not his mouth.'),
  ('KJV', 'ISA', 53, 8, 'He was taken from prison and from judgment: and who shall declare his generation? for he was cut off out of the land of the living: for the transgression of my people was he stricken.'),
  ('KJV', 'ISA', 53, 9, 'And he made his grave with the wicked, and with the rich in his death; because he had done no violence, neither was any deceit in his mouth.'),
  ('KJV', 'ISA', 53, 10, 'Yet it pleased the Lord to bruise him; he hath put him to grief: when thou shalt make his soul an offering for sin, he shall see his seed, he shall prolong his days, and the pleasure of the Lord shall prosper in his hand.'),
  ('KJV', 'ISA', 53, 11, 'He shall see of the travail of his soul, and shall be satisfied: by his knowledge shall my righteous servant justify many; for he shall bear their iniquities.'),
  ('KJV', 'ISA', 53, 12, 'Therefore will I divide him a portion with the great, and he shall divide the spoil with the strong; because he hath poured out his soul unto death: and he was numbered with the transgressors; and he bare the sin of many, and made intercession for the transgressors.'),
  ('KJV', 'EZK', 34, 1, 'And the word of the Lord came unto me, saying,'),
  ('KJV', 'EZK', 34, 2, 'Son of man, prophesy against the shepherds of Israel, prophesy, and say unto them, Thus saith the Lord God unto the shepherds; Woe be to the shepherds of Israel that do feed themselves! should not the shepherds feed the flocks?'),
  ('KJV', 'EZK', 34, 3, 'Ye eat the fat, and ye clothe you with the wool, ye kill them that are fed: but ye feed not the flock.'),
  ('KJV', 'EZK', 34, 4, 'The diseased have ye not strengthened, neither have ye healed that which was sick, neither have ye bound up that which was broken, neither have ye brought again that which was driven away, neither have ye sought that which was lost; but with force and with cruelty have ye ruled them.'),
  ('KJV', 'EZK', 34, 5, 'And they were scattered, because there is no shepherd: and they became meat to all the beasts of the field, when they were scattered.'),
  ('KJV', 'EZK', 34, 6, 'My sheep wandered through all the mountains, and upon every high hill: yea, my flock was scattered upon all the face of the earth, and none did search or seek after them.'),
  ('KJV', 'EZK', 34, 7, 'Therefore, ye shepherds, hear the word of the Lord;'),
  ('KJV', 'EZK', 34, 8, 'As I live, saith the Lord God, surely because my flock became a prey, and my flock became meat to every beast of the field, because there was no shepherd, neither did my shepherds search for my flock, but the shepherds fed themselves, and fed not my flock;'),
  ('KJV', 'EZK', 34, 9, 'Therefore, O ye shepherds, hear the word of the Lord;'),
  ('KJV', 'EZK', 34, 10, 'Thus saith the Lord God; Behold, I am against the shepherds; and I will require my flock at their hand, and cause them to cease from feeding the flock; neither shall the shepherds feed themselves any more; for I will deliver my flock from their mouth, that they may not be meat for them.'),
  ('KJV', 'EZK', 34, 11, 'For thus saith the Lord God; Behold, I, even I, will both search my sheep, and seek them out.'),
  ('KJV', 'EZK', 34, 12, 'As a shepherd seeketh out his flock in the day that he is among his sheep that are scattered; so will I seek out my sheep, and will deliver them out of all places where they have been scattered in the cloudy and dark day.'),
  ('KJV', 'EZK', 34, 13, 'And I will bring them out from the people, and gather them from the countries, and will bring them to their own land, and feed them upon the mountains of Israel by the rivers, and in all the inhabited places of the country.'),
  ('KJV', 'EZK', 34, 14, 'I will feed them in a good pasture, and upon the high mountains of Israel shall their fold be: there shall they lie in a good fold, and in a fat pasture shall they feed upon the mountains of Israel.'),
  ('KJV', 'EZK', 34, 15, 'I will feed my flock, and I will cause them to lie down, saith the Lord God.'),
  ('KJV', 'EZK', 34, 16, 'I will seek that which was lost, and bring again that which was driven away, and will bind up that which was broken, and will strengthen that which was sick: but I will destroy the fat and the strong; I will feed them with judgment.'),
  ('KJV', 'EZK', 34, 17, 'And as for you, O my flock, thus saith the Lord God; Behold, I judge between cattle and cattle, between the rams and the he goats.'),
  ('KJV', 'EZK', 34, 18, 'Seemeth it a small thing unto you to have eaten up the good pasture, but ye must tread down with your feet the residue of your pastures? and to have drunk of the deep waters, but ye must foul the residue with your feet?'),
  ('KJV', 'EZK', 34, 19, 'And as for my flock, they eat that which ye have trodden with your feet; and they drink that which ye have fouled with your feet.'),
  ('KJV', 'EZK', 34, 20, 'Therefore thus saith the Lord God unto them; Behold, I, even I, will judge between the fat cattle and between the lean cattle.'),
  ('KJV', 'EZK', 34, 21, 'Because ye have thrust with side and with shoulder, and pushed all the diseased with your horns, till ye have scattered them abroad;'),
  ('KJV', 'EZK', 34, 22, 'Therefore will I save my flock, and they shall no more be a prey; and I will judge between cattle and cattle.'),
  ('KJV', 'EZK', 34, 23, 'And I will set up one shepherd over them, and he shall feed them, even my servant David; he shall feed them, and he shall be their shepherd.'),
  ('KJV', 'EZK', 34, 24, 'And I the Lord will be their God, and my servant David a prince among them; I the Lord have spoken it.'),
  ('KJV', 'EZK', 34, 25, 'And I will make with them a covenant of peace, and will cause the evil beasts to cease out of the land: and they shall dwell safely in the wilderness, and sleep in the woods.'),
  ('KJV', 'EZK', 34, 26, 'And I will make them and the places round about my hill a blessing; and I will cause the shower to come down in his season; there shall be showers of blessing.'),
  ('KJV', 'EZK', 34, 27, 'And the tree of the field shall yield her fruit, and the earth shall yield her increase, and they shall be safe in their land, and shall know that I am the Lord, when I have broken the bands of their yoke, and delivered them out of the hand of those that served themselves of them.'),
  ('KJV', 'EZK', 34, 28, 'And they shall no more be a prey to the heathen, neither shall the beast of the land devour them; but they shall dwell safely, and none shall make them afraid.'),
  ('KJV', 'EZK', 34, 29, 'And I will raise up for them a plant of renown, and they shall be no more consumed with hunger in the land, neither bear the shame of the heathen any more.'),
  ('KJV', 'EZK', 34, 30, 'Thus shall they know that I the Lord their God am with them, and that they, even the house of Israel, are my people, saith the Lord God.'),
  ('KJV', 'EZK', 34, 31, 'And ye my flock, the flock of my pasture, are men, and I am your God, saith the Lord God.'),
  ('KJV', 'MAT', 13, 1, 'The same day went Jesus out of the house, and sat by the sea side.'),
  ('KJV', 'MAT', 13, 2, 'And great multitudes were gathered together unto him, so that he went into a ship, and sat; and the whole multitude stood on the shore.'),
  ('KJV', 'MAT', 13, 3, 'And he spake many things unto them in parables, saying, Behold, a sower went forth to sow;'),
  ('KJV', 'MAT', 13, 4, 'And when he sowed, some seeds fell by the way side, and the fowls came and devoured them up:'),
  ('KJV', 'MAT', 13, 5, 'Some fell upon stony places, where they had not much earth: and forthwith they sprung up, because they had no deepness of earth:'),
  ('KJV', 'MAT', 13, 6, 'And when the sun was up, they were scorched; and because they had no root, they withered away.'),
  ('KJV', 'MAT', 13, 7, 'And some fell among thorns; and the thorns sprung up, and choked them:'),
  ('KJV', 'MAT', 13, 8, 'But other fell into good ground, and brought forth fruit, some an hundredfold, some sixtyfold, some thirtyfold.'),
  ('KJV', 'MAT', 13, 9, 'Who hath ears to hear, let him hear.'),
  ('KJV', 'MAT', 13, 10, 'And the disciples came, and said unto him, Why speakest thou unto them in parables?'),
  ('KJV', 'MAT', 13, 11, 'He answered and said unto them, Because it is given unto you to know the mysteries of the kingdom of heaven, but to them it is not given.'),
  ('KJV', 'MAT', 13, 12, 'For whosoever hath, to him shall be given, and he shall have more abundance: but whosoever hath not, from him shall be taken away even that he hath.'),
  ('KJV', 'MAT', 13, 13, 'Therefore speak I to them in parables: because they seeing see not; and hearing they hear not, neither do they understand.'),
  ('KJV', 'MAT', 13, 14, 'And in them is fulfilled the prophecy of Esaias, which saith, By hearing ye shall hear, and shall not understand; and seeing ye shall see, and shall not perceive:'),
  ('KJV', 'MAT', 13, 15, 'For this people’s heart is waxed gross, and their ears are dull of hearing, and their eyes they have closed; lest at any time they should see with their eyes, and hear with their ears, and should understand with their heart, and should be converted, and I should heal them.'),
  ('KJV', 'MAT', 13, 16, 'But blessed are your eyes, for they see: and your ears, for they hear.'),
  ('KJV', 'MAT', 13, 17, 'For verily I say unto you, That many prophets and righteous men have desired to see those things which ye see, and have not seen them; and to hear those things which ye hear, and have not heard them.'),
  ('KJV', 'MAT', 13, 18, 'Hear ye therefore the parable of the sower.'),
  ('KJV', 'MAT', 13, 19, 'When any one heareth the word of the kingdom, and understandeth it not, then cometh the wicked one, and catcheth away that which was sown in his heart. This is he which received seed by the way side.'),
  ('KJV', 'MAT', 13, 20, 'But he that received the seed into stony places, the same is he that heareth the word, and anon with joy receiveth it;'),
  ('KJV', 'MAT', 13, 21, 'Yet hath he not root in himself, but dureth for a while: for when tribulation or persecution ariseth because of the word, by and by he is offended.'),
  ('KJV', 'MAT', 13, 22, 'He also that received seed among the thorns is he that heareth the word; and the care of this world, and the deceitfulness of riches, choke the word, and he becometh unfruitful.'),
  ('KJV', 'MAT', 13, 23, 'But he that received seed into the good ground is he that heareth the word, and understandeth it; which also beareth fruit, and bringeth forth, some an hundredfold, some sixty, some thirty.'),
  ('KJV', 'MAT', 13, 24, 'Another parable put he forth unto them, saying, The kingdom of heaven is likened unto a man which sowed good seed in his field:'),
  ('KJV', 'MAT', 13, 25, 'But while men slept, his enemy came and sowed tares among the wheat, and went his way.'),
  ('KJV', 'MAT', 13, 26, 'But when the blade was sprung up, and brought forth fruit, then appeared the tares also.'),
  ('KJV', 'MAT', 13, 27, 'So the servants of the householder came and said unto him, Sir, didst not thou sow good seed in thy field? from whence then hath it tares?'),
  ('KJV', 'MAT', 13, 28, 'He said unto them, An enemy hath done this. The servants said unto him, Wilt thou then that we go and gather them up?'),
  ('KJV', 'MAT', 13, 29, 'But he said, Nay; lest while ye gather up the tares, ye root up also the wheat with them.'),
  ('KJV', 'MAT', 13, 30, 'Let both grow together until the harvest: and in the time of harvest I will say to the reapers, Gather ye together first the tares, and bind them in bundles to burn them: but gather the wheat into my barn.'),
  ('KJV', 'MAT', 13, 31, 'Another parable put he forth unto them, saying, The kingdom of heaven is like to a grain of mustard seed, which a man took, and sowed in his field:'),
  ('KJV', 'MAT', 13, 32, 'Which indeed is the least of all seeds: but when it is grown, it is the greatest among herbs, and becometh a tree, so that the birds of the air come and lodge in the branches thereof.'),
  ('KJV', 'MAT', 13, 33, 'Another parable spake he unto them; The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened.'),
  ('KJV', 'MAT', 13, 34, 'All these things spake Jesus unto the multitude in parables; and without a parable spake he not unto them:'),
  ('KJV', 'MAT', 13, 35, 'That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables; I will utter things which have been kept secret from the foundation of the world.'),
  ('KJV', 'MAT', 13, 36, 'Then Jesus sent the multitude away, and went into the house: and his disciples came unto him, saying, Declare unto us the parable of the tares of the field.'),
  ('KJV', 'MAT', 13, 37, 'He answered and said unto them, He that soweth the good seed is the Son of man;'),
  ('KJV', 'MAT', 13, 38, 'The field is the world; the good seed are the children of the kingdom; but the tares are the children of the wicked one;'),
  ('KJV', 'MAT', 13, 39, 'The enemy that sowed them is the devil; the harvest is the end of the world; and the reapers are the angels.'),
  ('KJV', 'MAT', 13, 40, 'As therefore the tares are gathered and burned in the fire; so shall it be in the end of this world.'),
  ('KJV', 'MAT', 13, 41, 'The Son of man shall send forth his angels, and they shall gather out of his kingdom all things that offend, and them which do iniquity;'),
  ('KJV', 'MAT', 13, 42, 'And shall cast them into a furnace of fire: there shall be wailing and gnashing of teeth.'),
  ('KJV', 'MAT', 13, 43, 'Then shall the righteous shine forth as the sun in the kingdom of their Father. Who hath ears to hear, let him hear.'),
  ('KJV', 'MAT', 13, 44, 'Again, the kingdom of heaven is like unto treasure hid in a field; the which when a man hath found, he hideth, and for joy thereof goeth and selleth all that he hath, and buyeth that field.'),
  ('KJV', 'MAT', 13, 45, 'Again, the kingdom of heaven is like unto a merchant man, seeking goodly pearls:'),
  ('KJV', 'MAT', 13, 46, 'Who, when he had found one pearl of great price, went and sold all that he had, and bought it.'),
  ('KJV', 'MAT', 13, 47, 'Again, the kingdom of heaven is like unto a net, that was cast into the sea, and gathered of every kind:'),
  ('KJV', 'MAT', 13, 48, 'Which, when it was full, they drew to shore, and sat down, and gathered the good into vessels, but cast the bad away.'),
  ('KJV', 'MAT', 13, 49, 'So shall it be at the end of the world: the angels shall come forth, and sever the wicked from among the just,'),
  ('KJV', 'MAT', 13, 50, 'And shall cast them into the furnace of fire: there shall be wailing and gnashing of teeth.'),
  ('KJV', 'MAT', 13, 51, 'Jesus saith unto them, Have ye understood all these things? They say unto him, Yea, Lord.'),
  ('KJV', 'MAT', 13, 52, 'Then said he unto them, Therefore every scribe which is instructed unto the kingdom of heaven is like unto a man that is an householder, which bringeth forth out of his treasure things new and old.'),
  ('KJV', 'MAT', 13, 53, 'And it came to pass, that when Jesus had finished these parables, he departed thence.'),
  ('KJV', 'MAT', 13, 54, 'And when he was come into his own country, he taught them in their synagogue, insomuch that they were astonished, and said, Whence hath this man this wisdom, and these mighty works?'),
  ('KJV', 'MAT', 13, 55, 'Is not this the carpenter’s son? is not his mother called Mary? and his brethren, James, and Joses, and Simon, and Judas?'),
  ('KJV', 'MAT', 13, 56, 'And his sisters, are they not all with us? Whence then hath this man all these things?'),
  ('KJV', 'MAT', 13, 57, 'And they were offended in him. But Jesus said unto them, A prophet is not without honour, save in his own country, and in his own house.'),
  ('KJV', 'MAT', 13, 58, 'And he did not many mighty works there because of their unbelief.'),
  ('KJV', 'JHN', 1, 1, 'In the beginning was the Word, and the Word was with God, and the Word was God.'),
  ('KJV', 'JHN', 1, 2, 'The same was in the beginning with God.'),
  ('KJV', 'JHN', 1, 3, 'All things were made by him; and without him was not any thing made that was made.'),
  ('KJV', 'JHN', 1, 4, 'In him was life; and the life was the light of men.'),
  ('KJV', 'JHN', 1, 5, 'And the light shineth in darkness; and the darkness comprehended it not.'),
  ('KJV', 'JHN', 1, 6, 'There was a man sent from God, whose name was John.'),
  ('KJV', 'JHN', 1, 7, 'The same came for a witness, to bear witness of the Light, that all men through him might believe.'),
  ('KJV', 'JHN', 1, 8, 'He was not that Light, but was sent to bear witness of that Light.'),
  ('KJV', 'JHN', 1, 9, 'That was the true Light, which lighteth every man that cometh into the world.'),
  ('KJV', 'JHN', 1, 10, 'He was in the world, and the world was made by him, and the world knew him not.'),
  ('KJV', 'JHN', 1, 11, 'He came unto his own, and his own received him not.'),
  ('KJV', 'JHN', 1, 12, 'But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:'),
  ('KJV', 'JHN', 1, 13, 'Which were born, not of blood, nor of the will of the flesh, nor of the will of man, but of God.'),
  ('KJV', 'JHN', 1, 14, 'And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.'),
  ('KJV', 'JHN', 1, 15, 'John bare witness of him, and cried, saying, This was he of whom I spake, He that cometh after me is preferred before me: for he was before me.'),
  ('KJV', 'JHN', 1, 16, 'And of his fulness have all we received, and grace for grace.'),
  ('KJV', 'JHN', 1, 17, 'For the law was given by Moses, but grace and truth came by Jesus Christ.'),
  ('KJV', 'JHN', 1, 18, 'No man hath seen God at any time; the only begotten Son, which is in the bosom of the Father, he hath declared him.'),
  ('KJV', 'JHN', 1, 19, 'And this is the record of John, when the Jews sent priests and Levites from Jerusalem to ask him, Who art thou?'),
  ('KJV', 'JHN', 1, 20, 'And he confessed, and denied not; but confessed, I am not the Christ.'),
  ('KJV', 'JHN', 1, 21, 'And they asked him, What then? Art thou Elias? And he saith, I am not. Art thou that prophet? And he answered, No.'),
  ('KJV', 'JHN', 1, 22, 'Then said they unto him, Who art thou? that we may give an answer to them that sent us. What sayest thou of thyself?'),
  ('KJV', 'JHN', 1, 23, 'He said, I am the voice of one crying in the wilderness, Make straight the way of the Lord, as said the prophet Esaias.'),
  ('KJV', 'JHN', 1, 24, 'And they which were sent were of the Pharisees.'),
  ('KJV', 'JHN', 1, 25, 'And they asked him, and said unto him, Why baptizest thou then, if thou be not that Christ, nor Elias, neither that prophet?'),
  ('KJV', 'JHN', 1, 26, 'John answered them, saying, I baptize with water: but there standeth one among you, whom ye know not;'),
  ('KJV', 'JHN', 1, 27, 'He it is, who coming after me is preferred before me, whose shoe’s latchet I am not worthy to unloose.'),
  ('KJV', 'JHN', 1, 28, 'These things were done in Bethabara beyond Jordan, where John was baptizing.'),
  ('KJV', 'JHN', 1, 29, 'The next day John seeth Jesus coming unto him, and saith, Behold the Lamb of God, which taketh away the sin of the world.'),
  ('KJV', 'JHN', 1, 30, 'This is he of whom I said, After me cometh a man which is preferred before me: for he was before me.'),
  ('KJV', 'JHN', 1, 31, 'And I knew him not: but that he should be made manifest to Israel, therefore am I come baptizing with water.'),
  ('KJV', 'JHN', 1, 32, 'And John bare record, saying, I saw the Spirit descending from heaven like a dove, and it abode upon him.'),
  ('KJV', 'JHN', 1, 33, 'And I knew him not: but he that sent me to baptize with water, the same said unto me, Upon whom thou shalt see the Spirit descending, and remaining on him, the same is he which baptizeth with the Holy Ghost.'),
  ('KJV', 'JHN', 1, 34, 'And I saw, and bare record that this is the Son of God.'),
  ('KJV', 'JHN', 1, 35, 'Again the next day after John stood, and two of his disciples;'),
  ('KJV', 'JHN', 1, 36, 'And looking upon Jesus as he walked, he saith, Behold the Lamb of God!'),
  ('KJV', 'JHN', 1, 37, 'And the two disciples heard him speak, and they followed Jesus.'),
  ('KJV', 'JHN', 1, 38, 'Then Jesus turned, and saw them following, and saith unto them, What seek ye? They said unto him, Rabbi, (which is to say, being interpreted, Master,) where dwellest thou?'),
  ('KJV', 'JHN', 1, 39, 'He saith unto them, Come and see. They came and saw where he dwelt, and abode with him that day: for it was about the tenth hour.'),
  ('KJV', 'JHN', 1, 40, 'One of the two which heard John speak, and followed him, was Andrew, Simon Peter’s brother.'),
  ('KJV', 'JHN', 1, 41, 'He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ.'),
  ('KJV', 'JHN', 1, 42, 'And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone.'),
  ('KJV', 'JHN', 1, 43, 'The day following Jesus would go forth into Galilee, and findeth Philip, and saith unto him, Follow me.'),
  ('KJV', 'JHN', 1, 44, 'Now Philip was of Bethsaida, the city of Andrew and Peter.'),
  ('KJV', 'JHN', 1, 45, 'Philip findeth Nathanael, and saith unto him, We have found him, of whom Moses in the law, and the prophets, did write, Jesus of Nazareth, the son of Joseph.'),
  ('KJV', 'JHN', 1, 46, 'And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see.'),
  ('KJV', 'JHN', 1, 47, 'Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!'),
  ('KJV', 'JHN', 1, 48, 'Nathanael saith unto him, Whence knowest thou me? Jesus answered and said unto him, Before that Philip called thee, when thou wast under the fig tree, I saw thee.'),
  ('KJV', 'JHN', 1, 49, 'Nathanael answered and saith unto him, Rabbi, thou art the Son of God; thou art the King of Israel.'),
  ('KJV', 'JHN', 1, 50, 'Jesus answered and said unto him, Because I said unto thee, I saw thee under the fig tree, believest thou? thou shalt see greater things than these.'),
  ('KJV', 'JHN', 1, 51, 'And he saith unto him, Verily, verily, I say unto you, Hereafter ye shall see heaven open, and the angels of God ascending and descending upon the Son of man.'),
  ('KJV', 'JHN', 4, 1, 'When therefore the Lord knew how the Pharisees had heard that Jesus made and baptized more disciples than John,'),
  ('KJV', 'JHN', 4, 2, '(Though Jesus himself baptized not, but his disciples,)'),
  ('KJV', 'JHN', 4, 3, 'He left Judea, and departed again into Galilee.'),
  ('KJV', 'JHN', 4, 4, 'And he must needs go through Samaria.'),
  ('KJV', 'JHN', 4, 5, 'Then cometh he to a city of Samaria, which is called Sychar, near to the parcel of ground that Jacob gave to his son Joseph.'),
  ('KJV', 'JHN', 4, 6, 'Now Jacob’s well was there. Jesus therefore, being wearied with his journey, sat thus on the well: and it was about the sixth hour.'),
  ('KJV', 'JHN', 4, 7, 'There cometh a woman of Samaria to draw water: Jesus saith unto her, Give me to drink.'),
  ('KJV', 'JHN', 4, 8, '(For his disciples were gone away unto the city to buy meat.)'),
  ('KJV', 'JHN', 4, 9, 'Then saith the woman of Samaria unto him, How is it that thou, being a Jew, askest drink of me, which am a woman of Samaria? for the Jews have no dealings with the Samaritans.'),
  ('KJV', 'JHN', 4, 10, 'Jesus answered and said unto her, If thou knewest the gift of God, and who it is that saith to thee, Give me to drink; thou wouldest have asked of him, and he would have given thee living water.'),
  ('KJV', 'JHN', 4, 11, 'The woman saith unto him, Sir, thou hast nothing to draw with, and the well is deep: from whence then hast thou that living water?'),
  ('KJV', 'JHN', 4, 12, 'Art thou greater than our father Jacob, which gave us the well, and drank thereof himself, and his children, and his cattle?'),
  ('KJV', 'JHN', 4, 13, 'Jesus answered and said unto her, Whosoever drinketh of this water shall thirst again:'),
  ('KJV', 'JHN', 4, 14, 'But whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life.'),
  ('KJV', 'JHN', 4, 15, 'The woman saith unto him, Sir, give me this water, that I thirst not, neither come hither to draw.'),
  ('KJV', 'JHN', 4, 16, 'Jesus saith unto her, Go, call thy husband, and come hither.'),
  ('KJV', 'JHN', 4, 17, 'The woman answered and said, I have no husband. Jesus said unto her, Thou hast well said, I have no husband:'),
  ('KJV', 'JHN', 4, 18, 'For thou hast had five husbands; and he whom thou now hast is not thy husband: in that saidst thou truly.'),
  ('KJV', 'JHN', 4, 19, 'The woman saith unto him, Sir, I perceive that thou art a prophet.'),
  ('KJV', 'JHN', 4, 20, 'Our fathers worshipped in this mountain; and ye say, that in Jerusalem is the place where men ought to worship.'),
  ('KJV', 'JHN', 4, 21, 'Jesus saith unto her, Woman, believe me, the hour cometh, when ye shall neither in this mountain, nor yet at Jerusalem, worship the Father.'),
  ('KJV', 'JHN', 4, 22, 'Ye worship ye know not what: we know what we worship: for salvation is of the Jews.'),
  ('KJV', 'JHN', 4, 23, 'But the hour cometh, and now is, when the true worshippers shall worship the Father in spirit and in truth: for the Father seeketh such to worship him.'),
  ('KJV', 'JHN', 4, 24, 'God is a Spirit: and they that worship him must worship him in spirit and in truth.'),
  ('KJV', 'JHN', 4, 25, 'The woman saith unto him, I know that Messias cometh, which is called Christ: when he is come, he will tell us all things.'),
  ('KJV', 'JHN', 4, 26, 'Jesus saith unto her, I that speak unto thee am he.'),
  ('KJV', 'JHN', 4, 27, 'And upon this came his disciples, and marvelled that he talked with the woman: yet no man said, What seekest thou? or, Why talkest thou with her?'),
  ('KJV', 'JHN', 4, 28, 'The woman then left her waterpot, and went her way into the city, and saith to the men,'),
  ('KJV', 'JHN', 4, 29, 'Come, see a man, which told me all things that ever I did: is not this the Christ?'),
  ('KJV', 'JHN', 4, 30, 'Then they went out of the city, and came unto him.'),
  ('KJV', 'JHN', 4, 31, 'In the mean while his disciples prayed him, saying, Master, eat.'),
  ('KJV', 'JHN', 4, 32, 'But he said unto them, I have meat to eat that ye know not of.'),
  ('KJV', 'JHN', 4, 33, 'Therefore said the disciples one to another, Hath any man brought him ought to eat?'),
  ('KJV', 'JHN', 4, 34, 'Jesus saith unto them, My meat is to do the will of him that sent me, and to finish his work.'),
  ('KJV', 'JHN', 4, 35, 'Say not ye, There are yet four months, and then cometh harvest? behold, I say unto you, Lift up your eyes, and look on the fields; for they are white already to harvest.'),
  ('KJV', 'JHN', 4, 36, 'And he that reapeth receiveth wages, and gathereth fruit unto life eternal: that both he that soweth and he that reapeth may rejoice together.'),
  ('KJV', 'JHN', 4, 37, 'And herein is that saying true, One soweth, and another reapeth.'),
  ('KJV', 'JHN', 4, 38, 'I sent you to reap that whereon ye bestowed no labour: other men laboured, and ye are entered into their labours.'),
  ('KJV', 'JHN', 4, 39, 'And many of the Samaritans of that city believed on him for the saying of the woman, which testified, He told me all that ever I did.'),
  ('KJV', 'JHN', 4, 40, 'So when the Samaritans were come unto him, they besought him that he would tarry with them: and he abode there two days.'),
  ('KJV', 'JHN', 4, 41, 'And many more believed because of his own word;'),
  ('KJV', 'JHN', 4, 42, 'And said unto the woman, Now we believe, not because of thy saying: for we have heard him ourselves, and know that this is indeed the Christ, the Saviour of the world.'),
  ('KJV', 'JHN', 4, 43, 'Now after two days he departed thence, and went into Galilee.'),
  ('KJV', 'JHN', 4, 44, 'For Jesus himself testified, that a prophet hath no honour in his own country.'),
  ('KJV', 'JHN', 4, 45, 'Then when he was come into Galilee, the Galileans received him, having seen all the things that he did at Jerusalem at the feast: for they also went unto the feast.'),
  ('KJV', 'JHN', 4, 46, 'So Jesus came again into Cana of Galilee, where he made the water wine. And there was a certain nobleman, whose son was sick at Capernaum.'),
  ('KJV', 'JHN', 4, 47, 'When he heard that Jesus was come out of Judea into Galilee, he went unto him, and besought him that he would come down, and heal his son: for he was at the point of death.'),
  ('KJV', 'JHN', 4, 48, 'Then said Jesus unto him, Except ye see signs and wonders, ye will not believe.'),
  ('KJV', 'JHN', 4, 49, 'The nobleman saith unto him, Sir, come down ere my child die.'),
  ('KJV', 'JHN', 4, 50, 'Jesus saith unto him, Go thy way; thy son liveth. And the man believed the word that Jesus had spoken unto him, and he went his way.'),
  ('KJV', 'JHN', 4, 51, 'And as he was now going down, his servants met him, and told him, saying, Thy son liveth.'),
  ('KJV', 'JHN', 4, 52, 'Then enquired he of them the hour when he began to amend. And they said unto him, Yesterday at the seventh hour the fever left him.'),
  ('KJV', 'JHN', 4, 53, 'So the father knew that it was at the same hour, in the which Jesus said unto him, Thy son liveth: and himself believed, and his whole house.'),
  ('KJV', 'JHN', 4, 54, 'This is again the second miracle that Jesus did, when he was come out of Judea into Galilee.'),
  ('KJV', 'JHN', 5, 1, 'After this there was a feast of the Jews; and Jesus went up to Jerusalem.'),
  ('KJV', 'JHN', 5, 2, 'Now there is at Jerusalem by the sheep market a pool, which is called in the Hebrew tongue Bethesda, having five porches.'),
  ('KJV', 'JHN', 5, 3, 'In these lay a great multitude of impotent folk, of blind, halt, withered, waiting for the moving of the water.'),
  ('KJV', 'JHN', 5, 4, 'For an angel went down at a certain season into the pool, and troubled the water: whosoever then first after the troubling of the water stepped in was made whole of whatsoever disease he had.'),
  ('KJV', 'JHN', 5, 5, 'And a certain man was there, which had an infirmity thirty and eight years.'),
  ('KJV', 'JHN', 5, 6, 'When Jesus saw him lie, and knew that he had been now a long time in that case, he saith unto him, Wilt thou be made whole?'),
  ('KJV', 'JHN', 5, 7, 'The impotent man answered him, Sir, I have no man, when the water is troubled, to put me into the pool: but while I am coming, another steppeth down before me.'),
  ('KJV', 'JHN', 5, 8, 'Jesus saith unto him, Rise, take up thy bed, and walk.'),
  ('KJV', 'JHN', 5, 9, 'And immediately the man was made whole, and took up his bed, and walked: and on the same day was the sabbath.'),
  ('KJV', 'JHN', 5, 10, 'The Jews therefore said unto him that was cured, It is the sabbath day: it is not lawful for thee to carry thy bed.'),
  ('KJV', 'JHN', 5, 11, 'He answered them, He that made me whole, the same said unto me, Take up thy bed, and walk.'),
  ('KJV', 'JHN', 5, 12, 'Then asked they him, What man is that which said unto thee, Take up thy bed, and walk?'),
  ('KJV', 'JHN', 5, 13, 'And he that was healed wist not who it was: for Jesus had conveyed himself away, a multitude being in that place.'),
  ('KJV', 'JHN', 5, 14, 'Afterward Jesus findeth him in the temple, and said unto him, Behold, thou art made whole: sin no more, lest a worse thing come unto thee.'),
  ('KJV', 'JHN', 5, 15, 'The man departed, and told the Jews that it was Jesus, which had made him whole.'),
  ('KJV', 'JHN', 5, 16, 'And therefore did the Jews persecute Jesus, and sought to slay him, because he had done these things on the sabbath day.'),
  ('KJV', 'JHN', 5, 17, 'But Jesus answered them, My Father worketh hitherto, and I work.'),
  ('KJV', 'JHN', 5, 18, 'Therefore the Jews sought the more to kill him, because he not only had broken the sabbath, but said also that God was his Father, making himself equal with God.'),
  ('KJV', 'JHN', 5, 19, 'Then answered Jesus and said unto them, Verily, verily, I say unto you, The Son can do nothing of himself, but what he seeth the Father do: for what things soever he doeth, these also doeth the Son likewise.'),
  ('KJV', 'JHN', 5, 20, 'For the Father loveth the Son, and sheweth him all things that himself doeth: and he will shew him greater works than these, that ye may marvel.'),
  ('KJV', 'JHN', 5, 21, 'For as the Father raiseth up the dead, and quickeneth them; even so the Son quickeneth whom he will.'),
  ('KJV', 'JHN', 5, 22, 'For the Father judgeth no man, but hath committed all judgment unto the Son:'),
  ('KJV', 'JHN', 5, 23, 'That all men should honour the Son, even as they honour the Father. He that honoureth not the Son honoureth not the Father which hath sent him.'),
  ('KJV', 'JHN', 5, 24, 'Verily, verily, I say unto you, He that heareth my word, and believeth on him that sent me, hath everlasting life, and shall not come into condemnation; but is passed from death unto life.'),
  ('KJV', 'JHN', 5, 25, 'Verily, verily, I say unto you, The hour is coming, and now is, when the dead shall hear the voice of the Son of God: and they that hear shall live.'),
  ('KJV', 'JHN', 5, 26, 'For as the Father hath life in himself; so hath he given to the Son to have life in himself;'),
  ('KJV', 'JHN', 5, 27, 'And hath given him authority to execute judgment also, because he is the Son of man.'),
  ('KJV', 'JHN', 5, 28, 'Marvel not at this: for the hour is coming, in the which all that are in the graves shall hear his voice,'),
  ('KJV', 'JHN', 5, 29, 'And shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation.'),
  ('KJV', 'JHN', 5, 30, 'I can of mine own self do nothing: as I hear, I judge: and my judgment is just; because I seek not mine own will, but the will of the Father which hath sent me.'),
  ('KJV', 'JHN', 5, 31, 'If I bear witness of myself, my witness is not true.'),
  ('KJV', 'JHN', 5, 32, 'There is another that beareth witness of me; and I know that the witness which he witnesseth of me is true.'),
  ('KJV', 'JHN', 5, 33, 'Ye sent unto John, and he bare witness unto the truth.'),
  ('KJV', 'JHN', 5, 34, 'But I receive not testimony from man: but these things I say, that ye might be saved.'),
  ('KJV', 'JHN', 5, 35, 'He was a burning and a shining light: and ye were willing for a season to rejoice in his light.'),
  ('KJV', 'JHN', 5, 36, 'But I have greater witness than that of John: for the works which the Father hath given me to finish, the same works that I do, bear witness of me, that the Father hath sent me.'),
  ('KJV', 'JHN', 5, 37, 'And the Father himself, which hath sent me, hath borne witness of me. Ye have neither heard his voice at any time, nor seen his shape.'),
  ('KJV', 'JHN', 5, 38, 'And ye have not his word abiding in you: for whom he hath sent, him ye believe not.'),
  ('KJV', 'JHN', 5, 39, 'Search the scriptures; for in them ye think ye have eternal life: and they are they which testify of me.'),
  ('KJV', 'JHN', 5, 40, 'And ye will not come to me, that ye might have life.'),
  ('KJV', 'JHN', 5, 41, 'I receive not honour from men.'),
  ('KJV', 'JHN', 5, 42, 'But I know you, that ye have not the love of God in you.'),
  ('KJV', 'JHN', 5, 43, 'I am come in my Father’s name, and ye receive me not: if another shall come in his own name, him ye will receive.'),
  ('KJV', 'JHN', 5, 44, 'How can ye believe, which receive honour one of another, and seek not the honour that cometh from God only?'),
  ('KJV', 'JHN', 5, 45, 'Do not think that I will accuse you to the Father: there is one that accuseth you, even Moses, in whom ye trust.'),
  ('KJV', 'JHN', 5, 46, 'For had ye believed Moses, ye would have believed me: for he wrote of me.'),
  ('KJV', 'JHN', 5, 47, 'But if ye believe not his writings, how shall ye believe my words?'),
  ('KJV', 'JHN', 8, 1, 'Jesus went unto the mount of Olives.'),
  ('KJV', 'JHN', 8, 2, 'And early in the morning he came again into the temple, and all the people came unto him; and he sat down, and taught them.'),
  ('KJV', 'JHN', 8, 3, 'And the scribes and Pharisees brought unto him a woman taken in adultery; and when they had set her in the midst,'),
  ('KJV', 'JHN', 8, 4, 'They say unto him, Master, this woman was taken in adultery, in the very act.'),
  ('KJV', 'JHN', 8, 5, 'Now Moses in the law commanded us, that such should be stoned: but what sayest thou?'),
  ('KJV', 'JHN', 8, 6, 'This they said, tempting him, that they might have to accuse him. But Jesus stooped down, and with his finger wrote on the ground, as though he heard them not.'),
  ('KJV', 'JHN', 8, 7, 'So when they continued asking him, he lifted up himself, and said unto them, He that is without sin among you, let him first cast a stone at her.'),
  ('KJV', 'JHN', 8, 8, 'And again he stooped down, and wrote on the ground.'),
  ('KJV', 'JHN', 8, 9, 'And they which heard it, being convicted by their own conscience, went out one by one, beginning at the eldest, even unto the last: and Jesus was left alone, and the woman standing in the midst.'),
  ('KJV', 'JHN', 8, 10, 'When Jesus had lifted up himself, and saw none but the woman, he said unto her, Woman, where are those thine accusers? hath no man condemned thee?'),
  ('KJV', 'JHN', 8, 11, 'She said, No man, Lord. And Jesus said unto her, Neither do I condemn thee: go, and sin no more.'),
  ('KJV', 'JHN', 8, 12, 'Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.'),
  ('KJV', 'JHN', 8, 13, 'The Pharisees therefore said unto him, Thou bearest record of thyself; thy record is not true.'),
  ('KJV', 'JHN', 8, 14, 'Jesus answered and said unto them, Though I bear record of myself, yet my record is true: for I know whence I came, and whither I go; but ye cannot tell whence I come, and whither I go.'),
  ('KJV', 'JHN', 8, 15, 'Ye judge after the flesh; I judge no man.'),
  ('KJV', 'JHN', 8, 16, 'And yet if I judge, my judgment is true: for I am not alone, but I and the Father that sent me.'),
  ('KJV', 'JHN', 8, 17, 'It is also written in your law, that the testimony of two men is true.'),
  ('KJV', 'JHN', 8, 18, 'I am one that bear witness of myself, and the Father that sent me beareth witness of me.'),
  ('KJV', 'JHN', 8, 19, 'Then said they unto him, Where is thy Father? Jesus answered, Ye neither know me, nor my Father: if ye had known me, ye should have known my Father also.'),
  ('KJV', 'JHN', 8, 20, 'These words spake Jesus in the treasury, as he taught in the temple: and no man laid hands on him; for his hour was not yet come.'),
  ('KJV', 'JHN', 8, 21, 'Then said Jesus again unto them, I go my way, and ye shall seek me, and shall die in your sins: whither I go, ye cannot come.'),
  ('KJV', 'JHN', 8, 22, 'Then said the Jews, Will he kill himself? because he saith, Whither I go, ye cannot come.'),
  ('KJV', 'JHN', 8, 23, 'And he said unto them, Ye are from beneath; I am from above: ye are of this world; I am not of this world.'),
  ('KJV', 'JHN', 8, 24, 'I said therefore unto you, that ye shall die in your sins: for if ye believe not that I am he, ye shall die in your sins.'),
  ('KJV', 'JHN', 8, 25, 'Then said they unto him, Who art thou? And Jesus saith unto them, Even the same that I said unto you from the beginning.'),
  ('KJV', 'JHN', 8, 26, 'I have many things to say and to judge of you: but he that sent me is true; and I speak to the world those things which I have heard of him.'),
  ('KJV', 'JHN', 8, 27, 'They understood not that he spake to them of the Father.'),
  ('KJV', 'JHN', 8, 28, 'Then said Jesus unto them, When ye have lifted up the Son of man, then shall ye know that I am he, and that I do nothing of myself; but as my Father hath taught me, I speak these things.'),
  ('KJV', 'JHN', 8, 29, 'And he that sent me is with me: the Father hath not left me alone; for I do always those things that please him.'),
  ('KJV', 'JHN', 8, 30, 'As he spake these words, many believed on him.'),
  ('KJV', 'JHN', 8, 31, 'Then said Jesus to those Jews which believed on him, If ye continue in my word, then are ye my disciples indeed;'),
  ('KJV', 'JHN', 8, 32, 'And ye shall know the truth, and the truth shall make you free.'),
  ('KJV', 'JHN', 8, 33, 'They answered him, We be Abraham’s seed, and were never in bondage to any man: how sayest thou, Ye shall be made free?'),
  ('KJV', 'JHN', 8, 34, 'Jesus answered them, Verily, verily, I say unto you, Whosoever committeth sin is the servant of sin.'),
  ('KJV', 'JHN', 8, 35, 'And the servant abideth not in the house for ever: but the Son abideth ever.'),
  ('KJV', 'JHN', 8, 36, 'If the Son therefore shall make you free, ye shall be free indeed.'),
  ('KJV', 'JHN', 8, 37, 'I know that ye are Abraham’s seed; but ye seek to kill me, because my word hath no place in you.'),
  ('KJV', 'JHN', 8, 38, 'I speak that which I have seen with my Father: and ye do that which ye have seen with your father.'),
  ('KJV', 'JHN', 8, 39, 'They answered and said unto him, Abraham is our father. Jesus saith unto them, If ye were Abraham’s children, ye would do the works of Abraham.'),
  ('KJV', 'JHN', 8, 40, 'But now ye seek to kill me, a man that hath told you the truth, which I have heard of God: this did not Abraham.'),
  ('KJV', 'JHN', 8, 41, 'Ye do the deeds of your father. Then said they to him, We be not born of fornication; we have one Father, even God.'),
  ('KJV', 'JHN', 8, 42, 'Jesus said unto them, If God were your Father, ye would love me: for I proceeded forth and came from God; neither came I of myself, but he sent me.'),
  ('KJV', 'JHN', 8, 43, 'Why do ye not understand my speech? even because ye cannot hear my word.'),
  ('KJV', 'JHN', 8, 44, 'Ye are of your father the devil, and the lusts of your father ye will do. He was a murderer from the beginning, and abode not in the truth, because there is no truth in him. When he speaketh a lie, he speaketh of his own: for he is a liar, and the father of it.'),
  ('KJV', 'JHN', 8, 45, 'And because I tell you the truth, ye believe me not.'),
  ('KJV', 'JHN', 8, 46, 'Which of you convinceth me of sin? And if I say the truth, why do ye not believe me?'),
  ('KJV', 'JHN', 8, 47, 'He that is of God heareth God’s words: ye therefore hear them not, because ye are not of God.'),
  ('KJV', 'JHN', 8, 48, 'Then answered the Jews, and said unto him, Say we not well that thou art a Samaritan, and hast a devil?'),
  ('KJV', 'JHN', 8, 49, 'Jesus answered, I have not a devil; but I honour my Father, and ye do dishonour me.'),
  ('KJV', 'JHN', 8, 50, 'And I seek not mine own glory: there is one that seeketh and judgeth.'),
  ('KJV', 'JHN', 8, 51, 'Verily, verily, I say unto you, If a man keep my saying, he shall never see death.'),
  ('KJV', 'JHN', 8, 52, 'Then said the Jews unto him, Now we know that thou hast a devil. Abraham is dead, and the prophets; and thou sayest, If a man keep my saying, he shall never taste of death.'),
  ('KJV', 'JHN', 8, 53, 'Art thou greater than our father Abraham, which is dead? and the prophets are dead: whom makest thou thyself?'),
  ('KJV', 'JHN', 8, 54, 'Jesus answered, If I honour myself, my honour is nothing: it is my Father that honoureth me; of whom ye say, that he is your God:'),
  ('KJV', 'JHN', 8, 55, 'Yet ye have not known him; but I know him: and if I should say, I know him not, I shall be a liar like unto you: but I know him, and keep his saying.'),
  ('KJV', 'JHN', 8, 56, 'Your father Abraham rejoiced to see my day: and he saw it, and was glad.'),
  ('KJV', 'JHN', 8, 57, 'Then said the Jews unto him, Thou art not yet fifty years old, and hast thou seen Abraham?'),
  ('KJV', 'JHN', 8, 58, 'Jesus said unto them, Verily, verily, I say unto you, Before Abraham was, I am.'),
  ('KJV', 'JHN', 8, 59, 'Then took they up stones to cast at him: but Jesus hid himself, and went out of the temple, going through the midst of them, and so passed by.'),
  ('KJV', 'JHN', 10, 1, 'Verily, verily, I say unto you, He that entereth not by the door into the sheepfold, but climbeth up some other way, the same is a thief and a robber.'),
  ('KJV', 'JHN', 10, 2, 'But he that entereth in by the door is the shepherd of the sheep.'),
  ('KJV', 'JHN', 10, 3, 'To him the porter openeth; and the sheep hear his voice: and he calleth his own sheep by name, and leadeth them out.'),
  ('KJV', 'JHN', 10, 4, 'And when he putteth forth his own sheep, he goeth before them, and the sheep follow him: for they know his voice.'),
  ('KJV', 'JHN', 10, 5, 'And a stranger will they not follow, but will flee from him: for they know not the voice of strangers.'),
  ('KJV', 'JHN', 10, 6, 'This parable spake Jesus unto them: but they understood not what things they were which he spake unto them.'),
  ('KJV', 'JHN', 10, 7, 'Then said Jesus unto them again, Verily, verily, I say unto you, I am the door of the sheep.'),
  ('KJV', 'JHN', 10, 8, 'All that ever came before me are thieves and robbers: but the sheep did not hear them.'),
  ('KJV', 'JHN', 10, 9, 'I am the door: by me if any man enter in, he shall be saved, and shall go in and out, and find pasture.'),
  ('KJV', 'JHN', 10, 10, 'The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly.'),
  ('KJV', 'JHN', 10, 11, 'I am the good shepherd: the good shepherd giveth his life for the sheep.'),
  ('KJV', 'JHN', 10, 12, 'But he that is an hireling, and not the shepherd, whose own the sheep are not, seeth the wolf coming, and leaveth the sheep, and fleeth: and the wolf catcheth them, and scattereth the sheep.'),
  ('KJV', 'JHN', 10, 13, 'The hireling fleeth, because he is an hireling, and careth not for the sheep.'),
  ('KJV', 'JHN', 10, 14, 'I am the good shepherd, and know my sheep, and am known of mine.'),
  ('KJV', 'JHN', 10, 15, 'As the Father knoweth me, even so know I the Father: and I lay down my life for the sheep.'),
  ('KJV', 'JHN', 10, 16, 'And other sheep I have, which are not of this fold: them also I must bring, and they shall hear my voice; and there shall be one fold, and one shepherd.'),
  ('KJV', 'JHN', 10, 17, 'Therefore doth my Father love me, because I lay down my life, that I might take it again.'),
  ('KJV', 'JHN', 10, 18, 'No man taketh it from me, but I lay it down of myself. I have power to lay it down, and I have power to take it again. This commandment have I received of my Father.'),
  ('KJV', 'JHN', 10, 19, 'There was a division therefore again among the Jews for these sayings.'),
  ('KJV', 'JHN', 10, 20, 'And many of them said, He hath a devil, and is mad; why hear ye him?'),
  ('KJV', 'JHN', 10, 21, 'Others said, These are not the words of him that hath a devil. Can a devil open the eyes of the blind?'),
  ('KJV', 'JHN', 10, 22, 'And it was at Jerusalem the feast of the dedication, and it was winter.'),
  ('KJV', 'JHN', 10, 23, 'And Jesus walked in the temple in Solomon’s porch.'),
  ('KJV', 'JHN', 10, 24, 'Then came the Jews round about him, and said unto him, How long dost thou make us to doubt? If thou be the Christ, tell us plainly.'),
  ('KJV', 'JHN', 10, 25, 'Jesus answered them, I told you, and ye believed not: the works that I do in my Father’s name, they bear witness of me.'),
  ('KJV', 'JHN', 10, 26, 'But ye believe not, because ye are not of my sheep, as I said unto you.'),
  ('KJV', 'JHN', 10, 27, 'My sheep hear my voice, and I know them, and they follow me:'),
  ('KJV', 'JHN', 10, 28, 'And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.'),
  ('KJV', 'JHN', 10, 29, 'My Father, which gave them me, is greater than all; and no man is able to pluck them out of my Father’s hand.'),
  ('KJV', 'JHN', 10, 30, 'I and my Father are one.'),
  ('KJV', 'JHN', 10, 31, 'Then the Jews took up stones again to stone him.'),
  ('KJV', 'JHN', 10, 32, 'Jesus answered them, Many good works have I shewed you from my Father; for which of those works do ye stone me?'),
  ('KJV', 'JHN', 10, 33, 'The Jews answered him, saying, For a good work we stone thee not; but for blasphemy; and because that thou, being a man, makest thyself God.'),
  ('KJV', 'JHN', 10, 34, 'Jesus answered them, Is it not written in your law, I said, Ye are gods?'),
  ('KJV', 'JHN', 10, 35, 'If he called them gods, unto whom the word of God came, and the scripture cannot be broken;'),
  ('KJV', 'JHN', 10, 36, 'Say ye of him, whom the Father hath sanctified, and sent into the world, Thou blasphemest; because I said, I am the Son of God?'),
  ('KJV', 'JHN', 10, 37, 'If I do not the works of my Father, believe me not.'),
  ('KJV', 'JHN', 10, 38, 'But if I do, though ye believe not me, believe the works: that ye may know, and believe, that the Father is in me, and I in him.'),
  ('KJV', 'JHN', 10, 39, 'Therefore they sought again to take him: but he escaped out of their hand,'),
  ('KJV', 'JHN', 10, 40, 'And went away again beyond Jordan into the place where John at first baptized; and there he abode.'),
  ('KJV', 'JHN', 10, 41, 'And many resorted unto him, and said, John did no miracle: but all things that John spake of this man were true.'),
  ('KJV', 'JHN', 10, 42, 'And many believed on him there.'),
  ('KJV', 'JHN', 14, 1, 'Let not your heart be troubled: ye believe in God, believe also in me.'),
  ('KJV', 'JHN', 14, 2, 'In my Father’s house are many mansions: if it were not so, I would have told you. I go to prepare a place for you.'),
  ('KJV', 'JHN', 14, 3, 'And if I go and prepare a place for you, I will come again, and receive you unto myself; that where I am, there ye may be also.'),
  ('KJV', 'JHN', 14, 4, 'And whither I go ye know, and the way ye know.'),
  ('KJV', 'JHN', 14, 5, 'Thomas saith unto him, Lord, we know not whither thou goest; and how can we know the way?'),
  ('KJV', 'JHN', 14, 6, 'Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.'),
  ('KJV', 'JHN', 14, 7, 'If ye had known me, ye should have known my Father also: and from henceforth ye know him, and have seen him.'),
  ('KJV', 'JHN', 14, 8, 'Philip saith unto him, Lord, shew us the Father, and it sufficeth us.'),
  ('KJV', 'JHN', 14, 9, 'Jesus saith unto him, Have I been so long time with you, and yet hast thou not known me, Philip? he that hath seen me hath seen the Father; and how sayest thou then, Shew us the Father?'),
  ('KJV', 'JHN', 14, 10, 'Believest thou not that I am in the Father, and the Father in me? the words that I speak unto you I speak not of myself: but the Father that dwelleth in me, he doeth the works.'),
  ('KJV', 'JHN', 14, 11, 'Believe me that I am in the Father, and the Father in me: or else believe me for the very works’ sake.'),
  ('KJV', 'JHN', 14, 12, 'Verily, verily, I say unto you, He that believeth on me, the works that I do shall he do also; and greater works than these shall he do; because I go unto my Father.'),
  ('KJV', 'JHN', 14, 13, 'And whatsoever ye shall ask in my name, that will I do, that the Father may be glorified in the Son.'),
  ('KJV', 'JHN', 14, 14, 'If ye shall ask any thing in my name, I will do it.'),
  ('KJV', 'JHN', 14, 15, 'If ye love me, keep my commandments.'),
  ('KJV', 'JHN', 14, 16, 'And I will pray the Father, and he shall give you another Comforter, that he may abide with you for ever;'),
  ('KJV', 'JHN', 14, 17, 'Even the Spirit of truth; whom the world cannot receive, because it seeth him not, neither knoweth him: but ye know him; for he dwelleth with you, and shall be in you.'),
  ('KJV', 'JHN', 14, 18, 'I will not leave you comfortless: I will come to you.'),
  ('KJV', 'JHN', 14, 19, 'Yet a little while, and the world seeth me no more; but ye see me: because I live, ye shall live also.'),
  ('KJV', 'JHN', 14, 20, 'At that day ye shall know that I am in my Father, and ye in me, and I in you.'),
  ('KJV', 'JHN', 14, 21, 'He that hath my commandments, and keepeth them, he it is that loveth me: and he that loveth me shall be loved of my Father, and I will love him, and will manifest myself to him.'),
  ('KJV', 'JHN', 14, 22, 'Judas saith unto him, not Iscariot, Lord, how is it that thou wilt manifest thyself unto us, and not unto the world?'),
  ('KJV', 'JHN', 14, 23, 'Jesus answered and said unto him, If a man love me, he will keep my words: and my Father will love him, and we will come unto him, and make our abode with him.'),
  ('KJV', 'JHN', 14, 24, 'He that loveth me not keepeth not my sayings: and the word which ye hear is not mine, but the Father’s which sent me.'),
  ('KJV', 'JHN', 14, 25, 'These things have I spoken unto you, being yet present with you.'),
  ('KJV', 'JHN', 14, 26, 'But the Comforter, which is the Holy Ghost, whom the Father will send in my name, he shall teach you all things, and bring all things to your remembrance, whatsoever I have said unto you.'),
  ('KJV', 'JHN', 14, 27, 'Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.'),
  ('KJV', 'JHN', 14, 28, 'Ye have heard how I said unto you, I go away, and come again unto you. If ye loved me, ye would rejoice, because I said, I go unto the Father: for my Father is greater than I.'),
  ('KJV', 'JHN', 14, 29, 'And now I have told you before it come to pass, that, when it is come to pass, ye might believe.'),
  ('KJV', 'JHN', 14, 30, 'Hereafter I will not talk much with you: for the prince of this world cometh, and hath nothing in me.'),
  ('KJV', 'JHN', 14, 31, 'But that the world may know that I love the Father; and as the Father gave me commandment, even so I do. Arise, let us go hence.'),
  ('KJV', 'ACT', 3, 1, 'Now Peter and John went up together into the temple at the hour of prayer, being the ninth hour.'),
  ('KJV', 'ACT', 3, 2, 'And a certain man lame from his mother’s womb was carried, whom they laid daily at the gate of the temple which is called Beautiful, to ask alms of them that entered into the temple;'),
  ('KJV', 'ACT', 3, 3, 'Who seeing Peter and John about to go into the temple asked an alms.'),
  ('KJV', 'ACT', 3, 4, 'And Peter, fastening his eyes upon him with John, said, Look on us.'),
  ('KJV', 'ACT', 3, 5, 'And he gave heed unto them, expecting to receive something of them.'),
  ('KJV', 'ACT', 3, 6, 'Then Peter said, Silver and gold have I none; but such as I have give I thee: In the name of Jesus Christ of Nazareth rise up and walk.'),
  ('KJV', 'ACT', 3, 7, 'And he took him by the right hand, and lifted him up: and immediately his feet and ankle bones received strength.'),
  ('KJV', 'ACT', 3, 8, 'And he leaping up stood, and walked, and entered with them into the temple, walking, and leaping, and praising God.'),
  ('KJV', 'ACT', 3, 9, 'And all the people saw him walking and praising God:'),
  ('KJV', 'ACT', 3, 10, 'And they knew that it was he which sat for alms at the Beautiful gate of the temple: and they were filled with wonder and amazement at that which had happened unto him.'),
  ('KJV', 'ACT', 3, 11, 'And as the lame man which was healed held Peter and John, all the people ran together unto them in the porch that is called Solomon’s, greatly wondering.'),
  ('KJV', 'ACT', 3, 12, 'And when Peter saw it, he answered unto the people, Ye men of Israel, why marvel ye at this? or why look ye so earnestly on us, as though by our own power or holiness we had made this man to walk?'),
  ('KJV', 'ACT', 3, 13, 'The God of Abraham, and of Isaac, and of Jacob, the God of our fathers, hath glorified his Son Jesus; whom ye delivered up, and denied him in the presence of Pilate, when he was determined to let him go.'),
  ('KJV', 'ACT', 3, 14, 'But ye denied the Holy One and the Just, and desired a murderer to be granted unto you;'),
  ('KJV', 'ACT', 3, 15, 'And killed the Prince of life, whom God hath raised from the dead; whereof we are witnesses.'),
  ('KJV', 'ACT', 3, 16, 'And his name through faith in his name hath made this man strong, whom ye see and know: yea, the faith which is by him hath given him this perfect soundness in the presence of you all.'),
  ('KJV', 'ACT', 3, 17, 'And now, brethren, I wot that through ignorance ye did it, as did also your rulers.'),
  ('KJV', 'ACT', 3, 18, 'But those things, which God before had shewed by the mouth of all his prophets, that Christ should suffer, he hath so fulfilled.'),
  ('KJV', 'ACT', 3, 19, 'Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of the Lord;'),
  ('KJV', 'ACT', 3, 20, 'And he shall send Jesus Christ, which before was preached unto you:'),
  ('KJV', 'ACT', 3, 21, 'Whom the heaven must receive until the times of restitution of all things, which God hath spoken by the mouth of all his holy prophets since the world began.'),
  ('KJV', 'ACT', 3, 22, 'For Moses truly said unto the fathers, A prophet shall the Lord your God raise up unto you of your brethren, like unto me; him shall ye hear in all things whatsoever he shall say unto you.'),
  ('KJV', 'ACT', 3, 23, 'And it shall come to pass, that every soul, which will not hear that prophet, shall be destroyed from among the people.'),
  ('KJV', 'ACT', 3, 24, 'Yea, and all the prophets from Samuel and those that follow after, as many as have spoken, have likewise foretold of these days.'),
  ('KJV', 'ACT', 3, 25, 'Ye are the children of the prophets, and of the covenant which God made with our fathers, saying unto Abraham, And in thy seed shall all the kindreds of the earth be blessed.'),
  ('KJV', 'ACT', 3, 26, 'Unto you first God, having raised up his Son Jesus, sent him to bless you, in turning away every one of you from his iniquities.'),
  ('KJV', 'ACT', 28, 1, 'And when they were escaped, then they knew that the island was called Melita.'),
  ('KJV', 'ACT', 28, 2, 'And the barbarous people shewed us no little kindness: for they kindled a fire, and received us every one, because of the present rain, and because of the cold.'),
  ('KJV', 'ACT', 28, 3, 'And when Paul had gathered a bundle of sticks, and laid them on the fire, there came a viper out of the heat, and fastened on his hand.'),
  ('KJV', 'ACT', 28, 4, 'And when the barbarians saw the venomous beast hang on his hand, they said among themselves, No doubt this man is a murderer, whom, though he hath escaped the sea, yet vengeance suffereth not to live.'),
  ('KJV', 'ACT', 28, 5, 'And he shook off the beast into the fire, and felt no harm.'),
  ('KJV', 'ACT', 28, 6, 'Howbeit they looked when he should have swollen, or fallen down dead suddenly: but after they had looked a great while, and saw no harm come to him, they changed their minds, and said that he was a god.'),
  ('KJV', 'ACT', 28, 7, 'In the same quarters were possessions of the chief man of the island, whose name was Publius; who received us, and lodged us three days courteously.'),
  ('KJV', 'ACT', 28, 8, 'And it came to pass, that the father of Publius lay sick of a fever and of a bloody flux: to whom Paul entered in, and prayed, and laid his hands on him, and healed him.'),
  ('KJV', 'ACT', 28, 9, 'So when this was done, others also, which had diseases in the island, came, and were healed:'),
  ('KJV', 'ACT', 28, 10, 'Who also honoured us with many honours; and when we departed, they laded us with such things as were necessary.'),
  ('KJV', 'ACT', 28, 11, 'And after three months we departed in a ship of Alexandria, which had wintered in the isle, whose sign was Castor and Pollux.'),
  ('KJV', 'ACT', 28, 12, 'And landing at Syracuse, we tarried there three days.'),
  ('KJV', 'ACT', 28, 13, 'And from thence we fetched a compass, and came to Rhegium: and after one day the south wind blew, and we came the next day to Puteoli:'),
  ('KJV', 'ACT', 28, 14, 'Where we found brethren, and were desired to tarry with them seven days: and so we went toward Rome.'),
  ('KJV', 'ACT', 28, 15, 'And from thence, when the brethren heard of us, they came to meet us as far as Appii forum, and The three taverns: whom when Paul saw, he thanked God, and took courage.'),
  ('KJV', 'ACT', 28, 16, 'And when we came to Rome, the centurion delivered the prisoners to the captain of the guard: but Paul was suffered to dwell by himself with a soldier that kept him.'),
  ('KJV', 'ACT', 28, 17, 'And it came to pass, that after three days Paul called the chief of the Jews together: and when they were come together, he said unto them, Men and brethren, though I have committed nothing against the people, or customs of our fathers, yet was I delivered prisoner from Jerusalem into the hands of the Romans.'),
  ('KJV', 'ACT', 28, 18, 'Who, when they had examined me, would have let me go, because there was no cause of death in me.'),
  ('KJV', 'ACT', 28, 19, 'But when the Jews spake against it, I was constrained to appeal unto Cesar; not that I had ought to accuse my nation of.'),
  ('KJV', 'ACT', 28, 20, 'For this cause therefore have I called for you, to see you, and to speak with you: because that for the hope of Israel I am bound with this chain.'),
  ('KJV', 'ACT', 28, 21, 'And they said unto him, We neither received letters out of Judea concerning thee, neither any of the brethren that came shewed or spake any harm of thee.'),
  ('KJV', 'ACT', 28, 22, 'But we desire to hear of thee what thou thinkest: for as concerning this sect, we know that every where it is spoken against.'),
  ('KJV', 'ACT', 28, 23, 'And when they had appointed him a day, there came many to him into his lodging; to whom he expounded and testified the kingdom of God, persuading them concerning Jesus, both out of the law of Moses, and out of the prophets, from morning till evening.'),
  ('KJV', 'ACT', 28, 24, 'And some believed the things which were spoken, and some believed not.'),
  ('KJV', 'ACT', 28, 25, 'And when they agreed not among themselves, they departed, after that Paul had spoken one word, Well spake the Holy Ghost by Esaias the prophet unto our fathers,'),
  ('KJV', 'ACT', 28, 26, 'Saying, Go unto this people, and say, Hearing ye shall hear, and shall not understand; and seeing ye shall see, and not perceive:'),
  ('KJV', 'ACT', 28, 27, 'For the heart of this people is waxed gross, and their ears are dull of hearing, and their eyes have they closed; lest they should see with their eyes, and hear with their ears, and understand with their heart, and should be converted, and I should heal them.'),
  ('KJV', 'ACT', 28, 28, 'Be it known therefore unto you, that the salvation of God is sent unto the Gentiles, and that they will hear it.'),
  ('KJV', 'ACT', 28, 29, 'And when he had said these words, the Jews departed, and had great reasoning among themselves.'),
  ('KJV', 'ACT', 28, 30, 'And Paul dwelt two whole years in his own hired house, and received all that came in unto him,'),
  ('KJV', 'ACT', 28, 31, 'Preaching the kingdom of God, and teaching those things which concern the Lord Jesus Christ, with all confidence, no man forbidding him.'),
  ('KJV', 'ROM', 8, 1, 'There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.'),
  ('KJV', 'ROM', 8, 2, 'For the law of the Spirit of life in Christ Jesus hath made me free from the law of sin and death.'),
  ('KJV', 'ROM', 8, 3, 'For what the law could not do, in that it was weak through the flesh, God sending his own Son in the likeness of sinful flesh, and for sin, condemned sin in the flesh:'),
  ('KJV', 'ROM', 8, 4, 'That the righteousness of the law might be fulfilled in us, who walk not after the flesh, but after the Spirit.'),
  ('KJV', 'ROM', 8, 5, 'For they that are after the flesh do mind the things of the flesh; but they that are after the Spirit the things of the Spirit.'),
  ('KJV', 'ROM', 8, 6, 'For to be carnally minded is death; but to be spiritually minded is life and peace.'),
  ('KJV', 'ROM', 8, 7, 'Because the carnal mind is enmity against God: for it is not subject to the law of God, neither indeed can be.'),
  ('KJV', 'ROM', 8, 8, 'So then they that are in the flesh cannot please God.'),
  ('KJV', 'ROM', 8, 9, 'But ye are not in the flesh, but in the Spirit, if so be that the Spirit of God dwell in you. Now if any man have not the Spirit of Christ, he is none of his.'),
  ('KJV', 'ROM', 8, 10, 'And if Christ be in you, the body is dead because of sin; but the Spirit is life because of righteousness.'),
  ('KJV', 'ROM', 8, 11, 'But if the Spirit of him that raised up Jesus from the dead dwell in you, he that raised up Christ from the dead shall also quicken your mortal bodies by his Spirit that dwelleth in you.'),
  ('KJV', 'ROM', 8, 12, 'Therefore, brethren, we are debtors, not to the flesh, to live after the flesh.'),
  ('KJV', 'ROM', 8, 13, 'For if ye live after the flesh, ye shall die: but if ye through the Spirit do mortify the deeds of the body, ye shall live.'),
  ('KJV', 'ROM', 8, 14, 'For as many as are led by the Spirit of God, they are the sons of God.'),
  ('KJV', 'ROM', 8, 15, 'For ye have not received the spirit of bondage again to fear; but ye have received the Spirit of adoption, whereby we cry, Abba, Father.'),
  ('KJV', 'ROM', 8, 16, 'The Spirit itself beareth witness with our spirit, that we are the children of God:'),
  ('KJV', 'ROM', 8, 17, 'And if children, then heirs; heirs of God, and joint-heirs with Christ; if so be that we suffer with him, that we may be also glorified together.'),
  ('KJV', 'ROM', 8, 18, 'For I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us.'),
  ('KJV', 'ROM', 8, 19, 'For the earnest expectation of the creature waiteth for the manifestation of the sons of God.'),
  ('KJV', 'ROM', 8, 20, 'For the creature was made subject to vanity, not willingly, but by reason of him who hath subjected the same in hope,'),
  ('KJV', 'ROM', 8, 21, 'Because the creature itself also shall be delivered from the bondage of corruption into the glorious liberty of the children of God.'),
  ('KJV', 'ROM', 8, 22, 'For we know that the whole creation groaneth and travaileth in pain together until now.'),
  ('KJV', 'ROM', 8, 23, 'And not only they, but ourselves also, which have the firstfruits of the Spirit, even we ourselves groan within ourselves, waiting for the adoption, to wit, the redemption of our body.'),
  ('KJV', 'ROM', 8, 24, 'For we are saved by hope: but hope that is seen is not hope: for what a man seeth, why doth he yet hope for?'),
  ('KJV', 'ROM', 8, 25, 'But if we hope for that we see not, then do we with patience wait for it.'),
  ('KJV', 'ROM', 8, 26, 'Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered.'),
  ('KJV', 'ROM', 8, 27, 'And he that searcheth the hearts knoweth what is the mind of the Spirit, because he maketh intercession for the saints according to the will of God.'),
  ('KJV', 'ROM', 8, 28, 'And we know that all things work together for good to them that love God, to them who are the called according to his purpose.'),
  ('KJV', 'ROM', 8, 29, 'For whom he did foreknow, he also did predestinate to be conformed to the image of his Son, that he might be the firstborn among many brethren.'),
  ('KJV', 'ROM', 8, 30, 'Moreover whom he did predestinate, them he also called: and whom he called, them he also justified: and whom he justified, them he also glorified.'),
  ('KJV', 'ROM', 8, 31, 'What shall we then say to these things? If God be for us, who can be against us?'),
  ('KJV', 'ROM', 8, 32, 'He that spared not his own Son, but delivered him up for us all, how shall he not with him also freely give us all things?'),
  ('KJV', 'ROM', 8, 33, 'Who shall lay any thing to the charge of God’s elect? It is God that justifieth.'),
  ('KJV', 'ROM', 8, 34, 'Who is he that condemneth? It is Christ that died, yea rather, that is risen again, who is even at the right hand of God, who also maketh intercession for us.'),
  ('KJV', 'ROM', 8, 35, 'Who shall separate us from the love of Christ? shall tribulation, or distress, or persecution, or famine, or nakedness, or peril, or sword?'),
  ('KJV', 'ROM', 8, 36, 'As it is written, For thy sake we are killed all the day long; we are accounted as sheep for the slaughter.'),
  ('KJV', 'ROM', 8, 37, 'Nay, in all these things we are more than conquerors through him that loved us.'),
  ('KJV', 'ROM', 8, 38, 'For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come,'),
  ('KJV', 'ROM', 8, 39, 'Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.'),
  ('KJV', 'ROM', 11, 1, 'I say then, Hath God cast away his people? God forbid. For I also am an Israelite, of the seed of Abraham, of the tribe of Benjamin.'),
  ('KJV', 'ROM', 11, 2, 'God hath not cast away his people which he foreknew. Wot ye not what the scripture saith of Elias? how he maketh intercession to God against Israel, saying,'),
  ('KJV', 'ROM', 11, 3, 'Lord, they have killed thy prophets, and digged down thine altars; and I am left alone, and they seek my life.'),
  ('KJV', 'ROM', 11, 4, 'But what saith the answer of God unto him? I have reserved to myself seven thousand men, who have not bowed the knee to the image of Baal.'),
  ('KJV', 'ROM', 11, 5, 'Even so then at this present time also there is a remnant according to the election of grace.'),
  ('KJV', 'ROM', 11, 6, 'And if by grace, then is it no more of works: otherwise grace is no more grace. But if it be of works, then is it no more grace: otherwise work is no more work.'),
  ('KJV', 'ROM', 11, 7, 'What then? Israel hath not obtained that which he seeketh for; but the election hath obtained it, and the rest were blinded'),
  ('KJV', 'ROM', 11, 8, '(According as it is written, God hath given them the spirit of slumber, eyes that they should not see, and ears that they should not hear;) unto this day.'),
  ('KJV', 'ROM', 11, 9, 'And David saith, Let their table be made a snare, and a trap, and a stumblingblock, and a recompence unto them:'),
  ('KJV', 'ROM', 11, 10, 'Let their eyes be darkened, that they may not see, and bow down their back alway.'),
  ('KJV', 'ROM', 11, 11, 'I say then, Have they stumbled that they should fall? God forbid: but rather through their fall salvation is come unto the Gentiles, for to provoke them to jealousy.'),
  ('KJV', 'ROM', 11, 12, 'Now if the fall of them be the riches of the world, and the diminishing of them the riches of the Gentiles; how much more their fulness?'),
  ('KJV', 'ROM', 11, 13, 'For I speak to you Gentiles, inasmuch as I am the apostle of the Gentiles, I magnify mine office:'),
  ('KJV', 'ROM', 11, 14, 'If by any means I may provoke to emulation them which are my flesh, and might save some of them.'),
  ('KJV', 'ROM', 11, 15, 'For if the casting away of them be the reconciling of the world, what shall the receiving of them be, but life from the dead?'),
  ('KJV', 'ROM', 11, 16, 'For if the firstfruit be holy, the lump is also holy: and if the root be holy, so are the branches.'),
  ('KJV', 'ROM', 11, 17, 'And if some of the branches be broken off, and thou, being a wild olive tree, wert graffed in among them, and with them partakest of the root and fatness of the olive tree;'),
  ('KJV', 'ROM', 11, 18, 'Boast not against the branches. But if thou boast, thou bearest not the root, but the root thee.'),
  ('KJV', 'ROM', 11, 19, 'Thou wilt say then, The branches were broken off, that I might be graffed in.'),
  ('KJV', 'ROM', 11, 20, 'Well; because of unbelief they were broken off, and thou standest by faith. Be not highminded, but fear:'),
  ('KJV', 'ROM', 11, 21, 'For if God spared not the natural branches, take heed lest he also spare not thee.'),
  ('KJV', 'ROM', 11, 22, 'Behold therefore the goodness and severity of God: on them which fell, severity; but toward thee, goodness, if thou continue in his goodness: otherwise thou also shalt be cut off.'),
  ('KJV', 'ROM', 11, 23, 'And they also, if they abide not still in unbelief, shall be graffed in: for God is able to graff them in again.'),
  ('KJV', 'ROM', 11, 24, 'For if thou wert cut out of the olive tree which is wild by nature, and wert graffed contrary to nature into a good olive tree: how much more shall these, which be the natural branches, be graffed into their own olive tree?'),
  ('KJV', 'ROM', 11, 25, 'For I would not, brethren, that ye should be ignorant of this mystery, lest ye should be wise in your own conceits; that blindness in part is happened to Israel, until the fulness of the Gentiles be come in.'),
  ('KJV', 'ROM', 11, 26, 'And so all Israel shall be saved: as it is written, There shall come out of Sion the Deliverer, and shall turn away ungodliness from Jacob:'),
  ('KJV', 'ROM', 11, 27, 'For this is my covenant unto them, when I shall take away their sins.'),
  ('KJV', 'ROM', 11, 28, 'As concerning the gospel, they are enemies for your sakes: but as touching the election, they are beloved for the fathers’ sakes.'),
  ('KJV', 'ROM', 11, 29, 'For the gifts and calling of God are without repentance.'),
  ('KJV', 'ROM', 11, 30, 'For as ye in times past have not believed God, yet have now obtained mercy through their unbelief:'),
  ('KJV', 'ROM', 11, 31, 'Even so have these also now not believed, that through your mercy they also may obtain mercy.'),
  ('KJV', 'ROM', 11, 32, 'For God hath concluded them all in unbelief, that he might have mercy upon all.'),
  ('KJV', 'ROM', 11, 33, 'O the depth of the riches both of the wisdom and knowledge of God! how unsearchable are his judgments, and his ways past finding out!'),
  ('KJV', 'ROM', 11, 34, 'For who hath known the mind of the Lord? or who hath been his counsellor?'),
  ('KJV', 'ROM', 11, 35, 'Or who hath first given to him, and it shall be recompensed unto him again?'),
  ('KJV', 'ROM', 11, 36, 'For of him, and through him, and to him, are all things: to whom be glory for ever. Amen.'),
  ('KJV', 'ROM', 12, 1, 'I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.'),
  ('KJV', 'ROM', 12, 2, 'And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.'),
  ('KJV', 'ROM', 12, 3, 'For I say, through the grace given unto me, to every man that is among you, not to think of himself more highly than he ought to think; but to think soberly, according as God hath dealt to every man the measure of faith.'),
  ('KJV', 'ROM', 12, 4, 'For as we have many members in one body, and all members have not the same office:'),
  ('KJV', 'ROM', 12, 5, 'So we, being many, are one body in Christ, and every one members one of another.'),
  ('KJV', 'ROM', 12, 6, 'Having then gifts differing according to the grace that is given to us, whether prophecy, let us prophesy according to the proportion of faith;'),
  ('KJV', 'ROM', 12, 7, 'Or ministry, let us wait on our ministering: or he that teacheth, on teaching;'),
  ('KJV', 'ROM', 12, 8, 'Or he that exhorteth, on exhortation: he that giveth, let him do it with simplicity; he that ruleth, with diligence; he that sheweth mercy, with cheerfulness.'),
  ('KJV', 'ROM', 12, 9, 'Let love be without dissimulation. Abhor that which is evil; cleave to that which is good.'),
  ('KJV', 'ROM', 12, 10, 'Be kindly affectioned one to another with brotherly love; in honour preferring one another;'),
  ('KJV', 'ROM', 12, 11, 'Not slothful in business; fervent in spirit; serving the Lord;'),
  ('KJV', 'ROM', 12, 12, 'Rejoicing in hope; patient in tribulation; continuing instant in prayer;'),
  ('KJV', 'ROM', 12, 13, 'Distributing to the necessity of saints; given to hospitality.'),
  ('KJV', 'ROM', 12, 14, 'Bless them which persecute you: bless, and curse not.'),
  ('KJV', 'ROM', 12, 15, 'Rejoice with them that do rejoice, and weep with them that weep.'),
  ('KJV', 'ROM', 12, 16, 'Be of the same mind one toward another. Mind not high things, but condescend to men of low estate. Be not wise in your own conceits.'),
  ('KJV', 'ROM', 12, 17, 'Recompense to no man evil for evil. Provide things honest in the sight of all men.'),
  ('KJV', 'ROM', 12, 18, 'If it be possible, as much as lieth in you, live peaceably with all men.'),
  ('KJV', 'ROM', 12, 19, 'Dearly beloved, avenge not yourselves, but rather give place unto wrath: for it is written, Vengeance is mine; I will repay, saith the Lord.'),
  ('KJV', 'ROM', 12, 20, 'Therefore if thine enemy hunger, feed him; if he thirst, give him drink: for in so doing thou shalt heap coals of fire on his head.'),
  ('KJV', 'ROM', 12, 21, 'Be not overcome of evil, but overcome evil with good.'),
  ('KJV', '2CO', 3, 1, 'Do we begin again to commend ourselves? or need we, as some others, epistles of commendation to you, or letters of commendation from you?'),
  ('KJV', '2CO', 3, 2, 'Ye are our epistle written in our hearts, known and read of all men:'),
  ('KJV', '2CO', 3, 3, 'Forasmuch as ye are manifestly declared to be the epistle of Christ ministered by us, written not with ink, but with the Spirit of the living God; not in tables of stone, but in fleshy tables of the heart.'),
  ('KJV', '2CO', 3, 4, 'And such trust have we through Christ to God-ward:'),
  ('KJV', '2CO', 3, 5, 'Not that we are sufficient of ourselves to think any thing as of ourselves; but our sufficiency is of God;'),
  ('KJV', '2CO', 3, 6, 'Who also hath made us able ministers of the new testament; not of the letter, but of the spirit: for the letter killeth, but the spirit giveth life.'),
  ('KJV', '2CO', 3, 7, 'But if the ministration of death, written and engraven in stones, was glorious, so that the children of Israel could not stedfastly behold the face of Moses for the glory of his countenance; which glory was to be done away:'),
  ('KJV', '2CO', 3, 8, 'How shall not the ministration of the spirit be rather glorious?'),
  ('KJV', '2CO', 3, 9, 'For if the ministration of condemnation be glory, much more doth the ministration of righteousness exceed in glory.'),
  ('KJV', '2CO', 3, 10, 'For even that which was made glorious had no glory in this respect, by reason of the glory that excelleth.'),
  ('KJV', '2CO', 3, 11, 'For if that which is done away was glorious, much more that which remaineth is glorious.'),
  ('KJV', '2CO', 3, 12, 'Seeing then that we have such hope, we use great plainness of speech:'),
  ('KJV', '2CO', 3, 13, 'And not as Moses, which put a vail over his face, that the children of Israel could not stedfastly look to the end of that which is abolished:'),
  ('KJV', '2CO', 3, 14, 'But their minds were blinded: for until this day remaineth the same vail untaken away in the reading of the old testament; which vail is done away in Christ.'),
  ('KJV', '2CO', 3, 15, 'But even unto this day, when Moses is read, the vail is upon their heart.'),
  ('KJV', '2CO', 3, 16, 'Nevertheless when it shall turn to the Lord, the vail shall be taken away.'),
  ('KJV', '2CO', 3, 17, 'Now the Lord is that Spirit: and where the Spirit of the Lord is, there is liberty.'),
  ('KJV', '2CO', 3, 18, 'But we all, with open face beholding as in a glass the glory of the Lord, are changed into the same image from glory to glory, even as by the Spirit of the Lord.'),
  ('KJV', '2CO', 4, 1, 'Therefore seeing we have this ministry, as we have received mercy, we faint not;'),
  ('KJV', '2CO', 4, 2, 'But have renounced the hidden things of dishonesty, not walking in craftiness, nor handling the word of God deceitfully; but by manifestation of the truth commending ourselves to every man’s conscience in the sight of God.'),
  ('KJV', '2CO', 4, 3, 'But if our gospel be hid, it is hid to them that are lost:'),
  ('KJV', '2CO', 4, 4, 'In whom the god of this world hath blinded the minds of them which believe not, lest the light of the glorious gospel of Christ, who is the image of God, should shine unto them.'),
  ('KJV', '2CO', 4, 5, 'For we preach not ourselves, but Christ Jesus the Lord; and ourselves your servants for Jesus’ sake.'),
  ('KJV', '2CO', 4, 6, 'For God, who commanded the light to shine out of darkness, hath shined in our hearts, to give the light of the knowledge of the glory of God in the face of Jesus Christ.'),
  ('KJV', '2CO', 4, 7, 'But we have this treasure in earthen vessels, that the excellency of the power may be of God, and not of us.'),
  ('KJV', '2CO', 4, 8, 'We are troubled on every side, yet not distressed; we are perplexed, but not in despair;'),
  ('KJV', '2CO', 4, 9, 'Persecuted, but not forsaken; cast down, but not destroyed;'),
  ('KJV', '2CO', 4, 10, 'Always bearing about in the body the dying of the Lord Jesus, that the life also of Jesus might be made manifest in our body.'),
  ('KJV', '2CO', 4, 11, 'For we which live are alway delivered unto death for Jesus’ sake, that the life also of Jesus might be made manifest in our mortal flesh.'),
  ('KJV', '2CO', 4, 12, 'So then death worketh in us, but life in you.'),
  ('KJV', '2CO', 4, 13, 'We having the same spirit of faith, according as it is written, I believed, and therefore have I spoken; we also believe, and therefore speak;'),
  ('KJV', '2CO', 4, 14, 'Knowing that he which raised up the Lord Jesus shall raise up us also by Jesus, and shall present us with you.'),
  ('KJV', '2CO', 4, 15, 'For all things are for your sakes, that the abundant grace might through the thanksgiving of many redound to the glory of God.'),
  ('KJV', '2CO', 4, 16, 'For which cause we faint not; but though our outward man perish, yet the inward man is renewed day by day.'),
  ('KJV', '2CO', 4, 17, 'For our light affliction, which is but for a moment, worketh for us a far more exceeding and eternal weight of glory;'),
  ('KJV', '2CO', 4, 18, 'While we look not at the things which are seen, but at the things which are not seen: for the things which are seen are temporal; but the things which are not seen are eternal.'),
  ('KJV', 'GAL', 3, 1, 'O foolish Galatians, who hath bewitched you, that ye should not obey the truth, before whose eyes Jesus Christ hath been evidently set forth, crucified among you?'),
  ('KJV', 'GAL', 3, 2, 'This only would I learn of you, Received ye the Spirit by the works of the law, or by the hearing of faith?'),
  ('KJV', 'GAL', 3, 3, 'Are ye so foolish? having begun in the Spirit, are ye now made perfect by the flesh?'),
  ('KJV', 'GAL', 3, 4, 'Have ye suffered so many things in vain? if it be yet in vain.'),
  ('KJV', 'GAL', 3, 5, 'He therefore that ministereth to you the Spirit, and worketh miracles among you, doeth he it by the works of the law, or by the hearing of faith?'),
  ('KJV', 'GAL', 3, 6, 'Even as Abraham believed God, and it was accounted to him for righteousness.'),
  ('KJV', 'GAL', 3, 7, 'Know ye therefore that they which are of faith, the same are the children of Abraham.'),
  ('KJV', 'GAL', 3, 8, 'And the scripture, foreseeing that God would justify the heathen through faith, preached before the gospel unto Abraham, saying, In thee shall all nations be blessed.'),
  ('KJV', 'GAL', 3, 9, 'So then they which be of faith are blessed with faithful Abraham.'),
  ('KJV', 'GAL', 3, 10, 'For as many as are of the works of the law are under the curse: for it is written, Cursed is every one that continueth not in all things which are written in the book of the law to do them.'),
  ('KJV', 'GAL', 3, 11, 'But that no man is justified by the law in the sight of God, it is evident: for, The just shall live by faith.'),
  ('KJV', 'GAL', 3, 12, 'And the law is not of faith: but, The man that doeth them shall live in them.'),
  ('KJV', 'GAL', 3, 13, 'Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:'),
  ('KJV', 'GAL', 3, 14, 'That the blessing of Abraham might come on the Gentiles through Jesus Christ; that we might receive the promise of the Spirit through faith.'),
  ('KJV', 'GAL', 3, 15, 'Brethren, I speak after the manner of men; Though it be but a man’s covenant, yet if it be confirmed, no man disannulleth, or addeth thereto.'),
  ('KJV', 'GAL', 3, 16, 'Now to Abraham and his seed were the promises made. He saith not, And to seeds, as of many; but as of one, And to thy seed, which is Christ.'),
  ('KJV', 'GAL', 3, 17, 'And this I say, that the covenant, that was confirmed before of God in Christ, the law, which was four hundred and thirty years after, cannot disannul, that it should make the promise of none effect.'),
  ('KJV', 'GAL', 3, 18, 'For if the inheritance be of the law, it is no more of promise: but God gave it to Abraham by promise.'),
  ('KJV', 'GAL', 3, 19, 'Wherefore then serveth the law? It was added because of transgressions, till the seed should come to whom the promise was made; and it was ordained by angels in the hand of a mediator.'),
  ('KJV', 'GAL', 3, 20, 'Now a mediator is not a mediator of one, but God is one.'),
  ('KJV', 'GAL', 3, 21, 'Is the law then against the promises of God? God forbid: for if there had been a law given which could have given life, verily righteousness should have been by the law.'),
  ('KJV', 'GAL', 3, 22, 'But the scripture hath concluded all under sin, that the promise by faith of Jesus Christ might be given to them that believe.'),
  ('KJV', 'GAL', 3, 23, 'But before faith came, we were kept under the law, shut up unto the faith which should afterwards be revealed.'),
  ('KJV', 'GAL', 3, 24, 'Wherefore the law was our schoolmaster to bring us unto Christ, that we might be justified by faith.'),
  ('KJV', 'GAL', 3, 25, 'But after that faith is come, we are no longer under a schoolmaster.'),
  ('KJV', 'GAL', 3, 26, 'For ye are all the children of God by faith in Christ Jesus.'),
  ('KJV', 'GAL', 3, 27, 'For as many of you as have been baptized into Christ have put on Christ.'),
  ('KJV', 'GAL', 3, 28, 'There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus.'),
  ('KJV', 'GAL', 3, 29, 'And if ye be Christ’s, then are ye Abraham’s seed, and heirs according to the promise.'),
  ('KJV', 'GAL', 5, 1, 'Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage.'),
  ('KJV', 'GAL', 5, 2, 'Behold, I Paul say unto you, that if ye be circumcised, Christ shall profit you nothing.'),
  ('KJV', 'GAL', 5, 3, 'For I testify again to every man that is circumcised, that he is a debtor to do the whole law.'),
  ('KJV', 'GAL', 5, 4, 'Christ is become of no effect unto you, whosoever of you are justified by the law; ye are fallen from grace.'),
  ('KJV', 'GAL', 5, 5, 'For we through the Spirit wait for the hope of righteousness by faith.'),
  ('KJV', 'GAL', 5, 6, 'For in Jesus Christ neither circumcision availeth any thing, nor uncircumcision; but faith which worketh by love.'),
  ('KJV', 'GAL', 5, 7, 'Ye did run well; who did hinder you that ye should not obey the truth?'),
  ('KJV', 'GAL', 5, 8, 'This persuasion cometh not of him that calleth you.'),
  ('KJV', 'GAL', 5, 9, 'A little leaven leaveneth the whole lump.'),
  ('KJV', 'GAL', 5, 10, 'I have confidence in you through the Lord, that ye will be none otherwise minded: but he that troubleth you shall bear his judgment, whosoever he be.'),
  ('KJV', 'GAL', 5, 11, 'And I, brethren, if I yet preach circumcision, why do I yet suffer persecution? then is the offence of the cross ceased.'),
  ('KJV', 'GAL', 5, 12, 'I would they were even cut off which trouble you.'),
  ('KJV', 'GAL', 5, 13, 'For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another.'),
  ('KJV', 'GAL', 5, 14, 'For all the law is fulfilled in one word, even in this; Thou shalt love thy neighbour as thyself.'),
  ('KJV', 'GAL', 5, 15, 'But if ye bite and devour one another, take heed that ye be not consumed one of another.'),
  ('KJV', 'GAL', 5, 16, 'This I say then, Walk in the Spirit, and ye shall not fulfil the lust of the flesh.'),
  ('KJV', 'GAL', 5, 17, 'For the flesh lusteth against the Spirit, and the Spirit against the flesh: and these are contrary the one to the other: so that ye cannot do the things that ye would.'),
  ('KJV', 'GAL', 5, 18, 'But if ye be led of the Spirit, ye are not under the law.'),
  ('KJV', 'GAL', 5, 19, 'Now the works of the flesh are manifest, which are these; Adultery, fornication, uncleanness, lasciviousness,'),
  ('KJV', 'GAL', 5, 20, 'Idolatry, witchcraft, hatred, variance, emulations, wrath, strife, seditions, heresies,'),
  ('KJV', 'GAL', 5, 21, 'Envyings, murders, drunkenness, revellings, and such like: of the which I tell you before, as I have also told you in time past, that they which do such things shall not inherit the kingdom of God.'),
  ('KJV', 'GAL', 5, 22, 'But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,'),
  ('KJV', 'GAL', 5, 23, 'Meekness, temperance: against such there is no law.'),
  ('KJV', 'GAL', 5, 24, 'And they that are Christ’s have crucified the flesh with the affections and lusts.'),
  ('KJV', 'GAL', 5, 25, 'If we live in the Spirit, let us also walk in the Spirit.'),
  ('KJV', 'GAL', 5, 26, 'Let us not be desirous of vain glory, provoking one another, envying one another.'),
  ('KJV', 'PHP', 2, 1, 'If there be therefore any consolation in Christ, if any comfort of love, if any fellowship of the Spirit, if any bowels and mercies,'),
  ('KJV', 'PHP', 2, 2, 'Fulfil ye my joy, that ye be likeminded, having the same love, being of one accord, of one mind.'),
  ('KJV', 'PHP', 2, 3, 'Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves.'),
  ('KJV', 'PHP', 2, 4, 'Look not every man on his own things, but every man also on the things of others.'),
  ('KJV', 'PHP', 2, 5, 'Let this mind be in you, which was also in Christ Jesus:'),
  ('KJV', 'PHP', 2, 6, 'Who, being in the form of God, thought it not robbery to be equal with God:'),
  ('KJV', 'PHP', 2, 7, 'But made himself of no reputation, and took upon him the form of a servant, and was made in the likeness of men:'),
  ('KJV', 'PHP', 2, 8, 'And being found in fashion as a man, he humbled himself, and became obedient unto death, even the death of the cross.'),
  ('KJV', 'PHP', 2, 9, 'Wherefore God also hath highly exalted him, and given him a name which is above every name:'),
  ('KJV', 'PHP', 2, 10, 'That at the name of Jesus every knee should bow, of things in heaven, and things in earth, and things under the earth;'),
  ('KJV', 'PHP', 2, 11, 'And that every tongue should confess that Jesus Christ is Lord, to the glory of God the Father.'),
  ('KJV', 'PHP', 2, 12, 'Wherefore, my beloved, as ye have always obeyed, not as in my presence only, but now much more in my absence, work out your own salvation with fear and trembling.'),
  ('KJV', 'PHP', 2, 13, 'For it is God which worketh in you both to will and to do of his good pleasure.'),
  ('KJV', 'PHP', 2, 14, 'Do all things without murmurings and disputings:'),
  ('KJV', 'PHP', 2, 15, 'That ye may be blameless and harmless, the sons of God, without rebuke, in the midst of a crooked and perverse nation, among whom ye shine as lights in the world;'),
  ('KJV', 'PHP', 2, 16, 'Holding forth the word of life; that I may rejoice in the day of Christ, that I have not run in vain, neither laboured in vain.'),
  ('KJV', 'PHP', 2, 17, 'Yea, and if I be offered upon the sacrifice and service of your faith, I joy, and rejoice with you all.'),
  ('KJV', 'PHP', 2, 18, 'For the same cause also do ye joy, and rejoice with me.'),
  ('KJV', 'PHP', 2, 19, 'But I trust in the Lord Jesus to send Timotheus shortly unto you, that I also may be of good comfort, when I know your state.'),
  ('KJV', 'PHP', 2, 20, 'For I have no man likeminded, who will naturally care for your state.'),
  ('KJV', 'PHP', 2, 21, 'For all seek their own, not the things which are Jesus Christ’s.'),
  ('KJV', 'PHP', 2, 22, 'But ye know the proof of him, that, as a son with the father, he hath served with me in the gospel.'),
  ('KJV', 'PHP', 2, 23, 'Him therefore I hope to send presently, so soon as I shall see how it will go with me.'),
  ('KJV', 'PHP', 2, 24, 'But I trust in the Lord that I also myself shall come shortly.'),
  ('KJV', 'PHP', 2, 25, 'Yet I supposed it necessary to send to you Epaphroditus, my brother, and companion in labour, and fellowsoldier, but your messenger, and he that ministered to my wants.'),
  ('KJV', 'PHP', 2, 26, 'For he longed after you all, and was full of heaviness, because that ye had heard that he had been sick.'),
  ('KJV', 'PHP', 2, 27, 'For indeed he was sick nigh unto death: but God had mercy on him; and not on him only, but on me also, lest I should have sorrow upon sorrow.'),
  ('KJV', 'PHP', 2, 28, 'I sent him therefore the more carefully, that, when ye see him again, ye may rejoice, and that I may be the less sorrowful.'),
  ('KJV', 'PHP', 2, 29, 'Receive him therefore in the Lord with all gladness; and hold such in reputation:'),
  ('KJV', 'PHP', 2, 30, 'Because for the work of Christ he was nigh unto death, not regarding his life, to supply your lack of service toward me.'),
  ('KJV', 'PHP', 3, 1, 'Finally, my brethren, rejoice in the Lord. To write the same things to you, to me indeed is not grievous, but for you it is safe.'),
  ('KJV', 'PHP', 3, 2, 'Beware of dogs, beware of evil workers, beware of the concision.'),
  ('KJV', 'PHP', 3, 3, 'For we are the circumcision, which worship God in the spirit, and rejoice in Christ Jesus, and have no confidence in the flesh.'),
  ('KJV', 'PHP', 3, 4, 'Though I might also have confidence in the flesh. If any other man thinketh that he hath whereof he might trust in the flesh, I more:'),
  ('KJV', 'PHP', 3, 5, 'Circumcised the eighth day, of the stock of Israel, of the tribe of Benjamin, an Hebrew of the Hebrews; as touching the law, a Pharisee;'),
  ('KJV', 'PHP', 3, 6, 'Concerning zeal, persecuting the church; touching the righteousness which is in the law, blameless.'),
  ('KJV', 'PHP', 3, 7, 'But what things were gain to me, those I counted loss for Christ.'),
  ('KJV', 'PHP', 3, 8, 'Yea doubtless, and I count all things but loss for the excellency of the knowledge of Christ Jesus my Lord: for whom I have suffered the loss of all things, and do count them but dung, that I may win Christ,'),
  ('KJV', 'PHP', 3, 9, 'And be found in him, not having mine own righteousness, which is of the law, but that which is through the faith of Christ, the righteousness which is of God by faith:'),
  ('KJV', 'PHP', 3, 10, 'That I may know him, and the power of his resurrection, and the fellowship of his sufferings, being made conformable unto his death;'),
  ('KJV', 'PHP', 3, 11, 'If by any means I might attain unto the resurrection of the dead.'),
  ('KJV', 'PHP', 3, 12, 'Not as though I had already attained, either were already perfect: but I follow after, if that I may apprehend that for which also I am apprehended of Christ Jesus.'),
  ('KJV', 'PHP', 3, 13, 'Brethren, I count not myself to have apprehended: but this one thing I do, forgetting those things which are behind, and reaching forth unto those things which are before,'),
  ('KJV', 'PHP', 3, 14, 'I press toward the mark for the prize of the high calling of God in Christ Jesus.'),
  ('KJV', 'PHP', 3, 15, 'Let us therefore, as many as be perfect, be thus minded: and if in any thing ye be otherwise minded, God shall reveal even this unto you.'),
  ('KJV', 'PHP', 3, 16, 'Nevertheless, whereto we have already attained, let us walk by the same rule, let us mind the same thing.'),
  ('KJV', 'PHP', 3, 17, 'Brethren, be followers together of me, and mark them which walk so as ye have us for an ensample.'),
  ('KJV', 'PHP', 3, 18, '(For many walk, of whom I have told you often, and now tell you even weeping, that they are the enemies of the cross of Christ:'),
  ('KJV', 'PHP', 3, 19, 'Whose end is destruction, whose God is their belly, and whose glory is in their shame, who mind earthly things.)'),
  ('KJV', 'PHP', 3, 20, 'For our conversation is in heaven; from whence also we look for the Saviour, the Lord Jesus Christ:'),
  ('KJV', 'PHP', 3, 21, 'Who shall change our vile body, that it may be fashioned like unto his glorious body, according to the working whereby he is able even to subdue all things unto himself.'),
  ('KJV', 'PHP', 4, 1, 'Therefore, my brethren dearly beloved and longed for, my joy and crown, so stand fast in the Lord, my dearly beloved.'),
  ('KJV', 'PHP', 4, 2, 'I beseech Euodias, and beseech Syntyche, that they be of the same mind in the Lord.'),
  ('KJV', 'PHP', 4, 3, 'And I intreat thee also, true yokefellow, help those women which laboured with me in the gospel, with Clement also, and with other my fellowlabourers, whose names are in the book of life.'),
  ('KJV', 'PHP', 4, 4, 'Rejoice in the Lord alway: and again I say, Rejoice.'),
  ('KJV', 'PHP', 4, 5, 'Let your moderation be known unto all men. The Lord is at hand.'),
  ('KJV', 'PHP', 4, 6, 'Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.'),
  ('KJV', 'PHP', 4, 7, 'And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.'),
  ('KJV', 'PHP', 4, 8, 'Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.'),
  ('KJV', 'PHP', 4, 9, 'Those things, which ye have both learned, and received, and heard, and seen in me, do: and the God of peace shall be with you.'),
  ('KJV', 'PHP', 4, 10, 'But I rejoiced in the Lord greatly, that now at the last your care of me hath flourished again; wherein ye were also careful, but ye lacked opportunity.'),
  ('KJV', 'PHP', 4, 11, 'Not that I speak in respect of want: for I have learned, in whatsoever state I am, therewith to be content.'),
  ('KJV', 'PHP', 4, 12, 'I know both how to be abased, and I know how to abound: every where and in all things I am instructed both to be full and to be hungry, both to abound and to suffer need.'),
  ('KJV', 'PHP', 4, 13, 'I can do all things through Christ which strengtheneth me.'),
  ('KJV', 'PHP', 4, 14, 'Notwithstanding ye have well done, that ye did communicate with my affliction.'),
  ('KJV', 'PHP', 4, 15, 'Now ye Philippians know also, that in the beginning of the gospel, when I departed from Macedonia, no church communicated with me as concerning giving and receiving, but ye only.'),
  ('KJV', 'PHP', 4, 16, 'For even in Thessalonica ye sent once and again unto my necessity.'),
  ('KJV', 'PHP', 4, 17, 'Not because I desire a gift: but I desire fruit that may abound to your account.'),
  ('KJV', 'PHP', 4, 18, 'But I have all, and abound: I am full, having received of Epaphroditus the things which were sent from you, an odour of a sweet smell, a sacrifice acceptable, wellpleasing to God.'),
  ('KJV', 'PHP', 4, 19, 'But my God shall supply all your need according to his riches in glory by Christ Jesus.'),
  ('KJV', 'PHP', 4, 20, 'Now unto God and our Father be glory for ever and ever. Amen.'),
  ('KJV', 'PHP', 4, 21, 'Salute every saint in Christ Jesus. The brethren which are with me greet you.'),
  ('KJV', 'PHP', 4, 22, 'All the saints salute you, chiefly they that are of Cesar’s household.'),
  ('KJV', 'PHP', 4, 23, 'The grace of our Lord Jesus Christ be with you all. Amen. It was written to the Philippians from Rome by Epaphroditus.'),
  ('KJV', 'COL', 1, 1, 'Paul, an apostle of Jesus Christ by the will of God, and Timotheus our brother,'),
  ('KJV', 'COL', 1, 2, 'To the saints and faithful brethren in Christ which are at Colosse: Grace be unto you, and peace, from God our Father and the Lord Jesus Christ.'),
  ('KJV', 'COL', 1, 3, 'We give thanks to God and the Father of our Lord Jesus Christ, praying always for you,'),
  ('KJV', 'COL', 1, 4, 'Since we heard of your faith in Christ Jesus, and of the love which ye have to all the saints,'),
  ('KJV', 'COL', 1, 5, 'For the hope which is laid up for you in heaven, whereof ye heard before in the word of the truth of the gospel;'),
  ('KJV', 'COL', 1, 6, 'Which is come unto you, as it is in all the world; and bringeth forth fruit, as it doth also in you, since the day ye heard of it, and knew the grace of God in truth:'),
  ('KJV', 'COL', 1, 7, 'As ye also learned of Epaphras our dear fellowservant, who is for you a faithful minister of Christ;'),
  ('KJV', 'COL', 1, 8, 'Who also declared unto us your love in the Spirit.'),
  ('KJV', 'COL', 1, 9, 'For this cause we also, since the day we heard it, do not cease to pray for you, and to desire that ye might be filled with the knowledge of his will in all wisdom and spiritual understanding;'),
  ('KJV', 'COL', 1, 10, 'That ye might walk worthy of the Lord unto all pleasing, being fruitful in every good work, and increasing in the knowledge of God;'),
  ('KJV', 'COL', 1, 11, 'Strengthened with all might, according to his glorious power, unto all patience and longsuffering with joyfulness;'),
  ('KJV', 'COL', 1, 12, 'Giving thanks unto the Father, which hath made us meet to be partakers of the inheritance of the saints in light:'),
  ('KJV', 'COL', 1, 13, 'Who hath delivered us from the power of darkness, and hath translated us into the kingdom of his dear Son:'),
  ('KJV', 'COL', 1, 14, 'In whom we have redemption through his blood, even the forgiveness of sins:'),
  ('KJV', 'COL', 1, 15, 'Who is the image of the invisible God, the firstborn of every creature:'),
  ('KJV', 'COL', 1, 16, 'For by him were all things created, that are in heaven, and that are in earth, visible and invisible, whether they be thrones, or dominions, or principalities, or powers: all things were created by him, and for him:'),
  ('KJV', 'COL', 1, 17, 'And he is before all things, and by him all things consist.'),
  ('KJV', 'COL', 1, 18, 'And he is the head of the body, the church: who is the beginning, the firstborn from the dead; that in all things he might have the preeminence.'),
  ('KJV', 'COL', 1, 19, 'For it pleased the Father that in him should all fulness dwell;'),
  ('KJV', 'COL', 1, 20, 'And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven.'),
  ('KJV', 'COL', 1, 21, 'And you, that were sometime alienated and enemies in your mind by wicked works, yet now hath he reconciled'),
  ('KJV', 'COL', 1, 22, 'In the body of his flesh through death, to present you holy and unblameable and unreproveable in his sight:'),
  ('KJV', 'COL', 1, 23, 'If ye continue in the faith grounded and settled, and be not moved away from the hope of the gospel, which ye have heard, and which was preached to every creature which is under heaven; whereof I Paul am made a minister;'),
  ('KJV', 'COL', 1, 24, 'Who now rejoice in my sufferings for you, and fill up that which is behind of the afflictions of Christ in my flesh for his body’s sake, which is the church:'),
  ('KJV', 'COL', 1, 25, 'Whereof I am made a minister, according to the dispensation of God which is given to me for you, to fulfil the word of God;'),
  ('KJV', 'COL', 1, 26, 'Even the mystery which hath been hid from ages and from generations, but now is made manifest to his saints:'),
  ('KJV', 'COL', 1, 27, 'To whom God would make known what is the riches of the glory of this mystery among the Gentiles; which is Christ in you, the hope of glory:'),
  ('KJV', 'COL', 1, 28, 'Whom we preach, warning every man, and teaching every man in all wisdom; that we may present every man perfect in Christ Jesus:'),
  ('KJV', 'COL', 1, 29, 'Whereunto I also labour, striving according to his working, which worketh in me mightily.'),
  ('KJV', 'COL', 2, 1, 'For I would that ye knew what great conflict I have for you, and for them at Laodicea, and for as many as have not seen my face in the flesh;'),
  ('KJV', 'COL', 2, 2, 'That their hearts might be comforted, being knit together in love, and unto all riches of the full assurance of understanding, to the acknowledgement of the mystery of God, and of the Father, and of Christ;'),
  ('KJV', 'COL', 2, 3, 'In whom are hid all the treasures of wisdom and knowledge.'),
  ('KJV', 'COL', 2, 4, 'And this I say, lest any man should beguile you with enticing words.'),
  ('KJV', 'COL', 2, 5, 'For though I be absent in the flesh, yet am I with you in the spirit, joying and beholding your order, and the stedfastness of your faith in Christ.'),
  ('KJV', 'COL', 2, 6, 'As ye have therefore received Christ Jesus the Lord, so walk ye in him:'),
  ('KJV', 'COL', 2, 7, 'Rooted and built up in him, and stablished in the faith, as ye have been taught, abounding therein with thanksgiving.'),
  ('KJV', 'COL', 2, 8, 'Beware lest any man spoil you through philosophy and vain deceit, after the tradition of men, after the rudiments of the world, and not after Christ.'),
  ('KJV', 'COL', 2, 9, 'For in him dwelleth all the fulness of the Godhead bodily.'),
  ('KJV', 'COL', 2, 10, 'And ye are complete in him, which is the head of all principality and power:'),
  ('KJV', 'COL', 2, 11, 'In whom also ye are circumcised with the circumcision made without hands, in putting off the body of the sins of the flesh by the circumcision of Christ:'),
  ('KJV', 'COL', 2, 12, 'Buried with him in baptism, wherein also ye are risen with him through the faith of the operation of God, who hath raised him from the dead.'),
  ('KJV', 'COL', 2, 13, 'And you, being dead in your sins and the uncircumcision of your flesh, hath he quickened together with him, having forgiven you all trespasses;'),
  ('KJV', 'COL', 2, 14, 'Blotting out the handwriting of ordinances that was against us, which was contrary to us, and took it out of the way, nailing it to his cross;'),
  ('KJV', 'COL', 2, 15, 'And having spoiled principalities and powers, he made a shew of them openly, triumphing over them in it.'),
  ('KJV', 'COL', 2, 16, 'Let no man therefore judge you in meat, or in drink, or in respect of an holyday, or of the new moon, or of the sabbath days:'),
  ('KJV', 'COL', 2, 17, 'Which are a shadow of things to come; but the body is of Christ.'),
  ('KJV', 'COL', 2, 18, 'Let no man beguile you of your reward in a voluntary humility and worshipping of angels, intruding into those things which he hath not seen, vainly puffed up by his fleshly mind,'),
  ('KJV', 'COL', 2, 19, 'And not holding the Head, from which all the body by joints and bands having nourishment ministered, and knit together, increaseth with the increase of God.'),
  ('KJV', 'COL', 2, 20, 'Wherefore if ye be dead with Christ from the rudiments of the world, why, as though living in the world, are ye subject to ordinances,'),
  ('KJV', 'COL', 2, 21, '(Touch not; taste not; handle not;'),
  ('KJV', 'COL', 2, 22, 'Which all are to perish with the using;) after the commandments and doctrines of men?'),
  ('KJV', 'COL', 2, 23, 'Which things have indeed a shew of wisdom in will worship, and humility, and neglecting of the body; not in any honour to the satisfying of the flesh.'),
  ('KJV', 'COL', 3, 1, 'If ye then be risen with Christ, seek those things which are above, where Christ sitteth on the right hand of God.'),
  ('KJV', 'COL', 3, 2, 'Set your affection on things above, not on things on the earth.'),
  ('KJV', 'COL', 3, 3, 'For ye are dead, and your life is hid with Christ in God.'),
  ('KJV', 'COL', 3, 4, 'When Christ, who is our life, shall appear, then shall ye also appear with him in glory.'),
  ('KJV', 'COL', 3, 5, 'Mortify therefore your members which are upon the earth; fornication, uncleanness, inordinate affection, evil concupiscence, and covetousness, which is idolatry:'),
  ('KJV', 'COL', 3, 6, 'For which things’ sake the wrath of God cometh on the children of disobedience:'),
  ('KJV', 'COL', 3, 7, 'In the which ye also walked some time, when ye lived in them.'),
  ('KJV', 'COL', 3, 8, 'But now ye also put off all these; anger, wrath, malice, blasphemy, filthy communication out of your mouth.'),
  ('KJV', 'COL', 3, 9, 'Lie not one to another, seeing that ye have put off the old man with his deeds;'),
  ('KJV', 'COL', 3, 10, 'And have put on the new man, which is renewed in knowledge after the image of him that created him:'),
  ('KJV', 'COL', 3, 11, 'Where there is neither Greek nor Jew, circumcision nor uncircumcision, Barbarian, Scythian, bond nor free: but Christ is all, and in all.'),
  ('KJV', 'COL', 3, 12, 'Put on therefore, as the elect of God, holy and beloved, bowels of mercies, kindness, humbleness of mind, meekness, longsuffering;'),
  ('KJV', 'COL', 3, 13, 'Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye.'),
  ('KJV', 'COL', 3, 14, 'And above all these things put on charity, which is the bond of perfectness.'),
  ('KJV', 'COL', 3, 15, 'And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.'),
  ('KJV', 'COL', 3, 16, 'Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.'),
  ('KJV', 'COL', 3, 17, 'And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him.'),
  ('KJV', 'COL', 3, 18, 'Wives, submit yourselves unto your own husbands, as it is fit in the Lord.'),
  ('KJV', 'COL', 3, 19, 'Husbands, love your wives, and be not bitter against them.'),
  ('KJV', 'COL', 3, 20, 'Children, obey your parents in all things: for this is well pleasing unto the Lord.'),
  ('KJV', 'COL', 3, 21, 'Fathers, provoke not your children to anger, lest they be discouraged.'),
  ('KJV', 'COL', 3, 22, 'Servants, obey in all things your masters according to the flesh; not with eyeservice, as menpleasers; but in singleness of heart, fearing God:'),
  ('KJV', 'COL', 3, 23, 'And whatsoever ye do, do it heartily, as to the Lord, and not unto men;'),
  ('KJV', 'COL', 3, 24, 'Knowing that of the Lord ye shall receive the reward of the inheritance: for ye serve the Lord Christ.'),
  ('KJV', 'COL', 3, 25, 'But he that doeth wrong shall receive for the wrong which he hath done: and there is no respect of persons.'),
  ('KJV', '1TI', 4, 1, 'Now the Spirit speaketh expressly, that in the latter times some shall depart from the faith, giving heed to seducing spirits, and doctrines of devils;'),
  ('KJV', '1TI', 4, 2, 'Speaking lies in hypocrisy; having their conscience seared with a hot iron;'),
  ('KJV', '1TI', 4, 3, 'Forbidding to marry, and commanding to abstain from meats, which God hath created to be received with thanksgiving of them which believe and know the truth.'),
  ('KJV', '1TI', 4, 4, 'For every creature of God is good, and nothing to be refused, if it be received with thanksgiving:'),
  ('KJV', '1TI', 4, 5, 'For it is sanctified by the word of God and prayer.'),
  ('KJV', '1TI', 4, 6, 'If thou put the brethren in remembrance of these things, thou shalt be a good minister of Jesus Christ, nourished up in the words of faith and of good doctrine, whereunto thou hast attained.'),
  ('KJV', '1TI', 4, 7, 'But refuse profane and old wives’ fables, and exercise thyself rather unto godliness.'),
  ('KJV', '1TI', 4, 8, 'For bodily exercise profiteth little: but godliness is profitable unto all things, having promise of the life that now is, and of that which is to come.'),
  ('KJV', '1TI', 4, 9, 'This is a faithful saying and worthy of all acceptation.'),
  ('KJV', '1TI', 4, 10, 'For therefore we both labour and suffer reproach, because we trust in the living God, who is the Saviour of all men, specially of those that believe.'),
  ('KJV', '1TI', 4, 11, 'These things command and teach.'),
  ('KJV', '1TI', 4, 12, 'Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity.'),
  ('KJV', '1TI', 4, 13, 'Till I come, give attendance to reading, to exhortation, to doctrine.'),
  ('KJV', '1TI', 4, 14, 'Neglect not the gift that is in thee, which was given thee by prophecy, with the laying on of the hands of the presbytery.'),
  ('KJV', '1TI', 4, 15, 'Meditate upon these things; give thyself wholly to them; that thy profiting may appear to all.'),
  ('KJV', '1TI', 4, 16, 'Take heed unto thyself, and unto the doctrine; continue in them: for in doing this thou shalt both save thyself, and them that hear thee.'),
  ('KJV', 'HEB', 11, 1, 'Now faith is the substance of things hoped for, the evidence of things not seen.'),
  ('KJV', 'HEB', 11, 2, 'For by it the elders obtained a good report.'),
  ('KJV', 'HEB', 11, 3, 'Through faith we understand that the worlds were framed by the word of God, so that things which are seen were not made of things which do appear.'),
  ('KJV', 'HEB', 11, 4, 'By faith Abel offered unto God a more excellent sacrifice than Cain, by which he obtained witness that he was righteous, God testifying of his gifts: and by it he being dead yet speaketh.'),
  ('KJV', 'HEB', 11, 5, 'By faith Enoch was translated that he should not see death; and was not found, because God had translated him: for before his translation he had this testimony, that he pleased God.'),
  ('KJV', 'HEB', 11, 6, 'But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.'),
  ('KJV', 'HEB', 11, 7, 'By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house; by the which he condemned the world, and became heir of the righteousness which is by faith.'),
  ('KJV', 'HEB', 11, 8, 'By faith Abraham, when he was called to go out into a place which he should after receive for an inheritance, obeyed; and he went out, not knowing whither he went.'),
  ('KJV', 'HEB', 11, 9, 'By faith he sojourned in the land of promise, as in a strange country, dwelling in tabernacles with Isaac and Jacob, the heirs with him of the same promise:'),
  ('KJV', 'HEB', 11, 10, 'For he looked for a city which hath foundations, whose builder and maker is God.'),
  ('KJV', 'HEB', 11, 11, 'Through faith also Sara herself received strength to conceive seed, and was delivered of a child when she was past age, because she judged him faithful who had promised.'),
  ('KJV', 'HEB', 11, 12, 'Therefore sprang there even of one, and him as good as dead, so many as the stars of the sky in multitude, and as the sand which is by the sea shore innumerable.'),
  ('KJV', 'HEB', 11, 13, 'These all died in faith, not having received the promises, but having seen them afar off, and were persuaded of them, and embraced them, and confessed that they were strangers and pilgrims on the earth.'),
  ('KJV', 'HEB', 11, 14, 'For they that say such things declare plainly that they seek a country.'),
  ('KJV', 'HEB', 11, 15, 'And truly, if they had been mindful of that country from whence they came out, they might have had opportunity to have returned.'),
  ('KJV', 'HEB', 11, 16, 'But now they desire a better country, that is, an heavenly: wherefore God is not ashamed to be called their God: for he hath prepared for them a city.'),
  ('KJV', 'HEB', 11, 17, 'By faith Abraham, when he was tried, offered up Isaac: and he that had received the promises offered up his only begotten son,'),
  ('KJV', 'HEB', 11, 18, 'Of whom it was said, That in Isaac shall thy seed be called:'),
  ('KJV', 'HEB', 11, 19, 'Accounting that God was able to raise him up, even from the dead; from whence also he received him in a figure.'),
  ('KJV', 'HEB', 11, 20, 'By faith Isaac blessed Jacob and Esau concerning things to come.'),
  ('KJV', 'HEB', 11, 21, 'By faith Jacob, when he was a dying, blessed both the sons of Joseph; and worshipped, leaning upon the top of his staff.'),
  ('KJV', 'HEB', 11, 22, 'By faith Joseph, when he died, made mention of the departing of the children of Israel; and gave commandment concerning his bones.'),
  ('KJV', 'HEB', 11, 23, 'By faith Moses, when he was born, was hid three months of his parents, because they saw he was a proper child; and they were not afraid of the king’s commandment.'),
  ('KJV', 'HEB', 11, 24, 'By faith Moses, when he was come to years, refused to be called the son of Pharaoh’s daughter;'),
  ('KJV', 'HEB', 11, 25, 'Choosing rather to suffer affliction with the people of God, than to enjoy the pleasures of sin for a season;'),
  ('KJV', 'HEB', 11, 26, 'Esteeming the reproach of Christ greater riches than the treasures in Egypt: for he had respect unto the recompence of the reward.'),
  ('KJV', 'HEB', 11, 27, 'By faith he forsook Egypt, not fearing the wrath of the king: for he endured, as seeing him who is invisible.'),
  ('KJV', 'HEB', 11, 28, 'Through faith he kept the passover, and the sprinkling of blood, lest he that destroyed the firstborn should touch them.'),
  ('KJV', 'HEB', 11, 29, 'By faith they passed through the Red sea as by dry land: which the Egyptians assaying to do were drowned.'),
  ('KJV', 'HEB', 11, 30, 'By faith the walls of Jericho fell down, after they were compassed about seven days.'),
  ('KJV', 'HEB', 11, 31, 'By faith the harlot Rahab perished not with them that believed not, when she had received the spies with peace.'),
  ('KJV', 'HEB', 11, 32, 'And what shall I more say? for the time would fail me to tell of Gedeon, and of Barak, and of Samson, and of Jephthae; of David also, and Samuel, and of the prophets:'),
  ('KJV', 'HEB', 11, 33, 'Who through faith subdued kingdoms, wrought righteousness, obtained promises, stopped the mouths of lions,'),
  ('KJV', 'HEB', 11, 34, 'Quenched the violence of fire, escaped the edge of the sword, out of weakness were made strong, waxed valiant in fight, turned to flight the armies of the aliens.'),
  ('KJV', 'HEB', 11, 35, 'Women received their dead raised to life again: and others were tortured, not accepting deliverance; that they might obtain a better resurrection:'),
  ('KJV', 'HEB', 11, 36, 'And others had trial of cruel mockings and scourgings, yea, moreover of bonds and imprisonment:'),
  ('KJV', 'HEB', 11, 37, 'They were stoned, they were sawn asunder, were tempted, were slain with the sword: they wandered about in sheepskins and goatskins; being destitute, afflicted, tormented;'),
  ('KJV', 'HEB', 11, 38, '(Of whom the world was not worthy:) they wandered in deserts, and in mountains, and in dens and caves of the earth.'),
  ('KJV', 'HEB', 11, 39, 'And these all, having obtained a good report through faith, received not the promise:'),
  ('KJV', 'HEB', 11, 40, 'God having provided some better thing for us, that they without us should not be made perfect.'),
  ('KJV', 'HEB', 13, 1, 'Let brotherly love continue.'),
  ('KJV', 'HEB', 13, 2, 'Be not forgetful to entertain strangers: for thereby some have entertained angels unawares.'),
  ('KJV', 'HEB', 13, 3, 'Remember them that are in bonds, as bound with them; and them which suffer adversity, as being yourselves also in the body.'),
  ('KJV', 'HEB', 13, 4, 'Marriage is honourable in all, and the bed undefiled: but whoremongers and adulterers God will judge.'),
  ('KJV', 'HEB', 13, 5, 'Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.'),
  ('KJV', 'HEB', 13, 6, 'So that we may boldly say, The Lord is my helper, and I will not fear what man shall do unto me.'),
  ('KJV', 'HEB', 13, 7, 'Remember them which have the rule over you, who have spoken unto you the word of God: whose faith follow, considering the end of their conversation.'),
  ('KJV', 'HEB', 13, 8, 'Jesus Christ the same yesterday, and to day, and for ever.'),
  ('KJV', 'HEB', 13, 9, 'Be not carried about with divers and strange doctrines. For it is a good thing that the heart be established with grace; not with meats, which have not profited them that have been occupied therein.'),
  ('KJV', 'HEB', 13, 10, 'We have an altar, whereof they have no right to eat which serve the tabernacle.'),
  ('KJV', 'HEB', 13, 11, 'For the bodies of those beasts, whose blood is brought into the sanctuary by the high priest for sin, are burned without the camp.'),
  ('KJV', 'HEB', 13, 12, 'Wherefore Jesus also, that he might sanctify the people with his own blood, suffered without the gate.'),
  ('KJV', 'HEB', 13, 13, 'Let us go forth therefore unto him without the camp, bearing his reproach.'),
  ('KJV', 'HEB', 13, 14, 'For here have we no continuing city, but we seek one to come.'),
  ('KJV', 'HEB', 13, 15, 'By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name.'),
  ('KJV', 'HEB', 13, 16, 'But to do good and to communicate forget not: for with such sacrifices God is well pleased.'),
  ('KJV', 'HEB', 13, 17, 'Obey them that have the rule over you, and submit yourselves: for they watch for your souls, as they that must give account, that they may do it with joy, and not with grief: for that is unprofitable for you.'),
  ('KJV', 'HEB', 13, 18, 'Pray for us: for we trust we have a good conscience, in all things willing to live honestly.'),
  ('KJV', 'HEB', 13, 19, 'But I beseech you the rather to do this, that I may be restored to you the sooner.'),
  ('KJV', 'HEB', 13, 20, 'Now the God of peace, that brought again from the dead our Lord Jesus, that great shepherd of the sheep, through the blood of the everlasting covenant,'),
  ('KJV', 'HEB', 13, 21, 'Make you perfect in every good work to do his will, working in you that which is wellpleasing in his sight, through Jesus Christ; to whom be glory for ever and ever. Amen.'),
  ('KJV', 'HEB', 13, 22, 'And I beseech you, brethren, suffer the word of exhortation: for I have written a letter unto you in few words.'),
  ('KJV', 'HEB', 13, 23, 'Know ye that our brother Timothy is set at liberty; with whom, if he come shortly, I will see you.'),
  ('KJV', 'HEB', 13, 24, 'Salute all them that have the rule over you, and all the saints. They of Italy salute you.'),
  ('KJV', 'HEB', 13, 25, 'Grace be with you all. Amen. Written to the Hebrews from Italy by Timothy.'),
  ('KJV', 'JAS', 4, 1, 'From whence come wars and fightings among you? come they not hence, even of your lusts that war in your members?'),
  ('KJV', 'JAS', 4, 2, 'Ye lust, and have not: ye kill, and desire to have, and cannot obtain: ye fight and war, yet ye have not, because ye ask not.'),
  ('KJV', 'JAS', 4, 3, 'Ye ask, and receive not, because ye ask amiss, that ye may consume it upon your lusts.'),
  ('KJV', 'JAS', 4, 4, 'Ye adulterers and adulteresses, know ye not that the friendship of the world is enmity with God? whosoever therefore will be a friend of the world is the enemy of God.'),
  ('KJV', 'JAS', 4, 5, 'Do ye think that the scripture saith in vain, The spirit that dwelleth in us lusteth to envy?'),
  ('KJV', 'JAS', 4, 6, 'But he giveth more grace. Wherefore he saith, God resisteth the proud, but giveth grace unto the humble.'),
  ('KJV', 'JAS', 4, 7, 'Submit yourselves therefore to God. Resist the devil, and he will flee from you.'),
  ('KJV', 'JAS', 4, 8, 'Draw nigh to God, and he will draw nigh to you. Cleanse your hands, ye sinners; and purify your hearts, ye double minded.'),
  ('KJV', 'JAS', 4, 9, 'Be afflicted, and mourn, and weep: let your laughter be turned to mourning, and your joy to heaviness.'),
  ('KJV', 'JAS', 4, 10, 'Humble yourselves in the sight of the Lord, and he shall lift you up.'),
  ('KJV', 'JAS', 4, 11, 'Speak not evil one of another, brethren. He that speaketh evil of his brother, and judgeth his brother, speaketh evil of the law, and judgeth the law: but if thou judge the law, thou art not a doer of the law, but a judge.'),
  ('KJV', 'JAS', 4, 12, 'There is one lawgiver, who is able to save and to destroy: who art thou that judgest another?'),
  ('KJV', 'JAS', 4, 13, 'Go to now, ye that say, To day or to morrow we will go into such a city, and continue there a year, and buy and sell, and get gain:'),
  ('KJV', 'JAS', 4, 14, 'Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away.'),
  ('KJV', 'JAS', 4, 15, 'For that ye ought to say, If the Lord will, we shall live, and do this, or that.'),
  ('KJV', 'JAS', 4, 16, 'But now ye rejoice in your boastings: all such rejoicing is evil.'),
  ('KJV', 'JAS', 4, 17, 'Therefore to him that knoweth to do good, and doeth it not, to him it is sin.'),
  ('KJV', '1PE', 1, 1, 'Peter, an apostle of Jesus Christ, to the strangers scattered throughout Pontus, Galatia, Cappadocia, Asia, and Bithynia,'),
  ('KJV', '1PE', 1, 2, 'Elect according to the foreknowledge of God the Father, through sanctification of the Spirit, unto obedience and sprinkling of the blood of Jesus Christ: Grace unto you, and peace, be multiplied.'),
  ('KJV', '1PE', 1, 3, 'Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead,'),
  ('KJV', '1PE', 1, 4, 'To an inheritance incorruptible, and undefiled, and that fadeth not away, reserved in heaven for you,'),
  ('KJV', '1PE', 1, 5, 'Who are kept by the power of God through faith unto salvation ready to be revealed in the last time.'),
  ('KJV', '1PE', 1, 6, 'Wherein ye greatly rejoice, though now for a season, if need be, ye are in heaviness through manifold temptations:'),
  ('KJV', '1PE', 1, 7, 'That the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire, might be found unto praise and honour and glory at the appearing of Jesus Christ:'),
  ('KJV', '1PE', 1, 8, 'Whom having not seen, ye love; in whom, though now ye see him not, yet believing, ye rejoice with joy unspeakable and full of glory:'),
  ('KJV', '1PE', 1, 9, 'Receiving the end of your faith, even the salvation of your souls.'),
  ('KJV', '1PE', 1, 10, 'Of which salvation the prophets have enquired and searched diligently, who prophesied of the grace that should come unto you:'),
  ('KJV', '1PE', 1, 11, 'Searching what, or what manner of time the Spirit of Christ which was in them did signify, when it testified beforehand the sufferings of Christ, and the glory that should follow.'),
  ('KJV', '1PE', 1, 12, 'Unto whom it was revealed, that not unto themselves, but unto us they did minister the things, which are now reported unto you by them that have preached the gospel unto you with the Holy Ghost sent down from heaven; which things the angels desire to look into.'),
  ('KJV', '1PE', 1, 13, 'Wherefore gird up the loins of your mind, be sober, and hope to the end for the grace that is to be brought unto you at the revelation of Jesus Christ;'),
  ('KJV', '1PE', 1, 14, 'As obedient children, not fashioning yourselves according to the former lusts in your ignorance:'),
  ('KJV', '1PE', 1, 15, 'But as he which hath called you is holy, so be ye holy in all manner of conversation;'),
  ('KJV', '1PE', 1, 16, 'Because it is written, Be ye holy; for I am holy.'),
  ('KJV', '1PE', 1, 17, 'And if ye call on the Father, who without respect of persons judgeth according to every man’s work, pass the time of your sojourning here in fear:'),
  ('KJV', '1PE', 1, 18, 'Forasmuch as ye know that ye were not redeemed with corruptible things, as silver and gold, from your vain conversation received by tradition from your fathers;'),
  ('KJV', '1PE', 1, 19, 'But with the precious blood of Christ, as of a lamb without blemish and without spot:'),
  ('KJV', '1PE', 1, 20, 'Who verily was foreordained before the foundation of the world, but was manifest in these last times for you,'),
  ('KJV', '1PE', 1, 21, 'Who by him do believe in God, that raised him up from the dead, and gave him glory; that your faith and hope might be in God.'),
  ('KJV', '1PE', 1, 22, 'Seeing ye have purified your souls in obeying the truth through the Spirit unto unfeigned love of the brethren, see that ye love one another with a pure heart fervently:'),
  ('KJV', '1PE', 1, 23, 'Being born again, not of corruptible seed, but of incorruptible, by the word of God, which liveth and abideth for ever.'),
  ('KJV', '1PE', 1, 24, 'For all flesh is as grass, and all the glory of man as the flower of grass. The grass withereth, and the flower thereof falleth away:'),
  ('KJV', '1PE', 1, 25, 'But the word of the Lord endureth for ever. And this is the word which by the gospel is preached unto you.'),
  ('KJV', '1JN', 1, 1, 'That which was from the beginning, which we have heard, which we have seen with our eyes, which we have looked upon, and our hands have handled, of the Word of life;'),
  ('KJV', '1JN', 1, 2, '(For the life was manifested, and we have seen it, and bear witness, and shew unto you that eternal life, which was with the Father, and was manifested unto us;)'),
  ('KJV', '1JN', 1, 3, 'That which we have seen and heard declare we unto you, that ye also may have fellowship with us: and truly our fellowship is with the Father, and with his Son Jesus Christ.'),
  ('KJV', '1JN', 1, 4, 'And these things write we unto you, that your joy may be full.'),
  ('KJV', '1JN', 1, 5, 'This then is the message which we have heard of him, and declare unto you, that God is light, and in him is no darkness at all.'),
  ('KJV', '1JN', 1, 6, 'If we say that we have fellowship with him, and walk in darkness, we lie, and do not the truth:'),
  ('KJV', '1JN', 1, 7, 'But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.'),
  ('KJV', '1JN', 1, 8, 'If we say that we have no sin, we deceive ourselves, and the truth is not in us.'),
  ('KJV', '1JN', 1, 9, 'If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.'),
  ('KJV', '1JN', 1, 10, 'If we say that we have not sinned, we make him a liar, and his word is not in us.'),
  ('KJV', '1JN', 2, 1, 'My little children, these things write I unto you, that ye sin not. And if any man sin, we have an advocate with the Father, Jesus Christ the righteous:'),
  ('KJV', '1JN', 2, 2, 'And he is the propitiation for our sins: and not for ours only, but also for the sins of the whole world.'),
  ('KJV', '1JN', 2, 3, 'And hereby we do know that we know him, if we keep his commandments.'),
  ('KJV', '1JN', 2, 4, 'He that saith, I know him, and keepeth not his commandments, is a liar, and the truth is not in him.'),
  ('KJV', '1JN', 2, 5, 'But whoso keepeth his word, in him verily is the love of God perfected: hereby know we that we are in him.'),
  ('KJV', '1JN', 2, 6, 'He that saith he abideth in him ought himself also so to walk, even as he walked.'),
  ('KJV', '1JN', 2, 7, 'Brethren, I write no new commandment unto you, but an old commandment which ye had from the beginning. The old commandment is the word which ye have heard from the beginning.'),
  ('KJV', '1JN', 2, 8, 'Again, a new commandment I write unto you, which thing is true in him and in you: because the darkness is past, and the true light now shineth.'),
  ('KJV', '1JN', 2, 9, 'He that saith he is in the light, and hateth his brother, is in darkness even until now.'),
  ('KJV', '1JN', 2, 10, 'He that loveth his brother abideth in the light, and there is none occasion of stumbling in him.'),
  ('KJV', '1JN', 2, 11, 'But he that hateth his brother is in darkness, and walketh in darkness, and knoweth not whither he goeth, because that darkness hath blinded his eyes.'),
  ('KJV', '1JN', 2, 12, 'I write unto you, little children, because your sins are forgiven you for his name’s sake.'),
  ('KJV', '1JN', 2, 13, 'I write unto you, fathers, because ye have known him that is from the beginning. I write unto you, young men, because ye have overcome the wicked one. I write unto you, little children, because ye have known the Father.'),
  ('KJV', '1JN', 2, 14, 'I have written unto you, fathers, because ye have known him that is from the beginning. I have written unto you, young men, because ye are strong, and the word of God abideth in you, and ye have overcome the wicked one.'),
  ('KJV', '1JN', 2, 15, 'Love not the world, neither the things that are in the world. If any man love the world, the love of the Father is not in him.'),
  ('KJV', '1JN', 2, 16, 'For all that is in the world, the lust of the flesh, and the lust of the eyes, and the pride of life, is not of the Father, but is of the world.'),
  ('KJV', '1JN', 2, 17, 'And the world passeth away, and the lust thereof: but he that doeth the will of God abideth for ever.'),
  ('KJV', '1JN', 2, 18, 'Little children, it is the last time: and as ye have heard that antichrist shall come, even now are there many antichrists; whereby we know that it is the last time.'),
  ('KJV', '1JN', 2, 19, 'They went out from us, but they were not of us; for if they had been of us, they would no doubt have continued with us: but they went out, that they might be made manifest that they were not all of us.'),
  ('KJV', '1JN', 2, 20, 'But ye have an unction from the Holy One, and ye know all things.'),
  ('KJV', '1JN', 2, 21, 'I have not written unto you because ye know not the truth, but because ye know it, and that no lie is of the truth.'),
  ('KJV', '1JN', 2, 22, 'Who is a liar but he that denieth that Jesus is the Christ? He is antichrist, that denieth the Father and the Son.'),
  ('KJV', '1JN', 2, 23, 'Whosoever denieth the Son, the same hath not the Father: [but] he that acknowledgeth the Son hath the Father also.'),
  ('KJV', '1JN', 2, 24, 'Let that therefore abide in you, which ye have heard from the beginning. If that which ye have heard from the beginning shall remain in you, ye also shall continue in the Son, and in the Father.'),
  ('KJV', '1JN', 2, 25, 'And this is the promise that he hath promised us, even eternal life.'),
  ('KJV', '1JN', 2, 26, 'These things have I written unto you concerning them that seduce you.'),
  ('KJV', '1JN', 2, 27, 'But the anointing which ye have received of him abideth in you, and ye need not that any man teach you: but as the same anointing teacheth you of all things, and is truth, and is no lie, and even as it hath taught you, ye shall abide in him.'),
  ('KJV', '1JN', 2, 28, 'And now, little children, abide in him; that, when he shall appear, we may have confidence, and not be ashamed before him at his coming.'),
  ('KJV', '1JN', 2, 29, 'If ye know that he is righteous, ye know that every one that doeth righteousness is born of him.'),
  ('KJV', '1JN', 3, 1, 'Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.'),
  ('KJV', '1JN', 3, 2, 'Beloved, now are we the sons of God, and it doth not yet appear what we shall be: but we know that, when he shall appear, we shall be like him; for we shall see him as he is.'),
  ('KJV', '1JN', 3, 3, 'And every man that hath this hope in him purifieth himself, even as he is pure.'),
  ('KJV', '1JN', 3, 4, 'Whosoever committeth sin transgresseth also the law: for sin is the transgression of the law.'),
  ('KJV', '1JN', 3, 5, 'And ye know that he was manifested to take away our sins; and in him is no sin.'),
  ('KJV', '1JN', 3, 6, 'Whosoever abideth in him sinneth not: whosoever sinneth hath not seen him, neither known him.'),
  ('KJV', '1JN', 3, 7, 'Little children, let no man deceive you: he that doeth righteousness is righteous, even as he is righteous.'),
  ('KJV', '1JN', 3, 8, 'He that committeth sin is of the devil; for the devil sinneth from the beginning. For this purpose the Son of God was manifested, that he might destroy the works of the devil.'),
  ('KJV', '1JN', 3, 9, 'Whosoever is born of God doth not commit sin; for his seed remaineth in him: and he cannot sin, because he is born of God.'),
  ('KJV', '1JN', 3, 10, 'In this the children of God are manifest, and the children of the devil: whosoever doeth not righteousness is not of God, neither he that loveth not his brother.'),
  ('KJV', '1JN', 3, 11, 'For this is the message that ye heard from the beginning, that we should love one another.'),
  ('KJV', '1JN', 3, 12, 'Not as Cain, who was of that wicked one, and slew his brother. And wherefore slew he him? Because his own works were evil, and his brother’s righteous.'),
  ('KJV', '1JN', 3, 13, 'Marvel not, my brethren, if the world hate you.'),
  ('KJV', '1JN', 3, 14, 'We know that we have passed from death unto life, because we love the brethren. He that loveth not his brother abideth in death.'),
  ('KJV', '1JN', 3, 15, 'Whosoever hateth his brother is a murderer: and ye know that no murderer hath eternal life abiding in him.'),
  ('KJV', '1JN', 3, 16, 'Hereby perceive we the love of God, because he laid down his life for us: and we ought to lay down our lives for the brethren.'),
  ('KJV', '1JN', 3, 17, 'But whoso hath this world’s good, and seeth his brother have need, and shutteth up his bowels of compassion from him, how dwelleth the love of God in him?'),
  ('KJV', '1JN', 3, 18, 'My little children, let us not love in word, neither in tongue; but in deed and in truth.'),
  ('KJV', '1JN', 3, 19, 'And hereby we know that we are of the truth, and shall assure our hearts before him.'),
  ('KJV', '1JN', 3, 20, 'For if our heart condemn us, God is greater than our heart, and knoweth all things.'),
  ('KJV', '1JN', 3, 21, 'Beloved, if our heart condemn us not, then have we confidence toward God.'),
  ('KJV', '1JN', 3, 22, 'And whatsoever we ask, we receive of him, because we keep his commandments, and do those things that are pleasing in his sight.'),
  ('KJV', '1JN', 3, 23, 'And this is his commandment, That we should believe on the name of his Son Jesus Christ, and love one another, as he gave us commandment.'),
  ('KJV', '1JN', 3, 24, 'And he that keepeth his commandments dwelleth in him, and he in him. And hereby we know that he abideth in us, by the Spirit which he hath given us.'),
  ('KJV', 'REV', 19, 1, 'And after these things I heard a great voice of much people in heaven, saying, Alleluia; Salvation, and glory, and honour, and power, unto the Lord our God:'),
  ('KJV', 'REV', 19, 2, 'For true and righteous are his judgments: for he hath judged the great whore, which did corrupt the earth with her fornication, and hath avenged the blood of his servants at her hand.'),
  ('KJV', 'REV', 19, 3, 'And again they said, Alleluia. And her smoke rose up for ever and ever.'),
  ('KJV', 'REV', 19, 4, 'And the four and twenty elders and the four beasts fell down and worshipped God that sat on the throne, saying, Amen; Alleluia.'),
  ('KJV', 'REV', 19, 5, 'And a voice came out of the throne, saying, Praise our God, all ye his servants, and ye that fear him, both small and great.'),
  ('KJV', 'REV', 19, 6, 'And I heard as it were the voice of a great multitude, and as the voice of many waters, and as the voice of mighty thunderings, saying, Alleluia: for the Lord God omnipotent reigneth.'),
  ('KJV', 'REV', 19, 7, 'Let us be glad and rejoice, and give honour to him: for the marriage of the Lamb is come, and his wife hath made herself ready.'),
  ('KJV', 'REV', 19, 8, 'And to her was granted that she should be arrayed in fine linen, clean and white: for the fine linen is the righteousness of saints.'),
  ('KJV', 'REV', 19, 9, 'And he saith unto me, Write, Blessed are they which are called unto the marriage supper of the Lamb. And he saith unto me, These are the true sayings of God.'),
  ('KJV', 'REV', 19, 10, 'And I fell at his feet to worship him. And he said unto me, See thou do it not: I am thy fellowservant, and of thy brethren that have the testimony of Jesus: worship God: for the testimony of Jesus is the spirit of prophecy.'),
  ('KJV', 'REV', 19, 11, 'And I saw heaven opened, and behold a white horse; and he that sat upon him was called Faithful and True, and in righteousness he doth judge and make war.'),
  ('KJV', 'REV', 19, 12, 'His eyes were as a flame of fire, and on his head were many crowns; and he had a name written, that no man knew, but he himself.'),
  ('KJV', 'REV', 19, 13, 'And he was clothed with a vesture dipped in blood: and his name is called The Word of God.'),
  ('KJV', 'REV', 19, 14, 'And the armies which were in heaven followed him upon white horses, clothed in fine linen, white and clean.'),
  ('KJV', 'REV', 19, 15, 'And out of his mouth goeth a sharp sword, that with it he should smite the nations: and he shall rule them with a rod of iron: and he treadeth the winepress of the fierceness and wrath of Almighty God.'),
  ('KJV', 'REV', 19, 16, 'And he hath on his vesture and on his thigh a name written, KING OF KINGS, AND LORD OF LORDS.'),
  ('KJV', 'REV', 19, 17, 'And I saw an angel standing in the sun; and he cried with a loud voice, saying to all the fowls that fly in the midst of heaven, Come and gather yourselves together unto the supper of the great God;'),
  ('KJV', 'REV', 19, 18, 'That ye may eat the flesh of kings, and the flesh of captains, and the flesh of mighty men, and the flesh of horses, and of them that sit on them, and the flesh of all men, both free and bond, both small and great.'),
  ('KJV', 'REV', 19, 19, 'And I saw the beast, and the kings of the earth, and their armies, gathered together to make war against him that sat on the horse, and against his army.'),
  ('KJV', 'REV', 19, 20, 'And the beast was taken, and with him the false prophet that wrought miracles before him, with which he deceived them that had received the mark of the beast, and them that worshipped his image. These both were cast alive into a lake of fire burning with brimstone.'),
  ('KJV', 'REV', 19, 21, 'And the remnant were slain with the sword of him that sat upon the horse, which sword proceeded out of his mouth: and all the fowls were filled with their flesh.'),
  ('YLT', 'GEN', 1, 1, 'In the beginning of God''s preparing the heavens and the earth--'),
  ('YLT', 'GEN', 1, 2, 'the earth hath existed waste and void, and darkness is on the face of the deep, and the Spirit of God fluttering on the face of the waters,'),
  ('YLT', 'GEN', 1, 3, 'and God saith, `Let light be;'' and light is.'),
  ('YLT', 'GEN', 1, 4, 'And God seeth the light that it is good, and God separateth between the light and the darkness,'),
  ('YLT', 'GEN', 1, 5, 'and God calleth to the light `Day,'' and to the darkness He hath called `Night;'' and there is an evening, and there is a morning--day one.'),
  ('YLT', 'GEN', 1, 6, 'And God saith, `Let an expanse be in the midst of the waters, and let it be separating between waters and waters.'''),
  ('YLT', 'GEN', 1, 7, 'And God maketh the expanse, and it separateth between the waters which are under the expanse, and the waters which are above the expanse: and it is so.'),
  ('YLT', 'GEN', 1, 8, 'And God calleth to the expanse `Heavens;'' and there is an evening, and there is a morning--day second.'),
  ('YLT', 'GEN', 1, 9, 'And God saith, `Let the waters under the heavens be collected unto one place, and let the dry land be seen:'' and it is so.'),
  ('YLT', 'GEN', 1, 10, 'And God calleth to the dry land `Earth,'' and to the collection of the waters He hath called `Seas;'' and God seeth that it is good.'),
  ('YLT', 'GEN', 1, 11, 'And God saith, `Let the earth yield tender grass, herb sowing seed, fruit-tree (whose seed is in itself) making fruit after its kind, on the earth:'' and it is so.'),
  ('YLT', 'GEN', 1, 12, 'And the earth bringeth forth tender grass, herb sowing seed after its kind, and tree making fruit (whose seed is in itself) after its kind; and God seeth that it is good;'),
  ('YLT', 'GEN', 1, 13, 'and there is an evening, and there is a morning--day third.'),
  ('YLT', 'GEN', 1, 14, 'And God saith, `Let luminaries be in the expanse of the heavens, to make a separation between the day and the night, then they have been for signs, and for seasons, and for days and years,'),
  ('YLT', 'GEN', 1, 15, 'and they have been for luminaries in the expanse of the heavens to give light upon the earth:'' and it is so.'),
  ('YLT', 'GEN', 1, 16, 'And God maketh the two great luminaries, the great luminary for the rule of the day, and the small luminary--and the stars--for the rule of the night;'),
  ('YLT', 'GEN', 1, 17, 'and God giveth them in the expanse of the heavens to give light upon the earth,'),
  ('YLT', 'GEN', 1, 18, 'and to rule over day and over night, and to make a separation between the light and the darkness; and God seeth that it is good;'),
  ('YLT', 'GEN', 1, 19, 'and there is an evening, and there is a morning--day fourth.'),
  ('YLT', 'GEN', 1, 20, 'And God saith, `Let the waters teem with the teeming living creature, and fowl let fly on the earth on the face of the expanse of the heavens.'''),
  ('YLT', 'GEN', 1, 21, 'And God prepareth the great monsters, and every living creature that is creeping, which the waters have teemed with, after their kind, and every fowl with wing, after its kind, and God seeth that it is good.'),
  ('YLT', 'GEN', 1, 22, 'And God blesseth them, saying, `Be fruitful, and multiply, and fill the waters in the seas, and the fowl let multiply in the earth:'''),
  ('YLT', 'GEN', 1, 23, 'and there is an evening, and there is a morning--day fifth.'),
  ('YLT', 'GEN', 1, 24, 'And God saith, `Let the earth bring forth the living creature after its kind, cattle and creeping thing, and beast of the earth after its kind:'' and it is so.'),
  ('YLT', 'GEN', 1, 25, 'And God maketh the beast of the earth after its kind, and the cattle after their kind, and every creeping thing of the ground after its kind, and God seeth that it is good.'),
  ('YLT', 'GEN', 1, 26, 'And God saith, `Let Us make man in Our image, according to Our likeness, and let them rule over fish of the sea, and over fowl of the heavens, and over cattle, and over all the earth, and over every creeping thing that is creeping on the earth.'''),
  ('YLT', 'GEN', 1, 27, 'And God prepareth the man in His image; in the image of God He prepared him, a male and a female He prepared them.'),
  ('YLT', 'GEN', 1, 28, 'And God blesseth them, and God saith to them, `Be fruitful, and multiply, and fill the earth, and subdue it, and rule over fish of the sea, and over fowl of the heavens, and over every living thing that is creeping upon the earth.'''),
  ('YLT', 'GEN', 1, 29, 'And God saith, `Lo, I have given to you every herb sowing seed, which is upon the face of all the earth, and every tree in which is the fruit of a tree sowing seed, to you it is for food;'),
  ('YLT', 'GEN', 1, 30, 'and to every beast of the earth, and to every fowl of the heavens, and to every creeping thing on the earth, in which is breath of life, every green herb is for food:'' and it is so.'),
  ('YLT', 'GEN', 1, 31, 'And God seeth all that He hath done, and lo, very good; and there is an evening, and there is a morning--day the sixth.'),
  ('YLT', 'GEN', 5, 1, 'This is an account of the births of Adam: In the day of God''s preparing man, in the likeness of God He hath made him;'),
  ('YLT', 'GEN', 5, 2, 'a male and a female He hath prepared them, and He blesseth them, and calleth their name Man, in the day of their being prepared.'),
  ('YLT', 'GEN', 5, 3, 'And Adam liveth an hundred and thirty years, and begetteth a son in his likeness, according to his image, and calleth his name Seth.'),
  ('YLT', 'GEN', 5, 4, 'And the days of Adam after his begetting Seth are eight hundred years, and he begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 5, 'And all the days of Adam which he lived are nine hundred and thirty years, and he dieth.'),
  ('YLT', 'GEN', 5, 6, 'And Seth liveth an hundred and five years, and begetteth Enos.'),
  ('YLT', 'GEN', 5, 7, 'And Seth liveth after his begetting Enos eight hundred and seven years, and begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 8, 'And all the days of Seth are nine hundred and twelve years, and he dieth.'),
  ('YLT', 'GEN', 5, 9, 'And Enos liveth ninety years, and begetteth Cainan.'),
  ('YLT', 'GEN', 5, 10, 'And Enos liveth after his begetting Cainan eight hundred and fifteen years, and begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 11, 'And all the days of Enos are nine hundred and five years, and he dieth.'),
  ('YLT', 'GEN', 5, 12, 'And Cainan liveth seventy years, and begetteth Mahalaleel.'),
  ('YLT', 'GEN', 5, 13, 'And Cainan liveth after his begetting Mahalaleel eight hundred and forty years, and begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 14, 'And all the days of Cainan are nine hundred and ten years, and he dieth.'),
  ('YLT', 'GEN', 5, 15, 'And Mahalaleel liveth five and sixty years, and begetteth Jared.'),
  ('YLT', 'GEN', 5, 16, 'And Mahalaleel liveth after his begetting Jared eight hundred and thirty years, and begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 17, 'And all the days of Mahalaleel are eight hundred and ninety and five years, and he dieth.'),
  ('YLT', 'GEN', 5, 18, 'And Jared liveth an hundred and sixty and two years, and begetteth Enoch.'),
  ('YLT', 'GEN', 5, 19, 'And Jared liveth after his begetting Enoch eight hundred years, and begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 20, 'And all the days of Jared are nine hundred and sixty and two years, and he dieth.'),
  ('YLT', 'GEN', 5, 21, 'And Enoch liveth five and sixty years, and begetteth Methuselah.'),
  ('YLT', 'GEN', 5, 22, 'And Enoch walketh habitually with God after his begetting Methuselah three hundred years, and begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 23, 'And all the days of Enoch are three hundred and sixty and five years.'),
  ('YLT', 'GEN', 5, 24, 'And Enoch walketh habitually with God, and he is not, for God hath taken him.'),
  ('YLT', 'GEN', 5, 25, 'And Methuselah liveth an hundred and eighty and seven years, and begetteth Lamech.'),
  ('YLT', 'GEN', 5, 26, 'And Methuselah liveth after his begetting Lamech seven hundred and eighty and two years, and begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 27, 'And all the days of Methuselah are nine hundred and sixty and nine years, and he dieth.'),
  ('YLT', 'GEN', 5, 28, 'And Lamech liveth an hundred and eighty and two years, and begetteth a son,'),
  ('YLT', 'GEN', 5, 29, 'and calleth his name Noah, saying, `This one doth comfort us concerning our work, and concerning the labour of our hands, because of the ground which Jehovah hath cursed.'''),
  ('YLT', 'GEN', 5, 30, 'And Lamech liveth after his begetting Noah five hundred and ninety and five years, and begetteth sons and daughters.'),
  ('YLT', 'GEN', 5, 31, 'And all the days of Lamech are seven hundred and seventy and seven years, and he dieth.'),
  ('YLT', 'GEN', 5, 32, 'And Noah is a son of five hundred years, and Noah begetteth Shem, Ham, and Japheth.'),
  ('YLT', 'EXO', 12, 1, 'And Jehovah speaketh unto Moses and unto Aaron, in the land of Egypt, saying,'),
  ('YLT', 'EXO', 12, 2, '`This month is to you the chief of months--it is the first to you of the months of the year;'),
  ('YLT', 'EXO', 12, 3, 'speak ye unto all the company of Israel, saying, In the tenth of this month--they take to them each man a lamb for the house of the fathers, a lamb for a house.'),
  ('YLT', 'EXO', 12, 4, '`(And if the household be too few for a lamb, then hath he taken, he and his neighbour who is near unto his house, for the number of persons, each according to his eating ye do count for the lamb,)'),
  ('YLT', 'EXO', 12, 5, 'a lamb, a perfect one, a male, a son of a year, let be to you; from the sheep or from the goats ye do take it.'),
  ('YLT', 'EXO', 12, 6, '`And it hath become a charge to you, until the fourteenth day of this month, and the whole assembly of the company of Israel have slaughtered it between the evenings;'),
  ('YLT', 'EXO', 12, 7, 'and they have taken of the blood, and have put on the two side-posts, and on the lintel over the houses in which they eat it.'),
  ('YLT', 'EXO', 12, 8, '`And they have eaten the flesh in this night, roast with fire; with unleavened things and bitters they do eat it;'),
  ('YLT', 'EXO', 12, 9, 'ye do not eat of it raw, or boiled at all in water, but roast with fire, its head with its legs, and with its inwards;'),
  ('YLT', 'EXO', 12, 10, 'and ye do not leave of it till morning, and that which is remaining of it till morning with fire ye do burn.'),
  ('YLT', 'EXO', 12, 11, '`And thus ye do eat it: your loins girded, your sandals on your feet, and your staff in your hand, and ye have eaten it in haste; it is Jehovah''s passover,'),
  ('YLT', 'EXO', 12, 12, 'and I have passed over through the land of Egypt during this night, and have smitten every first-born in the land of Egypt, from man even unto beast, and on all the gods of Egypt I do judgments; I am Jehovah.'),
  ('YLT', 'EXO', 12, 13, '`And the blood hath become a sign for you on the houses where ye are, and I have seen the blood, and have passed over you, and a plague is not on you for destruction in My smiting in the land of Egypt.'),
  ('YLT', 'EXO', 12, 14, '`And this day hath become to you a memorial, and ye have kept it a feast to Jehovah to your generations; --a statute age-during; ye keep it a feast.'),
  ('YLT', 'EXO', 12, 15, 'Seven days ye eat unleavened things; only--in the first day ye cause leaven to cease out of your houses; for any one eating anything fermented from the first day till the seventh day, even that person hath been cut off from Israel.'),
  ('YLT', 'EXO', 12, 16, '`And in the first day is a holy convocation, and in the seventh day ye have a holy convocation; any work is not done in them, only that which is eaten by any person--it alone is done by you,'),
  ('YLT', 'EXO', 12, 17, 'and ye have observed the unleavened things, for in this self-same day I have brought out your hosts from the land of Egypt, and ye have observed this day to your generations--a statute age-during.'),
  ('YLT', 'EXO', 12, 18, '`In the first month, in the fourteenth day of the month, in the evening, ye do eat unleavened things until the one and twentieth day of the month, at evening;'),
  ('YLT', 'EXO', 12, 19, 'seven days leaven is not found in your houses, for any one eating anything fermented--that person hath been cut off from the company of Israel, among the sojourners or among the natives of the land;'),
  ('YLT', 'EXO', 12, 20, 'anything fermented ye do not eat, in all your dwellings ye do eat unleavened things.'''),
  ('YLT', 'EXO', 12, 21, 'And Moses calleth for all the elders of Israel, and saith unto them, `Draw out and take for yourselves from the flock, for your families, and slaughter the passover-sacrifice;'),
  ('YLT', 'EXO', 12, 22, 'and ye have taken a bunch of hyssop, and have dipped it in the blood which is in the basin, and have struck it on the lintel, and on the two side-posts, from the blood which is in the basin, and ye, ye go not out each from the opening of his house till morning.'),
  ('YLT', 'EXO', 12, 23, '`And Jehovah hath passed on to smite the Egyptians, and hath seen the blood on the lintel, and on the two side-posts, and Jehovah hath passed over the opening, and doth not permit the destruction to come into your houses to smite.'),
  ('YLT', 'EXO', 12, 24, '`And ye have observed this thing, for a statute to thee, and to thy sons--unto the age;'),
  ('YLT', 'EXO', 12, 25, 'and it hath been, when ye come in unto the land which Jehovah giveth to you, as He hath spoken, that ye have kept this service;'),
  ('YLT', 'EXO', 12, 26, 'and it hath come to pass when your sons say unto you, What is this service ye have?'),
  ('YLT', 'EXO', 12, 27, 'that ye have said, A sacrifice of passover it is to Jehovah, who passed over the houses of the sons of Israel in Egypt, in His smiting the Egyptians, and our houses He delivered.'''),
  ('YLT', 'EXO', 12, 28, 'And the people bow and do obeisance, and the sons of Israel go and do as Jehovah commanded Moses and Aaron; so have they done.'),
  ('YLT', 'EXO', 12, 29, 'And it cometh to pass, at midnight, that Jehovah hath smitten every first-born in the land of Egypt, from the first-born of Pharaoh who is sitting on his throne, unto the first-born of the captive who is in the prison-house, and every first-born of beasts.'),
  ('YLT', 'EXO', 12, 30, 'And Pharaoh riseth by night, he and all his servants, and all the Egyptians, and there is a great cry in Egypt, for there is not a house where there is not one dead,'),
  ('YLT', 'EXO', 12, 31, 'and he calleth for Moses and for Aaron by night, and saith, `Rise, go out from the midst of my people, both ye and the sons of Israel, and go, serve Jehovah according to your word;'),
  ('YLT', 'EXO', 12, 32, 'both your flock and your herd take ye, as ye have spoken, and go; then ye have blessed also me.'''),
  ('YLT', 'EXO', 12, 33, 'And the Egyptians are urgent on the people, hasting to send them away out of the land, for they said, `We are all dead;'''),
  ('YLT', 'EXO', 12, 34, 'and the people taketh up its dough before it is fermented, their kneading-troughs are bound up in their garments on their shoulder.'),
  ('YLT', 'EXO', 12, 35, 'And the sons of Israel have done according to the word of Moses, and they ask from the Egyptians vessels of silver and vessels of gold, and garments;'),
  ('YLT', 'EXO', 12, 36, 'and Jehovah hath given the grace of the people in the eyes of the Egyptians, and they cause them to ask, and they spoil the Egyptians.'),
  ('YLT', 'EXO', 12, 37, 'And the sons of Israel journey from Rameses to Succoth, about six hundred thousand men on foot, apart from infants;'),
  ('YLT', 'EXO', 12, 38, 'and a great rabble also hath gone up with them, and flock and herd--very much cattle.'),
  ('YLT', 'EXO', 12, 39, 'And they bake with the dough which they have brought out from Egypt unleavened cakes, for it hath not fermented; for they have been cast out of Egypt, and have not been able to delay, and also provision they have not made for themselves.'),
  ('YLT', 'EXO', 12, 40, 'And the dwelling of the sons of Israel which they have dwelt in Egypt is four hundred and thirty years;'),
  ('YLT', 'EXO', 12, 41, 'and it cometh to pass, at the end of four hundred and thirty years--yea, it cometh to pass in this self-same day--all the hosts of Jehovah have gone out from the land of Egypt.'),
  ('YLT', 'EXO', 12, 42, 'A night of watchings it is to Jehovah, to bring them out from the land of Egypt; it is this night to Jehovah of watchings to all the sons of Israel to their generations.'),
  ('YLT', 'EXO', 12, 43, 'And Jehovah saith unto Moses and Aaron, `This is a statute of the passover; Any son of a stranger doth not eat of it;'),
  ('YLT', 'EXO', 12, 44, 'and any man''s servant, the purchase of money, when thou hast circumcised him--then he doth eat of it;'),
  ('YLT', 'EXO', 12, 45, 'a settler or hired servant doth not eat of it;'),
  ('YLT', 'EXO', 12, 46, 'in one house it is eaten, thou dost not carry out of the house any of the flesh without, and a bone ye do not break of it;'),
  ('YLT', 'EXO', 12, 47, 'all the company of Israel do keep it.'),
  ('YLT', 'EXO', 12, 48, '`And when a sojourner sojourneth with thee, and hath made a passover to Jehovah, every male of his is to be circumcised, and then he doth come near to keep it, and he hath been as a native of the land, but any uncircumcised one doth not eat of it;'),
  ('YLT', 'EXO', 12, 49, 'one law is to a native, and to a sojourner who is sojourning in your midst.'''),
  ('YLT', 'EXO', 12, 50, 'And all the sons of Israel do as Jehovah commanded Moses and Aaron; so have they done.'),
  ('YLT', 'EXO', 12, 51, 'And it cometh to pass in this self-same day, Jehovah hath brought out the sons of Israel from the land of Egypt, by their hosts.'),
  ('YLT', 'EXO', 34, 1, 'And Jehovah saith unto Moses, `Hew for thyself two tables of stone like the first, and I have written on the tables the words which were on the first tables which thou hast broken;'),
  ('YLT', 'EXO', 34, 2, 'and be prepared at morning, and thou hast come up in the morning unto mount Sinai, and hast stood before Me there, on the top of the mount,'),
  ('YLT', 'EXO', 34, 3, 'and no man cometh up with thee, and also no man is seen in all the mount, also the flock and the herd do not feed over-against that mount.'''),
  ('YLT', 'EXO', 34, 4, 'And he heweth two tables of stone like the first, and Moses riseth early in the morning, and goeth up unto mount Sinai, as Jehovah commanded him, and he taketh in his hand two tables of stone.'),
  ('YLT', 'EXO', 34, 5, 'And Jehovah cometh down in a cloud, and stationeth Himself with him there, and calleth in the Name of Jehovah,'),
  ('YLT', 'EXO', 34, 6, 'and Jehovah passeth over before his face, and calleth: `Jehovah, Jehovah God, merciful and gracious, slow to anger, and abundant in kindness and truth,'),
  ('YLT', 'EXO', 34, 7, 'keeping kindness for thousands, taking away iniquity, and transgression, and sin, and not entirely acquitting, charging iniquity of fathers on children, and on children''s children, on a third generation, and on a fourth.'''),
  ('YLT', 'EXO', 34, 8, 'And Moses hasteth, and boweth to the earth, and doth obeisance,'),
  ('YLT', 'EXO', 34, 9, 'and saith, `If, I pray Thee, I have found grace in Thine eyes, O my Lord, let my Lord, I pray Thee, go in our midst (for it is a stiff-necked people), and thou hast forgiven our iniquity and our sin, and hast inherited us.'''),
  ('YLT', 'EXO', 34, 10, 'And He saith, `Lo, I am making a covenant: before all thy people I do wonders, which have not been done in all the earth, or in any nation, and all the people in whose midst thou art have seen the work of Jehovah, for it is fearful that which I am doing with thee.'),
  ('YLT', 'EXO', 34, 11, '`Observe for thyself that which I am commanding thee to-day: lo, I am casting out from before thee the Amorite, and the Canaanite, and the Hittite, and the Perizzite, and the Hivite, and the Jebusite;'),
  ('YLT', 'EXO', 34, 12, 'take heed to thyself, lest thou make a covenant with the inhabitant of the land into which thou art going, lest it become a snare in thy midst;'),
  ('YLT', 'EXO', 34, 13, 'for their altars ye break down, and their standing pillars ye shiver, and its shrines ye cut down;'),
  ('YLT', 'EXO', 34, 14, 'for ye do not bow yourselves to another god--for Jehovah, whose name is Zealous, is a zealous God.'),
  ('YLT', 'EXO', 34, 15, '`Lest thou make a covenant with the inhabitant of the land, and they have gone a-whoring after their gods, and have sacrificed to their gods, and one hath called to thee, and thou hast eaten of his sacrifice,'),
  ('YLT', 'EXO', 34, 16, 'and thou hast taken of their daughters to thy sons, and their daughters have gone a-whoring after their gods, and have caused thy sons to go a-whoring after their gods;'),
  ('YLT', 'EXO', 34, 17, 'a molten god thou dost not make to thyself.'),
  ('YLT', 'EXO', 34, 18, '`The feast of unleavened things thou dost keep; seven days thou dost eat unleavened things, as I have commanded thee, at an appointed time, the month of Abib: for in the month of Abib thou didst come out from Egypt.'),
  ('YLT', 'EXO', 34, 19, '`All opening a womb are Mine, and every firstling of thy cattle born a male, ox or sheep;'),
  ('YLT', 'EXO', 34, 20, 'and the firstling of an ass thou dost ransom with a lamb; and if thou dost not ransom, then thou hast beheaded it; every first-born of thy sons thou dost ransom, and they do not appear before Me empty.'),
  ('YLT', 'EXO', 34, 21, '`Six days thou dost work, and on the seventh day thou dost rest; in ploughing-time and in harvest thou dost rest.'),
  ('YLT', 'EXO', 34, 22, '`And a feast of weeks thou dost observe for thyself; first-fruits of wheat-harvest; and the feast of in-gathering, at the revolution of the year.'),
  ('YLT', 'EXO', 34, 23, '`Three times in a year do all thy males appear before the Lord Jehovah, God of Israel;'),
  ('YLT', 'EXO', 34, 24, 'for I dispossess nations from before thee, and have enlarged thy border, and no man doth desire thy land in thy going up to appear before Jehovah thy God three times in a year.'),
  ('YLT', 'EXO', 34, 25, '`Thou dost not slaughter with a fermented thing the blood of My sacrifice; and the sacrifice of the feast of the passover doth not remain till morning:'),
  ('YLT', 'EXO', 34, 26, 'the first of the first-fruits of the land thou dost bring into the house of Jehovah thy God; thou dost not boil a kid in its mother''s milk.'''),
  ('YLT', 'EXO', 34, 27, 'And Jehovah saith unto Moses, `Write for thyself these words, for, according to the tenor of these words I have made with thee a covenant, and with Israel.'''),
  ('YLT', 'EXO', 34, 28, 'And he is there with Jehovah forty days and forty nights; bread he hath not eaten, and water he hath not drunk; and he writeth on the tables the matters of the covenant--the ten matters.'),
  ('YLT', 'EXO', 34, 29, 'And it cometh to pass, when Moses is coming down from mount Sinai (and the two tables of the testimony are in the hand of Moses in his coming down from the mount), that Moses hath not known that the skin of his face hath shone in His speaking with him,'),
  ('YLT', 'EXO', 34, 30, 'and Aaron seeth--all the sons of Israel also--Moses, and lo, the skin of his face hath shone, and they are afraid of coming nigh unto him.'),
  ('YLT', 'EXO', 34, 31, 'And Moses calleth unto them, and Aaron and all the princes in the company return unto him, and Moses speaketh unto them;'),
  ('YLT', 'EXO', 34, 32, 'and afterwards have all the sons of Israel come nigh, and he chargeth them with all that Jehovah hath spoken with him in mount Sinai.'),
  ('YLT', 'EXO', 34, 33, 'And Moses finisheth speaking with them, and putteth on his face a vail;'),
  ('YLT', 'EXO', 34, 34, 'and in the going in of Moses before Jehovah to speak with Him, he turneth aside the vail until his coming out; and he hath come out and hath spoken unto the sons of Israel that which he is commanded;'),
  ('YLT', 'EXO', 34, 35, 'and the sons of Israel have seen the face of Moses that the skin of the face of Moses hath shone, and Moses hath put back the vail on his face until his going in to speak with Him.'),
  ('YLT', 'EXO', 40, 1, 'And Jehovah speaketh unto Moses, saying,'),
  ('YLT', 'EXO', 40, 2, '`On the first day of the month, in the first month, thou dost raise up the tabernacle of the tent of meeting,'),
  ('YLT', 'EXO', 40, 3, 'and hast set there the ark of the testimony, and hast covered over the ark with the vail,'),
  ('YLT', 'EXO', 40, 4, 'and hast brought in the table, and set its arrangement in order, and hast brought in the candlestick, and caused its lamps to go up.'),
  ('YLT', 'EXO', 40, 5, '`And thou hast put the golden altar for perfume before the ark of the testimony, and hast put the covering of the opening to the tabernacle,'),
  ('YLT', 'EXO', 40, 6, 'and hast put the altar of the burnt-offering before the opening of the tabernacle of the tent of meeting,'),
  ('YLT', 'EXO', 40, 7, 'and hast put the laver between the tent of meeting and the altar, and hast put water there.'),
  ('YLT', 'EXO', 40, 8, '`And thou hast set the court round about, and hast placed the covering of the gate of the court,'),
  ('YLT', 'EXO', 40, 9, 'and hast taken the anointing oil, and anointed the tabernacle, and all that is in it, and hallowed it, and all its vessels, and it hath been holy;'),
  ('YLT', 'EXO', 40, 10, 'and thou hast anointed the altar of the burnt-offering, and all its vessels, and sanctified the altar, and the altar hath been most holy;'),
  ('YLT', 'EXO', 40, 11, 'and thou hast anointed the laver and its base, and sanctified it.'),
  ('YLT', 'EXO', 40, 12, '`And thou hast brought near Aaron and his sons unto the opening of the tent of meeting, and hast bathed them with water;'),
  ('YLT', 'EXO', 40, 13, 'and thou hast clothed Aaron with the holy garments, and anointed him, and sanctified him, and he hath acted as priest to Me.'),
  ('YLT', 'EXO', 40, 14, '`And his sons thou dost bring near, and hast clothed them with coats,'),
  ('YLT', 'EXO', 40, 15, 'and anointed them as thou hast anointed their father, and they have acted as priests to Me, and their anointing hath been to be to them for a priesthood age-during, to their generations.'''),
  ('YLT', 'EXO', 40, 16, 'And Moses doth according to all that Jehovah hath commanded him; so he hath done.'),
  ('YLT', 'EXO', 40, 17, 'And it cometh to pass, in the first month, in the second year, in the first of the month, the tabernacle hath been raised up;'),
  ('YLT', 'EXO', 40, 18, 'and Moses raiseth up the tabernacle, and setteth its sockets, and placeth its boards, and placeth its bars, and raiseth its pillars,'),
  ('YLT', 'EXO', 40, 19, 'and spreadeth the tent over the tabernacle, and putteth the covering of the tent upon it above, as Jehovah hath commanded Moses.'),
  ('YLT', 'EXO', 40, 20, 'And he taketh and putteth the testimony unto the ark, and setteth the staves on the ark, and putteth the mercy-seat on the ark above;'),
  ('YLT', 'EXO', 40, 21, 'and bringeth in the ark unto the tabernacle, and placeth the vail of the covering, and covereth over the ark of the testimony, as Jehovah hath commanded Moses.'),
  ('YLT', 'EXO', 40, 22, 'And he putteth the table in the tent of meeting, on the side of the tabernacle northward, at the outside of the vail,'),
  ('YLT', 'EXO', 40, 23, 'and setteth in order upon it the arrangement of bread, before Jehovah, as Jehovah hath commanded Moses.'),
  ('YLT', 'EXO', 40, 24, 'And he putteth the candlestick in the tent of meeting, over-against the table, on the side of the tabernacle southward,'),
  ('YLT', 'EXO', 40, 25, 'and causeth the lamps to go up before Jehovah, as Jehovah hath commanded Moses.'),
  ('YLT', 'EXO', 40, 26, 'And he setteth the golden altar in the tent of meeting, before the vail,'),
  ('YLT', 'EXO', 40, 27, 'and maketh perfume on it--spice-perfume--as Jehovah hath commanded Moses.'),
  ('YLT', 'EXO', 40, 28, 'And he setteth the covering of the opening to the tabernacle,'),
  ('YLT', 'EXO', 40, 29, 'and the altar of the burnt-offering he hath set at the opening of the tabernacle of the tent of meeting, and causeth the burnt-offering to go up upon it, and the present, as Jehovah hath commanded Moses.'),
  ('YLT', 'EXO', 40, 30, 'And he putteth the laver between the tent of meeting and the altar, and putteth water there for washing,'),
  ('YLT', 'EXO', 40, 31, 'and Moses and Aaron and his sons have washed their hands and their feet at the same;'),
  ('YLT', 'EXO', 40, 32, 'in their going in unto the tent of meeting, and in their drawing near unto the altar, they wash, as Jehovah hath commanded Moses.'),
  ('YLT', 'EXO', 40, 33, 'And he raiseth up the court round about the tabernacle, and about the altar, and placeth the covering of the gate of the court; and Moses completeth the work.'),
  ('YLT', 'EXO', 40, 34, 'And the cloud covereth the tent of meeting, and the honour of Jehovah hath filled the tabernacle;'),
  ('YLT', 'EXO', 40, 35, 'and Moses hath not been able to go in unto the tent of meeting, for the cloud hath tabernacled on it, and the honour of Jehovah hath filled the tabernacle.'),
  ('YLT', 'EXO', 40, 36, 'And in the going up of the cloud from off the tabernacle the sons of Israel journey in all their journeys;'),
  ('YLT', 'EXO', 40, 37, 'and if the cloud go not up then they journey not, until the day of its going up:'),
  ('YLT', 'EXO', 40, 38, 'for the cloud of Jehovah is on the tabernacle by day, and fire is in it by night, before the eyes of all the house of Israel in all their journeys.'),
  ('YLT', 'PSA', 8, 1, 'To the Overseer, `On the Gittith.'' A Psalm of David. Jehovah, our Lord, How honourable Thy name in all the earth! Who settest thine honour on the heavens.'),
  ('YLT', 'PSA', 8, 2, 'From the mouths of infants and sucklings Thou hast founded strength, Because of Thine adversaries, To still an enemy and a self-avenger.'),
  ('YLT', 'PSA', 8, 3, 'For I see Thy heavens, a work of Thy fingers, Moon and stars that Thou didst establish.'),
  ('YLT', 'PSA', 8, 4, 'What is man that Thou rememberest him? The son of man that Thou inspectest him?'),
  ('YLT', 'PSA', 8, 5, 'And causest him to lack a little of Godhead, And with honour and majesty compassest him.'),
  ('YLT', 'PSA', 8, 6, 'Thou dost cause him to rule Over the works of Thy hands, All Thou hast placed under his feet.'),
  ('YLT', 'PSA', 8, 7, 'Sheep and oxen, all of them, And also beasts of the field,'),
  ('YLT', 'PSA', 8, 8, 'Bird of the heavens, and fish of the sea, Passing through the paths of the seas!'),
  ('YLT', 'PSA', 8, 9, 'Jehovah, our Lord, How honourable Thy name in all the earth!'),
  ('YLT', 'PSA', 23, 1, 'A Psalm of David. Jehovah is my shepherd, I do not lack,'),
  ('YLT', 'PSA', 23, 2, 'In pastures of tender grass He causeth me to lie down, By quiet waters He doth lead me.'),
  ('YLT', 'PSA', 23, 3, 'My soul He refresheth, He leadeth me in paths of righteousness, For His name''s sake,'),
  ('YLT', 'PSA', 23, 4, 'Also--when I walk in a valley of death-shade, I fear no evil, for Thou art with me, Thy rod and Thy staff--they comfort me.'),
  ('YLT', 'PSA', 23, 5, 'Thou arrangest before me a table, Over-against my adversaries, Thou hast anointed with oil my head, My cup is full!'),
  ('YLT', 'PSA', 23, 6, 'Only--goodness and kindness pursue me, All the days of my life, And my dwelling is in the house of Jehovah, For a length of days!'),
  ('YLT', 'PSA', 27, 1, 'By David. Jehovah is my light and my salvation, Whom do I fear? Jehovah is the strength of my life, Of whom am I afraid?'),
  ('YLT', 'PSA', 27, 2, 'When evil doers come near to me to eat my flesh, My adversaries and mine enemies to me, They have stumbled and fallen.'),
  ('YLT', 'PSA', 27, 3, 'Though a host doth encamp against me, My heart doth not fear, Though war riseth up against me, In this I am confident.'),
  ('YLT', 'PSA', 27, 4, 'One thing I asked of Jehovah--it I seek. My dwelling in the house of Jehovah, All the days of my life, To look on the pleasantness of Jehovah, And to inquire in His temple.'),
  ('YLT', 'PSA', 27, 5, 'For He hideth me in a tabernacle in the day of evil, He hideth me in a secret place of His tent, On a rock he raiseth me up.'),
  ('YLT', 'PSA', 27, 6, 'And now, lifted up is my head, Above my enemies--my surrounders, And I sacrifice in His tent sacrifices of shouting, I sing, yea, I sing praise to Jehovah.'),
  ('YLT', 'PSA', 27, 7, 'Hear, O Jehovah, my voice--I call, And favour me, and answer me.'),
  ('YLT', 'PSA', 27, 8, 'To Thee said my heart `They sought my face, Thy face, O Jehovah, I seek.'''),
  ('YLT', 'PSA', 27, 9, 'Hide not Thy face from me, Turn not aside in anger Thy servant, My help Thou hast been. Leave me not, nor forsake me, O God of my salvation.'),
  ('YLT', 'PSA', 27, 10, 'When my father and my mother Have forsaken me, then doth Jehovah gather me.'),
  ('YLT', 'PSA', 27, 11, 'Shew me, O Jehovah, Thy way, And lead me in a path of uprightness, For the sake of my beholders.'),
  ('YLT', 'PSA', 27, 12, 'Give me not to the will of my adversaries, For risen against me have false witnesses, And they breathe out violence to me.'),
  ('YLT', 'PSA', 27, 13, 'I had not believed to look on the goodness of Jehovah In the land of the living!'),
  ('YLT', 'PSA', 27, 14, 'Look unto Jehovah--be strong, And He doth strengthen thy heart, Yea, look unto Jehovah!'),
  ('YLT', 'PSA', 33, 1, 'Sing, ye righteous, in Jehovah, For upright ones praise is comely.'),
  ('YLT', 'PSA', 33, 2, 'Give ye thanks to Jehovah with a harp, With psaltery of ten strings sing praise to Him,'),
  ('YLT', 'PSA', 33, 3, 'Sing ye to Him a new song, Play skilfully with shouting.'),
  ('YLT', 'PSA', 33, 4, 'For upright is the word of Jehovah, And all His work is in faithfulness.'),
  ('YLT', 'PSA', 33, 5, 'Loving righteousness and judgment, Of the kindness of Jehovah is the earth full.'),
  ('YLT', 'PSA', 33, 6, 'By the word of Jehovah The heavens have been made, And by the breath of His mouth all their host.'),
  ('YLT', 'PSA', 33, 7, 'Gathering as a heap the waters of the sea, Putting in treasuries the depths.'),
  ('YLT', 'PSA', 33, 8, 'Afraid of Jehovah are all the earth, Of Him are all the inhabitants of the world afraid.'),
  ('YLT', 'PSA', 33, 9, 'For He hath said, and it is, He hath commanded, and it standeth.'),
  ('YLT', 'PSA', 33, 10, 'Jehovah made void the counsel of nations, He disallowed the thoughts of the peoples.'),
  ('YLT', 'PSA', 33, 11, 'The counsel of Jehovah to the age standeth, The thoughts of His heart to all generations.'),
  ('YLT', 'PSA', 33, 12, 'O the happiness of the nation whose God is Jehovah, Of the people He did choose, For an inheritance to Him.'),
  ('YLT', 'PSA', 33, 13, 'From the heavens hath Jehovah looked, He hath seen all the sons of men.'),
  ('YLT', 'PSA', 33, 14, 'From the fixed place of His dwelling, He looked unto all inhabitants of the earth;'),
  ('YLT', 'PSA', 33, 15, 'Who is forming their hearts together, Who is attending unto all their works.'),
  ('YLT', 'PSA', 33, 16, 'The king is not saved by the multitude of a force. A mighty man is not delivered, By abundance of power.'),
  ('YLT', 'PSA', 33, 17, 'A false thing is the horse for safety, And by the abundance of his strength He doth not deliver.'),
  ('YLT', 'PSA', 33, 18, 'Lo, the eye of Jehovah is to those fearing Him, To those waiting for His kindness,'),
  ('YLT', 'PSA', 33, 19, 'To deliver from death their soul, And to keep them alive in famine.'),
  ('YLT', 'PSA', 33, 20, 'Our soul hath waited for Jehovah, Our help and our shield is He,'),
  ('YLT', 'PSA', 33, 21, 'For in Him doth our heart rejoice, For in His holy name we have trusted.'),
  ('YLT', 'PSA', 33, 22, 'Let Thy kindness, O Jehovah, be upon us, As we have waited for Thee!'),
  ('YLT', 'ISA', 6, 1, 'In the year of the death of king Uzziah--I see the Lord, sitting on a throne, high and lifted up, and His train is filling the temple.'),
  ('YLT', 'ISA', 6, 2, 'Seraphs are standing above it: six wings hath each one; with two each covereth its face, and with two each covereth its feet, and with two each flieth.'),
  ('YLT', 'ISA', 6, 3, 'And this one hath called unto that, and hath said: `Holy, Holy, Holy, is Jehovah of Hosts, The fulness of all the earth is His glory.'''),
  ('YLT', 'ISA', 6, 4, 'And the posts of the thresholds are moved by the voice of him who is calling, and the house is full of smoke.'),
  ('YLT', 'ISA', 6, 5, 'And I say, `Woe to me, for I have been silent, For a man--unclean of lips am I, And in midst of a people unclean of lips I am dwelling, Because the King, Jehovah of Hosts, have my eyes seen.'''),
  ('YLT', 'ISA', 6, 6, 'And flee unto me doth one of the seraphs, and in his hand a burning coal, (with tongs he hath taken it from off the altar,)'),
  ('YLT', 'ISA', 6, 7, 'and he striketh against my mouth, and saith: `Lo, this hath stricken against thy lips, And turned aside is thine iniquity, And thy sin is covered.'''),
  ('YLT', 'ISA', 6, 8, 'And I hear the voice of the Lord, saying: `Whom do I send? and who doth go for Us?'' And I say, `Here am I, send me.'''),
  ('YLT', 'ISA', 6, 9, 'And He saith, `Go, and thou hast said to this people, Hear ye--to hear, and ye do not understand, And see ye--to see, and ye do not know.'),
  ('YLT', 'ISA', 6, 10, 'Declare fat the heart of this people, And its ears declare heavy, And its eyes declare dazzled, Lest it see with its eyes, And with its ears hear, and its heart consider, And it hath turned back, and hath health.'''),
  ('YLT', 'ISA', 6, 11, 'And I say, `Till when, O Lord?'' And He saith, `Surely till cities have been wasted without inhabitant, And houses without man, And the ground be wasted--a desolation,'),
  ('YLT', 'ISA', 6, 12, 'And Jehovah hath put man far off, And great is the forsaken part in the heart of the land.'),
  ('YLT', 'ISA', 6, 13, 'And yet in it a tenth, and it hath turned, And hath been for a burning, As a teil-tree, and as an oak, that in falling, Have substance in them, The holy seed is its substance!'''),
  ('YLT', 'ISA', 40, 1, 'Comfort ye, comfort ye, My people, saith your God.'),
  ('YLT', 'ISA', 40, 2, 'Speak to the heart of Jerusalem, and call to her, That her warfare hath been completed, That accepted hath been her punishment, That she hath received from the hand of Jehovah Double for all her sins.'),
  ('YLT', 'ISA', 40, 3, 'A voice is crying--in a wilderness--Prepare ye the way of Jehovah, Make straight in a desert a highway to our God.'),
  ('YLT', 'ISA', 40, 4, 'Every valley is raised up, And every mountain and hill become low, And the crooked place hath become a plain, And the entangled places a valley.'),
  ('YLT', 'ISA', 40, 5, 'And revealed hath been the honour of Jehovah, And seen it have all flesh together, For the mouth of Jehovah hath spoken.'),
  ('YLT', 'ISA', 40, 6, 'A voice is saying, `Call,'' And he said, `What do I call?'' All flesh is grass, and all its goodliness is As a flower of the field:'),
  ('YLT', 'ISA', 40, 7, 'Withered hath grass, faded the flower, For the Spirit of Jehovah blew upon it, Surely the people is grass;'),
  ('YLT', 'ISA', 40, 8, 'Withered hath grass, faded the flower, But a word of our God riseth for ever.'),
  ('YLT', 'ISA', 40, 9, 'On a high mountain get thee up, O Zion, Proclaiming tidings, Lift up with power thy voice, O Jerusalem, proclaiming tidings, Lift up, fear not, say to cities of Judah, `Lo, your God.'''),
  ('YLT', 'ISA', 40, 10, 'Lo, the Lord Jehovah with strength cometh, And His arm is ruling for Him, Lo, His hire is with Him, and His wage before Him.'),
  ('YLT', 'ISA', 40, 11, 'As a shepherd His flock He feedeth, With His arm He gathereth lambs, And in His bosom He carrieth them: Suckling ones He leadeth.'),
  ('YLT', 'ISA', 40, 12, 'Who hath measured in the hollow of his hand the waters? And the heavens by a span hath meted out, And comprehended in a measure the dust of the earth, And hath weighed in scales the mountains, And the hills in a balance?'),
  ('YLT', 'ISA', 40, 13, 'Who hath meted out the Spirit of Jehovah, And, being His counsellor, doth teach Him!'),
  ('YLT', 'ISA', 40, 14, 'With whom consulted He, That he causeth Him to understand? And teacheth Him in the path of judgment, And teacheth Him knowledge? And the way of understanding causeth Him to know?'),
  ('YLT', 'ISA', 40, 15, 'Lo, nations as a drop from a bucket, And as small dust of the balance, have been reckoned, Lo, isles as a small thing He taketh up.'),
  ('YLT', 'ISA', 40, 16, 'And Lebanon is not sufficient to burn, Nor its beasts sufficient for a burnt-offering.'),
  ('YLT', 'ISA', 40, 17, 'All the nations are as nothing before Him, Less than nothing and emptiness, They have been reckoned to Him.'),
  ('YLT', 'ISA', 40, 18, 'And unto whom do ye liken God, And what likeness do ye compare to Him?'),
  ('YLT', 'ISA', 40, 19, 'The graven image poured out hath a artisan, And a refiner with gold spreadeth it over, And chains of silver he is refining.'),
  ('YLT', 'ISA', 40, 20, 'He who is poor by heave-offerings, A tree not rotten doth choose, A skilful artisan he seeketh for it, To establish a graven image--not moved.'),
  ('YLT', 'ISA', 40, 21, 'Do ye not know--do ye not hear? Hath it not been declared from the first to you? Have ye not understood From the foundations of the earth?'),
  ('YLT', 'ISA', 40, 22, 'He who is sitting on the circle of the earth, And its inhabitants are as grasshoppers, He who is stretching out as a thin thing the heavens, And spreadeth them as a tent to dwell in.'),
  ('YLT', 'ISA', 40, 23, 'He who is making princes become nothing, Judges of earth as emptiness hath made;'),
  ('YLT', 'ISA', 40, 24, 'Yea, they have not been planted, Yea, they have not been sown, Yea, not taking root in the earth is their stock, And also He hath blown upon them, and they wither, And a whirlwind as stubble taketh them away.'),
  ('YLT', 'ISA', 40, 25, 'And unto whom do ye liken Me, And am I equal? saith the Holy One.'),
  ('YLT', 'ISA', 40, 26, 'Lift up on high your eyes, And see--who hath prepared these? He who is bringing out by number their host, To all of them by name He calleth, By abundance of strength (And he is strong in power) not one is lacking.'),
  ('YLT', 'ISA', 40, 27, 'Why sayest thou, O Jacob? and speakest thou, O Israel? `My way hath been hid from Jehovah, And from my God my judgment passeth over.'''),
  ('YLT', 'ISA', 40, 28, 'Hast thou not known? hast thou not heard? The God of the age--Jehovah, Preparer of the ends of the earth, Is not wearied nor fatigued, There is no searching of His understanding.'),
  ('YLT', 'ISA', 40, 29, 'He is giving power to the weary, And to those not strong He increaseth might.'),
  ('YLT', 'ISA', 40, 30, 'Even youths are wearied and fatigued, And young men utterly stumble,'),
  ('YLT', 'ISA', 40, 31, 'But those expecting Jehovah pass to power, They raise up the pinion as eagles, They run and are not fatigued, They go on and do not faint!'),
  ('YLT', 'ISA', 41, 1, 'Keep silent towards Me, O isles, And the peoples pass on to power, They come nigh, then they speak, `Together--to judgment we draw near.'''),
  ('YLT', 'ISA', 41, 2, 'Who stirred up from the east a righteous one? He calleth him to His foot, He giveth before him nations, And kings He causeth him to rule, He giveth them as dust to his sword, As driven stubble to his bow.'),
  ('YLT', 'ISA', 41, 3, 'He pursueth them, he passeth over in safety A path with his feet he entereth not.'),
  ('YLT', 'ISA', 41, 4, 'Who hath wrought and done, Calling the generations from the first? I, Jehovah, the first, and with the last I am He.'),
  ('YLT', 'ISA', 41, 5, 'Seen have isles and fear, ends of the earth tremble, They have drawn near, yea, they come.'),
  ('YLT', 'ISA', 41, 6, 'Each his neighbour they help, And to his brother he saith, `Be strong.'''),
  ('YLT', 'ISA', 41, 7, 'And strengthen doth an artisan the refiner, A smoother with a hammer, Him who is beating on an anvil, Saying, `For joining it is good,'' And he strengtheneth it with nails, it is not moved!'),
  ('YLT', 'ISA', 41, 8, '--And thou, O Israel, My servant, Jacob, whom I have chosen, Seed of Abraham, My lover,'),
  ('YLT', 'ISA', 41, 9, 'Whom I have taken hold of, from the ends of the earth, And from its near places I have called thee, And I say to thee, My servant Thou art, I have chosen thee, and not rejected thee.'),
  ('YLT', 'ISA', 41, 10, 'Be not afraid, for with thee I am, Look not around, for I am thy God, I have strengthened thee, Yea, I have helped thee, yea, I upheld thee, With the right hand of My righteousness.'),
  ('YLT', 'ISA', 41, 11, 'Lo, all those displeased with thee, They are ashamed and blush, They are as nothing, yea, perish Do the men who strive with thee.'),
  ('YLT', 'ISA', 41, 12, 'Thou seekest them, and findest them not, The men who debate with thee, They are as nothing, yea, as nothing, The men who war with thee.'),
  ('YLT', 'ISA', 41, 13, 'For I, Jehovah thy God, Am strengthening thy right hand, He who is saying to thee, `Fear not, I have helped thee.'''),
  ('YLT', 'ISA', 41, 14, 'Fear not, O worm Jacob, ye men of Israel, I helped thee, an affirmation of Jehovah, Even thy redeemer, the Holy One of Israel.'),
  ('YLT', 'ISA', 41, 15, 'Lo, I have set thee for a new sharp threshing instrument, Possessing teeth, thou threshest mountains, And beatest small, and hills as chaff thou makest.'),
  ('YLT', 'ISA', 41, 16, 'Thou winnowest them, and a wind lifteth them up, And a whirlwind scattereth them, And thou--thou rejoicest in Jehovah, In the Holy One of Israel dost boast thyself.'),
  ('YLT', 'ISA', 41, 17, 'The poor and the needy are seeking water, And there is none, Their tongue with thirst hath failed, I, Jehovah do answer them, The God of Israel--I forsake them not.'),
  ('YLT', 'ISA', 41, 18, 'I open on high places rivers, And in midst of valleys fountains, I make a wilderness become a pond of water, And a dry land become springs of water.'),
  ('YLT', 'ISA', 41, 19, 'I give in a wilderness the cedar, Shittah, and myrtle, and oil-tree, I set in a desert the fir-pine and box-wood together.'),
  ('YLT', 'ISA', 41, 20, 'So that they see, and know, And regard, and act wisely together, For the hand of Jehovah hath done this, And the Holy One of Israel hath prepared it.'),
  ('YLT', 'ISA', 41, 21, 'Bring near your cause, saith Jehovah, Bring nigh your mighty ones, saith the king of Jacob.'),
  ('YLT', 'ISA', 41, 22, 'They bring nigh, and declare to us that which doth happen, The first things--what they are declare ye, And we set our heart, and know their latter end, Or the coming things cause us to hear.'),
  ('YLT', 'ISA', 41, 23, 'Declare the things that are coming hereafter, And we know that ye are gods, Yea, ye may do good or do evil, And we look around and see it together.'),
  ('YLT', 'ISA', 41, 24, 'Lo, ye are of nothing, and your work of nought, An abomination--it fixeth on you.'),
  ('YLT', 'ISA', 41, 25, 'I have stirred up one from the north, And he cometh, From the rising of the sun he calleth in My name, And he cometh in on prefects as on clay, And as a potter treadeth down mire.'),
  ('YLT', 'ISA', 41, 26, 'Who hath declared from the first, and we know? And beforetime, and we say, `Righteous?'' yea, there is none declaring, Yea, there is none proclaiming, Yea, there is none hearing your sayings.'),
  ('YLT', 'ISA', 41, 27, 'First to Zion, Behold, behold them, And to Jerusalem one proclaiming tidings I give,'),
  ('YLT', 'ISA', 41, 28, 'And I see that there is no man, Yea, of these that there is no counsellor, And I ask them, and they return word:'),
  ('YLT', 'ISA', 41, 29, '`Lo, all of them are vanity, Nought are their works, Wind and emptiness their molten images!'''),
  ('YLT', 'ISA', 53, 1, 'Who hath given credence to that which we heard? And the arm of Jehovah, On whom hath it been revealed?'),
  ('YLT', 'ISA', 53, 2, 'Yea, he cometh up as a tender plant before Him, And as a root out of a dry land, He hath no form, nor honour, when we observe him, Nor appearance, when we desire him.'),
  ('YLT', 'ISA', 53, 3, 'He is despised, and left of men, A man of pains, and acquainted with sickness, And as one hiding the face from us, He is despised, and we esteemed him not.'),
  ('YLT', 'ISA', 53, 4, 'Surely our sicknesses he hath borne, And our pains--he hath carried them, And we--we have esteemed him plagued, Smitten of God, and afflicted.'),
  ('YLT', 'ISA', 53, 5, 'And he is pierced for our transgressions, Bruised for our iniquities, The chastisement of our peace is on him, And by his bruise there is healing to us.'),
  ('YLT', 'ISA', 53, 6, 'All of us like sheep have wandered, Each to his own way we have turned, And Jehovah hath caused to meet on him, The punishment of us all.'),
  ('YLT', 'ISA', 53, 7, 'It hath been exacted, and he hath answered, And he openeth not his mouth, As a lamb to the slaughter he is brought, And as a sheep before its shearers is dumb, And he openeth not his mouth.'),
  ('YLT', 'ISA', 53, 8, 'By restraint and by judgment he hath been taken, And of his generation who doth meditate, That he hath been cut off from the land of the living? By the transgression of My people he is plagued,'),
  ('YLT', 'ISA', 53, 9, 'And it appointeth with the wicked his grave, And with the rich are his high places, Because he hath done no violence, Nor is deceit in his mouth.'),
  ('YLT', 'ISA', 53, 10, 'And Jehovah hath delighted to bruise him, He hath made him sick, If his soul doth make an offering for guilt, He seeth seed--he prolongeth days, And the pleasure of Jehovah in his hand doth prosper.'),
  ('YLT', 'ISA', 53, 11, 'Of the labour of his soul he seeth--he is satisfied, Through his knowledge give righteousness Doth the righteous one, My servant, to many, And their iniquities he doth bear.'),
  ('YLT', 'ISA', 53, 12, 'Therefore I give a portion to him among the many, And with the mighty he apportioneth spoil, Because that he exposed to death his soul, And with transgressors he was numbered, And he the sin of many hath borne, And for transgressors he intercedeth.'),
  ('YLT', 'EZK', 34, 1, 'And there is a word of Jehovah unto me, saying,'),
  ('YLT', 'EZK', 34, 2, '`Son of man, prophesy concerning shepherds of Israel, prophesy, and thou hast said unto them: To the shepherds, thus said the Lord Jehovah: Woe to the shepherds of Israel, Who have been feeding themselves! The flock do not the shepherds feed?'),
  ('YLT', 'EZK', 34, 3, 'The fat ye do eat, and the wool ye put on, The fed one ye slaughter, the flock ye feed not.'),
  ('YLT', 'EZK', 34, 4, 'The weak ye have not strengthened, And the sick one ye have not healed, And the broken ye have not bound up, And the driven away have not brought back, And the lost ye have not sought, And with might ye have ruled them and with rigour.'),
  ('YLT', 'EZK', 34, 5, 'And they are scattered from want of a shepherd, And are for food to every beast of the field, Yea, they are scattered.'),
  ('YLT', 'EZK', 34, 6, 'Go astray do My flock on all the mountains, And on every high hill, And on all the face of the land have My flock been scattered, And there is none inquiring, and none seeking.'),
  ('YLT', 'EZK', 34, 7, 'Therefore, shepherds, hear a word of Jehovah:'),
  ('YLT', 'EZK', 34, 8, 'I live--an affirmation of the Lord Jehovah, If not, because of My flock being for a prey, Yea, My flock is for food to every beast of the field, Because there is no shepherd, And My shepherds have not sought My flock, And the shepherds do feed themselves, And My flock they have not fed.'),
  ('YLT', 'EZK', 34, 9, 'Therefore, O shepherds, hear a word of Jehovah:'),
  ('YLT', 'EZK', 34, 10, 'Thus said the Lord Jehovah: Lo, I am against the shepherds, And have required My flock from their hand, And caused them to cease from feeding the flock, And no more do the shepherds feed themselves, And I have delivered My flock from their mouth, And they are not to them for food.'),
  ('YLT', 'EZK', 34, 11, 'For thus said the Lord Jehovah: Lo, I--even I, have required My flock, And I have sought it out.'),
  ('YLT', 'EZK', 34, 12, 'As a shepherd''s searching of his drove, In the day of his being in the midst of his scattered flock, so I do seek My flock, And have delivered them out of all places, Whither they have been scattered, In a day of cloud and thick darkness.'),
  ('YLT', 'EZK', 34, 13, 'And brought them out from the peoples, And have gathered them from the lands, And brought them unto their own ground, And have fed them on mountains of Israel, By streams, and by all dwellings of the land.'),
  ('YLT', 'EZK', 34, 14, 'With good pasture I do feed them, And on mountains of the high place of Israel is their habitation, There do they lie down in a good habitation, And fat pastures they enjoy on mountains of Israel.'),
  ('YLT', 'EZK', 34, 15, 'I feed My flock, and cause them to lie down, An affirmation of the Lord Jehovah.'),
  ('YLT', 'EZK', 34, 16, 'The lost I seek, and the driven away bring back, And the broken I bind up, and the sick I strengthen, And the fat and the strong I destroy, I feed it with judgment.'),
  ('YLT', 'EZK', 34, 17, 'And you, My flock, thus said the Lord Jehovah: Lo, I am judging between sheep and sheep, Between rams and he-goats.'),
  ('YLT', 'EZK', 34, 18, 'Is it a little thing for you--the good pasture ye enjoy, And the remnant of your pasture ye tread down with your feet, And a depth of waters ye do drink, And the remainder with your feet ye trample,'),
  ('YLT', 'EZK', 34, 19, 'And My flock the trodden thing of your feet consumeth, And the trampled thing of your feet drinketh?'),
  ('YLT', 'EZK', 34, 20, 'Therefore, thus said the Lord Jehovah to them: Lo, I--even I, have judged between fat sheep and lean sheep.'),
  ('YLT', 'EZK', 34, 21, 'Because with side and with shoulder ye thrust away, And with your horns push all the diseased, Till ye have scattered them to the out-place,'),
  ('YLT', 'EZK', 34, 22, 'And I have given safety to My flock, And they are not any more for prey, And I have judged between sheep and sheep.'),
  ('YLT', 'EZK', 34, 23, 'And have raised up over them one shepherd, And he hath fed them--my servant David, He doth feed them, and he is their shepherd,'),
  ('YLT', 'EZK', 34, 24, 'And I, Jehovah, I am their God, And My servant David prince in their midst, I, Jehovah, have spoken.'),
  ('YLT', 'EZK', 34, 25, 'And I have made for them a covenant of peace, And caused evil beasts to cease out of the land, And they have dwelt in a wilderness confidently, And they have slept in forests.'),
  ('YLT', 'EZK', 34, 26, 'And I have given them, and the suburbs of my hill, a blessing, And caused the shower to come down in its season, Showers of blessing they are.'),
  ('YLT', 'EZK', 34, 27, 'And given hath the tree of the field its fruit, And the land doth give her increase, And they have been on their land confident, And they have known that I am Jehovah, In My breaking the bands of their yoke, And I have delivered them from the hand of those laying service on them.'),
  ('YLT', 'EZK', 34, 28, 'And they are no more a prey to nations, And the beast of the earth devoureth them not, And they have dwelt confidently, And there is none troubling.'),
  ('YLT', 'EZK', 34, 29, 'And I have raised for them a plant for renown, And they are no more consumed by hunger in the land, And they bear no more the shame of the nations.'),
  ('YLT', 'EZK', 34, 30, 'And they have known that I, Jehovah, their God, am with them, And they--the house of Israel--My people, An affirmation of the Lord Jehovah.'),
  ('YLT', 'EZK', 34, 31, 'And ye, My flock, the flock of My pasture, Men ye are --I am your God, An affirmation of the Lord Jehovah!'''),
  ('YLT', 'MAT', 13, 1, 'And in that day Jesus, having gone forth from the house, was sitting by the sea,'),
  ('YLT', 'MAT', 13, 2, 'and gathered together unto him were many multitudes, so that he having gone into the boat did sit down, and all the multitude on the beach did stand,'),
  ('YLT', 'MAT', 13, 3, 'and he spake to them many things in similes, saying: `Lo, the sower went forth to sow,'),
  ('YLT', 'MAT', 13, 4, 'and in his sowing, some indeed fell by the way, and the fowls did come and devour them,'),
  ('YLT', 'MAT', 13, 5, 'and others fell upon the rocky places, where they had not much earth, and immediately they sprang forth, through not having depth of earth,'),
  ('YLT', 'MAT', 13, 6, 'and the sun having risen they were scorched, and through not having root, they withered,'),
  ('YLT', 'MAT', 13, 7, 'and others fell upon the thorns, and the thorns did come up and choke them,'),
  ('YLT', 'MAT', 13, 8, 'and others fell upon the good ground, and were giving fruit, some indeed a hundredfold, and some sixty, and some thirty.'),
  ('YLT', 'MAT', 13, 9, 'He who is having ears to hear--let him hear.'''),
  ('YLT', 'MAT', 13, 10, 'And the disciples having come near, said to him, `Wherefore in similes dost thou speak to them?'''),
  ('YLT', 'MAT', 13, 11, 'And he answering said to them that--`To you it hath been given to know the secrets of the reign of the heavens, and to these it hath not been given,'),
  ('YLT', 'MAT', 13, 12, 'for whoever hath, it shall be given to him, and he shall have overabundance, and whoever hath not, even that which he hath shall be taken from him.'),
  ('YLT', 'MAT', 13, 13, '`Because of this, in similes do I speak to them, because seeing they do not see, and hearing they do not hear, nor understand,'),
  ('YLT', 'MAT', 13, 14, 'and fulfilled on them is the prophecy of Isaiah, that saith, With hearing ye shall hear, and ye shall not understand, and seeing ye shall see, and ye shall not perceive,'),
  ('YLT', 'MAT', 13, 15, 'for made gross was the heart of this people, and with the ears they heard heavily, and their eyes they did close, lest they might see with the eyes, and with the ears might hear, and with the heart understand, and turn back, and I might heal them.'),
  ('YLT', 'MAT', 13, 16, '`And happy are your eyes because they see, and your ears because they hear,'),
  ('YLT', 'MAT', 13, 17, 'for verily I say to you, that many prophets and righteous men did desire to see that which ye look on, and they did not see, and to hear that which ye hear, and they did not hear.'),
  ('YLT', 'MAT', 13, 18, '`Ye, therefore, hear ye the simile of the sower:'),
  ('YLT', 'MAT', 13, 19, 'Every one hearing the word of the reign, and not understanding--the evil one doth come, and doth catch that which hath been sown in his heart; this is that sown by the way.'),
  ('YLT', 'MAT', 13, 20, '`And that sown on the rocky places, this is he who is hearing the word, and immediately with joy is receiving it,'),
  ('YLT', 'MAT', 13, 21, 'and he hath not root in himself, but is temporary, and persecution or tribulation having happened because of the word, immediately he is stumbled.'),
  ('YLT', 'MAT', 13, 22, '`And that sown toward the thorns, this is he who is hearing the word, and the anxiety of this age, and the deceitfulness of the riches, do choke the word, and it becometh unfruitful.'),
  ('YLT', 'MAT', 13, 23, '`And that sown on the good ground: this is he who is hearing the word, and is understanding, who indeed doth bear fruit, and doth make, some indeed a hundredfold, and some sixty, and some thirty.'''),
  ('YLT', 'MAT', 13, 24, 'Another simile he set before them, saying: `The reign of the heavens was likened to a man sowing good seed in his field,'),
  ('YLT', 'MAT', 13, 25, 'and, while men are sleeping, his enemy came and sowed darnel in the midst of the wheat, and went away,'),
  ('YLT', 'MAT', 13, 26, 'and when the herb sprang up, and yielded fruit, then appeared also the darnel.'),
  ('YLT', 'MAT', 13, 27, '`And the servants of the householder, having come near, said to him, Sir, good seed didst thou not sow in thy field? whence then hath it the darnel?'),
  ('YLT', 'MAT', 13, 28, 'And he saith to them, A man, an enemy, did this; and the servants said to him, Wilt thou, then, that having gone away we may gather it up?'),
  ('YLT', 'MAT', 13, 29, '`And he said, No, lest--gathering up the darnel--ye root up with it the wheat,'),
  ('YLT', 'MAT', 13, 30, 'suffer both to grow together till the harvest, and in the time of the harvest I will say to the reapers, Gather up first the darnel, and bind it in bundles, to burn it, and the wheat gather up into my storehouse.'''),
  ('YLT', 'MAT', 13, 31, 'Another simile he set before them, saying: `The reign of the heavens is like to a grain of mustard, which a man having taken, did sow in his field,'),
  ('YLT', 'MAT', 13, 32, 'which less, indeed, is than all the seeds, but when it may be grown, is greatest of the herbs, and becometh a tree, so that the birds of the heaven do come and rest in its branches.'''),
  ('YLT', 'MAT', 13, 33, 'Another simile spake he to them: `The reign of the heavens is like to leaven, which a woman having taken, hid in three measures of meal, till the whole was leavened.'''),
  ('YLT', 'MAT', 13, 34, 'All these things spake Jesus in similes to the multitudes, and without a simile he was not speaking to them,'),
  ('YLT', 'MAT', 13, 35, 'that it might be fulfilled that was spoken through the prophet, saying, `I will open in similes my mouth, I will utter things having been hidden from the foundation of the world.'''),
  ('YLT', 'MAT', 13, 36, 'Then having let away the multitudes, Jesus came to the house, and his disciples came near to him, saying, `Explain to us the simile of the darnel of the field.'''),
  ('YLT', 'MAT', 13, 37, 'And he answering said to them, `He who is sowing the good seed is the Son of Man,'),
  ('YLT', 'MAT', 13, 38, 'and the field is the world, and the good seed, these are the sons of the reign, and the darnel are the sons of the evil one,'),
  ('YLT', 'MAT', 13, 39, 'and the enemy who sowed them is the devil, and the harvest is a full end of the age, and the reapers are messengers.'),
  ('YLT', 'MAT', 13, 40, '`As, then, the darnel is gathered up, and is burned with fire, so shall it be in the full end of this age,'),
  ('YLT', 'MAT', 13, 41, 'the Son of Man shall send forth his messengers, and they shall gather up out of his kingdom all the stumbling-blocks, and those doing the unlawlessness,'),
  ('YLT', 'MAT', 13, 42, 'and shall cast them to the furnace of the fire; there shall be the weeping and the gnashing of the teeth.'),
  ('YLT', 'MAT', 13, 43, '`Then shall the righteous shine forth as the sun in the reign of their Father. He who is having ears to hear--let him hear.'),
  ('YLT', 'MAT', 13, 44, '`Again, the reign of the heavens is like to treasure hid in the field, which a man having found did hide, and from his joy goeth, and all, as much as he hath, he selleth, and buyeth that field.'),
  ('YLT', 'MAT', 13, 45, '`Again, the reign of the heavens is like to a man, a merchant, seeking goodly pearls,'),
  ('YLT', 'MAT', 13, 46, 'who having found one pearl of great price, having gone away, hath sold all, as much as he had, and bought it.'),
  ('YLT', 'MAT', 13, 47, '`Again, the reign of the heavens is like to a net that was cast into the sea, and did gather together of every kind,'),
  ('YLT', 'MAT', 13, 48, 'which, when it was filled, having drawn up again upon the beach, and having sat down, they gathered the good into vessels, and the bad they did cast out,'),
  ('YLT', 'MAT', 13, 49, 'so shall it be in the full end of the age, the messengers shall come forth and separate the evil out of the midst of the righteous,'),
  ('YLT', 'MAT', 13, 50, 'and shall cast them to the furnace of the fire, there shall be the weeping and the gnashing of the teeth.'''),
  ('YLT', 'MAT', 13, 51, 'Jesus saith to them, `Did ye understand all these?'' They say to him, `Yes, sir.'''),
  ('YLT', 'MAT', 13, 52, 'And he said to them, `Because of this every scribe having been discipled in regard to the reign of the heavens, is like to a man, a householder, who doth bring forth out of his treasure things new and old.'''),
  ('YLT', 'MAT', 13, 53, 'And it came to pass, when Jesus finished these similes, he removed thence,'),
  ('YLT', 'MAT', 13, 54, 'and having come to his own country, he was teaching them in their synagogue, so that they were astonished, and were saying, `Whence to this one this wisdom and the mighty works?'),
  ('YLT', 'MAT', 13, 55, 'is not this the carpenter''s son? is not his mother called Mary, and his brethren James, and Joses, and Simon, and Judas?'),
  ('YLT', 'MAT', 13, 56, 'and his sisters--are they not all with us? whence, then, to this one all these?'''),
  ('YLT', 'MAT', 13, 57, 'and they were stumbled at him. And Jesus said to them, `A prophet is not without honour except in his own country, and in his own house:'''),
  ('YLT', 'MAT', 13, 58, 'and he did not there many mighty works, because of their unbelief.'),
  ('YLT', 'JHN', 1, 1, 'In the beginning was the Word, and the Word was with God, and the Word was God;'),
  ('YLT', 'JHN', 1, 2, 'this one was in the beginning with God;'),
  ('YLT', 'JHN', 1, 3, 'all things through him did happen, and without him happened not even one thing that hath happened.'),
  ('YLT', 'JHN', 1, 4, 'In him was life, and the life was the light of men,'),
  ('YLT', 'JHN', 1, 5, 'and the light in the darkness did shine, and the darkness did not perceive it.'),
  ('YLT', 'JHN', 1, 6, 'There came a man--having been sent from God--whose name is John,'),
  ('YLT', 'JHN', 1, 7, 'this one came for testimony, that he might testify about the Light, that all might believe through him;'),
  ('YLT', 'JHN', 1, 8, 'that one was not the Light, but--that he might testify about the Light.'),
  ('YLT', 'JHN', 1, 9, 'He was the true Light, which doth enlighten every man, coming to the world;'),
  ('YLT', 'JHN', 1, 10, 'in the world he was, and the world through him was made, and the world did not know him:'),
  ('YLT', 'JHN', 1, 11, 'to his own things he came, and his own people did not receive him;'),
  ('YLT', 'JHN', 1, 12, 'but as many as did receive him to them he gave authority to become sons of God--to those believing in his name,'),
  ('YLT', 'JHN', 1, 13, 'who--not of blood nor of a will of flesh, nor of a will of man but--of God were begotten.'),
  ('YLT', 'JHN', 1, 14, 'And the Word became flesh, and did tabernacle among us, and we beheld his glory, glory as of an only begotten of a father, full of grace and truth.'),
  ('YLT', 'JHN', 1, 15, 'John doth testify concerning him, and hath cried, saying, `This was he of whom I said, He who after me is coming, hath come before me, for he was before me;'''),
  ('YLT', 'JHN', 1, 16, 'and out of his fulness did we all receive, and grace over-against grace;'),
  ('YLT', 'JHN', 1, 17, 'for the law through Moses was given, the grace and the truth through Jesus Christ did come;'),
  ('YLT', 'JHN', 1, 18, 'God no one hath ever seen; the only begotten Son, who is on the bosom of the Father--he did declare.'),
  ('YLT', 'JHN', 1, 19, 'And this is the testimony of John, when the Jews sent out of Jerusalem priests and Levites, that they might question him, `Who art thou?'''),
  ('YLT', 'JHN', 1, 20, 'and he confessed and did not deny, and confessed--`I am not the Christ.'''),
  ('YLT', 'JHN', 1, 21, 'And they questioned him, `What then? Elijah art thou?'' and he saith, `I am not.'' --`The prophet art thou?'' and he answered, `No.'''),
  ('YLT', 'JHN', 1, 22, 'They said then to him, `Who art thou, that we may give an answer to those sending us? what dost thou say concerning thyself?'''),
  ('YLT', 'JHN', 1, 23, 'He said, `I am a voice of one crying in the wilderness: Make straight the way of the Lord, as said Isaiah the prophet.'''),
  ('YLT', 'JHN', 1, 24, 'And those sent were of the Pharisees,'),
  ('YLT', 'JHN', 1, 25, 'and they questioned him and said to him, `Why, then, dost thou baptize, if thou art not the Christ, nor Elijah, nor the prophet?'''),
  ('YLT', 'JHN', 1, 26, 'John answered them, saying, `I baptize with water, but in midst of you he hath stood whom ye have not known, this one it is who is coming after me, who hath been before me,'),
  ('YLT', 'JHN', 1, 27, 'of whom I am not worthy that I may loose the cord of his sandal.'''),
  ('YLT', 'JHN', 1, 28, 'These things came to pass in Bethabara, beyond the Jordan, where John was baptizing,'),
  ('YLT', 'JHN', 1, 29, 'on the morrow John seeth Jesus coming unto him, and saith, `Lo, the Lamb of God, who is taking away the sin of the world;'),
  ('YLT', 'JHN', 1, 30, 'this is he concerning whom I said, After me doth come a man, who hath come before me, because he was before me:'),
  ('YLT', 'JHN', 1, 31, 'and I knew him not, but, that he might be manifested to Israel, because of this I came with the water baptizing.'),
  ('YLT', 'JHN', 1, 32, 'And John testified, saying--`I have seen the Spirit coming down, as a dove, out of heaven, and it remained on him;'),
  ('YLT', 'JHN', 1, 33, 'and I did not know him, but he who sent me to baptize with water, He said to me, On whomsoever thou mayest see the Spirit coming down, and remaining on him, this is he who is baptizing with the Holy Spirit;'),
  ('YLT', 'JHN', 1, 34, 'and I have seen, and have testified, that this is the Son of God.'''),
  ('YLT', 'JHN', 1, 35, 'On the morrow, again, John was standing, and two of his disciples,'),
  ('YLT', 'JHN', 1, 36, 'and having looked on Jesus walking, he saith, `Lo, the Lamb of God;'''),
  ('YLT', 'JHN', 1, 37, 'and the two disciples heard him speaking, and they followed Jesus.'),
  ('YLT', 'JHN', 1, 38, 'And Jesus having turned, and having beheld them following, saith to them, `What seek ye?'' and they said to them, `Rabbi, (which is, being interpreted, Teacher,) where remainest thou?'''),
  ('YLT', 'JHN', 1, 39, 'He saith to them, `Come and see;'' they came, and saw where he doth remain, and with him they remained that day and the hour was about the tenth.'),
  ('YLT', 'JHN', 1, 40, 'Andrew, the brother of Simon Peter, was one of the two who heard from John, and followed him;'),
  ('YLT', 'JHN', 1, 41, 'this one doth first find his own brother Simon, and saith to him, `We have found the Messiah,'' (which is, being interpreted, The Anointed,)'),
  ('YLT', 'JHN', 1, 42, 'and he brought him unto Jesus: and having looked upon him, Jesus saith, `Thou art Simon, the son of Jonas, thou shalt be called Cephas,'' (which is interpreted, A rock.)'),
  ('YLT', 'JHN', 1, 43, 'On the morrow, he willed to go forth to Galilee, and he findeth Philip, and saith to him, `Be following me.'''),
  ('YLT', 'JHN', 1, 44, 'And Philip was from Bethsaida, of the city of Andrew and Peter;'),
  ('YLT', 'JHN', 1, 45, 'Philip findeth Nathanael, and saith to him, `Him of whom Moses wrote in the Law, and the prophets, we have found, Jesus the son of Joseph, who is from Nazareth;'''),
  ('YLT', 'JHN', 1, 46, 'and Nathanael said to him, `Out of Nazareth is any good thing able to be?'' Philip said to him, `Come and see.'''),
  ('YLT', 'JHN', 1, 47, 'Jesus saw Nathanael coming unto him, and he saith concerning him, `Lo, truly an Israelite, in whom guile is not;'''),
  ('YLT', 'JHN', 1, 48, 'Nathanael saith to him, `Whence me dost thou know?'' Jesus answered and said to him, `Before Philip''s calling thee--thou being under the fig-tree--I saw thee.'''),
  ('YLT', 'JHN', 1, 49, 'Nathanael answered and saith to him, `Rabbi, thou art the Son of God, thou art the king of Israel.'''),
  ('YLT', 'JHN', 1, 50, 'Jesus answered and said to him, `Because I said to thee, I saw thee under the fig-tree, thou dost believe; greater things than these thou shalt see;'''),
  ('YLT', 'JHN', 1, 51, 'and he saith to him, `Verily, verily, I say to you, henceforth ye shall see the heaven opened, and the messengers of God going up and coming down upon the Son of Man.'''),
  ('YLT', 'JHN', 4, 1, 'When therefore the Lord knew that the Pharisees heard that Jesus more disciples doth make and baptize than John,'),
  ('YLT', 'JHN', 4, 2, '(though indeed Jesus himself was not baptizing, but his disciples,)'),
  ('YLT', 'JHN', 4, 3, 'he left Judea and went away again to Galilee,'),
  ('YLT', 'JHN', 4, 4, 'and it was behoving him to go through Samaria.'),
  ('YLT', 'JHN', 4, 5, 'He cometh, therefore, to a city of Samaria, called Sychar, near to the place that Jacob gave to Joseph his son;'),
  ('YLT', 'JHN', 4, 6, 'and there was there a well of Jacob. Jesus therefore having been weary from the journeying, was sitting thus on the well; it was as it were the sixth hour;'),
  ('YLT', 'JHN', 4, 7, 'there cometh a woman out of Samaria to draw water. Jesus saith to her, `Give me to drink;'''),
  ('YLT', 'JHN', 4, 8, 'for his disciples were gone away to the city, that they may buy victuals;'),
  ('YLT', 'JHN', 4, 9, 'the Samaritan woman therefore saith to him, `How dost thou, being a Jew, ask drink from me, being a Samaritan woman?'' for Jews have no dealing with Samaritans.'),
  ('YLT', 'JHN', 4, 10, 'Jesus answered and said to her, `If thou hadst known the gift of God, and who it is who is saying to thee, Give me to drink, thou wouldest have asked him, and he would have given thee living water.'''),
  ('YLT', 'JHN', 4, 11, 'The woman saith to him, `Sir, thou hast not even a vessel to draw with, and the well is deep; whence, then, hast thou the living water?'),
  ('YLT', 'JHN', 4, 12, 'Art thou greater than our father Jacob, who did give us the well, and himself out of it did drink, and his sons, and his cattle?'''),
  ('YLT', 'JHN', 4, 13, 'Jesus answered and said to her, `Every one who is drinking of this water shall thirst again;'),
  ('YLT', 'JHN', 4, 14, 'but whoever may drink of the water that I will give him, may not thirst--to the age; and the water that I will give him shall become in him a well of water, springing up to life age-during.'''),
  ('YLT', 'JHN', 4, 15, 'The woman saith unto him, `Sir, give me this water, that I may not thirst, nor come hither to draw.'''),
  ('YLT', 'JHN', 4, 16, 'Jesus saith to her, `Go, call thy husband, and come hither;'''),
  ('YLT', 'JHN', 4, 17, 'the woman answered and said, `I have not a husband.'' Jesus saith to her, `Well didst thou say--A husband I have not;'),
  ('YLT', 'JHN', 4, 18, 'for five husbands thou hast had, and, now, he whom thou hast is not thy husband; this hast thou said truly.'''),
  ('YLT', 'JHN', 4, 19, 'The woman saith to him, `Sir, I perceive that thou art a prophet;'),
  ('YLT', 'JHN', 4, 20, 'our fathers in this mountain did worship, and ye--ye say that in Jerusalem is the place where it behoveth to worship.'''),
  ('YLT', 'JHN', 4, 21, 'Jesus saith to her, `Woman, believe me, that there doth come an hour, when neither in this mountain, nor in Jerusalem, shall ye worship the Father;'),
  ('YLT', 'JHN', 4, 22, 'ye worship what ye have not known; we worship what we have known, because the salvation is of the Jews;'),
  ('YLT', 'JHN', 4, 23, 'but, there cometh an hour, and it now is, when the true worshippers will worship the Father in spirit and truth, for the Father also doth seek such to worship him;'),
  ('YLT', 'JHN', 4, 24, 'God is a Spirit, and those worshipping Him, in spirit and truth it doth behove to worship.'''),
  ('YLT', 'JHN', 4, 25, 'The woman saith to him, `I have known that Messiah doth come, who is called Christ, when that one may come, he will tell us all things;'''),
  ('YLT', 'JHN', 4, 26, 'Jesus saith to her, `I am he, who am speaking to thee.'''),
  ('YLT', 'JHN', 4, 27, 'And upon this came his disciples, and were wondering that with a woman he was speaking, no one, however, said, `What seekest thou?'' or `Why speakest thou with her?'''),
  ('YLT', 'JHN', 4, 28, 'The woman then left her water-jug, and went away to the city, and saith to the men,'),
  ('YLT', 'JHN', 4, 29, '`Come, see a man, who told me all things--as many as I did; is this the Christ?'''),
  ('YLT', 'JHN', 4, 30, 'They went forth therefore out of the city, and were coming unto him.'),
  ('YLT', 'JHN', 4, 31, 'And in the meanwhile his disciples were asking him, saying, `Rabbi, eat;'''),
  ('YLT', 'JHN', 4, 32, 'and he said to them, `I have food to eat that ye have not known.'''),
  ('YLT', 'JHN', 4, 33, 'The disciples then said one to another, `Did any one bring him anything to eat?'''),
  ('YLT', 'JHN', 4, 34, 'Jesus saith to them, `My food is, that I may do the will of Him who sent me, and may finish His work;'),
  ('YLT', 'JHN', 4, 35, 'do not say that it is yet four months, and the harvest cometh; lo, I say to you, Lift up your eyes, and see the fields, that they are white unto harvest already.'),
  ('YLT', 'JHN', 4, 36, '`And he who is reaping doth receive a reward, and doth gather fruit to life age-during, that both he who is sowing and he who is reaping may rejoice together;'),
  ('YLT', 'JHN', 4, 37, 'for in this the saying is the true one, that one is the sower and another the reaper.'),
  ('YLT', 'JHN', 4, 38, 'I sent you to reap that on which ye have not laboured; others laboured, and ye into their labour have entered.'),
  ('YLT', 'JHN', 4, 39, 'And from that city many believed in him, of the Samaritans, because of the word of the woman testifying, --`He told me all things--as many as I did.'''),
  ('YLT', 'JHN', 4, 40, 'When, then, the Samaritans came unto him, they were asking him to remain with them, and he remained there two days;'),
  ('YLT', 'JHN', 4, 41, 'and many more did believe because of his word,'),
  ('YLT', 'JHN', 4, 42, 'and said to the woman--`No more because of thy speaking do we believe; for we ourselves have heard and known that this is truly the Saviour of the world--the Christ.'''),
  ('YLT', 'JHN', 4, 43, 'And after the two days he went forth thence, and went away to Galilee,'),
  ('YLT', 'JHN', 4, 44, 'for Jesus himself testified that a prophet in his own country shall not have honour;'),
  ('YLT', 'JHN', 4, 45, 'when then, he came to Galilee, the Galileans received him, having seen all things that he did in Jerusalem in the feast--for they also went to the feast.'),
  ('YLT', 'JHN', 4, 46, 'Jesus came, therefore, again to Cana of Galilee, where he made the water wine, and there was a certain courtier, whose son was ailing in Capernaum,'),
  ('YLT', 'JHN', 4, 47, 'he, having heard that Jesus is come out of Judea to Galilee, went away unto him, and was asking him that he may come down and may heal his son, for he was about to die.'),
  ('YLT', 'JHN', 4, 48, 'Jesus then said unto him, `If signs and wonders ye may not see, ye will not believe.'''),
  ('YLT', 'JHN', 4, 49, 'The courtier saith unto him, `Sir, come down before my child die;'''),
  ('YLT', 'JHN', 4, 50, 'Jesus saith to him, `Be going on; thy son doth live.'' And the man believed the word that Jesus said to him, and was going on,'),
  ('YLT', 'JHN', 4, 51, 'and he now going down, his servants met him, and told, saying--`Thy child doth live;'''),
  ('YLT', 'JHN', 4, 52, 'he inquired then of them the hour in which he became better, and they said to him--`Yesterday at the seventh hour the fever left him;'''),
  ('YLT', 'JHN', 4, 53, 'then the father knew that it was in that hour in which Jesus said to him--`Thy son doth live,'' and he himself believed, and his whole house;'),
  ('YLT', 'JHN', 4, 54, 'this again a second sign did Jesus, having come out of Judea to Galilee.'),
  ('YLT', 'JHN', 5, 1, 'After these things there was a feast of the Jews, and Jesus went up to Jerusalem,'),
  ('YLT', 'JHN', 5, 2, 'and there is in Jerusalem by the sheep- gate a pool that is called in Hebrew Bethesda, having five porches,'),
  ('YLT', 'JHN', 5, 3, 'in these were lying a great multitude of the ailing, blind, lame, withered, waiting for the moving of the water,'),
  ('YLT', 'JHN', 5, 4, 'for a messenger at a set time was going down in the pool, and was troubling the water, the first then having gone in after the troubling of the water, became whole of whatever sickness he was held.'),
  ('YLT', 'JHN', 5, 5, 'and there was a certain man there being in ailment thirty and eight years,'),
  ('YLT', 'JHN', 5, 6, 'him Jesus having seen lying, and having known that he is already a long time, he saith to him, `Dost thou wish to become whole?'''),
  ('YLT', 'JHN', 5, 7, 'The ailing man answered him, `Sir, I have no man, that, when the water may be troubled, he may put me into the pool, and while I am coming, another doth go down before me.'''),
  ('YLT', 'JHN', 5, 8, 'Jesus saith to him, `Rise, take up thy couch, and be walking;'''),
  ('YLT', 'JHN', 5, 9, 'and immediately the man became whole, and he took up his couch, and was walking, and it was a sabbath on that day,'),
  ('YLT', 'JHN', 5, 10, 'the Jews then said to him that hath been healed, `It is a sabbath; it is not lawful to thee to take up the couch.'''),
  ('YLT', 'JHN', 5, 11, 'He answered them, `He who made me whole--that one said to me, Take up thy couch, and be walking;'''),
  ('YLT', 'JHN', 5, 12, 'they questioned him, then, `Who is the man who is saying to thee, Take up thy couch and be walking?'''),
  ('YLT', 'JHN', 5, 13, 'But he that was healed had not known who he is, for Jesus did move away, a multitude being in the place.'),
  ('YLT', 'JHN', 5, 14, 'After these things, Jesus findeth him in the temple, and said to him, `Lo, thou hast become whole; sin no more, lest something worse may happen to thee.'''),
  ('YLT', 'JHN', 5, 15, 'The man went away, and told the Jews that it is Jesus who made him whole,'),
  ('YLT', 'JHN', 5, 16, 'and because of this were the Jews persecuting Jesus, and seeking to kill him, because these things he was doing on a sabbath.'),
  ('YLT', 'JHN', 5, 17, 'And Jesus answered them, `My Father till now doth work, and I work;'''),
  ('YLT', 'JHN', 5, 18, 'because of this, then, were the Jews seeking the more to kill him, because not only was he breaking the sabbath, but he also called God his own Father, making himself equal to God.'),
  ('YLT', 'JHN', 5, 19, 'Jesus therefore responded and said to them, `Verily, verily, I say to you, The Son is not able to do anything of himself, if he may not see the Father doing anything; for whatever things He may do, these also the Son in like manner doth;'),
  ('YLT', 'JHN', 5, 20, 'for the Father doth love the Son, and doth shew to him all things that He himself doth; and greater works than these He will shew him, that ye may wonder.'),
  ('YLT', 'JHN', 5, 21, '`For, as the Father doth raise the dead, and doth make alive, so also the Son doth make alive whom he willeth;'),
  ('YLT', 'JHN', 5, 22, 'for neither doth the Father judge any one, but all the judgment He hath given to the Son,'),
  ('YLT', 'JHN', 5, 23, 'that all may honour the Son according as they honour the Father; he who is not honouring the Son, doth not honour the Father who sent him.'),
  ('YLT', 'JHN', 5, 24, '`Verily, verily, I say to you--He who is hearing my word, and is believing Him who sent me, hath life age-during, and to judgment he doth not come, but hath passed out of the death to the life.'),
  ('YLT', 'JHN', 5, 25, '`Verily, verily, I say to you--There cometh an hour, and it now is, when the dead shall hear the voice of the Son of God, and those having heard shall live;'),
  ('YLT', 'JHN', 5, 26, 'for, as the Father hath life in himself, so He gave also to the Son to have life in himself,'),
  ('YLT', 'JHN', 5, 27, 'and authority He gave him also to do judgment, because he is Son of Man.'),
  ('YLT', 'JHN', 5, 28, '`Wonder not at this, because there doth come an hour in which all those in the tombs shall hear his voice,'),
  ('YLT', 'JHN', 5, 29, 'and they shall come forth; those who did the good things to a rising again of life, and those who practised the evil things to a rising again of judgment.'),
  ('YLT', 'JHN', 5, 30, '`I am not able of myself to do anything; according as I hear I judge, and my judgment is righteous, because I seek not my own will, but the will of the Father who sent me.'),
  ('YLT', 'JHN', 5, 31, '`If I testify concerning myself, my testimony is not true;'),
  ('YLT', 'JHN', 5, 32, 'another there is who is testifying concerning me, and I have known that the testimony that he doth testify concerning me is true;'),
  ('YLT', 'JHN', 5, 33, 'ye have sent unto John, and he hath testified to the truth.'),
  ('YLT', 'JHN', 5, 34, '`But I do not receive testimony from man, but these things I say that ye may be saved;'),
  ('YLT', 'JHN', 5, 35, 'he was the burning and shining lamp, and ye did will to be glad, for an hour, in his light.'),
  ('YLT', 'JHN', 5, 36, '`But I have the testimony greater than John''s, for the works that the Father gave me, that I might finish them, the works themselves that I do, they testify concerning me, that the Father hath sent me.'),
  ('YLT', 'JHN', 5, 37, '`And the Father who sent me Himself hath testified concerning me; ye have neither heard His voice at any time, nor His appearance have ye seen;'),
  ('YLT', 'JHN', 5, 38, 'and His word ye have not remaining in you, because whom He sent, him ye do not believe.'),
  ('YLT', 'JHN', 5, 39, '`Ye search the Writings, because ye think in them to have life age-during, and these are they that are testifying concerning me;'),
  ('YLT', 'JHN', 5, 40, 'and ye do not will to come unto me, that ye may have life;'),
  ('YLT', 'JHN', 5, 41, 'glory from man I do not receive,'),
  ('YLT', 'JHN', 5, 42, 'but I have known you, that the love of God ye have not in yourselves.'),
  ('YLT', 'JHN', 5, 43, '`I have come in the name of my Father, and ye do not receive me; if another may come in his own name, him ye will receive;'),
  ('YLT', 'JHN', 5, 44, 'how are ye able--ye--to believe, glory from one another receiving, and the glory that is from God alone ye seek not?'),
  ('YLT', 'JHN', 5, 45, '`Do not think that I will accuse you unto the Father; there is who is accusing you, Moses--in whom ye have hoped;'),
  ('YLT', 'JHN', 5, 46, 'for if ye were believing Moses, ye would have been believing me, for he wrote concerning me;'),
  ('YLT', 'JHN', 5, 47, 'but if his writings ye believe not, how shall ye believe my sayings?'''),
  ('YLT', 'JHN', 8, 1, 'And at dawn he came again to the temple,'),
  ('YLT', 'JHN', 8, 2, 'and all the people were coming unto him, and having sat down, he was teaching them;'),
  ('YLT', 'JHN', 8, 3, 'and the scribes and the Pharisees bring unto him a woman having been taken in adultery, and having set her in the midst,'),
  ('YLT', 'JHN', 8, 4, 'they say to him, `Teacher, this woman was taken in the very crime--committing adultery,'),
  ('YLT', 'JHN', 8, 5, 'and in the law, Moses did command us that such be stoned; thou, therefore, what dost thou say?'''),
  ('YLT', 'JHN', 8, 6, 'and this they said, trying him, that they might have to accuse him. And Jesus, having stooped down, with the finger he was writing on the ground,'),
  ('YLT', 'JHN', 8, 7, 'and when they continued asking him, having bent himself back, he said unto them, `The sinless of you--let him first cast the stone at her;'''),
  ('YLT', 'JHN', 8, 8, 'and again having stooped down, he was writing on the ground,'),
  ('YLT', 'JHN', 8, 9, 'and they having heard, and by the conscience being convicted, were going forth one by one, having begun from the elders--unto the last; and Jesus was left alone, and the woman standing in the midst.'),
  ('YLT', 'JHN', 8, 10, 'And Jesus having bent himself back, and having seen no one but the woman, said to her, `Woman, where are those--thine accusers? did no one pass sentence upon thee?'''),
  ('YLT', 'JHN', 8, 11, 'and she said, `No one, Sir;'' and Jesus said to her, `Neither do I pass sentence on thee; be going on, and no more sin.'''),
  ('YLT', 'JHN', 8, 12, 'Again, therefore, Jesus spake to them, saying, `I am the light of the world; he who is following me shall not walk in the darkness, but he shall have the light of the life.'''),
  ('YLT', 'JHN', 8, 13, 'The Pharisees, therefore, said to him, `Thou of thyself dost testify, thy testimony is not true;'''),
  ('YLT', 'JHN', 8, 14, 'Jesus answered and said to them, `And if I testify of myself--my testimony is true, because I have known whence I came, and whither I go, and ye--ye have not known whence I come, or whither I go.'),
  ('YLT', 'JHN', 8, 15, '`Ye according to the flesh do judge; I do not judge any one,'),
  ('YLT', 'JHN', 8, 16, 'and even if I do judge my judgment is true, because I am not alone, but I and the Father who sent me;'),
  ('YLT', 'JHN', 8, 17, 'and also in your law it hath been written, that the testimony of two men are true;'),
  ('YLT', 'JHN', 8, 18, 'I am one who is testifying of myself, and the Father who sent me doth testify of me.'''),
  ('YLT', 'JHN', 8, 19, 'They said, therefore, to him, `Where is thy father?'' Jesus answered, `Ye have neither known me nor my Father: if me ye had known, my Father also ye had known.'''),
  ('YLT', 'JHN', 8, 20, 'These sayings spake Jesus in the treasury, teaching in the temple, and no one seized him, because his hour had not yet come;'),
  ('YLT', 'JHN', 8, 21, 'therefore said Jesus again to them, `I go away, and ye will seek me, and in your sin ye shall die; whither I go away, ye are not able to come.'''),
  ('YLT', 'JHN', 8, 22, 'The Jews, therefore, said, `Will he kill himself, because he saith, Whither I go away, ye are not able to come?'''),
  ('YLT', 'JHN', 8, 23, 'and he said to them, `Ye are from beneath, I am from above; ye are of this world, I am not of this world;'),
  ('YLT', 'JHN', 8, 24, 'I said, therefore, to you, that ye shall die in your sins, for if ye may not believe that I am he, ye shall die in your sins.'''),
  ('YLT', 'JHN', 8, 25, 'They said, therefore, to him, `Thou--who art thou?'' and Jesus said to them, `Even what I did speak of to you at the beginning;'),
  ('YLT', 'JHN', 8, 26, 'many things I have to speak concerning you and to judge, but He who sent me is true, and I--what things I heard from Him--these I say to the world.'''),
  ('YLT', 'JHN', 8, 27, 'They knew not that of the Father he spake to them;'),
  ('YLT', 'JHN', 8, 28, 'Jesus, therefore, said to them, `When ye may lift up the Son of Man then ye will know that I am he; and of myself I do nothing, but according as my Father did teach me, these things I speak;'),
  ('YLT', 'JHN', 8, 29, 'and He who sent me is with me; the Father did not leave me alone, because I, the things pleasing to Him, do always.'''),
  ('YLT', 'JHN', 8, 30, 'As he is speaking these things, many believed in him;'),
  ('YLT', 'JHN', 8, 31, 'Jesus, therefore, said unto the Jews who believed in him, `If ye may remain in my word, truly my disciples ye are, and ye shall know the truth,'),
  ('YLT', 'JHN', 8, 32, 'and the truth shall make you free.'''),
  ('YLT', 'JHN', 8, 33, 'They answered him, `Seed of Abraham we are; and to no one have we been servants at any time; how dost thou say--Ye shall become free?'''),
  ('YLT', 'JHN', 8, 34, 'Jesus answered them, `Verily, verily, I say to you--Every one who is committing sin, is a servant of the sin,'),
  ('YLT', 'JHN', 8, 35, 'and the servant doth not remain in the house--to the age, the son doth remain--to the age;'),
  ('YLT', 'JHN', 8, 36, 'if then the son may make you free, in reality ye shall be free.'),
  ('YLT', 'JHN', 8, 37, '`I have known that ye are seed of Abraham, but ye seek to kill me, because my word hath no place in you;'),
  ('YLT', 'JHN', 8, 38, 'I--that which I have seen with my Father do speak, and ye, therefore, that which ye have seen with your father--ye do.'''),
  ('YLT', 'JHN', 8, 39, 'They answered and said to him, `Our father is Abraham;'' Jesus saith to them, `If children of Abraham ye were, the works of Abraham ye were doing;'),
  ('YLT', 'JHN', 8, 40, 'and now, ye seek to kill me--a man who hath spoken to you the truth I heard from God; this Abraham did not;'),
  ('YLT', 'JHN', 8, 41, 'ye do the works of your father.'' They said, therefore, to him, `We of whoredom have not been born; one Father we have--God;'''),
  ('YLT', 'JHN', 8, 42, 'Jesus then said to them, `If God were your father, ye were loving me, for I came forth from God, and am come; for neither have I come of myself, but He sent me;'),
  ('YLT', 'JHN', 8, 43, 'wherefore do ye not know my speech? because ye are not able to hear my word.'),
  ('YLT', 'JHN', 8, 44, '`Ye are of a father--the devil, and the desires of your father ye will to do; he was a man-slayer from the beginning, and in the truth he hath not stood, because there is no truth in him; when one may speak the falsehood, of his own he speaketh, because he is a liar--also his father.'),
  ('YLT', 'JHN', 8, 45, '`And because I say the truth, ye do not believe me.'),
  ('YLT', 'JHN', 8, 46, 'Who of you doth convict me of sin? and if I speak truth, wherefore do ye not believe me?'),
  ('YLT', 'JHN', 8, 47, 'he who is of God, the sayings of God he doth hear; because of this ye do not hear, because of God ye are not.'''),
  ('YLT', 'JHN', 8, 48, 'The Jews, therefore, answered and said to him, `Do we not say well, that thou art a Samaritan, and hast a demon?'''),
  ('YLT', 'JHN', 8, 49, 'Jesus answered, `I have not a demon, but I honour my Father, and ye dishonour me;'),
  ('YLT', 'JHN', 8, 50, 'and I do not seek my own glory; there is who is seeking and is judging;'),
  ('YLT', 'JHN', 8, 51, 'verily, verily, I say to you, If any one may keep my word, death he may not see--to the age.'''),
  ('YLT', 'JHN', 8, 52, 'The Jews, therefore, said to him, `Now we have known that thou hast a demon; Abraham did die, and the prophets, and thou dost say, If any one may keep my word, he shall not taste of death--to the age!'),
  ('YLT', 'JHN', 8, 53, 'Art thou greater than our father Abraham, who died? and the prophets died; whom dost thou make thyself?'''),
  ('YLT', 'JHN', 8, 54, 'Jesus answered, `If I glorify myself, my glory is nothing; it is my Father who is glorifying me, of whom ye say that He is your God;'),
  ('YLT', 'JHN', 8, 55, 'and ye have not known Him, and I have known Him, and if I say that I have not known Him, I shall be like you--speaking falsely; but I have known Him, and His word I keep;'),
  ('YLT', 'JHN', 8, 56, 'Abraham, your father, was glad that he might see my day; and he saw, and did rejoice.'''),
  ('YLT', 'JHN', 8, 57, 'The Jews, therefore, said unto him, `Thou art not yet fifty years old, and Abraham hast thou seen?'''),
  ('YLT', 'JHN', 8, 58, 'Jesus said to them, `Verily, verily, I say to you, Before Abraham''s coming--I am;'''),
  ('YLT', 'JHN', 8, 59, 'they took up, therefore, stones that they may cast at him, but Jesus hid himself, and went forth out of the temple, going through the midst of them, and so passed by.'),
  ('YLT', 'JHN', 10, 1, '`Verily, verily, I say to you, He who is not entering through the door to the fold of the sheep, but is going up from another side, that one is a thief and a robber;'),
  ('YLT', 'JHN', 10, 2, 'and he who is entering through the door is shepherd of the sheep;'),
  ('YLT', 'JHN', 10, 3, 'to this one the doorkeeper doth open, and the sheep hear his voice, and his own sheep he doth call by name, and doth lead them forth;'),
  ('YLT', 'JHN', 10, 4, 'and when his own sheep he may put forth, before them he goeth on, and the sheep follow him, because they have known his voice;'),
  ('YLT', 'JHN', 10, 5, 'and a stranger they will not follow, but will flee from him, because they have not known the voice of strangers.'''),
  ('YLT', 'JHN', 10, 6, 'This similitude spake Jesus to them, and they knew not what the things were that he was speaking to them;'),
  ('YLT', 'JHN', 10, 7, 'Jesus said therefore again to them, `Verily, verily, I say to you--I am the door of the sheep;'),
  ('YLT', 'JHN', 10, 8, 'all, as many as came before me, are thieves and robbers, but the sheep did not hear them;'),
  ('YLT', 'JHN', 10, 9, 'I am the door, through me if any one may come in, he shall be saved, and he shall come in, and go out, and find pasture.'),
  ('YLT', 'JHN', 10, 10, '`The thief doth not come, except that he may steal, and kill, and destroy; I came that they may have life, and may have it abundantly.'),
  ('YLT', 'JHN', 10, 11, '`I am the good shepherd; the good shepherd his life layeth down for the sheep;'),
  ('YLT', 'JHN', 10, 12, 'and the hireling, and not being a shepherd, whose own the sheep are not, doth behold the wolf coming, and doth leave the sheep, and doth flee; and the wolf catcheth them, and scattereth the sheep;'),
  ('YLT', 'JHN', 10, 13, 'and the hireling doth flee because he is an hireling, and is not caring for the sheep.'),
  ('YLT', 'JHN', 10, 14, '`I am the good shepherd, and I know my sheep, and am known by mine,'),
  ('YLT', 'JHN', 10, 15, 'according as the Father doth know me, and I know the Father, and my life I lay down for the sheep,'),
  ('YLT', 'JHN', 10, 16, 'and other sheep I have that are not of this fold, these also it behoveth me to bring, and my voice they will hear, and there shall become one flock--one shepherd.'),
  ('YLT', 'JHN', 10, 17, '`Because of this doth the Father love me, because I lay down my life, that again I may take it;'),
  ('YLT', 'JHN', 10, 18, 'no one doth take it from me, but I lay it down of myself; authority I have to lay it down, and authority I have again to take it; this command I received from my Father.'''),
  ('YLT', 'JHN', 10, 19, 'Therefore, again, there came a division among the Jews, because of these words,'),
  ('YLT', 'JHN', 10, 20, 'and many of them said, `He hath a demon, and is mad, why do ye hear him?'''),
  ('YLT', 'JHN', 10, 21, 'others said, `These sayings are not those of a demoniac; is a demon able blind men''s eyes to open?'''),
  ('YLT', 'JHN', 10, 22, 'And the dedication in Jerusalem came, and it was winter,'),
  ('YLT', 'JHN', 10, 23, 'and Jesus was walking in the temple, in the porch of Solomon,'),
  ('YLT', 'JHN', 10, 24, 'the Jews, therefore, came round about him, and said to him, `Till when our soul dost thou hold in suspense? if thou art the Christ, tell us freely.'''),
  ('YLT', 'JHN', 10, 25, 'Jesus answered them, `I told you, and ye do not believe; the works that I do in the name of my Father, these testify concerning me;'),
  ('YLT', 'JHN', 10, 26, 'but ye do not believe, for ye are not of my sheep,'),
  ('YLT', 'JHN', 10, 27, 'according as I said to you: My sheep my voice do hear, and I know them, and they follow me,'),
  ('YLT', 'JHN', 10, 28, 'and life age-during I give to them, and they shall not perish--to the age, and no one shall pluck them out of my hand;'),
  ('YLT', 'JHN', 10, 29, 'my Father, who hath given to me, is greater than all, and no one is able to pluck out of the hand of my Father;'),
  ('YLT', 'JHN', 10, 30, 'I and the Father are one.'''),
  ('YLT', 'JHN', 10, 31, 'Therefore, again, did the Jews take up stones that they may stone him;'),
  ('YLT', 'JHN', 10, 32, 'Jesus answered them, `Many good works did I shew you from my Father; because of which work of them do ye stone me?'''),
  ('YLT', 'JHN', 10, 33, 'The Jews answered him, saying, `For a good work we do not stone thee, but for evil speaking, and because thou, being a man, dost make thyself God.'''),
  ('YLT', 'JHN', 10, 34, 'Jesus answered them, `Is it not having been written in your law: I said, ye are gods?'),
  ('YLT', 'JHN', 10, 35, 'if them he did call gods unto whom the word of God came, (and the Writing is not able to be broken,)'),
  ('YLT', 'JHN', 10, 36, 'of him whom the Father did sanctify, and send to the world, do ye say--Thou speakest evil, because I said, Son of God I am?'),
  ('YLT', 'JHN', 10, 37, 'if I do not the works of my Father, do not believe me;'),
  ('YLT', 'JHN', 10, 38, 'and if I do, even if me ye may not believe, the works believe, that ye may know and may believe that in me is the Father, and I in Him.'''),
  ('YLT', 'JHN', 10, 39, 'Therefore were they seeking again to seize him, and he went forth out of their hand,'),
  ('YLT', 'JHN', 10, 40, 'and went away again to the other side of the Jordan, to the place where John was at first baptizing, and remained there,'),
  ('YLT', 'JHN', 10, 41, 'and many came unto him, and said--`John, indeed, did no sign, and all things, as many as John said about this one were true;'''),
  ('YLT', 'JHN', 10, 42, 'and many did believe in him there.'),
  ('YLT', 'JHN', 14, 1, '`Let not your heart be troubled, believe in God, also in me believe;'),
  ('YLT', 'JHN', 14, 2, 'in the house of my Father are many mansions; and if not, I would have told you; I go on to prepare a place for you;'),
  ('YLT', 'JHN', 14, 3, 'and if I go on and prepare for you a place, again do I come, and will receive you unto myself, that where I am ye also may be;'),
  ('YLT', 'JHN', 14, 4, 'and whither I go away ye have known, and the way ye have known.'''),
  ('YLT', 'JHN', 14, 5, 'Thomas saith to him, `Sir, we have not known whither thou goest away, and how are we able to know the way?'''),
  ('YLT', 'JHN', 14, 6, 'Jesus saith to him, `I am the way, and the truth, and the life, no one doth come unto the Father, if not through me;'),
  ('YLT', 'JHN', 14, 7, 'if ye had known me, my Father also ye would have known, and from this time ye have known Him, and have seen Him.'''),
  ('YLT', 'JHN', 14, 8, 'Philip saith to him, `Sir, shew to us the Father, and it is enough for us;'''),
  ('YLT', 'JHN', 14, 9, 'Jesus saith to him, `So long time am I with you, and thou hast not known me, Philip? he who hath seen me hath seen the Father; and how dost thou say, Shew to us the Father?'),
  ('YLT', 'JHN', 14, 10, 'Believest thou not that I am in the Father, and the Father is in me? the sayings that I speak to you, from myself I speak not, and the Father who is abiding in me, Himself doth the works;'),
  ('YLT', 'JHN', 14, 11, 'believe me, that I am in the Father, and the Father in me; and if not, because of the works themselves, believe me.'),
  ('YLT', 'JHN', 14, 12, '`Verily, verily, I say to you, he who is believing in me, the works that I do--that one also shall do, and greater than these he shall do, because I go on to my Father;'),
  ('YLT', 'JHN', 14, 13, 'and whatever ye may ask in my name, I will do, that the Father may be glorified in the Son;'),
  ('YLT', 'JHN', 14, 14, 'if ye ask anything in my name I will do it.'),
  ('YLT', 'JHN', 14, 15, '`If ye love me, my commands keep,'),
  ('YLT', 'JHN', 14, 16, 'and I will ask the Father, and another Comforter He will give to you, that he may remain with you--to the age;'),
  ('YLT', 'JHN', 14, 17, 'the Spirit of truth, whom the world is not able to receive, because it doth not behold him, nor know him, and ye know him, because he doth remain with you, and shall be in you.'),
  ('YLT', 'JHN', 14, 18, '`I will not leave you bereaved, I come unto you;'),
  ('YLT', 'JHN', 14, 19, 'yet a little, and the world doth no more behold me, and ye behold me, because I live, and ye shall live;'),
  ('YLT', 'JHN', 14, 20, 'in that day ye shall know that I am in my Father, and ye in me, and I in you;'),
  ('YLT', 'JHN', 14, 21, 'he who is having my commands, and is keeping them, that one it is who is loving me, and he who is loving me shall be loved by my Father, and I will love him, and will manifest myself to him.'''),
  ('YLT', 'JHN', 14, 22, 'Judas saith to him, (not the Iscariot), `Sir, what hath come to pass, that to us thou are about to manifest thyself, and not to the world?'''),
  ('YLT', 'JHN', 14, 23, 'Jesus answered and said to him, `If any one may love me, my word he will keep, and my Father will love him, and unto him we will come, and abode with him we will make;'),
  ('YLT', 'JHN', 14, 24, 'he who is not loving me, my words doth not keep; and the word that ye hear is not mine, but the Father''s who sent me.'),
  ('YLT', 'JHN', 14, 25, '`These things I have spoken to you, remaining with you,'),
  ('YLT', 'JHN', 14, 26, 'and the Comforter, the Holy Spirit, whom the Father will send in my name, he will teach you all things, and remind you of all things that I said to you.'),
  ('YLT', 'JHN', 14, 27, '`Peace I leave to you; my peace I give to you, not according as the world doth give do I give to you; let not your heart be troubled, nor let it be afraid;'),
  ('YLT', 'JHN', 14, 28, 'ye heard that I said to you--I go away, and I come unto you; if ye did love me, ye would have rejoiced that I said--I go on to the Father, because my Father is greater than I.'),
  ('YLT', 'JHN', 14, 29, '`And now I have said it to you before it come to pass, that when it may come to pass, ye may believe;'),
  ('YLT', 'JHN', 14, 30, 'I will no more talk much with you, for the ruler of this world doth come, and in me he hath nothing;'),
  ('YLT', 'JHN', 14, 31, 'but that the world may know that I love the Father, and according as the Father gave me command so I do; arise, we may go hence.'),
  ('YLT', 'ACT', 3, 1, 'And Peter and John were going up at the same time to the temple, at the hour of the prayer, the ninth hour,'),
  ('YLT', 'ACT', 3, 2, 'and a certain man, being lame from the womb of his mother, was being carried, whom they were laying every day at the gate of the temple, called Beautiful, to ask a kindness from those entering into the temple,'),
  ('YLT', 'ACT', 3, 3, 'who, having seen Peter and John about to go into the temple, was begging to receive a kindness.'),
  ('YLT', 'ACT', 3, 4, 'And Peter, having looked stedfastly toward him with John, said, `Look toward us;'''),
  ('YLT', 'ACT', 3, 5, 'and he was giving heed to them, looking to receive something from them;'),
  ('YLT', 'ACT', 3, 6, 'and Peter said, `Silver and gold I have none, but what I have, that I give to thee; in the name of Jesus Christ of Nazareth, rise up and be walking.'''),
  ('YLT', 'ACT', 3, 7, 'And having seized him by the right hand, he raised him up, and presently his feet and ankles were strengthened,'),
  ('YLT', 'ACT', 3, 8, 'and springing up, he stood, and was walking, and did enter with them into the temple, walking and springing, and praising God;'),
  ('YLT', 'ACT', 3, 9, 'and all the people saw him walking and praising God,'),
  ('YLT', 'ACT', 3, 10, 'they were knowing him also that this it was who for a kindness was sitting at the Beautiful gate of the temple, and they were filled with wonder and amazement at what hath happened to him.'),
  ('YLT', 'ACT', 3, 11, 'And at the lame man who was healed holding Peter and John, all the people ran together unto them in the porch called Solomon''s--greatly amazed,'),
  ('YLT', 'ACT', 3, 12, 'and Peter having seen, answered unto the people, `Men, Israelites! why wonder ye at this? or on us why look ye so earnestly, as if by our own power or piety we have made him to walk?'),
  ('YLT', 'ACT', 3, 13, '`The God of Abraham, and of Isaac, and of Jacob, the God of our fathers, did glorify His child Jesus, whom ye delivered up, and denied him in the presence of Pilate, he having given judgment to release him,'),
  ('YLT', 'ACT', 3, 14, 'and ye the Holy and Righteous One did deny, and desired a man--a murderer--to be granted to you,'),
  ('YLT', 'ACT', 3, 15, 'and the Prince of the life ye did kill, whom God did raise out of the dead, of which we are witnesses;'),
  ('YLT', 'ACT', 3, 16, 'and on the faith of his name, this one whom ye see and have known, his name made strong, even the faith that is through him did give to him this perfect soundness before you all.'),
  ('YLT', 'ACT', 3, 17, '`And now, brethren, I have known that through ignorance ye did it, as also your rulers;'),
  ('YLT', 'ACT', 3, 18, 'and God, what things before He had declared through the mouth of all His prophets, that the Christ should suffer, He did thus fulfil;'),
  ('YLT', 'ACT', 3, 19, 'reform ye, therefore, and turn back, for your sins being blotted out, that times of refreshing may come from the presence of the Lord,'),
  ('YLT', 'ACT', 3, 20, 'and He may send Jesus Christ who before hath been preached to you,'),
  ('YLT', 'ACT', 3, 21, 'whom it behoveth heaven, indeed, to receive till times of a restitution of all things, of which God spake through the mouth of all His holy prophets from the age.'),
  ('YLT', 'ACT', 3, 22, '`For Moses, indeed, unto the fathers said--A prophet to you shall the Lord your God raise up out of your brethren, like to me; him shall ye hear in all things, as many as he may speak unto you;'),
  ('YLT', 'ACT', 3, 23, 'and it shall be, every soul that may not hear that prophet shall be utterly destroyed out of the people;'),
  ('YLT', 'ACT', 3, 24, 'and also all the prophets from Samuel and those following in order, as many as spake, did also foretell of these days.'),
  ('YLT', 'ACT', 3, 25, '`Ye are sons of the prophets, and of the covenant that God made unto our fathers, saying unto Abraham: And in thy seed shall be blessed all the families of the earth;'),
  ('YLT', 'ACT', 3, 26, 'to you first, God, having raised up His child Jesus, did send him, blessing you, in the turning away of each one from your evil ways.'''),
  ('YLT', 'ACT', 28, 1, 'And having been saved, then they knew that the island is called Melita,'),
  ('YLT', 'ACT', 28, 2, 'and the foreigners were shewing us no ordinary kindness, for having kindled a fire, they received us all, because of the pressing rain, and because of the cold;'),
  ('YLT', 'ACT', 28, 3, 'but Paul having gathered together a quantity of sticks, and having laid them upon the fire, a viper--out of the heat having come--did fasten on his hand.'),
  ('YLT', 'ACT', 28, 4, 'And when the foreigners saw the beast hanging from his hand, they said unto one another, `Certainly this man is a murderer, whom, having been saved out of the sea, the justice did not suffer to live;'''),
  ('YLT', 'ACT', 28, 5, 'he then, indeed, having shaken off the beast into the fire, suffered no evil,'),
  ('YLT', 'ACT', 28, 6, 'and they were expecting him to be about to be inflamed, or to fall down suddenly dead, and they, expecting it a long time, and seeing nothing uncommon happening to him, changing their minds, said he was a god.'),
  ('YLT', 'ACT', 28, 7, 'And in the neighbourhood of that place were lands of the principal man of the island, by name Publius, who, having received us, three days did courteously lodge us;'),
  ('YLT', 'ACT', 28, 8, 'and it came to pass, the father of Publius with feverish heats and dysentery pressed, was laid, unto whom Paul having entered, and having prayed, having laid his hands on him, healed him;'),
  ('YLT', 'ACT', 28, 9, 'this, therefore, being done, the others also in the island having infirmities were coming and were healed;'),
  ('YLT', 'ACT', 28, 10, 'who also with many honours did honour us, and we setting sail--they were lading us with the things that were necessary.'),
  ('YLT', 'ACT', 28, 11, 'And after three months, we set sail in a ship (that had wintered in the isle) of Alexandria, with the sign Dioscuri,'),
  ('YLT', 'ACT', 28, 12, 'and having landed at Syracuse, we remained three days,'),
  ('YLT', 'ACT', 28, 13, 'thence having gone round, we came to Rhegium, and after one day, a south wind having sprung up, the second day we came to Puteoli;'),
  ('YLT', 'ACT', 28, 14, 'where, having found brethren, we were called upon to remain with them seven days, and thus to Rome we came;'),
  ('YLT', 'ACT', 28, 15, 'and thence, the brethren having heard the things concerning us, came forth to meet us, unto Appii Forum, and Three Taverns--whom Paul having seen, having given thanks to God, took courage.'),
  ('YLT', 'ACT', 28, 16, 'And when we came to Rome, the centurion delivered up the prisoners to the captain of the barrack, but Paul was suffered to remain by himself, with the soldier guarding him.'),
  ('YLT', 'ACT', 28, 17, 'And it came to pass after three days, Paul called together those who are the principal men of the Jews, and they having come together, he said unto them: `Men, brethren, I--having done nothing contrary to the people, or to the customs of the fathers--a prisoner from Jerusalem, was delivered up to the hands of the Romans;'),
  ('YLT', 'ACT', 28, 18, 'who, having examined me, were wishing to release me, because of their being no cause of death in me,'),
  ('YLT', 'ACT', 28, 19, 'and the Jews having spoken against it, I was constrained to appeal unto Caesar--not as having anything to accuse my nation of;'),
  ('YLT', 'ACT', 28, 20, 'for this cause, therefore, I called for you to see and to speak with you, for because of the hope of Israel with this chain I am bound.'''),
  ('YLT', 'ACT', 28, 21, 'And they said unto him, `We did neither receive letters concerning thee from Judea, nor did any one who came of the brethren declare or speak any evil concerning thee,'),
  ('YLT', 'ACT', 28, 22, 'and we think it good from thee to hear what thou dost think, for, indeed, concerning this sect it is known to us that everywhere it is spoken against;'''),
  ('YLT', 'ACT', 28, 23, 'and having appointed him a day, they came, more of them unto him, to the lodging, to whom he was expounding, testifying fully the reign of God, persuading them also of the things concerning Jesus, both from the law of Moses, and the prophets, from morning till evening,'),
  ('YLT', 'ACT', 28, 24, 'and, some, indeed, were believing the things spoken, and some were not believing.'),
  ('YLT', 'ACT', 28, 25, 'And not being agreed with one another, they were going away, Paul having spoken one word--`Well did the Holy Spirit speak through Isaiah the prophet unto our fathers,'),
  ('YLT', 'ACT', 28, 26, 'saying, Go on unto this people and say, With hearing ye shall hear, and ye shall not understand, and seeing ye shall see, and ye shall not perceive,'),
  ('YLT', 'ACT', 28, 27, 'for made gross was the heart of this people, and with the ears they heard heavily, and their eyes they did close, lest they may see with the eyes, and with the heart may understand, and be turned back, and I may heal them.'),
  ('YLT', 'ACT', 28, 28, '`Be it known, therefore, to you, that to the nations was sent the salvation of God, these also will hear it;'''),
  ('YLT', 'ACT', 28, 29, 'and he having said these things, the Jews went away, having much disputation among themselves;'),
  ('YLT', 'ACT', 28, 30, 'and Paul remained an entire two years in his own hired house, and was receiving all those coming in unto him,'),
  ('YLT', 'ACT', 28, 31, 'preaching the reign of God, and teaching the things concerning the Lord Jesus Christ with all boldness--unforbidden.'),
  ('YLT', 'ROM', 8, 1, 'There is, then, now no condemnation to those in Christ Jesus, who walk not according to the flesh, but according to the Spirit;'),
  ('YLT', 'ROM', 8, 2, 'for the law of the Spirit of the life in Christ Jesus did set me free from the law of the sin and of the death;'),
  ('YLT', 'ROM', 8, 3, 'for what the law was not able to do, in that it was weak through the flesh, God, His own Son having sent in the likeness of sinful flesh, and for sin, did condemn the sin in the flesh,'),
  ('YLT', 'ROM', 8, 4, 'that the righteousness of the law may be fulfilled in us, who do not walk according to the flesh, but according to the Spirit.'),
  ('YLT', 'ROM', 8, 5, 'For those who are according to the flesh, the things of the flesh do mind; and those according to the Spirit, the things of the Spirit;'),
  ('YLT', 'ROM', 8, 6, 'for the mind of the flesh is death, and the mind of the Spirit--life and peace;'),
  ('YLT', 'ROM', 8, 7, 'because the mind of the flesh is enmity to God, for to the law of God it doth not subject itself,'),
  ('YLT', 'ROM', 8, 8, 'for neither is it able; and those who are in the flesh are not able to please God.'),
  ('YLT', 'ROM', 8, 9, 'And ye are not in the flesh, but in the Spirit, if indeed the Spirit of God doth dwell in you; and if any one hath not the Spirit of Christ--this one is not His;'),
  ('YLT', 'ROM', 8, 10, 'and if Christ is in you, the body, indeed, is dead because of sin, and the Spirit is life because of righteousness,'),
  ('YLT', 'ROM', 8, 11, 'and if the Spirit of Him who did raise up Jesus out of the dead doth dwell in you, He who did raise up the Christ out of the dead shall quicken also your dying bodies, through His Spirit dwelling in you.'),
  ('YLT', 'ROM', 8, 12, 'So, then, brethren, we are debtors, not to the flesh, to live according to the flesh;'),
  ('YLT', 'ROM', 8, 13, 'for if according to the flesh ye do live, ye are about to die; and if, by the Spirit, the deeds of the body ye put to death, ye shall live;'),
  ('YLT', 'ROM', 8, 14, 'for as many as are led by the Spirit of God, these are the sons of God;'),
  ('YLT', 'ROM', 8, 15, 'for ye did not receive a spirit of bondage again for fear, but ye did receive a spirit of adoption in which we cry, `Abba--Father.'''),
  ('YLT', 'ROM', 8, 16, 'The Spirit himself doth testify with our spirit, that we are children of God;'),
  ('YLT', 'ROM', 8, 17, 'and if children, also heirs, heirs, indeed, of God, and heirs together of Christ--if, indeed, we suffer together, that we may also be glorified together.'),
  ('YLT', 'ROM', 8, 18, 'For I reckon that the sufferings of the present time are not worthy to be compared with the glory about to be revealed in us;'),
  ('YLT', 'ROM', 8, 19, 'for the earnest looking out of the creation doth expect the revelation of the sons of God;'),
  ('YLT', 'ROM', 8, 20, 'for to vanity was the creation made subject--not of its will, but because of Him who did subject it --in hope,'),
  ('YLT', 'ROM', 8, 21, 'that also the creation itself shall be set free from the servitude of the corruption to the liberty of the glory of the children of God;'),
  ('YLT', 'ROM', 8, 22, 'for we have known that all the creation doth groan together, and doth travail in pain together till now.'),
  ('YLT', 'ROM', 8, 23, 'And not only so, but also we ourselves, having the first-fruit of the Spirit, we also ourselves in ourselves do groan, adoption expecting--the redemption of our body;'),
  ('YLT', 'ROM', 8, 24, 'for in hope we were saved, and hope beheld is not hope; for what any one doth behold, why also doth he hope for it?'),
  ('YLT', 'ROM', 8, 25, 'and if what we do not behold we hope for, through continuance we expect it.'),
  ('YLT', 'ROM', 8, 26, 'And, in like manner also, the Spirit doth help our weaknesses; for, what we may pray for, as it behoveth us, we have not known, but the Spirit himself doth make intercession for us with groanings unutterable,'),
  ('YLT', 'ROM', 8, 27, 'and He who is searching the hearts hath known what is the mind of the Spirit, because according to God he doth intercede for saints.'),
  ('YLT', 'ROM', 8, 28, 'And we have known that to those loving God all things do work together for good, to those who are called according to purpose;'),
  ('YLT', 'ROM', 8, 29, 'because whom He did foreknow, He also did fore-appoint, conformed to the image of His Son, that he might be first-born among many brethren;'),
  ('YLT', 'ROM', 8, 30, 'and whom He did fore-appoint, these also He did call; and whom He did call, these also He declared righteous; and whom He declared righteous, these also He did glorify.'),
  ('YLT', 'ROM', 8, 31, 'What, then, shall we say unto these things? if God is for us, who is against us?'),
  ('YLT', 'ROM', 8, 32, 'He who indeed His own Son did not spare, but for us all did deliver him up, how shall He not also with him the all things grant to us?'),
  ('YLT', 'ROM', 8, 33, 'Who shall lay a charge against the choice ones of God? God is He that is declaring righteous,'),
  ('YLT', 'ROM', 8, 34, 'who is he that is condemning? Christ is He that died, yea, rather also, was raised up; who is also on the right hand of God--who also doth intercede for us.'),
  ('YLT', 'ROM', 8, 35, 'Who shall separate us from the love of the Christ? tribulation, or distress, or persecution, or famine, or nakedness, or peril, or sword?'),
  ('YLT', 'ROM', 8, 36, '(according as it hath been written--`For Thy sake we are put to death all the day long, we were reckoned as sheep of slaughter,'')'),
  ('YLT', 'ROM', 8, 37, 'but in all these we more than conquer, through him who loved us;'),
  ('YLT', 'ROM', 8, 38, 'for I am persuaded that neither death, nor life, nor messengers, nor principalities, nor powers, nor things present,'),
  ('YLT', 'ROM', 8, 39, 'nor things about to be, nor height, nor depth, nor any other created thing, shall be able to separate us from the love of god, that is in Christ Jesus our Lord.'),
  ('YLT', 'ROM', 11, 1, 'I say, then, Did God cast away His people? let it not be! for I also am an Israelite, of the seed of Abraham, of the tribe of Benjamin:'),
  ('YLT', 'ROM', 11, 2, 'God did not cast away His people whom He knew before; have ye not known--in Elijah--what the Writing saith? how he doth plead with God concerning Israel, saying,'),
  ('YLT', 'ROM', 11, 3, '`Lord, Thy prophets they did kill, and Thy altars they dug down, and I was left alone, and they seek my life;'''),
  ('YLT', 'ROM', 11, 4, 'but what saith the divine answer to him? `I left to Myself seven thousand men, who did not bow a knee to Baal.'''),
  ('YLT', 'ROM', 11, 5, 'So then also in the present time a remnant according to the choice of grace there hath been;'),
  ('YLT', 'ROM', 11, 6, 'and if by grace, no more of works, otherwise the grace becometh no more grace; and if of works, it is no more grace, otherwise the work is no more work.'),
  ('YLT', 'ROM', 11, 7, 'What then? What Israel doth seek after, this it did not obtain, and the chosen did obtain, and the rest were hardened,'),
  ('YLT', 'ROM', 11, 8, 'according as it hath been written, `God gave to them a spirit of deep sleep, eyes not to see, and ears not to hear,'' --unto this very day,'),
  ('YLT', 'ROM', 11, 9, 'and David saith, `Let their table become for a snare, and for a trap, and for a stumbling-block, and for a recompense to them;'),
  ('YLT', 'ROM', 11, 10, 'let their eyes be darkened--not to behold, and their back do Thou always bow down.'''),
  ('YLT', 'ROM', 11, 11, 'I say, then, Did they stumble that they might fall? let it not be! but by their fall the salvation is to the nations, to arouse them to jealousy;'),
  ('YLT', 'ROM', 11, 12, 'and if the fall of them is the riches of a world, and the diminution of them the riches of nations, how much more the fulness of them?'),
  ('YLT', 'ROM', 11, 13, 'For to you I speak--to the nations--inasmuch as I am indeed an apostle of nations, my ministration I do glorify;'),
  ('YLT', 'ROM', 11, 14, 'if by any means I shall arouse to jealousy mine own flesh, and shall save some of them,'),
  ('YLT', 'ROM', 11, 15, 'for if the casting away of them is a reconciliation of the world, what the reception--if not life out of the dead?'),
  ('YLT', 'ROM', 11, 16, 'and if the first-fruit is holy, the lump also; and if the root is holy, the branches also.'),
  ('YLT', 'ROM', 11, 17, 'And if certain of the branches were broken off, and thou, being a wild olive tree, wast graffed in among them, and a fellow-partaker of the root and of the fatness of the olive tree didst become--'),
  ('YLT', 'ROM', 11, 18, 'do not boast against the branches; and if thou dost boast, thou dost not bear the root, but the root thee!'),
  ('YLT', 'ROM', 11, 19, 'Thou wilt say, then, `The branches were broken off, that I might be graffed in;'' right!'),
  ('YLT', 'ROM', 11, 20, 'by unbelief they were broken off, and thou hast stood by faith; be not high-minded, but be fearing;'),
  ('YLT', 'ROM', 11, 21, 'for if God the natural branches did not spare--lest perhaps He also shall not spare thee.'),
  ('YLT', 'ROM', 11, 22, 'Lo, then, goodness and severity of God--upon those indeed who fell, severity; and upon thee, goodness, if thou mayest remain in the goodness, otherwise, thou also shalt be cut off.'),
  ('YLT', 'ROM', 11, 23, 'And those also, if they may not remain in unbelief, shall be graffed in, for God is able again to graff them in;'),
  ('YLT', 'ROM', 11, 24, 'for if thou, out of the olive tree, wild by nature, wast cut out, and, contrary to nature, wast graffed into a good olive tree, how much rather shall they, who are according to nature, be graffed into their own olive tree?'),
  ('YLT', 'ROM', 11, 25, 'For I do not wish you to be ignorant, brethren, of this secret--that ye may not be wise in your own conceits--that hardness in part to Israel hath happened till the fulness of the nations may come in;'),
  ('YLT', 'ROM', 11, 26, 'and so all Israel shall be saved, according as it hath been written, `There shall come forth out of Sion he who is delivering, and he shall turn away impiety from Jacob,'),
  ('YLT', 'ROM', 11, 27, 'and this to them is the covenant from Me, when I may take away their sins.'''),
  ('YLT', 'ROM', 11, 28, 'As regards, indeed, the good tidings, they are enemies on your account; and as regards the choice--beloved on account of the fathers;'),
  ('YLT', 'ROM', 11, 29, 'for unrepented of are the gifts and the calling of God;'),
  ('YLT', 'ROM', 11, 30, 'for as ye also once did not believe in God, and now did find kindness by the unbelief of these:'),
  ('YLT', 'ROM', 11, 31, 'so also these now did not believe, that in your kindness they also may find kindness;'),
  ('YLT', 'ROM', 11, 32, 'for God did shut up together the whole to unbelief, that to the whole He might do kindness.'),
  ('YLT', 'ROM', 11, 33, 'O depth of riches, and wisdom and knowledge of God! how unsearchable His judgments, and untraceable His ways!'),
  ('YLT', 'ROM', 11, 34, 'for who did know the mind of the Lord? or who did become His counsellor?'),
  ('YLT', 'ROM', 11, 35, 'or who did first give to Him, and it shall be given back to him again?'),
  ('YLT', 'ROM', 11, 36, 'because of Him, and through Him, and to Him are the all things; to Him is the glory--to the ages. Amen.'),
  ('YLT', 'ROM', 12, 1, 'I call upon you, therefore, brethren, through the compassions of God, to present your bodies a sacrifice--living, sanctified, acceptable to God--your intelligent service;'),
  ('YLT', 'ROM', 12, 2, 'and be not conformed to this age, but be transformed by the renewing of your mind, for your proving what is the will of God--the good, and acceptable, and perfect.'),
  ('YLT', 'ROM', 12, 3, 'For I say, through the grace that was given to me, to every one who is among you, not to think above what it behoveth to think; but to think so as to think wisely, as to each God did deal a measure of faith,'),
  ('YLT', 'ROM', 12, 4, 'for as in one body we have many members, and all the members have not the same office,'),
  ('YLT', 'ROM', 12, 5, 'so we, the many, one body are in Christ, and members each one of one another.'),
  ('YLT', 'ROM', 12, 6, 'And having gifts, different according to the grace that was given to us; whether prophecy--`According to the proportion of faith!'''),
  ('YLT', 'ROM', 12, 7, 'or ministration--`In the ministration!'' or he who is teaching--`In the teaching!'''),
  ('YLT', 'ROM', 12, 8, 'or he who is exhorting--`In the exhortation!'' he who is sharing--`In simplicity!'' he who is leading--`In diligence?'' he who is doing kindness--`In cheerfulness.'''),
  ('YLT', 'ROM', 12, 9, 'The love unfeigned: abhorring the evil; cleaving to the good;'),
  ('YLT', 'ROM', 12, 10, 'in the love of brethren, to one another kindly affectioned: in the honour going before one another;'),
  ('YLT', 'ROM', 12, 11, 'in the diligence not slothful; in the spirit fervent; the Lord serving;'),
  ('YLT', 'ROM', 12, 12, 'in the hope rejoicing; in the tribulation enduring; in the prayer persevering;'),
  ('YLT', 'ROM', 12, 13, 'to the necessities of the saints communicating; the hospitality pursuing.'),
  ('YLT', 'ROM', 12, 14, 'Bless those persecuting you; bless, and curse not;'),
  ('YLT', 'ROM', 12, 15, 'to rejoice with the rejoicing, and to weep with the weeping,'),
  ('YLT', 'ROM', 12, 16, 'of the same mind one toward another, not minding the high things, but with the lowly going along; become not wise in your own conceit;'),
  ('YLT', 'ROM', 12, 17, 'giving back to no one evil for evil; providing right things before all men.'),
  ('YLT', 'ROM', 12, 18, 'If possible--so far as in you--with all men being in peace;'),
  ('YLT', 'ROM', 12, 19, 'not avenging yourselves, beloved, but give place to the wrath, for it hath been written, `Vengeance is Mine,'),
  ('YLT', 'ROM', 12, 20, 'I will recompense again, saith the Lord;'' if, then, thine enemy doth hunger, feed him; if he doth thirst, give him drink; for this doing, coals of fire thou shalt heap upon his head;'),
  ('YLT', 'ROM', 12, 21, 'Be not overcome by the evil, but overcome, in the good, the evil.'),
  ('YLT', '2CO', 3, 1, 'Do we begin again to recommend ourselves, except we need, as some, letters of recommendation unto you, or from you?'),
  ('YLT', '2CO', 3, 2, 'our letter ye are, having been written in our hearts, known and read by all men,'),
  ('YLT', '2CO', 3, 3, 'manifested that ye are a letter of Christ ministered by us, written not with ink, but with the Spirit of the living God, not in the tablets of stone, but in fleshy tablets of the heart,'),
  ('YLT', '2CO', 3, 4, 'and such trust we have through the Christ toward God,'),
  ('YLT', '2CO', 3, 5, 'not that we are sufficient of ourselves to think anything, as of ourselves, but our sufficiency is of God,'),
  ('YLT', '2CO', 3, 6, 'who also made us sufficient to be ministrants of a new covenant, not of letter, but of spirit; for the letter doth kill, and the spirit doth make alive.'),
  ('YLT', '2CO', 3, 7, 'and if the ministration of the death, in letters, engraved in stones, came in glory, so that the sons of Israel were not able to look stedfastly to the face of Moses, because of the glory of his face--which was being made useless,'),
  ('YLT', '2CO', 3, 8, 'how shall the ministration of the Spirit not be more in glory?'),
  ('YLT', '2CO', 3, 9, 'for if the ministration of the condemnation is glory, much more doth the ministration of the righteousness abound in glory;'),
  ('YLT', '2CO', 3, 10, 'for also even that which hath been glorious, hath not been glorious--in this respect, because of the superior glory;'),
  ('YLT', '2CO', 3, 11, 'for if that which is being made useless is through glory, much more that which is remaining is in glory.'),
  ('YLT', '2CO', 3, 12, 'Having, then, such hope, we use much freedom of speech,'),
  ('YLT', '2CO', 3, 13, 'and are not as Moses, who was putting a vail upon his own face, for the sons of Israel not stedfastly to look to the end of that which is being made useless,'),
  ('YLT', '2CO', 3, 14, 'but their minds were hardened, for unto this day the same vail at the reading of the Old Covenant doth remain unwithdrawn--which in Christ is being made useless--'),
  ('YLT', '2CO', 3, 15, 'but till to-day, when Moses is read, a vail upon their heart doth lie,'),
  ('YLT', '2CO', 3, 16, 'and whenever they may turn unto the Lord, the vail is taken away.'),
  ('YLT', '2CO', 3, 17, 'And the Lord is the Spirit; and where the Spirit of the Lord is, there is liberty;'),
  ('YLT', '2CO', 3, 18, 'and we all, with unvailed face, the glory of the Lord beholding in a mirror, to the same image are being transformed, from glory to glory, even as by the Spirit of the Lord.'),
  ('YLT', '2CO', 4, 1, 'Because of this, having this ministration, according as we did receive kindness, we do not faint,'),
  ('YLT', '2CO', 4, 2, 'but did renounce for ourselves the hidden things of shame, not walking in craftiness, nor deceitfully using the word of God, but by the manifestation of the truth recommending ourselves unto every conscience of men, before God;'),
  ('YLT', '2CO', 4, 3, 'and if also our good news is vailed, in those perishing it is vailed,'),
  ('YLT', '2CO', 4, 4, 'in whom the god of this age did blind the minds of the unbelieving, that there doth not shine forth to them the enlightening of the good news of the glory of the Christ, who is the image of God;'),
  ('YLT', '2CO', 4, 5, 'for not ourselves do we preach, but Christ Jesus--Lord, and ourselves your servants because of Jesus;'),
  ('YLT', '2CO', 4, 6, 'because it is God who said, Out of darkness light is to shine, who did shine in our hearts, for the enlightening of the knowledge of the glory of God in the face of Jesus Christ.'),
  ('YLT', '2CO', 4, 7, 'And we have this treasure in earthen vessels, that the excellency of the power may be of God, and not of us;'),
  ('YLT', '2CO', 4, 8, 'on every side being in tribulation, but not straitened; perplexed, but not in despair;'),
  ('YLT', '2CO', 4, 9, 'persecuted, but not forsaken; cast down, but not destroyed;'),
  ('YLT', '2CO', 4, 10, 'at all times the dying of the Lord Jesus bearing about in the body, that the life also of Jesus in our body may be manifested,'),
  ('YLT', '2CO', 4, 11, 'for always are we who are living delivered up to death because of Jesus, that the life also of Jesus may be manifested in our dying flesh,'),
  ('YLT', '2CO', 4, 12, 'so that, the death indeed in us doth work, and the life in you.'),
  ('YLT', '2CO', 4, 13, 'And having the same spirit of the faith, according to that which hath been written, `I believed, therefore I did speak;'' we also do believe, therefore also do we speak;'),
  ('YLT', '2CO', 4, 14, 'knowing that He who did raise up the Lord Jesus, us also through Jesus shall raise up, and shall present with you,'),
  ('YLT', '2CO', 4, 15, 'for the all things are because of you, that the grace having been multiplied, because of the thanksgiving of the more, may abound to the glory of God;'),
  ('YLT', '2CO', 4, 16, 'wherefore, we faint not, but if also our outward man doth decay, yet the inward is renewed day by day;'),
  ('YLT', '2CO', 4, 17, 'for the momentary light matter of our tribulation, more and more exceedingly an age-during weight of glory doth work out for us--'),
  ('YLT', '2CO', 4, 18, 'we not looking to the things seen, but to the things not seen; for the things seen are temporary, but the things not seen are age-during.'),
  ('YLT', 'GAL', 3, 1, 'O thoughtless Galatians, who did bewitch you, not to obey the truth--before whose eyes Jesus Christ was described before among you crucified?'),
  ('YLT', 'GAL', 3, 2, 'this only do I wish to learn from you--by works of law the Spirit did ye receive, or by the hearing of faith?'),
  ('YLT', 'GAL', 3, 3, 'so thoughtless are ye! having begun in the Spirit, now in the flesh do ye end?'),
  ('YLT', 'GAL', 3, 4, 'so many things did ye suffer in vain! if, indeed, even in vain.'),
  ('YLT', 'GAL', 3, 5, 'He, therefore, who is supplying to you the Spirit, and working mighty acts among you--by works of law or by the hearing of faith is it?'),
  ('YLT', 'GAL', 3, 6, 'according as Abraham did believe God, and it was reckoned to him--to righteousness;'),
  ('YLT', 'GAL', 3, 7, 'know ye, then, that those of faith--these are sons of Abraham,'),
  ('YLT', 'GAL', 3, 8, 'and the Writing having foreseen that by faith God doth declare righteous the nations did proclaim before the good news to Abraham--'),
  ('YLT', 'GAL', 3, 9, '`Blessed in thee shall be all the nations;'' so that those of faith are blessed with the faithful Abraham,'),
  ('YLT', 'GAL', 3, 10, 'for as many as are of works of law are under a curse, for it hath been written, `Cursed is every one who is not remaining in all things that have been written in the Book of the Law--to do them,'''),
  ('YLT', 'GAL', 3, 11, 'and that in law no one is declared righteous with God, is evident, because `The righteous by faith shall live;'''),
  ('YLT', 'GAL', 3, 12, 'and the law is not by faith, but--`The man who did them shall live in them.'''),
  ('YLT', 'GAL', 3, 13, 'Christ did redeem us from the curse of the law, having become for us a curse, for it hath been written, `Cursed is every one who is hanging on a tree,'''),
  ('YLT', 'GAL', 3, 14, 'that to the nations the blessing of Abraham may come in Christ Jesus, that the promise of the Spirit we may receive through the faith.'),
  ('YLT', 'GAL', 3, 15, 'Brethren, as a man I say it, even of man a confirmed covenant no one doth make void or doth add to,'),
  ('YLT', 'GAL', 3, 16, 'and to Abraham were the promises spoken, and to his seed; He doth not say, `And to seeds,'' as of many, but as of one, `And to thy seed,'' which is Christ;'),
  ('YLT', 'GAL', 3, 17, 'and this I say, A covenant confirmed before by God to Christ, the law, that came four hundred and thirty years after, doth not set aside, to make void the promise,'),
  ('YLT', 'GAL', 3, 18, 'for if by law be the inheritance, it is no more by promise, but to Abraham through promise did God grant it.'),
  ('YLT', 'GAL', 3, 19, 'Why, then, the law? on account of the transgressions it was added, till the seed might come to which the promise hath been made, having been set in order through messengers in the hand of a mediator--'),
  ('YLT', 'GAL', 3, 20, 'and the mediator is not of one, and God is one--'),
  ('YLT', 'GAL', 3, 21, 'the law, then, is against the promises of God? --let it not be! for if a law was given that was able to make alive, truly by law there would have been the righteousness,'),
  ('YLT', 'GAL', 3, 22, 'but the Writing did shut up the whole under sin, that the promise by faith of Jesus Christ may be given to those believing.'),
  ('YLT', 'GAL', 3, 23, 'And before the coming of the faith, under law we were being kept, shut up to the faith about to be revealed,'),
  ('YLT', 'GAL', 3, 24, 'so that the law became our child-conductor--to Christ, that by faith we may be declared righteous,'),
  ('YLT', 'GAL', 3, 25, 'and the faith having come, no more under a child-conductor are we,'),
  ('YLT', 'GAL', 3, 26, 'for ye are all sons of God through the faith in Christ Jesus,'),
  ('YLT', 'GAL', 3, 27, 'for as many as to Christ were baptized did put on Christ;'),
  ('YLT', 'GAL', 3, 28, 'there is not here Jew or Greek, there is not here servant nor freeman, there is not here male and female, for all ye are one in Christ Jesus;'),
  ('YLT', 'GAL', 3, 29, 'and if ye are of Christ then of Abraham ye are seed, and according to promise--heirs.'),
  ('YLT', 'GAL', 5, 1, 'In the freedom, then, with which Christ did make you free--stand ye, and be not held fast again by a yoke of servitude;'),
  ('YLT', 'GAL', 5, 2, 'lo, I Paul do say to you, that if ye be circumcised, Christ shall profit you nothing;'),
  ('YLT', 'GAL', 5, 3, 'and I testify again to every man circumcised, that he is a debtor to do the whole law;'),
  ('YLT', 'GAL', 5, 4, 'ye were freed from the Christ, ye who in law are declared righteous; from the grace ye fell away;'),
  ('YLT', 'GAL', 5, 5, 'for we by the Spirit, by faith, a hope of righteousness do wait for,'),
  ('YLT', 'GAL', 5, 6, 'for in Christ Jesus neither circumcision availeth anything, nor uncircumcision, but faith through love working.'),
  ('YLT', 'GAL', 5, 7, 'Ye were running well; who did hinder you--not to obey the truth?'),
  ('YLT', 'GAL', 5, 8, 'the obedience is not of him who is calling you!'),
  ('YLT', 'GAL', 5, 9, 'a little leaven the whole lump doth leaven;'),
  ('YLT', 'GAL', 5, 10, 'I have confidence in regard to you in the Lord, that ye will be none otherwise minded; and he who is troubling you shall bear the judgment, whoever he may be.'),
  ('YLT', 'GAL', 5, 11, 'And I, brethren, if uncircumcision I yet preach, why yet am I persecuted? then hath the stumbling-block of the cross been done away;'),
  ('YLT', 'GAL', 5, 12, 'O that even they would cut themselves off who are unsettling you!'),
  ('YLT', 'GAL', 5, 13, 'For ye--to freedom ye were called, brethren, only not the freedom for an occasion to the flesh, but through the love serve ye one another,'),
  ('YLT', 'GAL', 5, 14, 'for all the law in one word is fulfilled--in this: `Thou shalt love thy neighbour as thyself;'''),
  ('YLT', 'GAL', 5, 15, 'and if one another ye do bite and devour, see--that ye may not by one another be consumed.'),
  ('YLT', 'GAL', 5, 16, 'And I say: In the Spirit walk ye, and the desire of the flesh ye may not complete;'),
  ('YLT', 'GAL', 5, 17, 'for the flesh doth desire contrary to the Spirit, and the Spirit contrary to the flesh, and these are opposed one to another, that the things that ye may will--these ye may not do;'),
  ('YLT', 'GAL', 5, 18, 'and if by the Spirit ye are led, ye are not under law.'),
  ('YLT', 'GAL', 5, 19, 'And manifest also are the works of the flesh, which are: Adultery, whoredom, uncleanness, lasciviousness,'),
  ('YLT', 'GAL', 5, 20, 'idolatry, witchcraft, hatred, strifes, emulations, wraths, rivalries, dissensions, sects,'),
  ('YLT', 'GAL', 5, 21, 'envyings, murders, drunkennesses, revellings, and such like, of which I tell you before, as I also said before, that those doing such things the reign of God shall not inherit.'),
  ('YLT', 'GAL', 5, 22, 'And the fruit of the Spirit is: Love, joy, peace, long-suffering, kindness, goodness, faith,'),
  ('YLT', 'GAL', 5, 23, 'meekness, temperance: against such there is no law;'),
  ('YLT', 'GAL', 5, 24, 'and those who are Christ''s, the flesh did crucify with the affections, and the desires;'),
  ('YLT', 'GAL', 5, 25, 'if we may live in the Spirit, in the Spirit also we may walk;'),
  ('YLT', 'GAL', 5, 26, 'let us not become vain-glorious--one another provoking, one another envying!'),
  ('YLT', 'PHP', 2, 1, 'If, then, any exhortation is in Christ, if any comfort of love, if any fellowship of spirit, if any bowels and mercies,'),
  ('YLT', 'PHP', 2, 2, 'fulfil ye my joy, that ye may mind the same thing--having the same love--of one soul--minding the one thing,'),
  ('YLT', 'PHP', 2, 3, 'nothing in rivalry or vain-glory, but in humility of mind one another counting more excellent than yourselves--'),
  ('YLT', 'PHP', 2, 4, 'each not to your own look ye, but each also to the things of others.'),
  ('YLT', 'PHP', 2, 5, 'For, let this mind be in you that is also in Christ Jesus,'),
  ('YLT', 'PHP', 2, 6, 'who, being in the form of God, thought it not robbery to be equal to God,'),
  ('YLT', 'PHP', 2, 7, 'but did empty himself, the form of a servant having taken, in the likeness of men having been made,'),
  ('YLT', 'PHP', 2, 8, 'and in fashion having been found as a man, he humbled himself, having become obedient unto death--death even of a cross,'),
  ('YLT', 'PHP', 2, 9, 'wherefore, also, God did highly exalt him, and gave to him a name that is above every name,'),
  ('YLT', 'PHP', 2, 10, 'that in the name of Jesus every knee may bow--of heavenlies, and earthlies, and what are under the earth--'),
  ('YLT', 'PHP', 2, 11, 'and every tongue may confess that Jesus Christ is Lord, to the glory of God the Father.'),
  ('YLT', 'PHP', 2, 12, 'So that, my beloved, as ye always obey, not as in my presence only, but now much more in my absence, with fear and trembling your own salvation work out,'),
  ('YLT', 'PHP', 2, 13, 'for God it is who is working in you both to will and to work for His good pleasure.'),
  ('YLT', 'PHP', 2, 14, 'All things do without murmurings and reasonings,'),
  ('YLT', 'PHP', 2, 15, 'that ye may become blameless and harmless, children of God, unblemished in the midst of a generation crooked and perverse, among whom ye do appear as luminaries in the world,'),
  ('YLT', 'PHP', 2, 16, 'the word of life holding forth, for rejoicing to me in regard to a day of Christ, that not in vain did I run, nor in vain did I labour;'),
  ('YLT', 'PHP', 2, 17, 'but if also I am poured forth upon the sacrifice and service of your faith, I rejoice and joy with you all,'),
  ('YLT', 'PHP', 2, 18, 'because of this do ye also rejoice and joy with me.'),
  ('YLT', 'PHP', 2, 19, 'And I hope, in the Lord Jesus, Timotheus to send quickly to you, that I also may be of good spirit, having known the things concerning you,'),
  ('YLT', 'PHP', 2, 20, 'for I have no one like-minded, who sincerely for the things concerning you will care,'),
  ('YLT', 'PHP', 2, 21, 'for the whole seek their own things, not the things of the Christ Jesus,'),
  ('YLT', 'PHP', 2, 22, 'and the proof of him ye know, that as a child serveth a father, with me he did serve in regard to the good news;'),
  ('YLT', 'PHP', 2, 23, 'him, indeed, therefore, I hope to send, when I may see through the things concerning me--immediately;'),
  ('YLT', 'PHP', 2, 24, 'and I trust in the Lord that I myself also shall quickly come.'),
  ('YLT', 'PHP', 2, 25, 'And I thought it necessary Epaphroditus--my brother, and fellow-workman, and fellow-soldier, and your apostle and servant to my need--to send unto you,'),
  ('YLT', 'PHP', 2, 26, 'seeing he was longing after you all, and in heaviness, because ye heard that he ailed,'),
  ('YLT', 'PHP', 2, 27, 'for he also ailed nigh to death, but God did deal kindly with him, and not with him only, but also with me, that sorrow upon sorrow I might not have.'),
  ('YLT', 'PHP', 2, 28, 'The more eagerly, therefore, I did send him, that having seen him again ye may rejoice, and I may be the less sorrowful;'),
  ('YLT', 'PHP', 2, 29, 'receive him, therefore, in the Lord, with all joy, and hold such in honour,'),
  ('YLT', 'PHP', 2, 30, 'because on account of the work of the Christ he drew near to death, having hazarded the life that he might fill up your deficiency of service unto me.'),
  ('YLT', 'PHP', 3, 1, 'As to the rest, my brethren, rejoice in the Lord; the same things to write to you to me indeed is not tiresome, and for you is sure;'),
  ('YLT', 'PHP', 3, 2, 'look to the dogs, look to the evil-workers, look to the concision;'),
  ('YLT', 'PHP', 3, 3, 'for we are the circumcision, who by the Spirit are serving God, and glorying in Christ Jesus, and in flesh having no trust,'),
  ('YLT', 'PHP', 3, 4, 'though I also have cause of trust in flesh. If any other one doth think to have trust in flesh, I more;'),
  ('YLT', 'PHP', 3, 5, 'circumcision on the eighth day! of the race of Israel! of the tribe of Benjamin! a Hebrew of Hebrews! according to law a Pharisee!'),
  ('YLT', 'PHP', 3, 6, 'according to zeal persecuting the assembly! according to righteousness that is in law becoming blameless!'),
  ('YLT', 'PHP', 3, 7, 'But what things were to me gains, these I have counted, because of the Christ, loss;'),
  ('YLT', 'PHP', 3, 8, 'yes, indeed, and I count all things to be loss, because of the excellency of the knowledge of Christ Jesus my Lord, because of whom of the all things I suffered loss, and do count them to be refuse, that Christ I may gain, and be found in him,'),
  ('YLT', 'PHP', 3, 9, 'not having my righteousness, which is of law, but that which is through faith of Christ--the righteousness that is of God by the faith,'),
  ('YLT', 'PHP', 3, 10, 'to know him, and the power of his rising again, and the fellowship of his sufferings, being conformed to his death,'),
  ('YLT', 'PHP', 3, 11, 'if anyhow I may attain to the rising again of the dead.'),
  ('YLT', 'PHP', 3, 12, 'Not that I did already obtain, or have been already perfected; but I pursue, if also I may lay hold of that for which also I was laid hold of by the Christ Jesus;'),
  ('YLT', 'PHP', 3, 13, 'brethren, I do not reckon myself to have laid hold; and one thing--the things behind indeed forgetting, and to the things before stretching forth--'),
  ('YLT', 'PHP', 3, 14, 'to the mark I pursue for the prize of the high calling of God in Christ Jesus.'),
  ('YLT', 'PHP', 3, 15, 'As many, therefore, as are perfect--let us think this, and if in anything ye think otherwise, this also shall God reveal to you,'),
  ('YLT', 'PHP', 3, 16, 'but to what we have come--by the same rule walk, the same thing think;'),
  ('YLT', 'PHP', 3, 17, 'become followers together of me, brethren, and observe those thus walking, according as ye have us--a pattern;'),
  ('YLT', 'PHP', 3, 18, 'for many walk of whom many times I told you--and now also weeping tell--the enemies of the cross of the Christ!'),
  ('YLT', 'PHP', 3, 19, 'whose end is destruction, whose god is the belly, and whose glory is in their shame, who the things on earth are minding.'),
  ('YLT', 'PHP', 3, 20, 'For our citizenship is in the heavens, whence also a Saviour we await--the Lord Jesus Christ--'),
  ('YLT', 'PHP', 3, 21, 'who shall transform the body of our humiliation to its becoming conformed to the body of his glory, according to the working of his power, even to subject to himself the all things.'),
  ('YLT', 'PHP', 4, 1, 'So then, my brethren, beloved and longed for, my joy and crown, so stand ye in the Lord, beloved.'),
  ('YLT', 'PHP', 4, 2, 'Euodia I exhort, and Syntyche I exhort, to be of the same mind in the Lord;'),
  ('YLT', 'PHP', 4, 3, 'and I ask also thee, genuine yoke-fellow, be assisting those women who in the good news did strive along with me, with Clement also, and the others, my fellow-workers, whose names are in the book of life.'),
  ('YLT', 'PHP', 4, 4, 'Rejoice in the Lord always; again I will say, rejoice;'),
  ('YLT', 'PHP', 4, 5, 'let your forbearance be known to all men; the Lord is near;'),
  ('YLT', 'PHP', 4, 6, 'for nothing be anxious, but in everything by prayer, and by supplication, with thanksgiving, let your requests be made known unto God;'),
  ('YLT', 'PHP', 4, 7, 'and the peace of God, that is surpassing all understanding, shall guard your hearts and your thoughts in Christ Jesus.'),
  ('YLT', 'PHP', 4, 8, 'As to the rest, brethren, as many things as are true, as many as are grave, as many as are righteous, as many as are pure, as many as are lovely, as many as are of good report, if any worthiness, and if any praise, these things think upon;'),
  ('YLT', 'PHP', 4, 9, 'the things that also ye did learn, and receive, and hear, and saw in me, those do, and the God of the peace shall be with you.'),
  ('YLT', 'PHP', 4, 10, 'And I rejoiced in the Lord greatly, that now at length ye flourished again in caring for me, for which also ye were caring, and lacked opportunity;'),
  ('YLT', 'PHP', 4, 11, 'not that in respect of want I say it, for I did learn in the things in which I am--to be content;'),
  ('YLT', 'PHP', 4, 12, 'I have known both to be abased, and I have known to abound; in everything and in all things I have been initiated, both to be full and to be hungry, both to abound and to be in want.'),
  ('YLT', 'PHP', 4, 13, 'For all things I have strength, in Christ''s strengthening me;'),
  ('YLT', 'PHP', 4, 14, 'but ye did well, having communicated with my tribulation;'),
  ('YLT', 'PHP', 4, 15, 'and ye have known, even ye Philippians, that in the beginning of the good news when I went forth from Macedonia, no assembly did communicate with me in regard to giving and receiving except ye only;'),
  ('YLT', 'PHP', 4, 16, 'because also in Thessalonica, both once and again to my need ye sent;'),
  ('YLT', 'PHP', 4, 17, 'not that I seek after the gift, but I seek after the fruit that is overflowing to your account;'),
  ('YLT', 'PHP', 4, 18, 'and I have all things, and abound; I am filled, having received from Epaphroditus the things from you--an odour of a sweet smell--a sacrifice acceptable, well-pleasing to God:'),
  ('YLT', 'PHP', 4, 19, 'and my God shall supply all your need, according to His riches in glory in Christ Jesus;'),
  ('YLT', 'PHP', 4, 20, 'and to God, even our Father, is the glory--to the ages of the ages. Amen.'),
  ('YLT', 'PHP', 4, 21, 'Salute ye every saint in Christ Jesus; there salute you the brethren with me;'),
  ('YLT', 'PHP', 4, 22, 'there salute you all the saints, and specially those of Caesar''s house;'),
  ('YLT', 'PHP', 4, 23, 'the grace of our Lord Jesus Christ is with you all. Amen.'),
  ('YLT', 'COL', 1, 1, 'Paul, an apostle of Jesus Christ through the will of God, and Timotheus the brother,'),
  ('YLT', 'COL', 1, 2, 'to the saints in Colossae, and to the faithful brethren in Christ: Grace to you, and peace from God our Father, and the Lord Jesus Christ!'),
  ('YLT', 'COL', 1, 3, 'We give thanks to the God and Father of our Lord Jesus Christ, always praying for you,'),
  ('YLT', 'COL', 1, 4, 'having heard of your faith in Christ Jesus, and of the love that is to all the saints,'),
  ('YLT', 'COL', 1, 5, 'because of the hope that is laid up for you in the heavens, which ye heard of before in the word of the truth of the good news,'),
  ('YLT', 'COL', 1, 6, 'which is present to you, as also in all the world, and is bearing fruit, as also in you, from the day in which ye heard, and knew the grace of God in truth;'),
  ('YLT', 'COL', 1, 7, 'as ye also learned from Epaphras, our beloved fellow-servant, who is for you a faithful ministrant of the Christ,'),
  ('YLT', 'COL', 1, 8, 'who also did declare to us your love in the Spirit.'),
  ('YLT', 'COL', 1, 9, 'Because of this, we also, from the day in which we heard, do not cease praying for you, and asking that ye may be filled with the full knowledge of His will in all wisdom and spiritual understanding,'),
  ('YLT', 'COL', 1, 10, 'to your walking worthily of the Lord to all pleasing, in every good work being fruitful, and increasing to the knowledge of God,'),
  ('YLT', 'COL', 1, 11, 'in all might being made mighty according to the power of His glory, to all endurance and long-suffering with joy.'),
  ('YLT', 'COL', 1, 12, 'Giving thanks to the Father who did make us meet for the participation of the inheritance of the saints in the light,'),
  ('YLT', 'COL', 1, 13, 'who did rescue us out of the authority of the darkness, and did translate us into the reign of the Son of His love,'),
  ('YLT', 'COL', 1, 14, 'in whom we have the redemption through his blood, the forgiveness of the sins,'),
  ('YLT', 'COL', 1, 15, 'who is the image of the invisible God, first-born of all creation,'),
  ('YLT', 'COL', 1, 16, 'because in him were the all things created, those in the heavens, and those upon the earth, those visible, and those invisible, whether thrones, whether lordships, whether principalities, whether authorities; all things through him, and for him, have been created,'),
  ('YLT', 'COL', 1, 17, 'and himself is before all, and the all things in him have consisted.'),
  ('YLT', 'COL', 1, 18, 'And himself is the head of the body--the assembly--who is a beginning, a first-born out of the dead, that he might become in all things --himself--first,'),
  ('YLT', 'COL', 1, 19, 'because in him it did please all the fulness to tabernacle,'),
  ('YLT', 'COL', 1, 20, 'and through him to reconcile the all things to himself--having made peace through the blood of his cross--through him, whether the things upon the earth, whether the things in the heavens.'),
  ('YLT', 'COL', 1, 21, 'And you--once being alienated, and enemies in the mind, in the evil works, yet now did he reconcile,'),
  ('YLT', 'COL', 1, 22, 'in the body of his flesh through the death, to present you holy, and unblemished, and unblameable before himself,'),
  ('YLT', 'COL', 1, 23, 'if also ye remain in the faith, being founded and settled, and not moved away from the hope of the good news, which ye heard, which was preached in all the creation that is under the heaven, of which I became--I Paul--a ministrant.'),
  ('YLT', 'COL', 1, 24, 'I now rejoice in my sufferings for you, and do fill up the things lacking of the tribulations of the Christ in my flesh for his body, which is the assembly,'),
  ('YLT', 'COL', 1, 25, 'of which I--I did become a ministrant according to the dispensation of God, that was given to me for you, to fulfil the word of God,'),
  ('YLT', 'COL', 1, 26, 'the secret that hath been hid from the ages and from the generations, but now was manifested to his saints,'),
  ('YLT', 'COL', 1, 27, 'to whom God did will to make known what is the riches of the glory of this secret among the nations--which is Christ in you, the hope of the glory,'),
  ('YLT', 'COL', 1, 28, 'whom we proclaim, warning every man, and teaching every man, in all wisdom, that we may present every man perfect in Christ Jesus,'),
  ('YLT', 'COL', 1, 29, 'for which also I labour, striving according to his working that is working in me in power.'),
  ('YLT', 'COL', 2, 1, 'For I wish you to know how great a conflict I have for you and those in Laodicea, and as many as have not seen my face in the flesh,'),
  ('YLT', 'COL', 2, 2, 'that their hearts may be comforted, being united in love, and to all riches of the full assurance of the understanding, to the full knowledge of the secret of the God and Father, and of the Christ,'),
  ('YLT', 'COL', 2, 3, 'in whom are all the treasures of the wisdom and the knowledge hid,'),
  ('YLT', 'COL', 2, 4, 'and this I say, that no one may beguile you in enticing words,'),
  ('YLT', 'COL', 2, 5, 'for if even in the flesh I am absent--yet in the spirit I am with you, joying and beholding your order, and the stedfastness of your faith in regard to Christ;'),
  ('YLT', 'COL', 2, 6, 'as, then, ye did receive Christ Jesus the Lord, in him walk ye,'),
  ('YLT', 'COL', 2, 7, 'being rooted and built up in him, and confirmed in the faith, as ye were taught--abounding in it in thanksgiving.'),
  ('YLT', 'COL', 2, 8, 'See that no one shall be carrying you away as spoil through the philosophy and vain deceit, according to the deliverance of men, according to the rudiments of the world, and not according to Christ,'),
  ('YLT', 'COL', 2, 9, 'because in him doth tabernacle all the fulness of the Godhead bodily,'),
  ('YLT', 'COL', 2, 10, 'and ye are in him made full, who is the head of all principality and authority,'),
  ('YLT', 'COL', 2, 11, 'in whom also ye were circumcised with a circumcision not made with hands, in the putting off of the body of the sins of the flesh in the circumcision of the Christ,'),
  ('YLT', 'COL', 2, 12, 'being buried with him in the baptism, in which also ye rose with him through the faith of the working of God, who did raise him out of the dead.'),
  ('YLT', 'COL', 2, 13, 'And you--being dead in the trespasses and the uncircumcision of your flesh--He made alive together with him, having forgiven you all the trespasses,'),
  ('YLT', 'COL', 2, 14, 'having blotted out the handwriting in the ordinances that is against us, that was contrary to us, and he hath taken it out of the way, having nailed it to the cross;'),
  ('YLT', 'COL', 2, 15, 'having stripped the principalities and the authorities, he made a shew of them openly--having triumphed over them in it.'),
  ('YLT', 'COL', 2, 16, 'Let no one, then, judge you in eating or in drinking, or in respect of a feast, or of a new moon, or of sabbaths,'),
  ('YLT', 'COL', 2, 17, 'which are a shadow of the coming things, and the body is of the Christ;'),
  ('YLT', 'COL', 2, 18, 'let no one beguile you of your prize, delighting in humble-mindedness and in worship of the messengers, intruding into the things he hath not seen, being vainly puffed up by the mind of his flesh,'),
  ('YLT', 'COL', 2, 19, 'and not holding the head, from which all the body--through the joints and bands gathering supply, and being knit together--may increase with the increase of God.'),
  ('YLT', 'COL', 2, 20, 'If, then, ye did die with the Christ from the rudiments of the world, why, as living in the world, are ye subject to ordinances?'),
  ('YLT', 'COL', 2, 21, '--thou mayest not touch, nor taste, nor handle--'),
  ('YLT', 'COL', 2, 22, 'which are all for destruction with the using, after the commands and teachings of men,'),
  ('YLT', 'COL', 2, 23, 'which are, indeed, having a matter of wisdom in will-worship, and humble-mindedness, and neglecting of body--not in any honour, unto a satisfying of the flesh.'),
  ('YLT', 'COL', 3, 1, 'If, then, ye were raised with the Christ, the things above seek ye, where the Christ is, on the right hand of God seated,'),
  ('YLT', 'COL', 3, 2, 'the things above mind ye, not the things upon the earth,'),
  ('YLT', 'COL', 3, 3, 'for ye did die, and your life hath been hid with the Christ in God;'),
  ('YLT', 'COL', 3, 4, 'when the Christ--our life--may be manifested, then also we with him shall be manifested in glory.'),
  ('YLT', 'COL', 3, 5, 'Put to death, then, your members that are upon the earth--whoredom, uncleanness, passion, evil desire, and the covetousness, which is idolatry--'),
  ('YLT', 'COL', 3, 6, 'because of which things cometh the anger of God upon the sons of the disobedience,'),
  ('YLT', 'COL', 3, 7, 'in which also ye--ye did walk once, when ye lived in them;'),
  ('YLT', 'COL', 3, 8, 'but now put off, even ye, the whole--anger, wrath, malice, evil-speaking, filthy talking--out of your mouth.'),
  ('YLT', 'COL', 3, 9, 'Lie not one to another, having put off the old man with his practices,'),
  ('YLT', 'COL', 3, 10, 'and having put on the new, which is renewed in regard to knowledge, after the image of Him who did create him;'),
  ('YLT', 'COL', 3, 11, 'where there is not Greek and Jew, circumcision and uncircumcision, foreigner, Scythian, servant, freeman--but the all and in all--Christ.'),
  ('YLT', 'COL', 3, 12, 'Put on, therefore, as choice ones of God, holy and beloved, bowels of mercies, kindness, humble-mindedness, meekness, long-suffering,'),
  ('YLT', 'COL', 3, 13, 'forbearing one another, and forgiving each other, if any one with any one may have a quarrel, as also the Christ did forgive you--so also ye;'),
  ('YLT', 'COL', 3, 14, 'and above all these things, have love, which is a bond of the perfection,'),
  ('YLT', 'COL', 3, 15, 'and let the peace of God rule in your hearts, to which also ye were called in one body, and become thankful.'),
  ('YLT', 'COL', 3, 16, 'Let the word of Christ dwell in you richly, in all wisdom, teaching and admonishing each other, in psalms, and hymns, and spiritual songs, in grace singing in your hearts to the Lord;'),
  ('YLT', 'COL', 3, 17, 'and all, whatever ye may do in word or in work, do all things in the name of the Lord Jesus--giving thanks to the God and Father, through him.'),
  ('YLT', 'COL', 3, 18, 'The wives! be subject to your own husbands, as is fit in the Lord;'),
  ('YLT', 'COL', 3, 19, 'the husbands! love your wives, and be not bitter with them;'),
  ('YLT', 'COL', 3, 20, 'the children! obey the parents in all things, for this is well-pleasing to the Lord;'),
  ('YLT', 'COL', 3, 21, 'the fathers! vex not your children, lest they be discouraged.'),
  ('YLT', 'COL', 3, 22, 'The servants! obey in all things those who are masters according to the flesh, not in eye-service as men-pleasers, but in simplicity of heart, fearing God;'),
  ('YLT', 'COL', 3, 23, 'and all, whatever ye may do--out of soul work--as to the Lord, and not to men,'),
  ('YLT', 'COL', 3, 24, 'having known that from the Lord ye shall receive the recompense of the inheritance--for the Lord Christ ye serve;'),
  ('YLT', 'COL', 3, 25, 'and he who is doing unrighteously shall receive what he did unrighteously, and there is no acceptance of persons.'),
  ('YLT', '1TI', 4, 1, 'And the Spirit expressly speaketh, that in latter times shall certain fall away from the faith, giving heed to seducing spirits and teachings of demons,'),
  ('YLT', '1TI', 4, 2, 'in hypocrisy speaking lies, being seared in their own conscience,'),
  ('YLT', '1TI', 4, 3, 'forbidding to marry--to abstain from meats that God created to be received with thanksgiving by those believing and acknowledging the truth,'),
  ('YLT', '1TI', 4, 4, 'because every creature of God is good, and nothing is to be rejected, with thanksgiving being received,'),
  ('YLT', '1TI', 4, 5, 'for it is sanctified through the word of God and intercession.'),
  ('YLT', '1TI', 4, 6, 'These things placing before the brethren, thou shalt be a good ministrant of Jesus Christ, being nourished by the words of the faith, and of the good teaching, which thou didst follow after,'),
  ('YLT', '1TI', 4, 7, 'and the profane and old women''s fables reject thou, and exercise thyself unto piety,'),
  ('YLT', '1TI', 4, 8, 'for the bodily exercise is unto little profit, and the piety is to all things profitable, a promise having of the life that now is, and of that which is coming;'),
  ('YLT', '1TI', 4, 9, 'stedfast is the word, and of all acceptation worthy;'),
  ('YLT', '1TI', 4, 10, 'for for this we both labour and are reproached, because we hope on the living God, who is Saviour of all men--especially of those believing.'),
  ('YLT', '1TI', 4, 11, 'Charge these things, and teach;'),
  ('YLT', '1TI', 4, 12, 'let no one despise thy youth, but a pattern become thou of those believing in word, in behaviour, in love, in spirit, in faith, in purity;'),
  ('YLT', '1TI', 4, 13, 'till I come, give heed to the reading, to the exhortation, to the teaching;'),
  ('YLT', '1TI', 4, 14, 'be not careless of the gift in thee, that was given thee through prophecy, with laying on of the hands of the eldership;'),
  ('YLT', '1TI', 4, 15, 'of these things be careful; in these things be, that thy advancement may be manifest in all things;'),
  ('YLT', '1TI', 4, 16, 'take heed to thyself, and to the teaching; remain in them, for this thing doing, both thyself thou shalt save, and those hearing thee.'),
  ('YLT', 'HEB', 11, 1, 'And faith is of things hoped for a confidence, of matters not seen a conviction,'),
  ('YLT', 'HEB', 11, 2, 'for in this were the elders testified of;'),
  ('YLT', 'HEB', 11, 3, 'by faith we understand the ages to have been prepared by a saying of God, in regard to the things seen not having come out of things appearing;'),
  ('YLT', 'HEB', 11, 4, 'by faith a better sacrifice did Abel offer to God than Cain, through which he was testified to be righteous, God testifying of his gifts, and through it, he being dead, doth yet speak.'),
  ('YLT', 'HEB', 11, 5, 'By faith Enoch was translated--not to see death, and was not found, because God did translate him; for before his translation he had been testified to--that he had pleased God well,'),
  ('YLT', 'HEB', 11, 6, 'and apart from faith it is impossible to please well, for it behoveth him who is coming to God to believe that He is, and to those seeking Him He becometh a rewarder.'),
  ('YLT', 'HEB', 11, 7, 'By faith Noah, having been divinely warned concerning the things not yet seen, having feared, did prepare an ark to the salvation of his house, through which he did condemn the world, and of the righteousness according to faith he became heir.'),
  ('YLT', 'HEB', 11, 8, 'By faith Abraham, being called, did obey, to go forth to the place that he was about to receive for an inheritance, and he went forth, not knowing whither he doth go;'),
  ('YLT', 'HEB', 11, 9, 'by faith he did sojourn in the land of the promise as a strange country, in tabernacles having dwelt with Isaac and Jacob, fellow-heirs of the same promise,'),
  ('YLT', 'HEB', 11, 10, 'for he was looking for the city having the foundations, whose artificer and constructor is God.'),
  ('YLT', 'HEB', 11, 11, 'By faith also Sarah herself did receive power to conceive seed, and she bare after the time of life, seeing she did judge Him faithful who did promise;'),
  ('YLT', 'HEB', 11, 12, 'wherefore, also from one were begotten--and that of one who had become dead--as the stars of the heaven in multitude, and as sand that is by the sea-shore--the innumerable.'),
  ('YLT', 'HEB', 11, 13, 'In faith died all these, not having received the promises, but from afar having seen them, and having been persuaded, and having saluted them, and having confessed that strangers and sojourners they are upon the earth,'),
  ('YLT', 'HEB', 11, 14, 'for those saying such things make manifest that they seek a country;'),
  ('YLT', 'HEB', 11, 15, 'and if, indeed, they had been mindful of that from which they came forth, they might have had an opportunity to return,'),
  ('YLT', 'HEB', 11, 16, 'but now they long for a better, that is, an heavenly, wherefore God is not ashamed of them, to be called their God, for He did prepare for them a city.'),
  ('YLT', 'HEB', 11, 17, 'By faith Abraham hath offered up Isaac, being tried, and the only begotten he did offer up who did receive the promises,'),
  ('YLT', 'HEB', 11, 18, 'of whom it was said--`In Isaac shall a seed be called to thee;'''),
  ('YLT', 'HEB', 11, 19, 'reckoning that even out of the dead God is able to raise up, whence also in a figure he did receive him.'),
  ('YLT', 'HEB', 11, 20, 'By faith, concerning coming things, Isaac did bless Jacob and Esau;'),
  ('YLT', 'HEB', 11, 21, 'by faith Jacob dying--each of the sons of Joseph did bless, and did bow down upon the top of his staff;'),
  ('YLT', 'HEB', 11, 22, 'by faith, Joseph dying, concerning the outgoing of the sons of Israel did make mention, and concerning his bones did give command.'),
  ('YLT', 'HEB', 11, 23, 'By faith Moses, having been born, was hid three months by his parents, because they saw the child comely, and were not afraid of the decree of the king;'),
  ('YLT', 'HEB', 11, 24, 'by faith Moses, having become great, did refuse to be called a son of the daughter of Pharaoh,'),
  ('YLT', 'HEB', 11, 25, 'having chosen rather to be afflicted with the people of God, than to have sin''s pleasure for a season,'),
  ('YLT', 'HEB', 11, 26, 'greater wealth having reckoned the reproach of the Christ than the treasures in Egypt, for he did look to the recompense of reward;'),
  ('YLT', 'HEB', 11, 27, 'by faith he left Egypt behind, not having been afraid of the wrath of the king, for, as seeing the Invisible One--he endured;'),
  ('YLT', 'HEB', 11, 28, 'by faith he kept the passover, and the sprinkling of the blood, that He who is destroying the first-born might not touch them.'),
  ('YLT', 'HEB', 11, 29, 'By faith they did pass through the Red Sea as through dry land, which the Egyptians having received a trial of, were swallowed up;'),
  ('YLT', 'HEB', 11, 30, 'by faith the walls of Jericho did fall, having been surrounded for seven days;'),
  ('YLT', 'HEB', 11, 31, 'by faith Rahab the harlot did not perish with those who disbelieved, having received the spies with peace.'),
  ('YLT', 'HEB', 11, 32, 'And what shall I yet say? for the time will fail me recounting about Gideon, Barak also, and Samson, and Jephthah, David also, and Samuel, and the prophets,'),
  ('YLT', 'HEB', 11, 33, 'who through faith did subdue kingdoms, wrought righteousness, obtained promises, stopped mouths of lions,'),
  ('YLT', 'HEB', 11, 34, 'quenched the power of fire, escaped the mouth of the sword, were made powerful out of infirmities, became strong in battle, caused to give way camps of the aliens.'),
  ('YLT', 'HEB', 11, 35, 'Women received by a rising again their dead, and others were tortured, not accepting the redemption, that a better rising again they might receive,'),
  ('YLT', 'HEB', 11, 36, 'and others of mockings and scourgings did receive trial, and yet of bonds and imprisonment;'),
  ('YLT', 'HEB', 11, 37, 'they were stoned, they were sawn asunder, they were tried; in the killing of the sword they died; they went about in sheepskins, in goatskins--being destitute, afflicted, injuriously treated,'),
  ('YLT', 'HEB', 11, 38, 'of whom the world was not worthy; in deserts wandering, and in mountains, and in caves, and in the holes of the earth;'),
  ('YLT', 'HEB', 11, 39, 'and these all, having been testified to through the faith, did not receive the promise,'),
  ('YLT', 'HEB', 11, 40, 'God for us something better having provided, that apart from us they might not be made perfect.'),
  ('YLT', 'HEB', 13, 1, 'Let brotherly love remain;'),
  ('YLT', 'HEB', 13, 2, 'of the hospitality be not forgetful, for through this unawares certain did entertain messengers;'),
  ('YLT', 'HEB', 13, 3, 'be mindful of those in bonds, as having been bound with them, of those maltreated, as also yourselves being in the body;'),
  ('YLT', 'HEB', 13, 4, 'honourable is the marriage in all, and the bed undefiled, and whoremongers and adulterers God shall judge.'),
  ('YLT', 'HEB', 13, 5, 'Without covetousness the behaviour, being content with the things present, for He hath said, `No, I will not leave, no, nor forsake thee,'''),
  ('YLT', 'HEB', 13, 6, 'so that we do boldly say, `The Lord is to me a helper, and I will not fear what man shall do to me.'''),
  ('YLT', 'HEB', 13, 7, 'Be mindful of those leading you, who did speak to you the word of God, whose faith--considering the issue of the behaviour--be imitating,'),
  ('YLT', 'HEB', 13, 8, 'Jesus Christ yesterday and to-day the same, and to the ages;'),
  ('YLT', 'HEB', 13, 9, 'with teachings manifold and strange be not carried about, for it is good that by grace the heart be confirmed, not with meats, in which they who were occupied were not profited;'),
  ('YLT', 'HEB', 13, 10, 'we have an altar, of which to eat they have no authority who the tabernacle are serving,'),
  ('YLT', 'HEB', 13, 11, 'for of those beasts whose blood is brought for sin into the holy places through the chief priest--of these the bodies are burned without the camp.'),
  ('YLT', 'HEB', 13, 12, 'Wherefore, also Jesus--that he might sanctify through his own blood the people--without the gate did suffer;'),
  ('YLT', 'HEB', 13, 13, 'now, then, may we go forth unto him without the camp, his reproach bearing;'),
  ('YLT', 'HEB', 13, 14, 'for we have not here an abiding city, but the coming one we seek;'),
  ('YLT', 'HEB', 13, 15, 'through him, then, we may offer up a sacrifice of praise always to God, that is, the fruit of lips, giving thanks to His name;'),
  ('YLT', 'HEB', 13, 16, 'and of doing good, and of fellowship, be not forgetful, for with such sacrifices God is well-pleased.'),
  ('YLT', 'HEB', 13, 17, 'Be obedient to those leading you, and be subject, for these do watch for your souls, as about to give account, that with joy they may do this, and not sighing, for this is unprofitable to you.'),
  ('YLT', 'HEB', 13, 18, 'Pray for us, for we trust that we have a good conscience, in all things willing to behave well,'),
  ('YLT', 'HEB', 13, 19, 'and more abundantly do I call upon you to do this, that more quickly I may be restored to you.'),
  ('YLT', 'HEB', 13, 20, 'And the God of the peace, who did bring up out of the dead the great shepherd of the sheep--in the blood of an age-during covenant--our Lord Jesus,'),
  ('YLT', 'HEB', 13, 21, 'make you perfect in every good work to do His will, doing in you that which is well-pleasing before Him, through Jesus Christ, to whom is the glory--to the ages of the ages! Amen.'),
  ('YLT', 'HEB', 13, 22, 'And I entreat you, brethren, suffer the word of the exhortation, for also through few words I have written to you.'),
  ('YLT', 'HEB', 13, 23, 'Know ye that the brother Timotheus is released, with whom, if he may come more shortly, I will see you.'),
  ('YLT', 'HEB', 13, 24, 'Salute all those leading you, and all the saints; salute you doth those from Italy:'),
  ('YLT', 'HEB', 13, 25, 'the grace is with you all! Amen.'),
  ('YLT', 'JAS', 4, 1, 'Whence are wars and fightings among you? not thence--out of your passions, that are as soldiers in your members?'),
  ('YLT', 'JAS', 4, 2, 'ye desire, and ye have not; ye murder, and are zealous, and are not able to attain; ye fight and war, and ye have not, because of your not asking;'),
  ('YLT', 'JAS', 4, 3, 'ye ask, and ye receive not, because evilly ye ask, that in your pleasures ye may spend it.'),
  ('YLT', 'JAS', 4, 4, 'Adulterers and adulteresses! have ye not known that friendship of the world is enmity with God? whoever, then, may counsel to be a friend of the world, an enemy of God he is set.'),
  ('YLT', 'JAS', 4, 5, 'Do ye think that emptily the Writing saith, `To envy earnestly desireth the spirit that did dwell in us,'''),
  ('YLT', 'JAS', 4, 6, 'and greater grace he doth give, wherefore he saith, `God against proud ones doth set Himself up, and to lowly ones He doth give grace?'''),
  ('YLT', 'JAS', 4, 7, 'be subject, then, to God; stand up against the devil, and he will flee from you;'),
  ('YLT', 'JAS', 4, 8, 'draw nigh to God, and He will draw nigh to you; cleanse hands, ye sinners! and purify hearts, ye two-souled!'),
  ('YLT', 'JAS', 4, 9, 'be exceeding afflicted, and mourn, and weep, let your laughter to mourning be turned, and the joy to heaviness;'),
  ('YLT', 'JAS', 4, 10, 'be made low before the Lord, and He shall exalt you.'),
  ('YLT', 'JAS', 4, 11, 'Speak not one against another, brethren; he who is speaking against a brother, and is judging his brother, doth speak against law, and doth judge law, and if law thou dost judge, thou art not a doer of law but a judge;'),
  ('YLT', 'JAS', 4, 12, 'one is the lawgiver, who is able to save and to destroy; thou--who art thou that dost judge the other?'),
  ('YLT', 'JAS', 4, 13, 'Go, now, ye who are saying, `To-day and to-morrow we will go on to such a city, and will pass there one year, and traffic, and make gain;'''),
  ('YLT', 'JAS', 4, 14, 'who do not know the thing of the morrow; for what is your life? for it is a vapour that is appearing for a little, and then is vanishing;'),
  ('YLT', 'JAS', 4, 15, 'instead of your saying, `If the Lord may will, we shall live, and do this or that;'''),
  ('YLT', 'JAS', 4, 16, 'and now ye glory in your pride; all such glorying is evil;'),
  ('YLT', 'JAS', 4, 17, 'to him, then, knowing to do good, and not doing, sin it is to him.'),
  ('YLT', '1PE', 1, 1, 'Peter, an apostle of Jesus Christ, to the choice sojourners of the dispersion of Pontus, Galatia, Cappadocia, Asia, and Bithynia,'),
  ('YLT', '1PE', 1, 2, 'according to a foreknowledge of God the Father, in sanctification of the Spirit, to obedience and sprinkling of the blood of Jesus Christ: Grace to you and peace be multiplied!'),
  ('YLT', '1PE', 1, 3, 'Blessed is the God and Father of our Lord Jesus Christ, who, according to the abundance of His kindness did beget us again to a living hope, through the rising again of Jesus Christ out of the dead,'),
  ('YLT', '1PE', 1, 4, 'to an inheritance incorruptible, and undefiled, and unfading, reserved in the heavens for you,'),
  ('YLT', '1PE', 1, 5, 'who, in the power of God are being guarded, through faith, unto salvation, ready to be revealed in the last time,'),
  ('YLT', '1PE', 1, 6, 'in which ye are glad, a little now, if it be necessary, being made to sorrow in manifold trials,'),
  ('YLT', '1PE', 1, 7, 'that the proof of your faith--much more precious than of gold that is perishing, and through fire being approved--may be found to praise, and honour, and glory, in the revelation of Jesus Christ,'),
  ('YLT', '1PE', 1, 8, 'whom, not having seen, ye love, in whom, now not seeing and believing, ye are glad with joy unspeakable and glorified,'),
  ('YLT', '1PE', 1, 9, 'receiving the end of your faith--salvation of souls;'),
  ('YLT', '1PE', 1, 10, 'concerning which salvation seek out and search out did prophets who concerning the grace toward you did prophecy,'),
  ('YLT', '1PE', 1, 11, 'searching in regard to what or what manner of time the Spirit of Christ that was in them was manifesting, testifying beforehand the sufferings of Christ and the glory after these,'),
  ('YLT', '1PE', 1, 12, 'to whom it was revealed, that not to themselves, but to us they were ministering these, which now were told to you (through those who did proclaim good news to you,) in the Holy Spirit sent from heaven, to which things messengers do desire to bend looking.'),
  ('YLT', '1PE', 1, 13, 'Wherefore having girded up the loins of your mind, being sober, hope perfectly upon the grace that is being brought to you in the revelation of Jesus Christ,'),
  ('YLT', '1PE', 1, 14, 'as obedient children, not fashioning yourselves to the former desires in your ignorance,'),
  ('YLT', '1PE', 1, 15, 'but according as He who did call you is holy, ye also, become holy in all behaviour,'),
  ('YLT', '1PE', 1, 16, 'because it hath been written, `Become ye holy, because I am holy;'''),
  ('YLT', '1PE', 1, 17, 'and if on the Father ye do call, who without acceptance of persons is judging according to the work of each, in fear the time of your sojourn pass ye,'),
  ('YLT', '1PE', 1, 18, 'having known that, not with corruptible things--silver or gold--were ye redeemed from your foolish behaviour delivered by fathers,'),
  ('YLT', '1PE', 1, 19, 'but with precious blood, as of a lamb unblemished and unspotted--Christ''s--'),
  ('YLT', '1PE', 1, 20, 'foreknown, indeed, before the foundation of the world, and manifested in the last times because of you,'),
  ('YLT', '1PE', 1, 21, 'who through him do believe in God, who did raise out of the dead, and glory to him did give, so that your faith and hope may be in God.'),
  ('YLT', '1PE', 1, 22, 'Your souls having purified in the obedience of the truth through the Spirit to brotherly love unfeigned, out of a pure heart one another love ye earnestly,'),
  ('YLT', '1PE', 1, 23, 'being begotten again, not out of seed corruptible, but incorruptible, through a word of God--living and remaining--to the age;'),
  ('YLT', '1PE', 1, 24, 'because all flesh is as grass, and all glory of man as flower of grass; wither did the grass, and the flower of it fell away,'),
  ('YLT', '1PE', 1, 25, 'and the saying of the Lord doth remain--to the age; and this is the saying that was proclaimed good news to you.'),
  ('YLT', '1JN', 1, 1, 'That which was from the beginning, that which we have heard, that which we have seen with our eyes, that which we did behold, and our hands did handle, concerning the Word of the Life--'),
  ('YLT', '1JN', 1, 2, 'and the Life was manifested, and we have seen, and do testify, and declare to you the Life, the age-during, which was with the Father, and was manifested to us--'),
  ('YLT', '1JN', 1, 3, 'that which we have seen and heard declare we to you, that ye also may have fellowship with us, and our fellowship is with the Father, and with His Son Jesus Christ;'),
  ('YLT', '1JN', 1, 4, 'and these things we write to you, that your joy may be full.'),
  ('YLT', '1JN', 1, 5, 'And this is the message that we have heard from Him, and announce to you, that God is light, and darkness in Him is not at all;'),
  ('YLT', '1JN', 1, 6, 'if we may say--`we have fellowship with Him,'' and in the darkness may walk--we lie, and do not the truth;'),
  ('YLT', '1JN', 1, 7, 'and if in the light we may walk, as He is in the light--we have fellowship one with another, and the blood of Jesus Christ His Son doth cleanse us from every sin;'),
  ('YLT', '1JN', 1, 8, 'if we may say--`we have not sin,'' ourselves we lead astray, and the truth is not in us;'),
  ('YLT', '1JN', 1, 9, 'if we may confess our sins, stedfast He is and righteous that He may forgive us the sins, and may cleanse us from every unrighteousness;'),
  ('YLT', '1JN', 1, 10, 'if we may say--`we have not sinned,'' a liar we make Him, and His word is not in us.'),
  ('YLT', '1JN', 2, 1, 'My little children, these things I write to you, that ye may not sin: and if any one may sin, an advocate we have with the Father, Jesus Christ, a righteous one,'),
  ('YLT', '1JN', 2, 2, 'and he--he is a propitiation for our sins, and not for ours only, but also for the whole world,'),
  ('YLT', '1JN', 2, 3, 'and in this we know that we have known him, if his commands we may keep;'),
  ('YLT', '1JN', 2, 4, 'he who is saying, `I have known him,'' and his command is not keeping, a liar he is, and in him the truth is not;'),
  ('YLT', '1JN', 2, 5, 'and whoever may keep his word, truly in him the love of God hath been perfected; in this we know that in him we are.'),
  ('YLT', '1JN', 2, 6, 'He who is saying in him he doth remain, ought according as he walked also himself so to walk.'),
  ('YLT', '1JN', 2, 7, 'Brethren, a new command I write not to you, but an old command, that ye had from the beginning--the old command is the word that ye heard from the beginning;'),
  ('YLT', '1JN', 2, 8, 'again, a new command I write to you, which thing is true in him and in you, because the darkness doth pass away, and the true light doth now shine;'),
  ('YLT', '1JN', 2, 9, 'he who is saying, in the light he is, and his brother is hating, in the darkness he is till now;'),
  ('YLT', '1JN', 2, 10, 'he who is loving his brother, in the light he doth remain, and a stumbling-block in him there is not;'),
  ('YLT', '1JN', 2, 11, 'and he who is hating his brother, in the darkness he is, and in the darkness he doth walk, and he hath not known whither he doth go, because the darkness did blind his eyes.'),
  ('YLT', '1JN', 2, 12, 'I write to you, little children, because the sins have been forgiven you through his name;'),
  ('YLT', '1JN', 2, 13, 'I write to you, fathers, because ye have known him who is from the beginning; I write to you, young men, because ye have overcome the evil. I write to you, little youths, because ye have known the Father:'),
  ('YLT', '1JN', 2, 14, 'I did write to you, fathers, because ye have known him who is from the beginning; I did write to you, young men, because ye are strong, and the word of God in you doth remain, and ye have overcome the evil.'),
  ('YLT', '1JN', 2, 15, 'Love not ye the world, nor the things in the world; if any one doth love the world, the love of the Father is not in him,'),
  ('YLT', '1JN', 2, 16, 'because all that is in the world--the desire of the flesh, and the desire of the eyes, and the ostentation of the life--is not of the Father, but of the world,'),
  ('YLT', '1JN', 2, 17, 'and the world doth pass away, and the desire of it, and he who is doing the will of God, he doth remain--to the age.'),
  ('YLT', '1JN', 2, 18, 'Little youths, it is the last hour; and even as ye heard that the antichrist doth come, even now antichrists have become many--whence we know that it is the last hour;'),
  ('YLT', '1JN', 2, 19, 'out of us they went forth, but they were not of us, for if they had been of us, they would have remained with us; but--that they might be manifested that they are not all of us.'),
  ('YLT', '1JN', 2, 20, 'And ye have an anointing from the Holy One, and have known all things;'),
  ('YLT', '1JN', 2, 21, 'I did not write to you because ye have not known the truth, but because ye have known it, and because no lie is of the truth.'),
  ('YLT', '1JN', 2, 22, 'Who is the liar, except he who is denying that Jesus is the Christ? this one is the antichrist who is denying the Father and the Son;'),
  ('YLT', '1JN', 2, 23, 'every one who is denying the Son, neither hath he the Father, he who is confessing the Son hath the Father also.'),
  ('YLT', '1JN', 2, 24, 'Ye, then, that which ye heard from the beginning, in you let it remain; if in you may remain that which from the beginning ye did hear, ye also in the Son and in the Father shall remain,'),
  ('YLT', '1JN', 2, 25, 'and this is the promise that He did promise us--the life the age-during.'),
  ('YLT', '1JN', 2, 26, 'These things I did write to you concerning those leading you astray;'),
  ('YLT', '1JN', 2, 27, 'and you, the anointing that ye did receive from him, in you it doth remain, and ye have no need that any one may teach you, but as the same anointing doth teach you concerning all, and is true, and is not a lie, and even as was taught you, ye shall remain in him.'),
  ('YLT', '1JN', 2, 28, 'And now, little children, remain in him, that when he may be manifested, we may have boldness, and may not be ashamed before him, in his presence;'),
  ('YLT', '1JN', 2, 29, 'if ye know that he is righteous, know ye that every one doing the righteousness, of him hath been begotten.'),
  ('YLT', '1JN', 3, 1, 'See ye what love the Father hath given to us, that children of God we may be called; because of this the world doth not know us, because it did not know Him;'),
  ('YLT', '1JN', 3, 2, 'beloved, now, children of God are we, and it was not yet manifested what we shall be, and we have known that if he may be manifested, like him we shall be, because we shall see him as he is;'),
  ('YLT', '1JN', 3, 3, 'and every one who is having this hope on him, doth purify himself, even as he is pure.'),
  ('YLT', '1JN', 3, 4, 'Every one who is doing the sin, the lawlessness also he doth do, and the sin is the lawlessness,'),
  ('YLT', '1JN', 3, 5, 'and ye have known that he was manifested that our sins he may take away, and sin is not in him;'),
  ('YLT', '1JN', 3, 6, 'every one who is remaining in him doth not sin; every one who is sinning, hath not seen him, nor known him.'),
  ('YLT', '1JN', 3, 7, 'Little children, let no one lead you astray; he who is doing the righteousness is righteous, even as he is righteous,'),
  ('YLT', '1JN', 3, 8, 'he who is doing the sin, of the devil he is, because from the beginning the devil doth sin; for this was the Son of God manifested, that he may break up the works of the devil;'),
  ('YLT', '1JN', 3, 9, 'every one who hath been begotten of God, sin he doth not, because his seed in him doth remain, and he is not able to sin, because of God he hath been begotten.'),
  ('YLT', '1JN', 3, 10, 'In this manifest are the children of God, and the children of the devil; every one who is not doing righteousness, is not of God, and he who is not loving his brother,'),
  ('YLT', '1JN', 3, 11, 'because this is the message that ye did hear from the beginning, that we may love one another,'),
  ('YLT', '1JN', 3, 12, 'not as Cain--of the evil one he was, and he did slay his brother, and wherefore did he slay him? because his works were evil, and those of his brother righteous.'),
  ('YLT', '1JN', 3, 13, 'Do not wonder, my brethren, if the world doth hate you;'),
  ('YLT', '1JN', 3, 14, 'we--we have known that we have passed out of the death to the life, because we love the brethren; he who is not loving the brother doth remain in the death.'),
  ('YLT', '1JN', 3, 15, 'Every one who is hating his brother--a man-killer he is, and ye have known that no man-killer hath life age-during in him remaining,'),
  ('YLT', '1JN', 3, 16, 'in this we have known the love, because he for us his life did lay down, and we ought for the brethren the lives to lay down;'),
  ('YLT', '1JN', 3, 17, 'and whoever may have the goods of the world, and may view his brother having need, and may shut up his bowels from him--how doth the love of God remain in him?'),
  ('YLT', '1JN', 3, 18, 'My little children, may we not love in word nor in tongue, but in word and in truth!'),
  ('YLT', '1JN', 3, 19, 'and in this we know that of the truth we are, and before Him we shall assure our hearts,'),
  ('YLT', '1JN', 3, 20, 'because if our heart may condemn--because greater is God than our heart, and He doth know all things.'),
  ('YLT', '1JN', 3, 21, 'Beloved, if our heart may not condemn us, we have boldness toward God,'),
  ('YLT', '1JN', 3, 22, 'and whatever we may ask, we receive from Him, because His commands we keep, and the things pleasing before Him we do,'),
  ('YLT', '1JN', 3, 23, 'and this is His command, that we may believe in the name of His Son Jesus Christ, and may love one another, even as He did give command to us,'),
  ('YLT', '1JN', 3, 24, 'and he who is keeping His commands, in Him he doth remain, and He in him; and in this we know that He doth remain in us, from the Spirit that He gave us.'),
  ('YLT', 'REV', 19, 1, 'And after these things I heard a great voice of a great multitude in the heaven, saying, `Alleluia! the salvation, and the glory, and the honour, and the power, is to the Lord our God;'),
  ('YLT', 'REV', 19, 2, 'because true and righteous are His judgments, because He did judge the great whore who did corrupt the earth in her whoredom, and He did avenge the blood of His servants at her hand;'''),
  ('YLT', 'REV', 19, 3, 'and a second time they said, `Alleluia;'' and her smoke doth come up--to the ages of the ages!'),
  ('YLT', 'REV', 19, 4, 'And fall down did the elders--the twenty and four--and the four living creatures, and they did bow before God who is sitting upon the throne, saying, `Amen, Alleluia.'''),
  ('YLT', 'REV', 19, 5, 'And a voice out of the throne did come forth, saying, `Praise our God, all ye His servants, and those fearing Him, both the small and the great;'''),
  ('YLT', 'REV', 19, 6, 'and I heard as the voice of a great multitude, and as the voice of many waters, and as the voice of mighty thunderings, saying, `Alleluia! because reign did the Lord God--the Almighty!'),
  ('YLT', 'REV', 19, 7, 'may we rejoice and exult, and give the glory to Him, because come did the marriage of the Lamb, and his wife did make herself ready;'),
  ('YLT', 'REV', 19, 8, 'and there was given to her that she may be arrayed with fine linen, pure and shining, for the fine linen is the righteous acts of the saints.'''),
  ('YLT', 'REV', 19, 9, 'And he saith to me, `Write: Happy are they who to the supper of the marriage of the Lamb have been called;'' and he saith to me, `These are the true words of God;'''),
  ('YLT', 'REV', 19, 10, 'and I fell before his feet, to bow before him, and he saith to me, `See--not! fellow servant of thee am I, and of thy brethren, those having the testimony of Jesus; bow before God, for the testimony of Jesus is the spirit of the prophecy.'''),
  ('YLT', 'REV', 19, 11, 'And I saw the heaven having been opened, and lo, a white horse, and he who is sitting upon it is called Faithful and True, and in righteousness doth he judge and war,'),
  ('YLT', 'REV', 19, 12, 'and his eyes are as a flame of fire, and upon his head are many diadems--having a name written that no one hath known, except himself,'),
  ('YLT', 'REV', 19, 13, 'and he is arrayed with a garment covered with blood, and his name is called, The Word of God.'),
  ('YLT', 'REV', 19, 14, 'And the armies in the heaven were following him upon white horses, clothed in fine linen--white and pure;'),
  ('YLT', 'REV', 19, 15, 'and out of his mouth doth proceed a sharp sword, that with it he may smite the nations, and he shall rule them with a rod of iron, and he doth tread the press of the wine of the wrath and the anger of God the Almighty,'),
  ('YLT', 'REV', 19, 16, 'and he hath upon the garment and upon his thigh the name written, `King of kings, and Lord of lords.'''),
  ('YLT', 'REV', 19, 17, 'And I saw one messenger standing in the sun, and he cried, a great voice, saying to all the birds that are flying in mid-heaven, `Come and be gathered together to the supper of the great God,'),
  ('YLT', 'REV', 19, 18, 'that ye may eat flesh of kings, and flesh of chiefs of thousands, and flesh of strong men, and flesh of horses, and of those sitting on them, and the flesh of all--freemen and servants--both small and great.'''),
  ('YLT', 'REV', 19, 19, 'And I saw the beast, and the kings of the earth, and their armies, having been gathered together to make war with him who is sitting upon the horse, and with his army;'),
  ('YLT', 'REV', 19, 20, 'and the beast was taken, and with him the false prophet who did the signs before him, in which he led astray those who did receive the mark of the beast, and those who did bow before his image; living they were cast--the two--to the lake of the fire, that is burning with brimstone;'),
  ('YLT', 'REV', 19, 21, 'and the rest were killed with the sword of him who is sitting on the horse, which sword is proceeding out of his mouth, and all the birds were filled out of their flesh.')
insert into public.strongs_lemmas (id, language, lemma, transliteration, pronunciation, definition, kjv_usage, plain_note) values
  ('G0018', 'greek', 'ἀγαθός', 'agathós', null, '"good" (in any sense, often as noun) a primary word;', 'benefit, good(-s, things), well', null),
  ('G0032', 'greek', 'ἄγγελος', 'ángelos', null, 'compare G34 (ἀγέλη)) (to bring tidings); a messenger; especially an "angel"; by implication, a pastor from (probably derived from G71 (ἄγω);', 'angel, messenger', null),
  ('G0040', 'greek', 'ἅγιος', 'hágios', null, 'sacred (physically, pure, morally blameless or religious, ceremonially, consecrated) from (an awful thing) (compare G53 (ἁγνός), G2282 (θάλπω));', '(most) holy (one, thing), saint', null),
  ('G0071', 'greek', 'ἄγω', 'ágō', null, 'properly, to lead; by implication, to bring, drive, (reflexively) go, (specially) pass (time), or (figuratively) induce a primary verb;', 'be, bring (forth), carry, (let) go, keep, lead away, be open', null),
  ('G0080', 'greek', 'ἀδελφός', 'adelphós', null, 'a brother (literally or figuratively) near or remote (much like G1 (Α)) from G1 (Α) (as a connective particle) and (the womb);', 'brother', null),
  ('G0129', 'greek', 'αἷμα', 'haîma', null, 'blood, literally (of men or animals), figuratively (the juice of grapes) or specially (the atoning blood of Christ); by implication, bloodshed, also kindred of uncertain derivation;', 'blood', null),
  ('G0142', 'greek', 'αἴρω', 'aírō', null, 'to lift up; by implication, to take up or away; figuratively, to raise (the voice), keep in suspense (the mind), specially, to sail away (i.e. weigh anchor); by Hebraism (compare H05375) to expiate sin a primary root;', 'away with, bear (up), carry, lift up, loose, make to doubt, put away, remove, take (away, up)', null),
  ('G0190', 'greek', 'ἀκολουθέω', 'akolouthéō', null, 'properly, to be in the same way with, i.e. to accompany (specially, as a disciple) from G1 (Α) (as a particle of union) and (a road);', 'follow, reach', null),
  ('G0191', 'greek', 'ἀκούω', 'akoúō', null, 'to hear (in various senses) a primary verb;', 'give (in the) audience (of), come (to the ears), (shall) hear(-er, -ken), be noised, be reported, understand', null),
  ('G0225', 'greek', 'ἀλήθεια', 'alḗtheia', null, 'truth from G227 (ἀληθής);', 'true, X truly, truth, verity', null),
  ('G0228', 'greek', 'ἀληθινός', 'alēthinós', null, 'truthful from G227 (ἀληθής);', 'true', null),
  ('G0230', 'greek', 'ἀληθῶς', 'alēthōs', null, 'truly adverb from G227 (ἀληθής);', 'indeed, surely, of a surety, truly, of a (in) truth, verily, very', null),
  ('G0235', 'greek', 'ἀλλά', 'allá', null, 'properly, other things, i.e. (adverbially) contrariwise (in many relations) neuter plural of G243 (ἄλλος);', 'and, but (even), howbeit, indeed, nay, nevertheless, no, notwithstanding, save, therefore, yea, yet', null),
  ('G0266', 'greek', 'ἁμαρτία', 'hamartía', null, 'a sin (properly abstract) from G264 (ἁμαρτάνω);', 'offence, sin(-ful)', null),
  ('G0281', 'greek', 'ἀμήν', 'amḗn', null, 'properly, firm, i.e. (figuratively) trustworthy; adverbially, surely (often as interjection, so be it) of Hebrew origin (H0543);', 'amen, verily', null),
  ('G0286', 'greek', 'ἀμνός', 'amnós', null, 'a lamb apparently a primary word;', 'lamb', null),
  ('G0302', 'greek', 'ἄν', 'án', null, 'a primary particle, denoting a supposition, wish, possibility or uncertainty', '(what-, where-, wither-, who-)soever', null),
  ('G0305', 'greek', 'ἀναβαίνω', 'anabaínō', null, 'to go up (literally or figuratively) from G303 (ἀνά) and the base of G939 (βάσις);', 'arise, ascend (up), climb (go, grow, rise, spring) up, come (up)', null),
  ('G0314', 'greek', 'ἀναγινώσκω', 'anaginṓskō', null, 'to know again, i.e. (by extension) to read from G303 (ἀνά) and G1097 (γινώσκω);', 'read', null),
  ('G0320', 'greek', 'ἀνάγνωσις', 'anágnōsis', null, '(the act of) reading from G314 (ἀναγινώσκω);', 'reading', null),
  ('G0343', 'greek', 'ἀνακαλύπτω', 'anakalýptō', null, 'to unveil from G303 (ἀνά) (in the sense of reversal) and G2572 (καλύπτω);', 'open, (un-)taken away', null),
  ('G0406', 'greek', 'Ἀνδρέας', 'Andréas', null, 'manly; Andreas, an Israelite from G435 (ἀνήρ);', 'Andrew', null),
  ('G0435', 'greek', 'ἀνήρ', 'anḗr', null, 'a man (properly as an individual male) a primary word (compare G444 (ἄνθρωπος));', 'fellow, husband, man, sir', null),
  ('G0444', 'greek', 'ἄνθρωπος', 'ánthrōpos', null, 'from G3700 (ὀπτάνομαι)); man-faced, i.e. a human being from G435 (ἀνήρ) and (the countenance;', 'certain, man', null),
  ('G0455', 'greek', 'ἀνοίγω', 'anoígō', null, 'to open up (literally or figuratively, in various applications) from G303 (ἀνά) and (to open);', 'open', null),
  ('G0473', 'greek', 'ἀντί', 'antí', null, 'opposite, i.e. instead or because of (rarely in addition to) a primary particle;', 'for, in the room of', null),
  ('G0514', 'greek', 'ἄξιος', 'áxios', null, 'deserving, comparable or suitable (as if drawing praise) probably from G71 (ἄγω);', 'due reward, meet, (un-)worthy', null),
  ('G0575', 'greek', 'ἀπό', 'apó', null, '"off," i.e. away (from something near), in various senses (of place, time, or relation; literal or figurative) a primary particle;', '(X here-)after, ago, at, because of, before, by (the space of), for(-th), from, in, (out) of, off, (up-)on(-ce), since, with', null),
  ('G0611', 'greek', 'ἀποκρίνομαι', 'apokrínomai', null, 'to conclude for oneself, i.e. (by implication) to respond; by Hebraism (compare H06030) to begin to speak (where an address is expected) from G575 (ἀπό) and ;', 'answer', null),
  ('G0612', 'greek', 'ἀπόκρισις', 'apókrisis', null, 'a response from G611 (ἀποκρίνομαι);', 'answer', null),
  ('G0615', 'greek', 'ἀποκτείνω', 'apokteínō', null, 'to kill outright; figuratively, to destroy from G575 (ἀπό) and (to slay);', 'put to death, kill, slay', null),
  ('G0649', 'greek', 'ἀποστέλλω', 'apostéllō', null, 'set apart, i.e. (by implication) to send out (properly, on a mission) literally or figuratively from G575 (ἀπό) and G4724 (στέλλω);', 'put in, send (away, forth, out), set (at liberty)', null),
  ('G0720', 'greek', 'ἀρνέομαι', 'arnéomai', null, 'to contradict, i.e. disavow, reject, abnegate perhaps from G1 (Α) (as a negative particle) and the middle voice of G4483 (ῥέω);', 'deny, refuse', null),
  ('G0746', 'greek', 'ἀρχή', 'archḗ', null, '(properly abstract) a commencement, or (concretely) chief (in various applications of order, time, place, or rank) from G756 (ἄρχομαι);', 'beginning, corner, (at the, the) first (estate), magistrate, power, principality, principle, rule', null),
  ('G0757', 'greek', 'ἄρχω', 'árchō', null, 'to be first (in political rank or power) a primary verb;', 'reign (rule) over', null),
  ('G0816', 'greek', 'ἀτενίζω', 'atenízō', null, 'to gaze intently from a compound of G1 (Α) (as a particle of union) and (to stretch);', 'behold earnestly (stedfastly), fasten (eyes), look (earnestly, stedfastly, up stedfastly), set eyes', null),
  ('G0846', 'greek', 'αὐτός', 'autós', null, 'the reflexive pronoun self, used (alone or in the comparative G1438 (ἑαυτοῦ)) of the third person , and (with the proper personal pronoun) of the other persons from the particle (perhaps akin to the base of G109 (ἀήρ) through the idea of a baffling wind) (backward);', 'her, it(-self), one, the other, (mine) own, said, (self-), the) same, ((him-, my-, thy- )self, (your-)selves, she, that, their(-s), them(-selves), there(-at, - by, -in, -into, -of, -on, -with), they, (these) things, this (man), those, together, very, which', null),
  ('G0891', 'greek', 'ἄχρι', 'áchri', null, '(of time) until or (of place) up to akin to G206 (ἄκρον) (through the idea of a terminus);', 'as far as, for, in(-to), till, (even, un-)to, until, while', null),
  ('G0907', 'greek', 'βαπτίζω', 'baptízō', null, 'to immerse, submerge; to make whelmed (i.e. fully wet); used only (in the New Testament) of ceremonial ablution, especially (technically) of the ordinance of Christian baptism from a derivative of G911 (βάπτω);', 'Baptist, baptize, wash', null),
  ('G0935', 'greek', 'βασιλεύς', 'basileús', null, 'a sovereign (abstractly, relatively, or figuratively) probably from G939 (βάσις) (through the notion of a foundation of power);', 'king', null),
  ('G0963', 'greek', 'Βηθανία', 'Bēthanía', null, 'date-house; Beth-any, a place in Palestine of Chaldee origin;', 'Bethany', null),
  ('G0966', 'greek', 'Βηθσαϊδά', 'Bēthsaïdá', null, 'fishing-house; Bethsaida, a place in Palestine of Chaldee origin (compare H01004 and H06719);', 'Bethsaida', null),
  ('G0991', 'greek', 'βλέπω', 'blépō', null, 'to look at (literally or figuratively) a primary verb;', 'behold, beware, lie, look (on, to), perceive, regard, see, sight, take heed', null),
  ('G0994', 'greek', 'βοάω', 'boáō', null, 'to halloo, i.e. shout (for help or in a tumultuous way) apparently a prolonged form of a primary verb;', 'cry', null),
  ('G1056', 'greek', 'Γαλιλαία', 'Galilaía', null, 'Galilæa (i.e. the heathen circle), a region of Palestine of Hebrew origin (H01551);', 'Galilee', null),
  ('G1063', 'greek', 'γάρ', 'gár', null, 'properly, assigning a reason (used in argument, explanation or intensification; often with other particles) a primary particle;', 'and, as, because (that), but, even, for, indeed, no doubt, seeing, then, therefore, verily, what, why, yet', null),
  ('G1080', 'greek', 'γεννάω', 'gennáō', null, 'to procreate (properly, of the father, but by extension of the mother); figuratively, to regenerate from a variation of G1085 (γένος);', 'bear, beget, be born, bring forth, conceive, be delivered of, gender, make, spring', null),
  ('G1096', 'greek', 'γίνομαι', 'gínomai', null, 'to cause to be ("gen"-erate), i.e. (reflexively) to become (come into being), used with great latitude (literal, figurative, intensive, etc.) a prolongation and middle voice form of a primary verb;', 'arise, be assembled, be(-come, -fall, -have self), be brought (to pass), (be) come (to pass), continue, be divided, draw, be ended, fall, be finished, follow, be found, be fulfilled, + God forbid, grow, happen, have, be kept, be made, be married, be ordained to be, partake, pass, be performed, be published, require, seem, be showed, X soon as it was, sound, be taken, be turned, use, wax, will, would, be wrought', null),
  ('G1097', 'greek', 'γινώσκω', 'ginṓskō', null, 'to "know" (absolutely) in a great variety of applications and with many implications (as follow, with others not thus clearly expressed) a prolonged form of a primary verb;', 'allow, be aware (of), feel, (have) know(-ledge), perceived, be resolved, can speak, be sure, understand', null),
  ('G1121', 'greek', 'γράμμα', 'grámma', null, 'a writing, i.e. a letter, note, epistle, book, etc.; plural learning from G1125 (γράφω);', 'bill, learning, letter, scripture, writing, written', null),
  ('G1125', 'greek', 'γράφω', 'gráphō', null, 'to "grave", especially to write; figuratively, to describe a primary verb;', 'describe, write(-ing, -ten)', null),
  ('G1161', 'greek', 'δέ', 'dé', null, 'but, and, etc. a primary particle (adversative or continuative);', 'also, and, but, moreover, now (often unexpressed in English)', null),
  ('G1182', 'greek', 'δέκατος', 'dékatos', null, 'tenth ordinal from G1176 (δέκα);', 'tenth', null),
  ('G1223', 'greek', 'διά', 'diá', null, 'through (in very wide applications, local, causal, or occasional) a primary preposition denoting the channel of an act;', 'after, always, among, at, to avoid, because of (that), briefly, by, for (cause) … fore, from, in, by occasion of, of, by reason of, for sake, that, thereby, therefore, X though, through(-out), to, wherefore, with (-in)', null),
  ('G1242', 'greek', 'διαθήκη', 'diathḗkē', null, 'properly, a disposition, i.e. (specially) a contract (especially a devisory will) from G1303 (διατίθεμαι);', 'covenant, testament', null),
  ('G1247', 'greek', 'διακονέω', 'diakonéō', null, 'to be an attendant, i.e. wait upon (menially or as a host, friend, or (figuratively) teacher); technically, to act as a Christian deacon from G1249 (διάκονος);', '(ad-)minister (unto), serve, use the office of a deacon', null),
  ('G1248', 'greek', 'διακονία', 'diakonía', null, 'attendance (as a servant, etc.); figuratively (eleemosynary) aid, (official) service (especially of the Christian teacher, or technically of the diaconate) from G1249 (διάκονος);', '(ad-)minister(-ing, -tration, -try), office, relief, service(-ing)', null),
  ('G1249', 'greek', 'διάκονος', 'diákonos', null, 'an attendant, i.e. (genitive case) a waiter (at table or in other menial duties); specially, a Christian teacher and pastor (technically, a deacon or deaconess) probably from an obsolete (to run on errands; compare G1377 (διώκω));', 'deacon, minister, servant', null),
  ('G1320', 'greek', 'διδάσκαλος', 'didáskalos', null, 'an instructor (genitive case or specially) from G1321 (διδάσκω);', 'doctor, master, teacher', null),
  ('G1325', 'greek', 'δίδωμι', 'dídōmi', null, 'to give (used in a very wide application, properly, or by implication, literally or figuratively; greatly modified by the connection) a prolonged form of a primary verb (which is used as an alternative in most of the tenses);', 'adventure, bestow, bring forth, commit, deliver (up), give, grant, hinder, make, minister, number, offer, have power, put, receive, set, shew, smite (+ with the hand), strike (+ with the palm of the hand), suffer, take, utter, yield', null),
  ('G1343', 'greek', 'δικαιοσύνη', 'dikaiosýnē', null, 'equity (of character or act); specially (Christian) justification from G1342 (δίκαιος);', 'righteousness', null),
  ('G1388', 'greek', 'δόλος', 'dólos', null, 'compare G1185 (δελεάζω)); a trick (bait), i.e. (figuratively) wile from an obsolete primary verb, (probably meaning to decoy;', 'craft, deceit, guile, subtilty', null),
  ('G1391', 'greek', 'δόξα', 'dóxa', null, 'glory (as very apparent), in a wide application (literal or figurative, objective or subjective) from the base of G1380 (δοκέω);', 'dignity, glory(-ious), honour, praise, worship', null),
  ('G1392', 'greek', 'δοξάζω', 'doxázō', null, 'to render (or esteem) glorious (in a wide application) from G1391 (δόξα);', '(make) glorify(-ious), full of (have) glory, honour, magnify', null),
  ('G1410', 'greek', 'δύναμαι', 'dýnamai', null, 'to be able or possible of uncertain affinity;', 'be able, can (do, + -not), could, may, might, be possible, be of power', null),
  ('G1417', 'greek', 'δύο', 'dýo', null, '"two" a primary numeral;', 'both, twain, two', null),
  ('G1437', 'greek', 'ἐάν', 'eán', null, 'a conditional particle; in case that, provided, etc.; often used in connection with other particles to denote indefiniteness or uncertainty from G1487 (εἰ) and G302 (ἄν);', 'before, but, except, (and) if, (if) so, (what-, whither-)soever, though, when (-soever), whether (or), to whom, (who-)so(-ever)', null),
  ('G1438', 'greek', 'ἑαυτοῦ', 'heautoû', null, 'him- (her-, it-, them-, also (in conjunction with the personal pronoun of the other persons) my-, thy-, our-, your-) self (selves), etc. from a reflexive pronoun otherwise obsolete and the genitive case (dative case or accusative case) of G846 (αὐτός);', 'alone, her (own, -self), (he) himself, his (own), itself, one (to) another, our (thine) own(-selves), + that she had, their (own, own selves), (of) them(-selves), they, thyself, you, your (own, own conceits, own selves, -selves)', null),
  ('G1449', 'greek', 'ἐγγράφω', 'engráphō', null, 'to "engrave", i.e. inscribe from G1722 (ἐν) and G1125 (γράφω);', 'write (in)', null),
  ('G1473', 'greek', 'ἐγώ', 'egṓ', null, 'a primary pronoun of the first person I (only expressed when emphatic)', 'I, me', null),
  ('G1487', 'greek', 'εἰ', 'ei', null, 'if, whether, that, etc. a primary particle of conditionality;', 'forasmuch as, if, that, (al-)though, whether', null),
  ('G1504', 'greek', 'εἰκών', 'eikṓn', null, 'a likeness, i.e. (literally) statue, profile, or (figuratively) representation, resemblance from G1503 (εἴκω);', 'image', null),
  ('G1510', 'greek', 'εἰμί', 'eimí', null, 'I exist (used only when emphatic) the first person singular present indicative; a prolonged form of a primary and defective verb;', 'am, have been, X it is I, was', 'This tiny word — "is" — carries enormous weight. Paul doesn’t say the Lord is like the Spirit, or represented by the Spirit. He says IS. A direct equation. Like saying "fire is hot." Theologians have spent centuries unpacking this one word, and it sits at the heart of everything Christians believe about the Trinity.'),
  ('G1519', 'greek', 'εἰς', 'eis', null, 'to or into (indicating the point reached or entered), of place, time, or (figuratively) purpose (result, etc.); also in adverbial phrases a primary preposition;', '(abundant-)ly, against, among, as, at, (back-)ward, before, by, concerning, + continual, + far more exceeding, for (intent, purpose), fore, + forth, in (among, at, unto, -so much that, -to), to the intent that, + of one mind, + never, of, (up-)on, + perish, + set at one again, (so) that, therefore(-unto), throughout, til, to (be, the end, -ward), (here-)until(-to), …ward, (where-)fore, with', null),
  ('G1520', 'greek', 'εἷς', 'heîs', null, 'one a primary numeral;', 'a(-n, -ny, certain), + abundantly, man, one (another), only, other, some', null),
  ('G1537', 'greek', 'ἐκ', 'ek', null, 'literal or figurative; direct or remote) a primary preposition denoting origin (the point whence action or motion proceeds), from, out (of place, time, or cause;', 'after, among, X are, at, betwixt(-yond), by (the means of), exceedingly, (+ abundantly above), for(- th), from (among, forth, up), + grudgingly, + heartily, X heavenly, X hereby, + very highly, in, …ly, (because, by reason) of, off (from), on, out among (from, of), over, since, X thenceforth, through, X unto, X vehemently, with(-out)', null),
  ('G1565', 'greek', 'ἐκεῖνος', 'ekeînos', null, 'that one (or (neuter) thing); often intensified by the article prefixed from G1563 (ἐκεῖ);', 'he, it, the other (same), selfsame, that (same, very), X their, X them, they, this, those', null),
  ('G1588', 'greek', 'ἐκλεκτός', 'eklektós', null, 'select; by implication, favorite from G1586 (ἐκλέγομαι);', 'chosen, elect', null),
  ('G1657', 'greek', 'ἐλευθερία', 'eleuthería', null, 'freedom (legitimate or licentious, chiefly moral or ceremonial) from G1658 (ἐλεύθερος);', 'liberty', 'In Paul’s world, a freed slave wasn’t just their own boss — they were adopted into their liberator’s family. That’s the freedom Paul means here. Not "do whatever you want." Deeper: you’re not just released, you’re welcomed in. You belong somewhere now. The veil keeping you at arm’s length from God — it’s gone.'),
  ('G1680', 'greek', 'ἐλπίς', 'elpís', null, 'expectation (abstractly or concretely) or confidence from a primary (to anticipate, usually with pleasure);', 'faith, hope', null),
  ('G1689', 'greek', 'ἐμβλέπω', 'emblépō', null, 'to look on, i.e. (relatively) to observe fixedly, or (absolutely) to discern clearly from G1722 (ἐν) and G991 (βλέπω);', 'behold, gaze up, look upon, (could) see', null),
  ('G1715', 'greek', 'ἔμπροσθεν', 'émprosthen', null, 'in front of (in place (literally or figuratively) or time) from G1722 (ἐν) and G4314 (πρός);', 'against, at, before, (in presence, sight) of', null),
  ('G1722', 'greek', 'ἐν', 'en', null, '"in," at, (up-)on, by, etc. a primary preposition denoting (fixed) position (in place, time or state), and (by implication) instrumentality (medially or constructively), i.e. a relation of rest (intermediate between G1519 (εἰς) and G1537 (ἐκ));', 'about, after, against, + almost, X altogether, among, X as, at, before, between, (here-)by (+ all means), for (… sake of), + give self wholly to, (here-)in(-to, -wardly), X mightily, (because) of, (up-)on, (open-)ly, X outwardly, one, X quickly, X shortly, (speedi-)ly, X that, X there(-in, -on), through(-out), (un-)to(-ward), under, when, where(-with), while, with(-in)', null),
  ('G1795', 'greek', 'ἐντυπόω', 'entypóō', null, 'to enstamp, i.e. engrave from G1722 (ἐν) and a derivative of G5179 (τύπος);', 'engrave', null),
  ('G1831', 'greek', 'ἐξέρχομαι', 'exérchomai', null, 'to issue (literally or figuratively) from G1537 (ἐκ) and G2064 (ἔρχομαι);', 'come (forth, out), depart (out of), escape, get out, go (abroad, away, forth, out, thence), proceed (forth), spread abroad', null),
  ('G1834', 'greek', 'ἐξηγέομαι', 'exēgéomai', null, 'to consider out (aloud), i.e. rehearse, unfold from G1537 (ἐκ) and G2233 (ἡγέομαι);', 'declare, tell', null),
  ('G1849', 'greek', 'ἐξουσία', 'exousía', null, 'privilege, i.e. (subjectively) force, capacity, competency, freedom, or (objectively) mastery (concretely, magistrate, superhuman, potentate, token of control), delegated influence from G1832 (ἔξεστι) (in the sense of ability);', 'authority, jurisdiction, liberty, power, right, strength', null),
  ('G1887', 'greek', 'ἐπαύριον', 'epaúrion', null, 'occurring on the succeeding day, i.e. (G2250 (ἡμέρα) being implied) to-morrow from G1909 (ἐπί) and G839 (αὔριον);', 'day following, morrow, next day (after)', null),
  ('G1909', 'greek', 'ἐπί', 'epí', null, 'properly, meaning superimposition (of time, place, order, etc.), as a relation of distribution (with the genitive case), i.e. over, upon, etc.; of rest (with the dative case) at, on, etc.; of direction (with the accusative case) towards, upon, etc. a primary preposition;', 'about (the times), above, after, against, among, as long as (touching), at, beside, X have charge of, (be-, (where-))fore, in (a place, as much as, the time of, -to), (because) of, (up-)on (behalf of), over, (by, for) the space of, through(-out), (un-)to(-ward), with', null),
  ('G1992', 'greek', 'ἐπιστολή', 'epistolḗ', null, 'a written message from G1989 (ἐπιστέλλω);', '"epistle," letter', null),
  ('G1994', 'greek', 'ἐπιστρέφω', 'epistréphō', null, 'to revert (literally, figuratively or morally) from G1909 (ἐπί) and G4762 (στρέφω);', 'come (go) again, convert, (re-)turn (about, again)', null),
  ('G2048', 'greek', 'ἔρημος', 'érēmos', null, 'of uncertain affinity; lonesome, i.e. (by implication) waste (usually as a noun, G5561 (χώρα) being implied)', 'desert, desolate, solitary, wilderness', null),
  ('G2059', 'greek', 'ἑρμηνεύω', 'hermēneúō', null, 'to translate from a presumed derivative of G2060 (Ἑρμῆς) (as the god of language);', 'interpret', null),
  ('G2064', 'greek', 'ἔρχομαι', 'érchomai', null, 'to come or go (in a great variety of applications, literally and figuratively) middle voice of a primary verb (used only in the present and imperfect tenses, the others being supplied by a kindred (middle voice) , or (active) , which do not otherwise occur);', 'accompany, appear, bring, come, enter, fall out, go, grow, X light, X next, pass, resort, be set', null),
  ('G2065', 'greek', 'ἐρωτάω', 'erōtáō', null, 'to interrogate; by implication, to request apparently from G2046 (ἐρέω) (compare G2045 (ἐρευνάω));', 'ask, beseech, desire, intreat, pray', null),
  ('G2116', 'greek', 'εὐθύνω', 'euthýnō', null, 'to straighten (level); technically, to steer from G2117 (εὐθύς);', 'governor, make straight', null),
  ('G2147', 'greek', 'εὑρίσκω', 'heurískō', null, 'to find (literally or figuratively) a prolonged form of a primary , which (together with another cognate form) is used for it in all the tenses except the present and imperfect;', 'find, get, obtain, perceive, see', null),
  ('G2192', 'greek', 'ἔχω', 'échō', null, 'to hold (used in very various applications, literally or figuratively, direct or remote; such as possession; ability, contiuity, relation, or condition) a primary verb;', 'be (able, X hold, possessed with), accompany, + begin to amend, can(+ -not), X conceive, count, diseased, do + eat, + enjoy, + fear, following, have, hold, keep, + lack, + go to law, lie, + must needs, + of necessity, + need, next, + recover, + reign, + rest, + return, X sick, take for, + tremble, + uncircumcised, use', null),
  ('G2193', 'greek', 'ἕως', 'héōs', null, 'a conjunction, preposition and adverb of continuance, until (of time and place) of uncertain affinity;', 'even (until, unto), (as) far (as), how long, (un-)til(-l), (hither-, un-, up) to, while(-s)', null),
  ('G2198', 'greek', 'ζάω', 'záō', null, 'to live (literally or figuratively) a primary verb;', 'life(-time), (a-)live(-ly), quick', null),
  ('G2212', 'greek', 'ζητέω', 'zētéō', null, 'to seek (literally or figuratively); specially, (by Hebraism) to worship (God), or (in a bad sense) to plot (against life) of uncertain affinity;', 'be (go) about, desire, endeavour, enquire (for), require, (X will) seek (after, for, means)', null),
  ('G2222', 'greek', 'ζωή', 'zōḗ', null, 'life (literally or figuratively) from G2198 (ζάω);', 'life(-time)', '"Zoe" is life in the fullest sense — not merely being alive, which Greek had another word for, but life that is going somewhere and is worth having. When John says this life was the light of men, he means the two are the same gift seen from two angles.'),
  ('G2227', 'greek', 'ζωοποιέω', 'zōopoiéō', null, 'to (re-)vitalize (literally or figuratively) from the same as G2226 (ζῶον) and G4160 (ποιέω);', 'make alive, give life, quicken', null),
  ('G2228', 'greek', 'ἤ', 'ḗ', null, 'disjunctive, or; comparative, than a primary particle of distinction between two connected terms;', 'and, but (either), (n-)either, except it be, (n-)or (else), rather, save, than, that, what, yea', null),
  ('G2243', 'greek', 'Ἡλίας', 'Hēlías', null, 'Helias (i.e. Elijah), an Israelite of Hebrew origin (H0452);', 'Elias', null),
  ('G2250', 'greek', 'ἡμέρα', 'hēméra', null, 'day, i.e. (literally) the time space between dawn and dark, or the whole 24 hours (but several days were usually reckoned by the Jews as inclusive of the parts of both extremes); figuratively, a period (always defined more or less clearly by the context) feminine (with G5610 (ὥρα) implied) of a derivative of (to sit; akin to the base of G1476 (ἑδραῖος)) meaning tame, i.e. gentle;', 'age, + alway, (mid-)day (by day, (-ly)), + for ever, judgment, (day) time, while, years', null),
  ('G2259', 'greek', 'ἡνίκα', 'hēníka', null, 'at which time of uncertain affinity;', 'when', null),
  ('G2268', 'greek', 'Ἡσαΐας', 'Hēsaḯas', null, 'Hesaias (i.e. Jeshajah), an Israelite of Hebrew origin (H03470);', 'Esaias', null),
  ('G2288', 'greek', 'θάνατος', 'thánatos', null, '(properly, an adjective used as a noun) death (literally or figuratively) from G2348 (θνήσκω);', 'X deadly, (be…) death', null),
  ('G2300', 'greek', 'θεάομαι', 'theáomai', null, 'to look closely at, i.e. (by implication) perceive (literally or figuratively); by extension to visit a prolonged form of a primary verb;', 'behold, look (upon), see', null),
  ('G2307', 'greek', 'θέλημα', 'thélēma', null, 'a determination (properly, the thing), i.e. (actively) choice (specially, purpose, decree; abstractly, volition) or (passively) inclination from the prolonged form of G2309 (θέλω);', 'desire, pleasure, will', null),
  ('G2309', 'greek', 'θέλω', 'thélō', null, 'to determine (as an active option from subjective impulse; whereas G1014 (βούλομαι) properly denotes rather a passive acquiescence in objective considerations), i.e. choose or prefer (literally or figuratively); by implication, to wish, i.e. be inclined to (sometimes adverbially, gladly); impersonally for the future tense, to be about to; by Hebraism, to delight in apparently strengthened from the alternate form of G138 (αἱρέομαι);', 'desire, be disposed (forward), intend, list, love, mean, please, have rather, (be) will (have, -ling, - ling(-ly))', null),
  ('G2316', 'greek', 'θεός', 'theós', null, 'figuratively, a magistrate; by Hebraism, very of uncertain affinity; a deity, especially (with G3588 (ὁ)) the supreme Divinity;', 'X exceeding, God, god(-ly, -ward)', null),
  ('G2396', 'greek', 'ἴδε', 'íde', null, 'used as an interjection to denote surprise; lo! second person singular imperative active of G1492 (εἴδω);', 'behold, lo, see', null),
  ('G2398', 'greek', 'ἴδιος', 'ídios', null, 'pertaining to self, i.e. one''s own; by implication, private or separate of uncertain affinity;', 'X his acquaintance, when they were alone, apart, aside, due, his (own, proper, several), home, (her, our, thine, your) own (business), private(-ly), proper, severally, their (own)', null),
  ('G2409', 'greek', 'ἱερεύς', 'hiereús', null, 'a priest (literally or figuratively) from G2413 (ἱερός);', '(high) priest', null),
  ('G2414', 'greek', 'Ἱεροσόλυμα', 'Hierosólyma', null, 'Hierosolyma (i.e. Jerushalaim), the capitol of Palestine of Hebrew origin (H03389);', 'Jerusalem', null),
  ('G2424', 'greek', 'Ἰησοῦς', 'Iēsoûs', null, 'Jesus (i.e. Jehoshua), the name of our Lord and two (three) other Israelites of Hebrew origin (H03091);', 'Jesus', null),
  ('G2425', 'greek', 'ἱκανός', 'hikanós', null, 'competent (as if coming in season), i.e. ample (in amount) or fit (in character) from ( or , akin to G2240 (ἥκω)) (to arrive);', 'able, + content, enough, good, great, large, long (while), many, meet, much, security, sore, sufficient, worthy', null),
  ('G2426', 'greek', 'ἱκανότης', 'hikanótēs', null, 'ability from G2425 (ἱκανός);', 'sufficiency', null),
  ('G2427', 'greek', 'ἱκανόω', 'hikanóō', null, 'to enable, i.e. qualify from G2425 (ἱκανός);', 'make able (meet)', null),
  ('G2438', 'greek', 'ἱμάς', 'himás', null, 'a strap, i.e. (specially) the tie (of a sandal) or the lash (of a scourge) perhaps from the same as G260 (ἅμα);', 'latchet, thong', null),
  ('G2443', 'greek', 'ἵνα', 'hína', null, 'compare G3588 (ὁ)); in order that (denoting the purpose or the result) probably from the same as the former part of G1438 (ἑαυτοῦ) (through the demonstrative idea;', 'albeit, because, to the intent (that), lest, so as, (so) that, (for) to', null),
  ('G2446', 'greek', 'Ἰορδάνης', 'Iordánēs', null, 'the Jordanes (i.e. Jarden), a river of Palestine of Hebrew origin (H03383);', 'Jordan', null),
  ('G2453', 'greek', 'Ἰουδαῖος', 'Ioudaîos', null, 'Judæan, i.e. belonging to Jehudah from G2448 (Ἰουδά) (in the sense of G2455 (Ἰούδας) as a country);', 'Jew(-ess), of Judæa', null),
  ('G2474', 'greek', 'Ἰσραήλ', 'Israḗl', null, 'Israel (i.e. Jisrael), the adopted name of Jacob, including his descendants (literally or figuratively) of Hebrew origin (H03478);', 'Israel', null),
  ('G2475', 'greek', 'Ἰσραηλίτης', 'Israēlítēs', null, 'an "Israelite", i.e. descendant of Israel (literally or figuratively) from G2474 (Ἰσραήλ);', 'Israelite', null),
  ('G2476', 'greek', 'ἵστημι', 'hístēmi', null, 'to stand (transitively or intransitively), used in various applications (literally or figuratively) a prolonged form of a primary (of the same meaning, and used for it in certain tenses);', 'abide, appoint, bring, continue, covenant, establish, hold up, lay, present, set (up), stanch, stand (by, forth, still, up)', null),
  ('G2491', 'greek', 'Ἰωάννης', 'Iōánnēs', null, 'Joannes (i.e. Jochanan), the name of four Israelites of Hebrew origin (H03110);', 'John', null),
  ('G2501', 'greek', 'Ἰωσήφ', 'Iōsḗph', null, 'Joseph, the name of seven Israelites of Hebrew origin (H03130);', 'Joseph', null),
  ('G2504', 'greek', 'κἀγώ', 'kagṓ', null, 'so also the dative case , and accusative case and (or also, even, etc.) I, (to) me from G2532 (καί) and G1473 (ἐγώ);', '(and, even, even so, so) I (also, in like wise), both me, me also', null),
  ('G2509', 'greek', 'καθάπερ', 'katháper', null, 'exactly as from G2505 (καθά) and G4007 (περ);', '(even, as well) as', null),
  ('G2531', 'greek', 'καθώς', 'kathṓs', null, 'just (or inasmuch) as, that from G2596 (κατά) and G5613 (ὡς);', 'according to, (according, even) as, how, when', null),
  ('G2532', 'greek', 'καί', 'kaí', null, 'and, also, even, so then, too, etc.; often used in connection (or composition) with other particles or small words apparently, a primary particle, having a copulative and sometimes also a cumulative force;', 'and, also, both, but, even, for, if, or, so, that, then, therefore, when, yet', null),
  ('G2537', 'greek', 'καινός', 'kainós', null, 'of uncertain affinity; new (especially in freshness; while G3501 (νέος) is properly so with respect to age', 'new', null),
  ('G2564', 'greek', 'καλέω', 'kaléō', null, 'to "call" (properly, aloud, but used in a variety of applications, directly or otherwise) akin to the base of G2753 (κελεύω);', 'bid, call (forth), (whose, whose sur-)name (was (called))', null),
  ('G2588', 'greek', 'καρδία', 'kardía', null, 'the heart, i.e. (figuratively) the thoughts or feelings (mind); also (by analogy) the middle prolonged from a primary (Latin cor, "heart");', '(+ broken-)heart(-ed)', null),
  ('G2597', 'greek', 'καταβαίνω', 'katabaínō', null, 'to descend (literally or figuratively) from G2596 (κατά) and the base of G939 (βάσις);', 'come (get, go, step) down, fall (down)', null),
  ('G2633', 'greek', 'κατάκρισις', 'katákrisis', null, 'sentencing adversely (the act) from G2632 (κατακρίνω);', 'condemn(-ation)', null),
  ('G2638', 'greek', 'καταλαμβάνω', 'katalambánō', null, 'to take eagerly, i.e. seize, possess, etc. (literally or figuratively) from G2596 (κατά) and G2983 (λαμβάνω);', 'apprehend, attain, come upon, comprehend, find, obtain, perceive, (over-)take', null),
  ('G2673', 'greek', 'καταργέω', 'katargéō', null, 'to be (render) entirely idle (useless), literally or figuratively from G2596 (κατά) and G691 (ἀργέω);', 'abolish, cease, cumber, deliver, destroy, do away, become (make) of no (none, without) effect, fail, loose, bring (come) to nought, put away (down), vanish away, make void', null),
  ('G2734', 'greek', 'κατοπτρίζομαι', 'katoptrízomai', null, 'to mirror oneself, i.e. to see reflected (figuratively) middle voice from a compound of G2596 (κατά) and a derivative of G3700 (ὀπτάνομαι) (compare G2072 (ἔσοπτρον));', 'behold as in a glass', null),
  ('G2749', 'greek', 'κεῖμαι', 'keîmai', null, 'to lie outstretched (literally or figuratively) middle voice of a primary verb;', 'be (appointed, laid up, made, set), lay, lie', null),
  ('G2786', 'greek', 'Κηφᾶς', 'Kēphâs', null, 'the Rock; Cephas (i.e. Kepha), a surname of Peter of Chaldee origin (compare H03710);', 'Cephas', null),
  ('G2859', 'greek', 'κόλπος', 'kólpos', null, 'the bosom; by analogy, a bay apparently a primary word;', 'bosom, creek', null),
  ('G2889', 'greek', 'κόσμος', 'kósmos', null, 'orderly arrangement, i.e. decoration; by implication, the world (in a wide or narrow sense, including its inhabitants, literally or figuratively (morally)) probably from the base of G2865 (κομίζω);', 'adorning, world', null),
  ('G2896', 'greek', 'κράζω', 'krázō', null, 'properly, to "croak" (as a raven) or scream, i.e. (genitive case) to call aloud (shriek, exclaim, intreat) a primary verb;', 'cry (out)', null),
  ('G2962', 'greek', 'κύριος', 'kýrios', null, 'supreme in authority, i.e. (as noun) controller; by implication, Master (as a respectful title) from (supremacy);', 'God, Lord, master, Sir', 'Kyrios means "Lord" — but it’s the same word the ancient Greek Bible used for God’s own personal name, YHWH. When Paul says "the Lord is the Spirit," he’s placing Jesus in that same space. The God of Abraham, Moses, and the burning bush — that’s who you’re encountering when you experience the Holy Spirit. That’s a breathtaking claim.'),
  ('G2980', 'greek', 'λαλέω', 'laléō', null, 'to talk, i.e. utter words a prolonged form of an otherwise obsolete verb;', 'preach, say, speak (after), talk, tell, utter', null),
  ('G2983', 'greek', 'λαμβάνω', 'lambánō', null, 'while G138 (αἱρέομαι) is more violent, to seize or remove)) a prolonged form of a primary verb, which is use only as an alternate in certain tenses; to take (in very many applications, literally and figuratively (properly objective or active, to get hold of; whereas G1209 (δέχομαι) is rather subjective or passive, to have offered to one;', 'accept, + be amazed, assay, attain, bring, X when I call, catch, come on (X unto), + forget, have, hold, obtain, receive (X after), take (away, up)', null),
  ('G3004', 'greek', 'λέγω', 'légō', null, 'properly, to "lay" forth, i.e. (figuratively) relate (in words (usually of systematic or set discourse; whereas G2036 (ἔπω) and G5346 (φημί) generally refer to an individual expression or speech respectively; while G4483 (ῥέω) is properly to break silence merely, and G2980 (λαλέω) means an extended or random harangue)); by implication, to mean a primary verb;', 'ask, bid, boast, call, describe, give out, name, put forth, say(-ing, on), shew, speak, tell, utter', null),
  ('G3019', 'greek', 'Λευΐτης', 'Leuḯtēs', null, 'a Levite, i.e. descendant of Levi from G3017 (Λευΐ);', 'Levite', null),
  ('G3035', 'greek', 'λίθινος', 'líthinos', null, 'stony, i.e. made of stone from G3037 (λίθος);', 'of stone', null),
  ('G3037', 'greek', 'λίθος', 'líthos', null, 'a stone (literally or figuratively) apparently a primary word;', '(mill-, stumbling-)stone', null),
  ('G3049', 'greek', 'λογίζομαι', 'logízomai', null, 'to take an inventory, i.e. estimate (literally or figuratively) middle voice from G3056 (λόγος);', 'conclude, (ac-)count (of), + despise, esteem, impute, lay, number, reason, reckon, suppose, think (on)', null),
  ('G3056', 'greek', 'λόγος', 'lógos', null, 'something said (including the thought); by implication, a topic (subject of discourse), also reasoning (the mental faculty) or motive; by extension, a computation; specially, (with the article in John) the Divine Expression (i.e. Christ) from G3004 (λέγω);', 'account, cause, communication, X concerning, doctrine, fame, X have to do, intent, matter, mouth, preaching, question, reason, + reckon, remove, say(-ing), shew, X speaker, speech, talk, thing, + none of these things move me, tidings, treatise, utterance, word, work', 'Logos means word, reason, or the logic behind a thing. Greek philosophers used it for the invisible order holding the universe together. John borrows their most abstract idea and does something outrageous with it: he says this ordering principle has a face, a name, and a mother.'),
  ('G3089', 'greek', 'λύω', 'lýō', null, 'to "loosen" (literally or figuratively) a primary verb;', 'break (up), destroy, dissolve, (un-)loose, melt, put off', null),
  ('G3101', 'greek', 'μαθητής', 'mathētḗs', null, 'a learner, i.e. pupil from G3129 (μανθάνω);', 'disciple', null),
  ('G3123', 'greek', 'μᾶλλον', 'mâllon', null, '(adverbially) more (in a greater degree)) or rather neuter of the comparative of the same as G3122 (μάλιστα);', '+ better, X far, (the) more (and more), (so) much (the more), rather', null),
  ('G3140', 'greek', 'μαρτυρέω', 'martyréō', null, 'to be a witness, i.e. testify (literally or figuratively) from G3144 (μάρτυς);', 'charge, give (evidence), bear record, have (obtain, of) good (honest) report, be well reported of, testify, give (have) testimony, (be, bear, give, obtain) witness', null),
  ('G3141', 'greek', 'μαρτυρία', 'martyría', null, 'evidence given (judicially or genitive case) from G3144 (μάρτυς);', 'record, report, testimony, witness', null),
  ('G3173', 'greek', 'μέγας', 'mégas', null, 'big (literally or figuratively, in a very wide application) (including the prolonged forms, feminine , plural , etc.; compare also G3176 (μέγιστος), G3187 (μείζων));', '(+ fear) exceedingly, great(-est), high, large, loud, mighty, + (be) sore (afraid), strong, X to years', null),
  ('G3177', 'greek', 'μεθερμηνεύω', 'methermēneúō', null, 'to explain over, i.e. translate from G3326 (μετά) and G2059 (ἑρμηνεύω);', '(by) interpret(-ation)', null),
  ('G3188', 'greek', 'μέλαν', 'mélan', null, 'ink neuter of G3189 (μέλας) as noun;', 'ink', null),
  ('G3306', 'greek', 'μένω', 'ménō', null, 'to stay (in a given place, state, relation or expectancy) a primary verb;', 'abide, continue, dwell, endure, be present, remain, stand, tarry (for), X thine own', null),
  ('G3313', 'greek', 'μέρος', 'méros', null, 'a division or share (literally or figuratively, in a wide application) from an obsolete but more primary form of (to get as a section or allotment);', 'behalf, course, coast, craft, particular (+ -ly), part (+ -ly), piece, portion, respect, side, some sort(-what)', null),
  ('G3319', 'greek', 'μέσος', 'mésos', null, 'middle (as an adjective or (neuter) noun) from G3326 (μετά);', 'among, X before them, between, + forth, mid(-day, -night), midst, way', null),
  ('G3323', 'greek', 'Μεσσίας', 'Messías', null, 'the Messias (i.e. Mashiach), or Christ of Hebrew origin (H04899);', 'Messias', null),
  ('G3361', 'greek', 'μή', 'mḗ', null, '(adverb) not, (conjunction) lest; also (as an interrogative implying a negative answer (whereas G3756 (οὐ) expects an affirmative one)) whether a primary particle of qualified negation (whereas G3756 (οὐ) expresses an absolute denial);', 'any but (that), X forbear, + God forbid, + lack, lest, neither, never, no (X wise in), none, nor, (can-)not, nothing, that not, un(-taken), without', null),
  ('G3439', 'greek', 'μονογενής', 'monogenḗs', null, 'only-born, i.e. sole from G3441 (μόνος) and G1096 (γίνομαι);', 'only (begotten, child)', null),
  ('G3482', 'greek', 'Ναθαναήλ', 'Nathanaḗl', null, 'Nathanaël (i.e. Nathanel), an Israelite and Christian of Hebrew origin (H05417);', 'Nathanael', null),
  ('G3540', 'greek', 'νόημα', 'nóēma', null, 'a perception, i.e. purpose, or (by implication) the intellect, disposition, itself from G3539 (νοιέω);', 'device, mind, thought', null),
  ('G3551', 'greek', 'νόμος', 'nómos', null, 'law (through the idea of prescriptive usage), genitive case (regulation), specially, (of Moses (including the volume); also of the Gospel), or figuratively (a principle) from a primary (to parcel out, especially food or grazing to animals);', 'law', null),
  ('G3588', 'greek', 'ὁ', 'ho', null, 'the (sometimes to be supplied, at others omitted, in English idiom) the definite article;', 'the, this, that, one, he, she, it, etc', null),
  ('G3598', 'greek', 'ὁδός', 'hodós', null, 'a road; by implication, a progress (the route, act or distance); figuratively, a mode or means apparently a primary word;', 'journey, (high-)way', null),
  ('G3670', 'greek', 'ὁμολογέω', 'homologéō', null, 'to assent, i.e. covenant, acknowledge from a compound of the base of G3674 (ὁμοῦ) and G3056 (λόγος);', 'con- (pro-)fess, confession is made, give thanks, promise', null),
  ('G3686', 'greek', 'ὄνομα', 'ónoma', null, 'a "name" (literally or figuratively) (authority, character) from a presumed derivative of the base of G1097 (γινώσκω) (compare G3685 (ὀνίνημι));', 'called, (+ sur-)name(-d)', null),
  ('G3694', 'greek', 'ὀπίσω', 'opísō', null, 'to the back, i.e. aback (as adverb or preposition of time or place; or as noun) from the same as G3693 (ὄπισθεν) with enclitic of direction;', 'after, back(-ward), (+ get) behind, + follow', null),
  ('G3699', 'greek', 'ὅπου', 'hópou', null, 'what(-ever) where, i.e. at whichever spot from G3739 (ὅς) and G4225 (πού);', 'in what place, where(-as, -soever), whither (+ soever)', null),
  ('G3708', 'greek', 'ὁράω', 'horáō', null, 'by extension, to attend to; by Hebraism, to experience; passively, to appear properly, to stare at (compare G3700 (ὀπτάνομαι)), i.e. (by implication) to discern clearly (physically or mentally);', 'behold, perceive, see, take heed', null),
  ('G3739', 'greek', 'ὅς', 'hós', null, 'the relatively (sometimes demonstrative) pronoun, who, which, what, that probably a primary word (or perhaps a form of the article G3588 (ὁ));', 'one, (an-, the) other, some, that, what, which, who(-m, -se), etc', null),
  ('G3745', 'greek', 'ὅσος', 'hósos', null, 'as (much, great, long, etc.) as by reduplication from G3739 (ὅς);', 'all (that), as (long, many, much) (as), how great (many, much), (in-)asmuch as, so many as, that (ever), the more, those things, what (great, -soever), wheresoever, wherewithsoever, which, X while, who(-soever)', null),
  ('G3753', 'greek', 'ὅτε', 'hóte', null, 'at which (thing) too, i.e. when from G3739 (ὅς) and G5037 (τέ);', 'after (that), as soon as, that, when, while', null),
  ('G3754', 'greek', 'ὅτι', 'hóti', null, 'demonstrative, that (sometimes redundant); causative, because neuter of G3748 (ὅστις) as conjunction;', 'as concerning that, as though, because (that), for (that), how (that), (in) that, though, why', null),
  ('G3756', 'greek', 'οὐ', 'ou', null, 'the absolute negative (compare G3361 (μή)) adverb; no or not a primary word;', '+ long, nay, neither, never, no (X man), none, (can-)not, + nothing, + special, un(-worthy), when, + without, + yet but', null),
  ('G3757', 'greek', 'οὗ', 'hoû', null, 'at which place, i.e. where genitive case of G3739 (ὅς) as adverb;', 'where(-in), whither(-soever)', '"Where" — not "if" or "someday." Wherever the Spirit shows up, freedom is already there waiting for you. You don’t have to earn it or work yourself up to it. It’s like warmth and sunlight — one comes with the other. You just have to step into it.'),
  ('G3761', 'greek', 'οὐδέ', 'oudé', null, 'not however, i.e. neither, nor, not even from G3756 (οὐ) and G1161 (δέ);', 'neither (indeed), never, no (more, nor, not), nor (yet), (also, even, then) not (even, so much as), + nothing, so much as', null),
  ('G3762', 'greek', 'οὐδείς', 'oudeís', null, 'not even one (man, woman or thing), i.e. none, nobody, nothing from G3761 (οὐδέ) and G1520 (εἷς);', 'any (man), aught, man, neither any (thing), never (man), no (man), none (+ of these things), not (any, at all, -thing), nought', null),
  ('G3767', 'greek', 'οὖν', 'oûn', null, '(adverbially) certainly, or (conjunctionally) accordingly apparently a primary word;', 'and (so, truly), but, now (then), so (likewise then), then, therefore, verily, wherefore', null),
  ('G3772', 'greek', 'οὐρανός', 'ouranós', null, 'the sky; by extension, heaven (as the abode of God); by implication, happiness, power, eternity; specially, the Gospel (Christianity) perhaps from the same as G3735 (ὄρος) (through the idea of elevation);', 'air, heaven(-ly), sky', null),
  ('G3778', 'greek', 'οὗτος', 'hoûtos', null, 'the he (she or it), i.e. this or that (often with article repeated) from the article G3588 (ὁ) and G846 (αὐτός);', 'he (it was that), hereof, it, she, such as, the same, these, they, this (man, same, woman), which, who', null),
  ('G3780', 'greek', 'οὐχί', 'ouchí', null, 'not indeed intensive of G3756 (οὐ);', 'nay, not', null),
  ('G3820', 'greek', 'παλαιός', 'palaiós', null, 'antique, i.e. not recent, worn out from G3819 (πάλαι);', 'old', null),
  ('G3825', 'greek', 'πάλιν', 'pálin', null, '(adverbially) anew, i.e. (of place) back, (of time) once more, or (conjunctionally) furthermore or on the other hand probably from the same as G3823 (πάλη) (through the idea of oscillatory repetition);', 'again', null),
  ('G3844', 'greek', 'παρά', 'pará', null, 'properly, near; i.e. (with genitive case) from beside (literally or figuratively), (with dative case) at (or in) the vicinity of (objectively or subjectively), (with accusative case) to the proximity with (local (especially beyond or opposed to) or causal (on account of) a primary preposition;', 'above, against, among, at, before, by, contrary to, X friend, from, + give (such things as they), + that (she) had, X his, in, more than, nigh unto, (out) of, past, save, side…by, in the sight of, than, (there-)fore, with', null),
  ('G3880', 'greek', 'παραλαμβάνω', 'paralambánō', null, 'to receive near, i.e. associate with oneself (in any familiar or intimate act or relation); by analogy, to assume an office; figuratively, to learn from G3844 (παρά) and G2983 (λαμβάνω);', 'receive, take (unto, with)', null),
  ('G3954', 'greek', 'παῤῥησία', 'parrhēsía', null, 'all out-spokenness, i.e. frankness, bluntness, publicity; by implication, assurance from G3956 (πᾶς) and a derivative of G4483 (ῥέω);', 'bold (X -ly, -ness, -ness of speech), confidence, X freely, X openly, X plainly(-ness)', null),
  ('G3956', 'greek', 'πᾶς', 'pâs', null, 'all, any, every, the whole including all the forms of declension; apparently a primary word;', 'all (manner of, means), alway(-s), any (one), X daily, + ever, every (one, way), as many as, + no(-thing), X thoroughly, whatsoever, whole, whosoever', null),
  ('G3962', 'greek', 'πατήρ', 'patḗr', null, 'a "father" (literally or figuratively, near or more remote) apparently a primary word;', 'father, parent', null),
  ('G3992', 'greek', 'πέμπω', 'pémpō', null, 'to dispatch (from the subjective view or point of departure, whereas (as a stronger form of ) refers rather to the objective point or terminus ad quem, and G4724 (στέλλω) denotes properly, the orderly motion involved), especially on a temporary errand; also to transmit, bestow, or wield apparently a primary verb;', 'send, thrust in', null),
  ('G4006', 'greek', 'πεποίθησις', 'pepoíthēsis', null, 'reliance from the perfect of the alternate of G3958 (πάσχω);', 'confidence, trust', null),
  ('G4008', 'greek', 'πέραν', 'péran', null, 'through (as adverb or preposition), i.e. across apparently accusative case of an obsolete derivative of (to "pierce");', 'beyond, farther (other) side, over', null),
  ('G4012', 'greek', 'περί', 'perí', null, 'properly, through (all over), i.e. around; figuratively with respect to; used in various applications, of place, cause or time (with the genitive case denoting the subject or occasion or superlative point; with the accusative case the locality, circuit, matter, circumstance or general period) from the base of G4008 (πέραν);', '(there-)about, above, against, at, on behalf of, X and his company, which concern, (as) concerning, for, X how it will go with, ((there-, where-)) of, on, over, pertaining (to), for sake, X (e-)state, (as) touching, (where-)by (in), with', null),
  ('G4014', 'greek', 'περιαιρέω', 'periairéō', null, 'to remove all around, i.e. unveil, cast off (anchor); figuratively, to expiate from G4012 (περί) and G138 (αἱρέομαι) (including its alternate);', 'take away (up)', null),
  ('G4043', 'greek', 'περιπατέω', 'peripatéō', null, 'to tread all around, i.e. walk at large (especially as proof of ability); figuratively, to live, deport oneself, follow (as a companion or votary) from G4012 (περί) and G3961 (πατέω);', 'go, be occupied with, walk (about)', null),
  ('G4052', 'greek', 'περισσεύω', 'perisseúō', null, 'to superabound (in quantity or quality), be in excess, be superfluous; also (transitively) to cause to superabound or excel from G4053 (περισσός);', '(make, more) abound, (have, have more) abundance (be more) abundant, be the better, enough and to spare, exceed, excel, increase, be left, redound, remain (over and above)', null),
  ('G4058', 'greek', 'περιστερά', 'peristerá', null, 'a pigeon of uncertain derivation;', 'dove, pigeon', null),
  ('G4074', 'greek', 'Πέτρος', 'Pétros', null, 'a (piece of) rock (larger than G3037 (λίθος)); as a name, Petrus, an apostle apparently a primary word;', 'Peter, rock', null),
  ('G4100', 'greek', 'πιστεύω', 'pisteúō', null, 'to have faith (in, upon, or with respect to, a person or thing), i.e. credit; by implication, to entrust (especially one''s spiritual well-being to Christ) from G4102 (πίστις);', 'believe(-r), commit (to trust), put in trust with', null),
  ('G4109', 'greek', 'πλάξ', 'pláx', null, 'a moulding-board, i.e. flat surface ("plate", or tablet, literally or figuratively) from G4111 (πλάσσω);', 'table', null),
  ('G4134', 'greek', 'πλήρης', 'plḗrēs', null, 'replete, or covered over; by analogy, complete from G4130 (πλήθω);', 'full', null),
  ('G4138', 'greek', 'πλήρωμα', 'plḗrōma', null, 'repletion or completion, i.e. (subjectively) what fills (as contents, supplement, copiousness, multitude), or (objectively) what is filled (as container, performance, period) from G4137 (πληρόω);', 'which is put in to fill up, piece that filled up, fulfilling, full, fulness', null),
  ('G4151', 'greek', 'πνεῦμα', 'pneûma', null, 'a current of air, i.e. breath (blast) or a breeze; by analogy or figuratively, a spirit, i.e. (human) the rational soul, (by implication) vital principle, mental disposition, etc., or (superhuman) an angel, demon, or (divine) God, Christ''s spirit, the Holy Spirit from G4154 (πνέω);', 'ghost, life, spirit(-ual, -ually), mind', 'Pneuma is the Greek word for breath, wind, or spirit — the same word used when God breathed life into Adam. You can’t see wind, but you feel it, and it moves everything it touches. Paul is saying God’s own breath, His living presence, is in you. Not a distant force. A Person, as close as the air in your lungs.'),
  ('G4159', 'greek', 'πόθεν', 'póthen', null, 'from which (as interrogative) or what (as relative) place, state, source or cause from the base of G4213 (πόσις) with enclitic adverb of origin;', 'whence', null),
  ('G4172', 'greek', 'πόλις', 'pólis', null, 'a town (properly, with walls, of greater or less size) probably from the same as G4171 (πόλεμος), or perhaps from G4183 (πολύς);', 'city', null),
  ('G4183', 'greek', 'πολύς', 'polýs', null, '(singular) much (in any respect) or (plural) many; neuter (singular) as adverbial, largely; neuter (plural) as adverb or noun often, mostly, largely including the forms from the alternate ;', 'abundant, + altogether, common, + far (passed, spent), (+ be of a) great (age, deal, -ly, while), long, many, much, oft(-en (-times)), plenteous, sore, straitly', null),
  ('G4226', 'greek', 'ποῦ', 'poû', null, 'as adverb of place; at (by implication, to) what locality genitive case of an interrogative pronoun (what) otherwise obsolete (perhaps the same as G4225 (πού) used with the rising slide of inquiry);', 'where, whither', null),
  ('G4253', 'greek', 'πρό', 'pró', null, '"fore", i.e. in front of, prior (figuratively, superior) to a primary preposition;', 'above, ago, before, or ever', null),
  ('G4314', 'greek', 'πρός', 'prós', null, 'a preposition of direction; forward to, i.e. toward (with the genitive case, the side of, i.e. pertaining to; with the dative case, by the side of, i.e. near to; usually with the accusative case, the place, time, occasion, or respect, which is the destination of the relation, i.e. whither or for which it is predicated) a strengthened form of G4253 (πρό);', 'about, according to , against, among, at, because of, before, between, (where-)by, for, X at thy house, in, for intent, nigh unto, of, which pertain to, that, to (the end that), X together, to (you) -ward, unto, with(-in)', null),
  ('G4383', 'greek', 'πρόσωπον', 'prósōpon', null, 'the front (as being towards view), i.e. the countenance, aspect, appearance, surface; by implication, presence, person from G4314 (πρός) and (the visage, from G3700 (ὀπτάνομαι));', '(outward) appearance, X before, countenance, face, fashion, (men''s) person, presence', null),
  ('G4396', 'greek', 'προφήτης', 'prophḗtēs', null, 'a foreteller ("prophet"); by analogy, an inspired speaker; by extension, a poet from a compound of G4253 (πρό) and G5346 (φημί);', 'prophet', null),
  ('G4413', 'greek', 'πρῶτος', 'prōtos', null, 'foremost (in time, place, order or importance) contracted superlative of G4253 (πρό);', 'before, beginning, best, chief(-est), first (of all), former', null),
  ('G4455', 'greek', 'πώποτε', 'pṓpote', null, 'at any time, i.e. (with negative particle) at no time from G4452 (-πω) and G4218 (ποτέ);', 'at any time, + never (…to any man), + yet, never man', null),
  ('G4456', 'greek', 'πωρόω', 'pōróō', null, 'to petrify, i.e. (figuratively) to indurate (render stupid or callous) apparently from (a kind of stone);', 'blind, harden', null),
  ('G4459', 'greek', 'πῶς', 'pōs', null, 'an interrogative particle of manner; in what way? (sometimes the question is indirect, how?); also as exclamation, how much! adverb from the base of G4226 (ποῦ);', 'how, after (by) what manner (means), that', null),
  ('G4461', 'greek', 'ῥαββί', 'rhabbí', null, 'my master, i.e Rabbi, as an official title of honor of Hebrew origin (H07227 with pronominal suffix);', 'Master, Rabbi', null),
  ('G4560', 'greek', 'σάρκινος', 'sárkinos', null, 'similar to flesh, i.e. (by analogy) soft from G4561 (σάρξ);', 'fleshly', null),
  ('G4561', 'greek', 'σάρξ', 'sárx', null, 'flesh (as stripped of the skin), i.e. (strictly) the meat of an animal (as food), or (by extension) the body (as opposed to the soul (or spirit), or as the symbol of what is external, or as the means of kindred), or (by implication) human nature (with its frailties (physically or morally) and passions), or (specially), a human being (as such) probably from the base of G4563 (σαρόω);', 'carnal(-ly, + -ly minded), flesh(-ly)', 'Sarx — flesh. Not "body" in a dignified, philosophical sense. This is meat, muscle, the part of you that gets tired and hungry and eventually dies. John chose the least elegant word available on purpose. God did not visit in a disguise. He became this.'),
  ('G4572', 'greek', 'σεαυτοῦ', 'seautoû', null, 'of (with, to) thyself genitive case from G4571 (σέ) and G846 (αὐτός), also dative case of the same, , and accusative case , likewise contracted , , and , respectively;', 'thee, thine own self, (thou) thy(-self)', null),
  ('G4594', 'greek', 'σήμερον', 'sḗmeron', null, 'on the (i.e. this) day (or night current or just passed); generally, now (i.e. at present, hitherto) neuter (as adverb) of a presumed compound of the article G3588 (ὁ) (t changed to s) and G2250 (ἡμέρα);', 'this (to-)day', null),
  ('G4613', 'greek', 'Σίμων', 'Símōn', null, 'Simon (i.e. Shimon), the name of nine Israelites of Hebrew origin (H08095);', 'Simon', null),
  ('G4637', 'greek', 'σκηνόω', 'skēnóō', null, 'to tent or encamp, i.e. (figuratively) to occupy (as a mansion) or (specially), to reside (as God did in the Tabernacle of old, a symbol of protection and communion) from G4636 (σκῆνος);', 'dwell', 'Literally "pitched a tent". It is the same word the Greek Old Testament uses for the tabernacle — the tent where God’s presence camped among the Israelites in the desert. John’s readers would have caught it instantly: God has moved back in, and this time the tent is a human being.'),
  ('G4653', 'greek', 'σκοτία', 'skotía', null, 'dimness, obscurity (literally or figuratively) from G4655 (σκότος);', 'dark(-ness)', null),
  ('G4762', 'greek', 'στρέφω', 'stréphō', null, 'to twist, i.e. turn quite around or reverse (literally or figuratively) strengthened from the base of G5157 (τροπή);', 'convert, turn (again, back again, self, self about)', null),
  ('G4771', 'greek', 'σύ', 'sý', null, 'thou the personal pronoun of the second person singular;', 'thou', null),
  ('G4808', 'greek', 'συκῆ', 'sykē', null, 'a fig-tree from G4810 (σῦκον);', 'fig tree', null),
  ('G4956', 'greek', 'συστατικός', 'systatikós', null, 'introductory, i.e. recommendatory from a derivative of G4921 (συνιστάω);', 'of commendation', null),
  ('G5043', 'greek', 'τέκνον', 'téknon', null, 'a child (as produced) from the base of G5098 (τιμωρία);', 'child, daughter, son', null),
  ('G5056', 'greek', 'τέλος', 'télos', null, 'properly, the point aimed at as a limit, i.e. (by implication) the conclusion of an act or state (termination (literally, figuratively or indefinitely), result (immediate, ultimate or prophetic), purpose); specially, an impost or levy (as paid) from a primary (to set out for a definite point or goal);', '+ continual, custom, end(-ing), finally, uttermost', null),
  ('G5087', 'greek', 'τίθημι', 'títhēmi', null, 'to place (in the widest application, literally and figuratively; properly, in a passive or horizontal posture, and thus different from G2476 (ἵστημι), which properly denotes an upright and active position, while G2749 (κεῖμαι) is properly reflexive and utterly prostrate) a prolonged form of a primary (which is used only as alternate in certain tenses);', '+ advise, appoint, bow, commit, conceive, give, X kneel down, lay (aside, down, up), make, ordain, purpose, put, set (forth), settle, sink down', null),
  ('G5100', 'greek', 'τὶς', 'tìs', null, 'some or any person or object an enclitic indefinite pronoun;', 'a (kind of), any (man, thing, thing at all), certain (thing), divers, he (every) man, one (X thing), ought, + partly, some (man, -body, - thing, -what), (+ that no-)thing, what(-soever), X wherewith, whom(-soever), whose(-soever)', null),
  ('G5101', 'greek', 'τίς', 'tís', null, 'an interrogative pronoun, who, which or what (in direct or indirect questions) probably emphatic of G5100 (τὶς);', 'every man, how (much), + no(-ne, thing), what (manner, thing), where (-by, -fore, -of, -unto, - with, -withal), whether, which, who(-m, -se), why', null),
  ('G5108', 'greek', 'τοιοῦτος', 'toioûtos', null, 'truly this, i.e. of this sort (to denote character or individuality) (including the other inflections); from G5104 (τοί) and G3778 (οὗτος);', 'like, such (an one)', null),
  ('G5204', 'greek', 'ὕδωρ', 'hýdōr', null, 'water (as if rainy) literally or figuratively from the base of G5205 (ὑετός);', 'water', null),
  ('G5207', 'greek', 'υἱός', 'huiós', null, 'a "son" (sometimes of animals), used very widely of immediate, remote or figuratively, kinship apparently a primary word;', 'child, foal, son', null),
  ('G5228', 'greek', 'ὑπέρ', 'hypér', null, '"over", i.e. (with the genitive case) of place, above, beyond, across, or causal, for the sake of, instead, regarding; with the accusative case superior to, more than a primary preposition;', '(+ exceeding, abundantly) above, in (on) behalf of, beyond, by, + very chiefest, concerning, exceeding (above, -ly), for, + very highly, more (than), of, over, on the part of, for sake of, in stead, than, to(-ward), very', null),
  ('G5235', 'greek', 'ὑπερβάλλω', 'hyperbállō', null, 'to throw beyod the usual mark, i.e. (figuratively) to surpass (only active participle supereminent) from G5228 (ὑπέρ) and G906 (βάλλω);', 'exceeding, excel, pass', null),
  ('G5259', 'greek', 'ὑπό', 'hypó', null, 'under, i.e. (with the genitive case) of place (beneath), or with verbs (the agency or means, through); (with the accusative case) of place (whither (underneath) or where (below) or time (when (at)) a primary preposition;', 'among, by, from, in, of, under, with', null),
  ('G5266', 'greek', 'ὑπόδημα', 'hypódēma', null, 'something bound under the feet, i.e. a shoe or sandal from G5265 (ὑποδέω);', 'shoe', null),
  ('G5270', 'greek', 'ὑποκάτω', 'hypokátō', null, 'down under, i.e. beneath from G5259 (ὑπό) and G2736 (κάτω);', 'under', null),
  ('G5316', 'greek', 'φαίνω', 'phaínō', null, 'to lighten (shine), i.e. show (transitive or intransitive, literal or figurative) prolongation for the base of G5457 (φῶς);', 'appear, seem, be seen, shine, X think', null),
  ('G5319', 'greek', 'φανερόω', 'phaneróō', null, 'to render apparent (literally or figuratively) from G5318 (φανερός);', 'appear, manifestly declare, (make) manifest (forth), shew (self)', null),
  ('G5330', 'greek', 'Φαρισαῖος', 'Pharisaîos', null, 'a separatist, i.e. exclusively religious; a Pharisean, i.e. Jewish sectary of Hebrew origin (compare H06567);', 'Pharisee', null),
  ('G5346', 'greek', 'φημί', 'phēmí', null, 'to show or make known one''s thoughts, i.e. speak or say properly, the same as the base of G5457 (φῶς) and G5316 (φαίνω);', 'affirm, say', null),
  ('G5376', 'greek', 'Φίλιππος', 'Phílippos', null, 'fond of horses; Philippus, the name of four Israelites from G5384 (φίλος) and G2462 (ἵππος);', 'Philip', null),
  ('G5455', 'greek', 'φωνέω', 'phōnéō', null, 'to emit a sound (animal, human or instrumental); by implication, to address in words or by name, also in imitation from G5456 (φωνή);', 'call (for), crow, cry', null),
  ('G5456', 'greek', 'φωνή', 'phōnḗ', null, 'a tone (articulate, bestial or artificial); by implication, an address (for any purpose), saying or language probably akin to G5316 (φαίνω) through the idea of disclosure;', 'noise, sound, voice', null),
  ('G5457', 'greek', 'φῶς', 'phōs', null, 'compare G5316 (φαίνω), G5346 (φημί)); luminousness (in the widest application, natural or artificial, abstract or concrete, literal or figurative) from an obsolete (to shine or make manifest, especially by rays;', 'fire, light', 'Light, in John, is never only illumination — it is exposure and it is life. Things grow in it and things are seen truly by it. When he says the light shines in the darkness, he means both: something is being revealed, and something is being made alive.'),
  ('G5461', 'greek', 'φωτίζω', 'phōtízō', null, 'to shed rays, i.e. to shine or (transitively) to brighten up (literally or figuratively) from G5457 (φῶς);', 'enlighten, illuminate, (bring to, give) light, make to see', null),
  ('G5485', 'greek', 'χάρις', 'cháris', null, 'graciousness (as gratifying), of manner or act (abstract or concrete; literal, figurative or spiritual; especially the divine influence upon the heart, and its reflection in the life; including gratitude) from G5463 (χαίρω);', 'acceptable, benefit, favour, gift, grace(- ious), joy, liberality, pleasure, thank(-s, -worthy)', null),
  ('G5530', 'greek', 'χράομαι', 'chráomai', null, 'to furnish what is needed; (give an oracle, "graze" (touch slightly), light upon, etc.), i.e. (by implication) to employ or (by extension) to act towards one in a given manner middle voice of a primary verb (perhaps rather from G5495 (χείρ), to handle);', 'entreat, use', null),
  ('G5535', 'greek', 'χρῄζω', 'chrḗizō', null, 'to make (i.e. have) necessity, i.e. be in want of from G5532 (χρεία);', '(have) need', null),
  ('G5547', 'greek', 'Χριστός', 'Christós', null, 'anointed, i.e. the Messiah, an epithet of Jesus from G5548 (χρίω);', 'Christ', null),
  ('G5565', 'greek', 'χωρίς', 'chōrís', null, 'at a space, i.e. separately or apart from (often as preposition) adverb from G5561 (χώρα);', 'beside, by itself, without', null),
  ('G5610', 'greek', 'ὥρα', 'hṓra', null, 'an "hour" (literally or figuratively) apparently a primary word;', 'day, hour, instant, season, X short, (even-)tide, (high) time', null),
  ('G5613', 'greek', 'ὡς', 'hōs', null, 'which how, i.e. in that manner (very variously used, as follows) probably adverb of comparative from G3739 (ὅς);', 'about, after (that), (according) as (it had been, it were), as soon (as), even as (like), for, how (greatly), like (as, unto), since, so (that), that, to wit, unto, when(-soever), while, X with all speed', null),
  ('G5620', 'greek', 'ὥστε', 'hṓste', null, 'so too, i.e. thus therefore (in various relations of consecution, as follow) from G5613 (ὡς) and G5037 (τέ);', '(insomuch) as, so that (then), (insomuch) that, therefore, to, wherefore', null),
  ('H0120', 'hebrew', 'אָדָם', 'ʼâdâm', 'aw-dawm''', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) from H119 (אָדַם);', '[idiom] another, [phrase] hypocrite, [phrase] common sort, [idiom] low, man (mean, of low degree), person.', null),
  ('H0127', 'hebrew', 'אֲדָמָה', 'ʼădâmâh', 'ad-aw-maw''', 'soil (from its general redness) from H119 (אָדַם);', 'country, earth, ground, husband(-man) (-ry), land.', null),
  ('H0215', 'hebrew', 'אוֹר', 'ʼôwr', 'ore', 'to be (causative, make) luminous (literally and metaphorically) a primitive root;', '[idiom] break of day, glorious, kindle, (be, en-, give, show) light (-en, -ened), set on fire, shine.', null),
  ('H0216', 'hebrew', 'אוֹר', 'ʼôwr', 'ore', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) from H215 (אוֹר);', 'bright, clear, [phrase] day, light (-ning), morning, sun.', null),
  ('H0226', 'hebrew', 'אוֹת', 'ʼôwth', 'oth', 'a signal (literally or figuratively), as aflag, beacon, monument, omen, prodigy, evidence, etc. probably from H225 (אוּת) (in the sense of appearing);', 'mark, miracle, (en-) sign, token.', null),
  ('H0259', 'hebrew', 'אֶחָד', 'ʼechâd', 'ekh-awd''', 'properly, united, i.e. one; or (as an ordinal) first a numeral from H258 (אָחַד);', 'a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), [phrase] eleven, every, few, first, [phrase] highway, a man, once, one, only, other, some, together,', null),
  ('H0389', 'hebrew', 'אַךְ', 'ʼak', 'ak', 'a particle of affirmation, surely; hence (by limitation) only akin to H403 (אָכֵן);', 'also, in any wise, at least, but, certainly, even, howbeit, nevertheless, notwithstanding, only, save, surely, of a surety, truly, verily, [phrase] wherefore, yet (but).', null),
  ('H0402', 'hebrew', 'אׇכְלָה', 'ʼoklâh', 'ok-law''', 'food feminine of H401 (אֻכָל);', 'consume, devour, eat, food, meat.', null),
  ('H0413', 'hebrew', 'אֵל', 'ʼêl', 'ale', 'near, with or among; often in general, to (but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.', 'about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, [idiom] hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', null),
  ('H0430', 'hebrew', 'אֱלֹהִים', 'ʼĕlôhîym', 'el-o-heem''', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative plural of H433 (אֱלוֹהַּ);', 'angels, [idiom] exceeding, God (gods) (-dess, -ly), [idiom] (very) great, judges, [idiom] mighty.', 'Elohim is grammatically plural but takes singular verbs throughout Genesis 1 — a construction Hebrew uses for majesty rather than number. The very first name for God in the Bible is one that stretches the language it is written in.'),
  ('H0559', 'hebrew', 'אָמַר', 'ʼâmar', 'aw-mar''', 'to say (used with great latitude) a primitive root;', 'answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, [phrase] (at the, give) command(-ment), commune, consider, declare, demand, [idiom] desire, determine, [idiom] expressly, [idiom] indeed, [idiom] intend, name, [idiom] plainly, promise, publish, report, require, say, speak (against, of), [idiom] still, [idiom] suppose, talk, tell, term, [idiom] that is, [idiom] think, use (speech), utter, [idiom] verily, [idiom] yet.', null),
  ('H0753', 'hebrew', 'אֹרֶךְ', 'ʼôrek', 'o''rek''', 'length from H748 (אָרַךְ);', '[phrase] forever, length, long.', null),
  ('H0776', 'hebrew', 'אֶרֶץ', 'ʼerets', 'eh''-rets', 'the earth (at large, or partitively a land) from an unused root probably meaning to be firm;', '[idiom] common, country, earth, field, ground, land, [idiom] natins, way, [phrase] wilderness, world.', null),
  ('H0834', 'hebrew', 'אֲשֶׁר', 'ʼăsher', 'ash-er''', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. a primitive relative pronoun (of every gender and number);', '[idiom] after, [idiom] alike, as (soon as), because, [idiom] every, for, [phrase] forasmuch, [phrase] from whence, [phrase] how(-soever), [idiom] if, (so) that ((thing) which, wherein), [idiom] though, [phrase] until, [phrase] whatsoever, when, where ([phrase] -as, -in, -of, -on, -soever, -with), which, whilst, [phrase] whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', null),
  ('H0853', 'hebrew', 'אֵת', 'ʼêth', 'ayth', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) apparent contracted from H226 (אוֹת) in the demonstrative sense of entity;', '(as such unrepresented in English).', null),
  ('H0859', 'hebrew', 'אַתָּה', 'ʼattâh', 'at-taw''', 'thou and thee, or (plural) ye and you or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;', 'thee, thou, ye, you.', null),
  ('H0914', 'hebrew', 'בָּדַל', 'bâdal', 'baw-dal''', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) a primitive root;', '(make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), [idiom] utterly.', null),
  ('H0922', 'hebrew', 'בֹּהוּ', 'bôhûw', 'bo''-hoo', 'a vacuity, i.e. (superficially) an undistinguishable ruin from an unused root (meaning to be empty);', 'emptiness, void.', null),
  ('H0929', 'hebrew', 'בְּהֵמָה', 'bᵉhêmâh', 'be-hay-maw''', 'properly, a dumb beast; especially any large quadruped or animal (often collective) from an unused root (probably meaning to be mute);', 'beast, cattle.', null),
  ('H0996', 'hebrew', 'בֵּין', 'bêyn', 'bane', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or (sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from H995 (בִּין); a distinction; but used only as a preposition,', 'among, asunder, at, between (-twixt...and), [phrase] from (the widest), [idiom] in, out of, whether (it be...or), within.', null),
  ('H1004', 'hebrew', 'בַּיִת', 'bayith', 'bah''-yith', 'a house (in the greatest variation of applications, especially family, etc.) probably from H1129 (בָּנָה) abbreviated;', 'court, daughter, door, [phrase] dungeon, family, [phrase] forth of, [idiom] great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, [phrase] prison, [phrase] steward, [phrase] tablet, temple, web, [phrase] within(-out).', null),
  ('H1242', 'hebrew', 'בֹּקֶר', 'bôqer', 'bo''-ker', 'properly, dawn (as the break of day); generally, morning from H1239 (בָּקַר);', '([phrase]) day, early, morning, morrow.', null),
  ('H1254', 'hebrew', 'בָּרָא', 'bârâʼ', 'baw-raw''', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) a primitive root;', 'choose, create (creator), cut down, dispatch, do, make (fat).', 'Bara — to create. In the entire Hebrew Bible, this verb never takes a human subject. People make, form, build and shape; only God baras. The grammar quietly makes a claim before the theology does.'),
  ('H1288', 'hebrew', 'בָרַךְ', 'bârak', 'baw-rak''', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) a primitive root;', '[idiom] abundantly, [idiom] altogether, [idiom] at all, blaspheme, bless, congratulate, curse, [idiom] greatly, [idiom] indeed, kneel (down), praise, salute, [idiom] still, thank.', null),
  ('H1419', 'hebrew', 'גָּדוֹל', 'gâdôwl', 'gaw-dole''', 'great (in any sense); hence, older; also insolent or גָּדֹל; (shortened) from H1431 (גָּדַל);', '[phrase] aloud, elder(-est), [phrase] exceeding(-ly), [phrase] far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, [idiom] sore, ([idiom]) very.', null),
  ('H1516', 'hebrew', 'גַּיְא', 'gayʼ', 'gah''-ee', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) or (shortened) גַּי; probably (by transmutation) from the same root as H1466 (גֵּוָה) (abbreviated);', 'valley.', null),
  ('H1571', 'hebrew', 'גַּם', 'gam', 'gam', 'properly, assemblage; used only adverbially also, even, yea, though; often repeated as correl. both...and by contraction from an unused root meaning to gather;', 'again, alike, also, (so much) as (soon), both (so)...and, but, either...or, even, for all, (in) likewise (manner), moreover, nay...neither, one, then(-refore), though, what, with, yea.', null),
  ('H1710', 'hebrew', 'דָּגָה', 'dâgâh', 'daw-gaw''', '{a fish (often used collectively)} feminine of H1709 (דָּג), and meaning the same', 'fish.', null),
  ('H1732', 'hebrew', 'דָּוִד', 'Dâvid', 'daw-veed''', 'David, the youngest son of Jesse rarely (fully); דָּוִיד; from the same as H1730 (דּוֹד); loving;', 'David.', null),
  ('H1823', 'hebrew', 'דְּמוּת', 'dᵉmûwth', 'dem-ooth''', 'resemblance; concretely, model, shape; adverbially, like from H1819 (דָּמָה);', 'fashion, like (-ness, as), manner, similitude.', null),
  ('H1876', 'hebrew', 'דָּשָׁא', 'dâshâʼ', 'daw-shaw''', 'to sprout a primitive root;', 'bring forth, spring.', null),
  ('H1877', 'hebrew', 'דֶּשֶׁא', 'desheʼ', 'deh''-sheh', 'a sprout; by analogy, grass from H1876 (דָּשָׁא);', '(tender) grass, green, (tender) herb.', null),
  ('H1878', 'hebrew', 'דָּשֵׁן', 'dâshên', 'daw-shane''', 'to be fat; transitively, to fatten (or regard as fat); specifically to anoint; figuratively, to satisfy; to remove (fat) ashes (of sacrifices) a primitive root; also denominatively (from H1880 (דֶּשֶׁן))', 'accept, anoint, take away the (receive) ashes (from), make (wax) fat.', null),
  ('H1961', 'hebrew', 'הָיָה', 'hâyâh', 'haw-yaw', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) a primitive root (compare H1933 (הָוָא));', 'beacon, [idiom] altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, [phrase] follow, happen, [idiom] have, last, pertain, quit (one-) self, require, [idiom] use.', null),
  ('H1992', 'hebrew', 'הֵם', 'hêm', 'haym', 'they (only used when emphatic) or (prolonged) הֵמָּה; masculine plural from H1981 (הֲלַךְ);', 'it, like, [idiom] (how, so) many (soever, more as) they (be), (the) same, [idiom] so, [idiom] such, their, them, these, they, those, which, who, whom, withal, ye.', null),
  ('H2009', 'hebrew', 'הִנֵּה', 'hinnêh', 'hin-nay''', 'lo! prolongation for H2005 (הֵן);', 'behold, lo, see.', null),
  ('H2145', 'hebrew', 'זָכָר', 'zâkâr', 'zaw-kawr''', 'properly, remembered, i.e. a male (of man or animals, as being the most noteworthy sex) from H2142 (זָכַר);', '[idiom] him, male, man(child, -kind).', null),
  ('H2232', 'hebrew', 'זָרַע', 'zâraʻ', 'zaw-rah''', 'to sow; figuratively, to disseminate, plant, fructify a primitive root;', 'bear, conceive seed, set with sow(-er), yield.', null),
  ('H2233', 'hebrew', 'זֶרַע', 'zeraʻ', 'zeh''-rah', 'seed; figuratively, fruit, plant, sowing-time, posterity from H2232 (זָרַע);', '[idiom] carnally, child, fruitful, seed(-time), sowing-time.', null),
  ('H2416', 'hebrew', 'חַי', 'chay', 'khah''-ee', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively from H2421 (חָיָה);', '[phrase] age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, [phrase] merry, multitude, [phrase] (be) old, quick, raw, running, springing, troop.', null),
  ('H2549', 'hebrew', 'חֲמִישִׁי', 'chămîyshîy', 'kham-ee-shee''', 'fifth; also a fifth or חֲמִשִּׁי; ordinal from H2568 (חָמֵשׁ);', 'fifth (part).', null),
  ('H2617', 'hebrew', 'חֵסֵד', 'chêçêd', 'kheh''-sed', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty from H2616 (חָסַד);', 'favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'Chesed is one of the hardest words in the Hebrew Bible to translate — mercy, steadfast love, loyal kindness. It describes commitment that persists when the relationship gives it no reason to. English needs a phrase where Hebrew has a word.'),
  ('H2637', 'hebrew', 'חָסֵר', 'châçêr', 'khaw-sare''', 'to lack; by implication, to fail, want, lessen a primitive root;', 'be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want.', null),
  ('H2822', 'hebrew', 'חֹשֶׁךְ', 'chôshek', 'kho-shek''', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness from H2821 (חָשַׁךְ);', 'dark(-ness), night, obscurity.', null),
  ('H2896', 'hebrew', 'טוֹב', 'ṭôwb', 'tobe', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) from H2895 (טוֹב);', 'beautiful, best, better, bountiful, cheerful, at ease, [idiom] fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, [idiom] most, pleasant, [phrase] pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', null),
  ('H3004', 'hebrew', 'יַבָּשָׁה', 'yabbâshâh', 'yab-baw-shaw''', 'dry ground from H3001 (יָבֵשׁ);', 'dry (ground, land).', null),
  ('H3068', 'hebrew', 'יְהֹוָה', 'Yᵉhôvâh', 'yeh-ho-vaw''', 'Jehovah, Jewish national name of God from H1961 (הָיָה); (the) self-Existent or Eternal;', 'Jehovah, the Lord. Compare H3050 (יָהּ), H3069 (יְהֹוִה).', 'YHWH — the personal name God gives himself at the burning bush, so revered in Jewish tradition that it is not spoken aloud. English Bibles render it as LORD in small capitals. Every time you see that, this name is underneath it.'),
  ('H3117', 'hebrew', 'יוֹם', 'yôwm', 'yome', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) from an unused root meaning to be hot;', 'age, [phrase] always, [phrase] chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), [phrase] elder, [idiom] end, [phrase] evening, [phrase] (for) ever(-lasting, -more), [idiom] full, life, as (so) long as (... live), (even) now, [phrase] old, [phrase] outlived, [phrase] perpetually, presently, [phrase] remaineth, [idiom] required, season, [idiom] since, space, then, (process of) time, [phrase] as at other times, [phrase] in trouble, weather, (as) when, (a, the, within a) while (that), [idiom] whole ([phrase] age), (full) year(-ly), [phrase] younger.', null),
  ('H3212', 'hebrew', 'יָלַךְ', 'yâlak', 'yaw-lak''', 'to walk (literally or figuratively); causatively, to carry (in various senses) a primitive root (compare H1980 (הָלַךְ));', '[idiom] again, away, bear, bring, carry (away), come (away), depart, flow, [phrase] follow(-ing), get (away, hence, him), (cause to, made) go (away, -ing, -ne, one''s way, out), grow, lead (forth), let down, march, prosper, [phrase] pursue, cause to run, spread, take away (-journey), vanish, (cause to) walk(-ing), wax, [idiom] be weak.', null),
  ('H3220', 'hebrew', 'יָם', 'yâm', 'yawm', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south from an unused root meaning to roar;', 'sea ([idiom] -faring man, (-shore)), south, west (-ern, side, -ward).', null),
  ('H3318', 'hebrew', 'יָצָא', 'yâtsâʼ', 'yaw-tsaw''', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. a primitive root;', '[idiom] after, appear, [idiom] assuredly, bear out, [idiom] begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), [phrase] be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, [idiom] scarce, send with commandment, shoot forth, spread, spring out, stand out, [idiom] still, [idiom] surely, take fort…', null),
  ('H3372', 'hebrew', 'יָרֵא', 'yârêʼ', 'yaw-ray''', 'to fear; morally, to revere; caus. to frighten a primitive root;', 'affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), [idiom] see, terrible (act, -ness, thing).', null),
  ('H3418', 'hebrew', 'יֶרֶק', 'yereq', 'yeh''-rek', 'properly, pallor, i.e. hence, the yellowish green of young and sickly vegetation; concretely, verdure, i.e. grass or vegetation from H3417 (יָרָק) (in the sense of vacuity of color);', 'grass, green (thing).', null),
  ('H3427', 'hebrew', 'יָשַׁב', 'yâshab', 'yaw-shab''', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry a primitive root;', '(make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, [idiom] fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, [idiom] marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', null),
  ('H3533', 'hebrew', 'כָּבַשׁ', 'kâbash', 'kaw-bash''', 'to tread down; hence, negatively, to disregard; positively, to conquer, subjugate, violate a primitive root;', 'bring into bondage, force, keep under, subdue, bring into subjection.', null),
  ('H3556', 'hebrew', 'כּוֹכָב', 'kôwkâb', 'ko-kawb''', 'a star (as round or as shining); figuratively, a prince probably from the same as H3522 (כַּבּוֹן) (in the sense of rolling) or H3554 (כָּוָה) (in the sense of blazing);', 'star(-gazer).', null),
  ('H3563', 'hebrew', 'כּוֹס', 'kôwç', 'koce', 'a cup (as a container), often figuratively, a lot (as if a potion); also some unclean bird, probably an owl (perhaps from the cup-like cavity of its eye) from an unused root meaning to hold together;', 'cup, (small) owl. Compare H3599 (כִּיס).', null),
  ('H3588', 'hebrew', 'כִּי', 'kîy', 'kee', '(by implication) very widely used as a relative conjunction or adverb (as below); often largely modified by other particles annexed a primitive particle (the full form of the prepositional prefix) indicating causal relations of all kinds, antecedent or consequent;', 'and, + (forasmuch, inasmuch, where-) as, assured(-ly), + but, certainly, doubtless, + else, even, + except, for, how, (because, in, so, than) that, + nevertheless, now, rightly, seeing, since, surely, then, therefore, + (al-) though, + till, truly, + until, when, whether, while, whom, yea, yet.', null),
  ('H3605', 'hebrew', 'כֹּל', 'kôl', 'kole', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) or (Jeremiah 33:8) כּוֹל; from H3634 (כָּלַל);', '(in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', null),
  ('H3651', 'hebrew', 'כֵּן', 'kên', 'kane', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) from H3559 (כּוּן);', '[phrase] after that (this, -ward, -wards), as... as, [phrase] (for-) asmuch as yet, [phrase] be (for which) cause, [phrase] following, howbeit, in (the) like (manner, -wise), [idiom] the more, right, (even) so, state, straightway, such (thing), surely, [phrase] there (where) -fore, this, thus, true, well, [idiom] you.', null),
  ('H3671', 'hebrew', 'כָּנָף', 'kânâph', 'kaw-nawf''', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle from H3670 (כָּנַף);', '[phrase] bird, border, corner, end, feather(-ed), [idiom] flying, [phrase] (one an-) other, overspreading, [idiom] quarters, skirt, [idiom] sort, uttermost part, wing(-ed).', null),
  ('H3808', 'hebrew', 'לֹא', 'lôʼ', 'lo', 'not (the simple or abs. negation); by implication, no; often used with other particles or לוֹא; or לֹה; (Deuteronomy 3:11), a primitive particle;', '[idiom] before, [phrase] or else, ere, [phrase] except, ig(-norant), much, less, nay, neither, never, no((-ne), -r, (-thing)), ([idiom] as though...,(can-), for) not (out of), of nought, otherwise, out of, [phrase] surely, [phrase] as truly as, [phrase] of a truth, [phrase] verily, for want, [phrase] whether, without.', null),
  ('H3915', 'hebrew', 'לַיִל', 'layil', 'lah''-yil', 'properly, a twist (away of the light), i.e. night; figuratively, adversity or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as H3883 (לוּל);', '(mid-)night (season).', null),
  ('H3966', 'hebrew', 'מְאֹד', 'mᵉʼôd', 'meh-ode''', 'properly, vehemence, i.e. (with or without preposition) vehemently; by implication, wholly, speedily, etc. (often with other words as an intensive or superlative; especially when repeated) from the same as H181 (אוּד);', 'diligently, especially, exceeding(-ly), far, fast, good, great(-ly), [idiom] louder and louder, might(-ily, -y), (so) much, quickly, (so) sore, utterly, very ([phrase] much, sore), well.', null),
  ('H3974', 'hebrew', 'מָאוֹר', 'mâʼôwr', 'maw-ore''', 'properly, a luminous body or luminary, i.e. (abstractly) light (as an element); figuratively, brightness, i.e.cheerfulness; specifically, a chandelier or מָאֹר; also (in plural) feminine מְאוֹרָה; or מְאֹרָה; from H215 (אוֹר);', 'bright, light.', null),
  ('H4150', 'hebrew', 'מוֹעֵד', 'môwʻêd', 'mo-ade''', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally ayear; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from H3259 (יָעַד);', 'appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', null),
  ('H4210', 'hebrew', 'מִזְמוֹר', 'mizmôwr', 'miz-more''', 'properly, instrumental music; by implication, a poem set to notes from H2167 (זָמַר);', 'psalm.', null),
  ('H4325', 'hebrew', 'מַיִם', 'mayim', 'mah''-yim', 'water; figuratively, juice; by euphemism, urine, semen dual of a primitive noun (but used in a singular sense);', '[phrase] piss, wasting, water(-ing, (-course, -flood, -spring)).', null),
  ('H4327', 'hebrew', 'מִין', 'mîyn', 'meen', 'a sort, i.e. species from an unused root meaning to portion out;', 'kind. Compare H4480 (מִן).', null),
  ('H4390', 'hebrew', 'מָלֵא', 'mâlêʼ', 'maw-lay''', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) or מָלָא; (Esther 7:5), a primitive root;', 'accomplish, confirm, [phrase] consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, [idiom] draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, [phrase] have wholly.', null),
  ('H4475', 'hebrew', 'מֶמְשָׁלָה', 'memshâlâh', 'mem-shaw-law''', 'rule; also (concretely in plural) a realm or a ruler feminine of H4474 (מִמְשָׁל);', 'dominion, government, power, to rule.', null),
  ('H4496', 'hebrew', 'מְנוּחָה', 'mᵉnûwchâh', 'men-oo-khaw''', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode or מְנֻחָה; feminine of H4495 (מָנוֹחַ);', 'comfortable, ease, quiet, rest(-ing place), still.', null),
  ('H4570', 'hebrew', 'מַעְגָּל', 'maʻgâl', 'mah-gawl''', 'a track (literally or figuratively); also a rampart (as circular) or feminine מַעְגָּלָה; from the same as H5696 (עָגֹל);', 'going, path, trench, way(-side).', null),
  ('H4616', 'hebrew', 'מַעַן', 'maʻan', 'mah''-an', 'properly, heed, i.e. purpose; used only adverbially, on account of (as a motive or an aim), teleologically, in order that from H6030 (עָנָה);', 'because of, to the end (intent) that, for (to,... ''s sake), [phrase] lest, that, to.', null),
  ('H4723', 'hebrew', 'מִקְוֶה', 'miqveh', 'mik-veh''', 'something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove or מִקְוֵה; (1 Kings 10:28), or מִקְוֵאlemma מִּקְוֵא extra dagesh, corrected to מִקְוֵא; (2 Chronicles 1:16), from H6960 (קָוָה);', 'abiding, gathering together, hope, linen yarn, plenty (of water), pool.', null),
  ('H4725', 'hebrew', 'מָקוֹם', 'mâqôwm', 'maw-kome''', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from H6965 (קוּם);', 'country, [idiom] home, [idiom] open, place, room, space, [idiom] whither(-soever).', null),
  ('H4910', 'hebrew', 'מָשַׁל', 'mâshal', 'maw-shal''', 'to rule a primitive root;', '(have, make to have) dominion, governor, [idiom] indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', null),
  ('H4938', 'hebrew', 'מִשְׁעֵנָה', 'mishʻênâh', 'mish-ay-naw''', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick or מִשְׁעֶנֶת; feminine of H4937 (מִשְׁעֵן);', 'staff.', null),
  ('H4999', 'hebrew', 'נָאָה', 'nâʼâh', 'naw-aw''', 'a home; figuratively, a pasture from H4998 (נָאָה);', 'habitation, house, pasture, pleasant place.', null),
  ('H5048', 'hebrew', 'נֶגֶד', 'neged', 'neh''-ghed', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before from H5046 (נָגַד);', 'about, (over) against, [idiom] aloof, [idiom] far (off), [idiom] from, over, presence, [idiom] other side, sight, [idiom] to view.', null),
  ('H5095', 'hebrew', 'נָהַל', 'nâhal', 'naw-hal''', 'properly, to run with asparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain a primitive root;', 'carry, feed, guide, lead (gently, on).', null),
  ('H5148', 'hebrew', 'נָחָה', 'nâchâh', 'naw-khaw''', 'to guide; by implication, to transport (into exile, or as colonists) a primitive root;', 'bestow, bring, govern, guide, lead (forth), put, straiten.', null),
  ('H5162', 'hebrew', 'נָחַם', 'nâcham', 'naw-kham''', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) a primitive root;', 'comfort (self), ease (one''s self), repent(-er,-ing, self).', null),
  ('H5315', 'hebrew', 'נֶפֶשׁ', 'nephesh', 'neh''-fesh', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) from H5314 (נָפַשׁ);', 'any, appetite, beast, body, breath, creature, [idiom] dead(-ly), desire, [idiom] (dis-) contented, [idiom] fish, ghost, [phrase] greedy, he, heart(-y), (hath, [idiom] jeopardy of) life ([idiom] in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, [phrase] slay, soul, [phrase] tablet, they, thing, ([idiom] she) will, [idiom] would have it.', null),
  ('H5347', 'hebrew', 'נְקֵבָה', 'nᵉqêbâh', 'nek-ay-baw''', 'female (from the sexual form) from H5344 (נָקַב);', 'female.', null),
  ('H5414', 'hebrew', 'נָתַן', 'nâthan', 'naw-than''', 'to give, used with greatest latitude of application (put, make, etc.) a primitive root;', 'add, apply, appoint, ascribe, assign, [idiom] avenge, [idiom] be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, [phrase] cry, deliver (up), direct, distribute, do, [idiom] doubtless, [idiom] without fail, fasten, frame, [idiom] get, give (forth, over, up), grant, hang (up), [idiom] have, [idiom] indeed, lay (unto charge, up), (give) leave, lend, let (out), [phrase] lie, lift up, make, [phrase] O that, occupy, offer, ordain, pay, perform, place, pour, print, [idiom] pull, put (forth), recompense, render, requite, restore, send (out), set (forth), s…', null),
  ('H5774', 'hebrew', 'עוּף', 'ʻûwph', 'oof', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) a primitive root; to cover (with wings or obscurity); hence (as denominative from H5775 (עוֹף))', 'brandish, be (wax) faint, flee away, fly (away), [idiom] set, shine forth, weary.', null),
  ('H5775', 'hebrew', 'עוֹף', 'ʻôwph', 'ofe', 'a bird (as covered with feathers, or rather as covering with wings), often collectively from H5774 (עוּף);', 'bird, that flieth, flying, fowl.', null),
  ('H5921', 'hebrew', 'עַל', 'ʻal', 'al', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications properly, the same as H5920 (עַל) used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);', 'above, according to(-ly), after, (as) against, among, and, [idiom] as, at, because of, beside (the rest of), between, beyond the time, [idiom] both and, by (reason of), [idiom] had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, [idiom] with.', null),
  ('H5978', 'hebrew', 'עִמָּד', 'ʻimmâd', 'im-mawd''', 'along with prolonged for H5973 (עִם);', 'against, by, from, [phrase] me, [phrase] mine, of, [phrase] that I take, unto, upon, with(-in.)', null),
  ('H6086', 'hebrew', 'עֵץ', 'ʻêts', 'ates', 'a tree (from its firmness); hence, wood (plural sticks) from H6095 (עָצָה);', '[phrase] carpenter, gallows, helve, [phrase] pine, plank, staff, stalk, stick, stock, timber, tree, wood.', null),
  ('H6153', 'hebrew', 'עֶרֶב', 'ʻereb', 'eh''-reb', 'dusk from H6150 (עָרַב);', '[phrase] day, even(-ing, tide), night.', null),
  ('H6186', 'hebrew', 'עָרַךְ', 'ʻârak', 'aw-rak''', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) a primitive root;', 'put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', null),
  ('H6212', 'hebrew', 'עֶשֶׂב', 'ʻeseb', 'eh''seb', 'grass (or any tender shoot) from an unused root meaning to glisten (or be green);', 'grass, herb.', null),
  ('H6213', 'hebrew', 'עָשָׂה', 'ʻâsâh', 'aw-saw''', 'to do or make, in the broadest sense and widest application a primitive root;', 'accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, [idiom] certainly, have the charge of, commit, deal (with), deck, [phrase] displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, [phrase] feast, (fight-) ing man, [phrase] finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, [phrase] hinder, hold (a feast), [idiom] indeed, [phrase] be industrious, [phrase] journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, [phrase] officer, pare, bring (come) to pass, perform, praci…', null),
  ('H6440', 'hebrew', 'פָּנִים', 'pânîym', 'paw-neem''', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) plural (but always as singular) of an unused noun פָּנֶה; from H6437 (פָּנָה));', '[phrase] accept, a-(be-) fore(-time), against, anger, [idiom] as (long as), at, [phrase] battle, [phrase] because (of), [phrase] beseech, countenance, edge, [phrase] employ, endure, [phrase] enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, [idiom] him(-self), [phrase] honourable, [phrase] impudent, [phrase] in, it, look(-eth) (-s), [idiom] me, [phrase] meet, [idiom] more than, mouth, of, off, (of) old (time), [idiom] on, open, [phrase] out of, over against, the partial, person, [phrase] please, presence, propect, was purposed, by reason of,…', null),
  ('H6509', 'hebrew', 'פָּרָה', 'pârâh', 'paw-raw''', 'to bear fruit (literally or figuratively) a primitive root;', 'bear, bring forth (fruit), (be, cause to be, make) fruitful, grow, increase.', null),
  ('H6529', 'hebrew', 'פְּרִי', 'pᵉrîy', 'per-ee''', 'fruit (literally or figuratively) from H6509 (פָּרָה);', 'bough, (first-)fruit(-ful), reward.', null),
  ('H6664', 'hebrew', 'צֶדֶק', 'tsedeq', 'tseh''-dek', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity from H6663 (צָדַק);', '[idiom] even, ([idiom] that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', null),
  ('H6754', 'hebrew', 'צֶלֶם', 'tselem', 'tseh''-lem', 'a phantom, i.e. (figuratively) illusion, resemblance; hence, a representative figure, especially an idol from an unused root meaning to shade;', 'image, vain shew.', null),
  ('H6757', 'hebrew', 'צַלְמָוֶת', 'tsalmâveth', 'tsal-maw''-veth', 'shade of death, i.e. the grave (figuratively, calamity) from H6738 (צֵל) and H4194 (מָוֶת);', 'shadow of death.', 'Tsalmavet — usually translated "shadow of death", and possibly built from the words for shadow and death. Whether or not the etymology holds, the sense is the same: the darkest ravine on the route, the place where you cannot see what is ahead.'),
  ('H6887', 'hebrew', 'צָרַר', 'tsârar', 'tsaw-rar''', 'to cramp, literally or figuratively, transitive or intransitive a primitive root;', 'adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', null),
  ('H6960', 'hebrew', 'קָוָה', 'qâvâh', 'kaw-vaw''', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect a primitive root;', 'gather (together), look, patiently, tarry, wait (for, on, upon).', null),
  ('H6996', 'hebrew', 'קָטָן', 'qâṭân', 'kaw-tawn''', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) or קָטֹן; from H6962 (קוּט);', 'least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', null),
  ('H7121', 'hebrew', 'קָרָא', 'qârâʼ', 'kaw-raw''', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) a primitive root (rather identical with H7122 (קָרָא) through the idea of accosting a person met);', 'bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', null),
  ('H7200', 'hebrew', 'רָאָה', 'râʼâh', 'raw-aw''', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) a primitive root;', 'advise self, appear, approve, behold, [idiom] certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, [idiom] indeed, [idiom] joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, [idiom] be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), [idiom] sight of others, (e-) spy, stare, [idiom] surely, [idiom] think, view, visions.', null),
  ('H7218', 'hebrew', 'רֹאשׁ', 'rôʼsh', 'roshe', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) from an unused root apparently meaning to shake;', 'band, beginning, captain, chapiter, chief(-est place, man, things), company, end, [idiom] every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), [idiom] lead, [idiom] poor, principal, ruler, sum, top.', null),
  ('H7225', 'hebrew', 'רֵאשִׁית', 'rêʼshîyth', 'ray-sheeth''', 'the first, in place, time, order or rank (specifically, a firstfruit) from the same as H7218 (רֹאשׁ);', 'beginning, chief(-est), first(-fruits, part, time), principal thing.', '"Reshit" means the first, the beginning, the choicest part of something. It is the same word used for the first fruits of a harvest. There is a hint in it that the beginning was not merely earliest, but best.'),
  ('H7235', 'hebrew', 'רָבָה', 'râbâh', 'raw-baw''', 'to increase (in whatever respect) a primitive root;', '(bring in) abundance ([idiom] -antly), [phrase] archer (by mistake for H7232 (רָבַב)), be in authority, bring up, [idiom] continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, [idiom] -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), [idiom] process (of time), sore, store, thoroughly, very.', null),
  ('H7243', 'hebrew', 'רְבִיעִי', 'rᵉbîyʻîy', 'reb-ee-ee''', 'fourth; also (fractionally) a fourth or רְבִעִי; from H7251 (רָבַע);', 'foursquare, fourth (part).', null),
  ('H7257', 'hebrew', 'רָבַץ', 'râbats', 'raw-bats''', 'to crouch (on all four legs folded, like a recumbent animal); be implication, to recline, repose, brood, lurk, imbed a primitive root;', 'crouch (down), fall down, make a fold, lay, (cause to, make to) lie (down), make to rest, sit.', null),
  ('H7287', 'hebrew', 'רָדָה', 'râdâh', 'raw-daw''', 'to tread down, i.e. subjugate; specifically, to crumble off a primitive root;', '(come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', null),
  ('H7291', 'hebrew', 'רָדַף', 'râdaph', 'raw-daf''', 'to run after (usually with hostile intent; figuratively (of time) gone by) a primitive root;', 'chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', null),
  ('H7307', 'hebrew', 'רוּחַ', 'rûwach', 'roo''-akh', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) from H7306 (רוּחַ);', 'air, anger, blast, breath, [idiom] cool, courage, mind, [idiom] quarter, [idiom] side, spirit(-ual), tempest, [idiom] vain, (whirl-) wind(-y).', null),
  ('H7310', 'hebrew', 'רְוָיָה', 'rᵉvâyâh', 'rev-aw-yaw''', 'satisfaction from H7301 (רָוָה);', 'runneth over, wealthy.', null),
  ('H7363', 'hebrew', 'רָחַף', 'râchaph', 'raw-khaf''', 'to brood; by implication, to be relaxed a primitive root;', 'flutter, move, shake.', null),
  ('H7430', 'hebrew', 'רָמַשׂ', 'râmas', 'raw-mas''', 'properly, to glide swiftly, i.e. to crawl or move with short steps; by analogy to swarm a primitive root;', 'creep, move.', null),
  ('H7431', 'hebrew', 'רֶמֶשׂ', 'remes', 'reh''-mes', 'a reptile or any other rapidly moving animal from H7430 (רָמַשׂ);', 'that creepeth, creeping (moving) thing.', null),
  ('H7451', 'hebrew', 'רַע', 'raʻ', 'rah', 'bad or (as noun) evil (natural or moral) from H7489 (רָעַע);', 'adversity, affliction, bad, calamity, [phrase] displease(-ure), distress, evil((-favouredness), man, thing), [phrase] exceedingly, [idiom] great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), [phrase] mark, mischief(-vous), misery, naught(-ty), noisome, [phrase] not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', null),
  ('H7462', 'hebrew', 'רָעָה', 'râʻâh', 'raw-aw''', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) a primitive root;', '[idiom] break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, [phrase] shearing house, shepherd, wander, waste.', 'Ro’eh — shepherd. David is not reaching for a soft image; he had done the job. It meant sleeping outside, fighting off predators and counting animals in the dark. When he calls God his shepherd he is describing someone who works hard on his behalf.'),
  ('H7549', 'hebrew', 'רָקִיעַ', 'râqîyaʻ', 'raw-kee''-ah', 'properly, an expanse, i.e. the firmament or (apparently) visible arch of the sky from H7554 (רָקַע);', 'firmament.', null),
  ('H7626', 'hebrew', 'שֵׁבֶט', 'shêbeṭ', 'shay''-bet', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan from an unused root probably meaning to branch off;', '[idiom] correction, dart, rod, sceptre, staff, tribe.', null),
  ('H7725', 'hebrew', 'שׁוּב', 'shûwb', 'shoob', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again a primitive root;', '((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) [idiom] again, (cause to) answer ([phrase] again), [idiom] in any case (wise), [idiom] at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, [idiom] certainly, come again (back), [idiom] consider, [phrase] continually, convert, deliver (again), [phrase] deny, draw back, fetch home again, [idiom] fro, get (oneself) (back) again, [idiom] give (again), go again (back, home), (go) out, hinder, let, (see) more, [idiom] needs, be past, [idio…', null),
  ('H7979', 'hebrew', 'שֻׁלְחָן', 'shulchân', 'shool-khawn''', 'a table (as spread out); by implication, a meal from H7971 (שָׁלַח);', 'table.', null),
  ('H7992', 'hebrew', 'שְׁלִישִׁי', 'shᵉlîyshîy', 'shel-ee-shee''', 'third; feminine athird (part); by extension, a third (day, year or time); specifically, a third-story cell) ordinal from H7969 (שָׁלוֹשׁ);', 'third (part, rank, time), three (years old).', null),
  ('H8034', 'hebrew', 'שֵׁם', 'shêm', 'shame', 'an appellation, as amark or memorial of individuality; by implication honor, authority, character a primitive word (perhaps rather from through the idea of definite and conspicuous position; compare H8064 (שָׁמַיִם));', '[phrase] base, (in-) fame(-ous), named(-d), renown, report.', null),
  ('H8064', 'hebrew', 'שָׁמַיִם', 'shâmayim', 'shaw-mah''-yim', 'the sky (as aloft; the dual perhaps alluding to the visible arch in which the clouds move, as well as to the higher ether where the celestial bodies revolve) dual of an unused singular שָׁמֶה; from an unused root meaning to be lofty;', 'air, [idiom] astrologer, heaven(-s).', null),
  ('H8081', 'hebrew', 'שֶׁמֶן', 'shemen', 'sheh''-men', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness from H8080 (שָׁמַן);', 'anointing, [idiom] fat (things), [idiom] fruitful, oil(-ed), ointment, olive, [phrase] pine.', null),
  ('H8141', 'hebrew', 'שָׁנֶה', 'shâneh', 'shaw-neh''', 'a year (as a revolution of time) (in plural or (feminine) שָׁנָה; from H8138 (שָׁנָה);', '[phrase] whole age, [idiom] long, [phrase] old, year([idiom] -ly).', null),
  ('H8145', 'hebrew', 'שֵׁנִי', 'shênîy', 'shay-nee''', 'properly, double, i.e. second; also adverbially, again from H8138 (שָׁנָה);', 'again, either (of them), (an-) other, second (time).', null),
  ('H8147', 'hebrew', 'שְׁנַיִם', 'shᵉnayim', 'shen-ah''-yim', 'two; also (as ordinal) twofold dual of H8145 (שֵׁנִי); feminine שְׁתַּיִם;', 'both, couple, double, second, twain, [phrase] twelfth, [phrase] twelve, [phrase] twenty (sixscore) thousand, twice, two.', null),
  ('H8317', 'hebrew', 'שָׁרַץ', 'shârats', 'shaw-rats''', 'to wriggle, i.e. (by implication) swarm or abound a primitive root;', 'breed (bring forth, increase) abundantly (in abundance), creep, move.', null),
  ('H8318', 'hebrew', 'שֶׁרֶץ', 'sherets', 'sheh''-rets', 'a swarm, i.e. active mass of minute animals from H8317 (שָׁרַץ);', 'creep(-ing thing), move(-ing creature).', null),
  ('H8345', 'hebrew', 'שִׁשִּׁי', 'shishshîy', 'shish-shee''', 'sixth, ord. or (feminine) fractional from H8337 (שֵׁשׁ);', 'sixth (part).', null),
  ('H8414', 'hebrew', 'תֹּהוּ', 'tôhûw', 'to''-hoo', 'a desolation (of surface), i.e. desert; figuratively, a worthless thing; adverbially, in vain from an unused root meaning to lie waste;', 'confusion, empty place, without form, nothing, (thing of) nought, vain, vanity, waste, wilderness.', null),
  ('H8415', 'hebrew', 'תְּהוֹם', 'tᵉhôwm', 'teh-home''', 'an abyss (as a surging mass of water), especially the deep (the main sea or the subterranean watersupply) or תְּהֹם; (usually feminine) from H1949 (הוּם);', 'deep (place), depth.', null),
  ('H8432', 'hebrew', 'תָּוֶךְ', 'tâvek', 'taw''-vek', 'a bisection, i.e. (by implication) the centre from an unused root meaning to sever;', 'among(-st), [idiom] between, half, [idiom] (there-, where-), in(-to), middle, mid(-night), midst (among), [idiom] out (of), [idiom] through, [idiom] with(-in).', null),
  ('H8478', 'hebrew', 'תַּחַת', 'tachath', 'takh''-ath', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. from the same as H8430 (תּוֹחַ);', 'as, beneath, [idiom] flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, [idiom] unto, [idiom] when...was mine, whereas, (where-) fore, with.', null),
  ('H8577', 'hebrew', 'תַּנִּין', 'tannîyn', 'tan-neen''', 'a marine or land monster, i.e. sea-serpent or jackal or תַּנִּים; (Ezekiel 29:3), intensive from the same as H8565 (תַּן);', 'dragon, sea-monster, serpent, whale.', null)
