insert into public.daily_verses (seq, ref, original_text, transliteration, badge) values
  (1, '2CO.3.17', 'ὁ δὲ κύριος τὸ πνεῦμά ἐστιν·', 'ho dè Kýrios tò Pneûmá estín...', 'GREEK · NT'),
  (2, 'PSA.23.1', 'מִזְמוֹר לְדָוִד יְהוָה רֹעִי לֹא אֶחְסָר', 'mizmor l’David, YHWH ro’i lo echsar', 'HEBREW · OT'),
  (3, 'JHN.1.1', 'Ἐν ἀρχῇ ἦν ὁ λόγος', 'En archē ēn ho logos', 'GREEK · NT'),
  (4, 'GEN.1.1', 'בְּרֵאשִׁית בָּרָא אֱלֹהִים', 'bereshit bara Elohim', 'HEBREW · OT'),
  (5, 'JHN.1.14', 'Καὶ ὁ λόγος σὰρξ ἐγένετο', 'Kai ho logos sarx egeneto', 'GREEK · NT'),
  (6, 'PSA.23.4', 'גַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת', 'gam ki elech begei tsalmavet', 'HEBREW · OT'),
